__reload_all = true
local System = require("System.System")
local readonly = System.readonly
local Text_Voice = readonly({
  Voice_100335_AwakerVoiceContent = {
    Text = "Keeper, when can I go back to the Mythag graveyard? The great souls buried there must give me great ideas! Don't worry, I promise I won't dig up those corpses for a closer look again..."
  },
  Voice_100335_AwakerVoiceTitle = {
    Text = "Chat: About Models"
  },
  Voice_100336_AwakerVoiceContent = {
    Text = "Wait! I've thought of a new technique. It's gonna shake the entire art world!"
  },
  Voice_100336_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_100337_AwakerVoiceContent = {
    Text = "I am the bleed of light into shadow. I am the whisper of pigment and varnish. I am... the hunger that paints!"
  },
  Voice_100337_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_100338_AwakerVoiceContent = {
    Text = "Hmm? ...There's a color in your psyche, one I've never seen... what is it..."
  },
  Voice_100338_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_100338_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_100339_AwakerVoiceContent = {
    Text = "Ah, an exquisite black paint! I used to use a lot of Dissolution liquid for paintings, but those works all vanished. Colors from the ancient universe, devouring my painting, forever forgotten by the world... Isn't that even better?!"
  },
  Voice_100339_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_100340_AwakerVoiceContent = {
    Text = "Let me get closer... let me see more! These lights, these shadows, these shapes... everything I've painted before is trash next to this..."
  },
  Voice_100340_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_100340_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_100341_AwakerVoiceContent = {
    Text = "Doresain always says his cooking is art. Come on. Eating has nothing to do with art! It wastes good painting time on preparing corpses, and after making a dish that looks and tastes good, I have to chew it up and swallow it! It's a crime against art!"
  },
  Voice_100341_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_100342_AwakerVoiceContent = {Text = "Ugh..."},
  Voice_100342_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_100343_AwakerVoiceContent = {
    Text = "Such a mean model..."
  },
  Voice_100343_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_100344_AwakerVoiceContent = {
    Text = "No, no, another terrible painting... Where can I find insight? A graveyard? Or a execution ground..."
  },
  Voice_100344_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_100345_AwakerVoiceContent = {
    Text = "I usually find sculpture stiff and boring, but that sculptor, Sanga, her chisel has a power beyond the technique... a real genius!"
  },
  Voice_100345_AwakerVoiceTitle = {
    Text = "Chat: About Sanga"
  },
  Voice_100345_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Sanga\""
  },
  Voice_100346_AwakerVoiceContent = {
    Text = "Have you seen this, Keeper? It's your portrait. Look how lovely you are eating corpses! I know not everyone gets my work, but you must feel the beautiful madness in it, right?! For me, that's enough. More than enough..."
  },
  Voice_100346_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_100346_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_100347_AwakerVoiceContent = {
    Text = "You want to buy this painting... really?! Th-thank you, Keeper! H-Humans rarely ever get it..."
  },
  Voice_100347_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_100347_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_100348_AwakerVoiceContent = {
    Text = "Keeper, do you have time to model again? Compared to what I saw on you last time, the other models are just a waste of my time..."
  },
  Voice_100348_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_100349_AwakerVoiceContent = {
    Text = "In this painting, witness a new birth!"
  },
  Voice_100349_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_100350_AwakerVoiceContent = {
    Text = "Look at these lively lines!"
  },
  Voice_100350_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_100351_AwakerVoiceContent = {
    Text = "This stroke... it will be a masterpiece of impasto! They will be astounded!"
  },
  Voice_100351_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_100352_AwakerVoiceContent = {
    Text = "Ah! A novel pigment! I must apply it where it will best complement the composition!"
  },
  Voice_100352_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_100353_AwakerVoiceContent = {
    Text = "This place gives me ideas! I have new work, Keeper. Do you have time to visit my studio? Come on, come on!"
  },
  Voice_100353_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_100353_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_100354_AwakerVoiceContent = {
    Text = "That's right, perfect! A victory painted in blood! What a brilliant composition!"
  },
  Voice_100354_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_100355_AwakerVoiceContent = {Text = "Ugh..."},
  Voice_100355_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_100356_AwakerVoiceContent = {
    Text = "Ah! Please, sit, Keeper. Modeling for me is hard work, I know. Trust me, I'll make you a masterpiece."
  },
  Voice_100356_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_100356_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_100357_AwakerVoiceContent = {
    Text = "An artist should only see the work, not care what others think... but I can't. Since I first held a brush, I wanted to show everyone true beauty."
  },
  Voice_100357_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_100357_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_100358_AwakerVoiceContent = {
    Text = "This place takes me back to art school. Most teachers and students knew nothing about art, but there were always one or two who could see the beauty in my paintings."
  },
  Voice_100358_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_100359_AwakerVoiceContent = {
    Text = "What kind of mad art will this barbaric performance create?!"
  },
  Voice_100359_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_100360_AwakerVoiceContent = {
    Text = "My palette!"
  },
  Voice_100360_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_100361_AwakerVoiceContent = {
    Text = "Pain is also art..."
  },
  Voice_100361_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_100362_AwakerVoiceContent = {
    Text = "Ah! I see it... the Pupilless Eye under the Abyss, the universe's final sight... Just a moment more, Keeper, it's almost done!"
  },
  Voice_100362_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_100362_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_100363_AwakerVoiceContent = {
    Text = "My brush, made from my shin bone. The palette, these colors from graveyards of twenty different cities... and my precious skin canvas! Keeper, take these and paint me! No, no, you don't need skill... I think when our souls meet on the canvas, it will be a masterpiece beyond my dreams...!"
  },
  Voice_100363_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_100363_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_100364_AwakerVoiceContent = {
    Text = "I am the bleed of light into shadow. I am the whisper of pigment and varnish. I am... the hunger that paints!"
  },
  Voice_100364_AwakerVoiceTitle = {
    Text = "Over-Exalt: II"
  },
  Voice_100365_AwakerVoiceContent = {
    Text = "How'd you like this color?"
  },
  Voice_100365_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_100366_AwakerVoiceContent = {
    Text = "The true essence of art lies in madness...!"
  },
  Voice_100366_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_100367_AwakerVoiceContent = {
    Text = "What? Are you suggesting a close-up on this part of the body in my next piece? Hmm... I never thought of that! Good idea!"
  },
  Voice_100367_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_100368_AwakerVoiceContent = {Text = "Watch out!"},
  Voice_100368_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_100369_AwakerVoiceContent = {
    Text = "The true essence of art lies in madness...!"
  },
  Voice_100369_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_100370_AwakerVoiceContent = {
    Text = "My palette!"
  },
  Voice_100370_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_100371_AwakerVoiceContent = {
    Text = "Oh! Look at that sharp jawline! Those brilliant eyes! And a figure of ideal proportions... plus the vast, starry sky of your spirit shining through... I am the painter Pickman! Might I have the supreme honor of capturing you as my model?"
  },
  Voice_100371_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_100372_AwakerVoiceContent = {
    Text = "My art is about madness and unrest, but that Hameln's music is tight, like tombstones in a graveyard. Yet for some reason, I always see the universe's worst chaos in those orderly notes..."
  },
  Voice_100372_AwakerVoiceTitle = {
    Text = "Chat: About Hameln"
  },
  Voice_100372_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Sanga\""
  },
  Voice_100373_AwakerVoiceContent = {
    Text = "Look, Keeper! The eternal, mad scene on the canvas! So beautiful, so devastating! What grows from this madness and pain is art..."
  },
  Voice_100373_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_100373_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_100374_AwakerVoiceContent = {
    Text = "Ah! I-I'm sorry, Keeper... I see something in you... more terrible, and lovelier than the Abyss..."
  },
  Voice_100374_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_100374_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_100375_AwakerVoiceContent = {
    Text = "I don't get it. Why would anyone turn down the chance to become a ghoul?! This bloody, mad beauty is much more fun than being some boring human in a big house, right?!"
  },
  Voice_100375_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_100376_AwakerVoiceContent = {Text = "Ha!"},
  Voice_100376_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_116964_AwakerVoiceContent = {
    Text = "Punishment！"
  },
  Voice_116964_AwakerVoiceTitle = {
    Text = "Special Skill: I"
  },
  Voice_116965_AwakerVoiceContent = {
    Text = "Punishment！"
  },
  Voice_116965_AwakerVoiceTitle = {
    Text = "Special Skill: II"
  },
  Voice_117791_AwakerVoiceContent = {
    Text = "I admit she has a crude skill for stealing, but a fine lady like me has no need for such despicable tricks. If I desire something, I simply make them hand it over \"voluntarily.\""
  },
  Voice_117791_AwakerVoiceTitle = {
    Text = "Chat: About Jenkin"
  },
  Voice_117791_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Jenkin\""
  },
  Voice_117792_AwakerVoiceContent = {
    Text = "Hahaha! Mine, all mine! All of Mythag's candies belong to me! What are you waiting for? Follow me, the great Candy Witch! We're going to conquer every candy shop in Londinium right now!"
  },
  Voice_117792_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_117792_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_117793_AwakerVoiceContent = {
    Text = "No candy? Then this Witch will be forced to get serious!"
  },
  Voice_117793_AwakerVoiceTitle = {
    Text = "Over-Exalt: II"
  },
  Voice_117794_AwakerVoiceContent = {
    Text = "How do they get the filling inside? I can't find any seams or pinholes! I wish these candy inventors would join Mythag's staff and invent a new dessert for me every single day!"
  },
  Voice_117794_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_117795_AwakerVoiceContent = {
    Text = "Don't you dare mess with the Witch!"
  },
  Voice_117795_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_117796_AwakerVoiceContent = {
    Text = "I used to find candy too plain and not elegant enough compared to cake, but now it seems I underestimated these little things in colorful plastic wrappers. They have such a long shelf life! I could hoard as much as I want, I could fill the whole room with them!"
  },
  Voice_117796_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_117797_AwakerVoiceContent = {
    Text = "You found a new candy? Let me see... Tsk, this Ring Pop looks so ridiculous! A \"diamond\" ring the size of an egg? Wait! What do you mean by presenting me with a ring? Explain yourself immediately!"
  },
  Voice_117797_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_117797_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_117798_AwakerVoiceContent = {
    Text = "I heard witches have a mysterious black cat. But that disgusting campus stray is too embarrassing for a fine lady like me. So, it's settled now. Put on this {Male=catboy,Female=catgirl} headband. I'll make you my little black cat."
  },
  Voice_117798_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_117798_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_117799_AwakerVoiceContent = {
    Text = "Resistance is pointless."
  },
  Voice_117799_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_117800_AwakerVoiceContent = {Text = "BLEEEHHH!"},
  Voice_117800_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_117801_AwakerVoiceContent = {
    Text = "Are there really Witches out there? If they live in deserted forests, who handles their cooking, cleaning, and dessert preparation? If you can't even host an afternoon tea, what is the point of that life? I can't even stand the thought of it."
  },
  Voice_117801_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_117801_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_117802_AwakerVoiceContent = {
    Text = "The Witch is coming!"
  },
  Voice_117802_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_117803_AwakerVoiceContent = {
    Text = "You still have chocolate? Excellent, give it all to me. What? Your stuff is my stuff; isn't that only natural?"
  },
  Voice_117803_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_117803_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_117804_AwakerVoiceContent = {
    Text = "Which candy do I like the most? Let me think... Hazelnut brittle is fragrant, caramel chocolate is delicious, those strawberry and grape-flavored gummies have quite the fun texture, and there's a malt sugar that can be pulled very long and has a beautiful color like honey... No, I refuse to choose. Every candy has its own unique charm! Anyway, I have plenty of pumpkin baskets, so I'll just take them all!"
  },
  Voice_117804_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_117804_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_117805_AwakerVoiceContent = {
    Text = "My current life goal is to eat every single candy in the world. Just thinking about the countless kinds of candy waiting for me out there... that is my entire reason for getting out of bed. Cake, you say? Cake is my other life goal."
  },
  Voice_117805_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_117805_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_117806_AwakerVoiceContent = {
    Text = "Don't be fooled by his looks! Tulu looks like a child, but he's practically a resident of the grave. He has no use for anything a living person enjoys, certainly not candy. So, the candy allocated to him... you should hand it all to me. I am the only one who will truly appreciate it."
  },
  Voice_117806_AwakerVoiceTitle = {
    Text = "Chat: About Tulu"
  },
  Voice_117806_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Tulu\""
  },
  Voice_117807_AwakerVoiceContent = {
    Text = "If I were a witch, my palace would be the height of luxury, of course. I'd hire ten master chefs to make new cakes and candies for me daily... That would make me a princess, not a witch, you say? So what? I shall be the Princess Witch!"
  },
  Voice_117807_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_117807_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_117808_AwakerVoiceContent = {
    Text = "Hey! Go fetch me several varieties of toothpaste, quickly! No, I haven't eaten that much candy! And I do not have a cavity! It just... hurts a little when I sleep..."
  },
  Voice_117808_AwakerVoiceTitle = {
    Text = "Chat: About Candy"
  },
  Voice_117809_AwakerVoiceContent = {
    Text = "The rules at Mythag's restaurant are often annoying, but their pastry skills... hmm, they're barely passable, I suppose."
  },
  Voice_117809_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_117810_AwakerVoiceContent = {
    Text = "The world is full of dark, disgusting things. Instead of worrying about its end, you'd be better off using that time to eat some more candy before it happens."
  },
  Voice_117810_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_117811_AwakerVoiceContent = {Text = "Ouch!"},
  Voice_117811_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_117812_AwakerVoiceContent = {
    Text = "No more plush lambskin rugs, black pearl necklaces or silk pajamas from the far east... and yet, to wake up every day in a room full of candy, with baskets overflowing... this might be what happiness truly looks like... Hey, wipe that silly smile off your face! If you want to serve me forever, you still have a lot of work to do!"
  },
  Voice_117812_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_117812_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_117813_AwakerVoiceContent = {
    Text = "Those despicable people at Mythag, daring to block my access to candy! See? I still got to have them in the end!"
  },
  Voice_117813_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_117814_AwakerVoiceContent = {
    Text = "You want some of my candy? Hmph. I'm feeling generous, so I might bestow a piece upon you... if you beg nicely, that is."
  },
  Voice_117814_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_117815_AwakerVoiceContent = {
    Text = "How dare you call this \"robbery?\" I am simply exercising a lady's noble privilege!"
  },
  Voice_117815_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_117816_AwakerVoiceContent = {
    Text = "The Righteous Candy Witch has arrived! All lost sweets shall return to their proper, glorious owner!"
  },
  Voice_117816_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_117817_AwakerVoiceContent = {
    Text = "Curse you, you stingy thing! I'll remember your face..."
  },
  Voice_117817_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_117818_AwakerVoiceContent = {
    Text = "Why does that little mouse get to blatantly steal candy, yet I cannot? This is blatant discrimination against a lady! Such disrespect!"
  },
  Voice_117818_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_117819_AwakerVoiceContent = {
    Text = "No candy? Then this Witch will be forced to get serious!"
  },
  Voice_117819_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_117820_AwakerVoiceContent = {
    Text = "Have some candy!"
  },
  Voice_117820_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_117821_AwakerVoiceContent = {
    Text = "You're far more thoughtful than those dreadful waiters—even reserved some candy just for me. Keep up the good work, my exclusive servant."
  },
  Voice_117821_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_117821_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_117822_AwakerVoiceContent = {Text = "BLEEEHHH!"},
  Voice_117822_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_117823_AwakerVoiceContent = {
    Text = "That's too much!"
  },
  Voice_117823_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_117824_AwakerVoiceContent = {
    Text = "Why are you stopping me? As my faithful servant, shouldn't you be actively helping me rob... I mean, acquire all the candy?"
  },
  Voice_117824_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_117825_AwakerVoiceContent = {
    Text = "Stop! This is a robbery! I suggest you be sensible and hand over all your candy, or else... Hmph."
  },
  Voice_117825_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_117826_AwakerVoiceContent = {
    Text = "Soft, hard, crunchy, flaky, milky, fruity, nutty, chocolatey... Ah, how can there be so many varieties I haven't tasted yet? I've decided: Mythag must make Halloween a weekly holiday!"
  },
  Voice_117826_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_117827_AwakerVoiceContent = {Text = "(Groan)"},
  Voice_117827_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_117828_AwakerVoiceContent = {
    Text = "The Great Witch shall be victorious! The great candy god protects me, and I, in turn, protect all candy! AHAHAHA!"
  },
  Voice_117828_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_117829_AwakerVoiceContent = {
    Text = "Resistance is pointless."
  },
  Voice_117829_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_117830_AwakerVoiceContent = {
    Text = "All candy shall eventually belong to me!"
  },
  Voice_117830_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_117831_AwakerVoiceContent = {
    Text = "That child is frighteningly obedient. She just hands over all her candy... which actually makes me feel marginally bad. Ahem! I mean, since she's so sensible, the benevolent Witch will naturally leave her some candies... as a small reward!"
  },
  Voice_117831_AwakerVoiceTitle = {
    Text = "Chat: About Lily"
  },
  Voice_117831_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Lily\""
  },
  Voice_117832_AwakerVoiceContent = {
    Text = "Don't you dare mess with the Witch!"
  },
  Voice_117832_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_117833_AwakerVoiceContent = {
    Text = "I am officially furious now!"
  },
  Voice_117833_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_117834_AwakerVoiceContent = {
    Text = "All candy shall eventually belong to me!"
  },
  Voice_117834_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_117835_AwakerVoiceContent = {
    Text = "What? You can roast this kind of marshmallow? But it's gonna get hot and sticky... You sure it tastes good? Let me try... Fine, I'll take a nibble. If you dare to trick me... Huh?! This soft and crispy texture is actually amazing!"
  },
  Voice_117835_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_117835_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_122115_AwakerVoiceContent = {
    Text = "Illusion, Inversion... These are the instruments of Fate!"
  },
  Voice_122115_AwakerVoiceTitle = {
    Text = "Over-Exaltation"
  },
  Voice_122117_AwakerVoiceContent = {
    Text = "Illusion, Inversion... These are the instruments of Fate!"
  },
  Voice_122117_AwakerVoiceTitle = {
    Text = "Over-Exaltation: II"
  },
  Voice_123312_AwakerVoiceContent = {
    Text = "So my true self doesn't scare you because you've \"seen true terror\"? Hmph... a cunning reply. But that just makes me... want to pick you apart even more."
  },
  Voice_123312_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_123312_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_123313_AwakerVoiceContent = {
    Text = "What's the world like in your eyes? Where are the limits of true terror? Don't just tell me; I wanna go feel it first hand with you, feel all the madness, death, and horror! Yeah, I've made up my mind! I'm not leaving your side until my curiosity is satisfied!"
  },
  Voice_123313_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_123313_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_123314_AwakerVoiceContent = {
    Text = "An uncontrollable maniac? Bingo! This is not my world; no tedious laws or rules can hold me back... Here, I do whatever I want. So be careful, Keeper, you never know when a maniac might bite."
  },
  Voice_123314_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_123314_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_123315_AwakerVoiceContent = {
    Text = "You want a deep conversation for my mental health? C'mon, spare me. If we must bore ourselves, let's at least be quick about it."
  },
  Voice_123315_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_123315_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_123316_AwakerVoiceContent = {
    Text = "I'm just pretending to be normal when answering your questions, you say? Heh, you caught me. So, are you ready to see what I really am?"
  },
  Voice_123316_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_123316_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_123770_AwakerVoiceContent = {
    Text = "Off with your head."
  },
  Voice_123770_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_123771_AwakerVoiceContent = {
    Text = "Here's everyone's favorite—Shining☆Tornado!"
  },
  Voice_123771_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_123772_AwakerVoiceContent = {
    Text = "It shouldn't be me..."
  },
  Voice_123772_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_123773_AwakerVoiceContent = {
    Text = "Shining☆Crush!"
  },
  Voice_123773_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_123774_AwakerVoiceContent = {
    Text = "You want to save this twisted, terrifying world? That's gonna be a crazy fun way to die. Let's see how far you can go."
  },
  Voice_123774_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_123775_AwakerVoiceContent = {
    Text = "Wanna taste my axe, sweeties? Don't fret, here it comes..."
  },
  Voice_123775_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_123776_AwakerVoiceContent = {
    Text = "Keeper, I think I saw a light... Did it work this time...? I wonder how my colleagues are doing? They'd better not leave a mountain of work for me; I will not work overtime."
  },
  Voice_123776_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_123776_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_123777_AwakerVoiceContent = {
    Text = "This ritual sends me home? You sure? How many times have we tried...? Well, trying never hurts, I guess."
  },
  Voice_123777_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_123777_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_123778_AwakerVoiceContent = {
    Text = "Haha, now this is the life! Beats the boring daily grind any day!"
  },
  Voice_123778_AwakerVoiceTitle = {
    Text = "Over-Exalt: II"
  },
  Voice_123779_AwakerVoiceContent = {Text = "Ha!"},
  Voice_123779_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_123780_AwakerVoiceContent = {
    Text = "It shouldn't be me..."
  },
  Voice_123780_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_123781_AwakerVoiceContent = {
    Text = "Shining☆Supernova—BLAST!"
  },
  Voice_123781_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_123782_AwakerVoiceContent = {
    Text = "Here's everyone's favorite—Shining☆Tornado!"
  },
  Voice_123782_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_123783_AwakerVoiceContent = {
    Text = "It feels like I'm stepping into the Mist again. Speaking of which, I already miss those little creatures in the Mist. Too bad I can't vent my bad mood on them anymore."
  },
  Voice_123783_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_123783_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_123784_AwakerVoiceContent = {
    Text = "Hate? I wouldn't say that. I merely wish those tedious meetings, social obligations, and universal values could one day poof! Be gone."
  },
  Voice_123784_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_123785_AwakerVoiceContent = {
    Text = "That's it... I'm getting closer to my \"true self\". I can feel it..."
  },
  Voice_123785_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_123786_AwakerVoiceContent = {
    Text = "Ah... So it didn't work. I expected as much. Life is full of ups and downs—well, mostly downs... you get used to it one day. Still, thanks for trying."
  },
  Voice_123786_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_123786_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_123787_AwakerVoiceContent = {
    Text = "I know as much about Dissolution as I do about the Mist Disaster back home—nothing, that is. But that's precisely what makes them so fascinating, right?"
  },
  Voice_123787_AwakerVoiceTitle = {
    Text = "Chat: About the Crisis"
  },
  Voice_123788_AwakerVoiceContent = {
    Text = "Name's Mouchette, investigator of... Oh right, I'm not A.U.G.E.'s vanguard anymore. Let me reintroduce myself—I'm Mouchette, just a sweet, cute girl."
  },
  Voice_123788_AwakerVoiceTitle = {Text = "Awakening"},
  Voice_123789_AwakerVoiceContent = {Text = "Go away!"},
  Voice_123789_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_123790_AwakerVoiceContent = {
    Text = "We're too close to human settlements here; boring adults are everywhere... Have you ever considered moving the school to the deserted deep mountains?"
  },
  Voice_123790_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_123791_AwakerVoiceContent = {
    Text = "(A pained groan)"
  },
  Voice_123791_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_123792_AwakerVoiceContent = {
    Text = "I'm starting to love this feeling of being stranded in another world! Strong Awakeners, terrifying Dissolution, and mysterious gods! Ah, the sheer exhilaration of being far away from the mundane!"
  },
  Voice_123792_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_123793_AwakerVoiceContent = {
    Text = "That's all? I was just starting to have fun! Come on, who's next for the chop?"
  },
  Voice_123793_AwakerVoiceTitle = {
    Text = "Investigation Successful"
  },
  Voice_123794_AwakerVoiceContent = {
    Text = "(A pained groan)"
  },
  Voice_123794_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_123795_AwakerVoiceContent = {
    Text = "They say one failure doesn't define you... I disagree! My axe's gonna do the defining, so keep your necks on a swivel!"
  },
  Voice_123795_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_123796_AwakerVoiceContent = {
    Text = "New mission? Skip the pleasantries next time; we're way past needing to perform the \"socialization rituals\" by now."
  },
  Voice_123796_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_123797_AwakerVoiceContent = {
    Text = "Sacrificing yourself for other people? What a stupid idea. It's infuriating. No one has the right to ask that of anyone, not even a god."
  },
  Voice_123797_AwakerVoiceTitle = {
    Text = "Chat: About Salvador"
  },
  Voice_123797_UnlockDesc = {
    Text = "Unlock after acquiring Awakener \"Salvador\""
  },
  Voice_123798_AwakerVoiceContent = {
    Text = "Hah, not bad..."
  },
  Voice_123798_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_123799_AwakerVoiceContent = {
    Text = "Finally, no more pretending... Now, let's have some <Italic:real> fun."
  },
  Voice_123799_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_123800_AwakerVoiceContent = {
    Text = "Is the ritual not over yet? I really wanna go back. Been craving some Ravenlog Stewed Fish and steaming Hazelnut Kava Tea lately. Though, the Ceylon Black Tea and Andalusian Churros here aren't bad either."
  },
  Voice_123800_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_123800_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_123801_AwakerVoiceContent = {
    Text = "So you're still building me. Aren't you afraid I might lose control someday? Just kidding... Haha!"
  },
  Voice_123801_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_123802_AwakerVoiceContent = {
    Text = "You know, it doesn't seem so bad to stay here for a while. I'll remember everything that happens here, write it down, and share it with them back home. How about the title <Italic:Mouchette's Otherworld Adventure>? It has a nice ring to it, right?"
  },
  Voice_123802_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_123802_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_123803_AwakerVoiceContent = {
    Text = "I admit she's quite cute... Yeah, she's adorable when chasing and fighting those campus strays."
  },
  Voice_123803_AwakerVoiceTitle = {
    Text = "Chat: About Murphy"
  },
  Voice_123803_UnlockDesc = {
    Text = "Unlock after acquiring Awakener \"Murphy\""
  },
  Voice_123804_AwakerVoiceContent = {
    Text = "I'm still stuck here, but hey, getting stronger is always nice."
  },
  Voice_123804_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_123805_AwakerVoiceContent = {
    Text = "A maid? I've been one too. I should find time to show her my vacuum cleaner moves in battle!"
  },
  Voice_123805_AwakerVoiceTitle = {
    Text = "Chat: About Karen"
  },
  Voice_123805_UnlockDesc = {
    Text = "Unlock after acquiring Awakener \"Karen\""
  },
  Voice_123806_AwakerVoiceContent = {
    Text = "Haha, now this is the life! Beats the boring daily grind any day!"
  },
  Voice_123806_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_124737_AwakerVoiceContent = {
    Text = "One strike, one kill."
  },
  Voice_124737_AwakerVoiceTitle = {
    Text = "Special Skill: II"
  },
  Voice_124738_AwakerVoiceContent = {
    Text = "Line up nicely for my axe!"
  },
  Voice_124738_AwakerVoiceTitle = {
    Text = "Special Skill: I"
  },
  Voice_124769_AwakerVoiceContent = {Text = "Vanish!"},
  Voice_124769_AwakerVoiceTitle = {
    Text = "Special Skill: I"
  },
  Voice_126946_AwakerVoiceContent = {
    Text = "Think not, Trouble not; Listen Blindly, Obey Mutely, for the Mortal Coil is only Burden!"
  },
  Voice_126946_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_126947_AwakerVoiceContent = {
    Text = "Think not, Trouble not; Listen Blindly, Obey Mutely, for the Mortal Coil is only Burden!"
  },
  Voice_126947_AwakerVoiceTitle = {
    Text = "Over-Exalt: II"
  },
  Voice_126948_AwakerVoiceContent = {
    Text = "You ask why Their crania are so vacant? Hmm, perhaps it is merely Their nature."
  },
  Voice_126948_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_126949_AwakerVoiceContent = {
    Text = "Suffer no Fury, know no Resentment, for All is Nullity."
  },
  Voice_126949_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_126950_AwakerVoiceContent = {
    Text = "Such attentiveness makes me want to tease you all the more."
  },
  Voice_126950_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_126951_AwakerVoiceContent = {
    Text = "<Italic:Aiyah!>"
  },
  Voice_126951_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_126952_AwakerVoiceContent = {
    Text = "Do you anticipate a greater beauty from me, or a greater dread?"
  },
  Voice_126952_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_126953_AwakerVoiceContent = {
    Text = "There was once a Princess born of Pleasure. Her robes were threaded with gold, her skin like ivory, the scent of agarwood drifted around her, and the mere sweep of her gaze could steal a soul."
  },
  Voice_126953_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_126953_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_126954_AwakerVoiceContent = {
    Text = "She soon tired of the sport. Her devotees merely repeated the same theatre, consumed by the Love born of Lust, or the Lust born of Love. Their foolishness—their heartbreak over betrayal and loss—it bored her. Their tears, too, bored her."
  },
  Voice_126954_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_126954_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_126955_AwakerVoiceContent = {
    Text = "The gaze of such petty, common minds is an utter vexation to me."
  },
  Voice_126955_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_126956_AwakerVoiceContent = {
    Text = [[
That Madam in Red once sent me several invitations to her salons.
The foreign confections were passable, but... 
She ought to have informed me sooner that at her residence, "desserts" and "servants" were not synonymous.]]
  },
  Voice_126956_AwakerVoiceTitle = {
    Text = "Chat: About Sorel"
  },
  Voice_126956_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Sorel\""
  },
  Voice_126958_AwakerVoiceContent = {
    Text = [[
Do you not love me? Then why cower when you are encompassed? Do you not loath me? Then why weep when there is no return?
Oh, now you fear my shadow? Has the fragrance of white magnolia become a cloying, inexplicable musk to you?]]
  },
  Voice_126958_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_126958_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_126959_AwakerVoiceContent = {Text = "Sure."},
  Voice_126959_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_126960_AwakerVoiceContent = {
    Text = "Oh? You ask why they bore those marks under their arms? Do you not find it utterly diverting?"
  },
  Voice_126960_AwakerVoiceTitle = {
    Text = "Chat: The Order of Swelling Grace"
  },
  Voice_126961_AwakerVoiceContent = {
    Text = "<Italic:Aiyah!>"
  },
  Voice_126961_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_126963_AwakerVoiceContent = {
    Text = "These slight diversions are more to my liking than the offerings of my devotees."
  },
  Voice_126963_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_126964_AwakerVoiceContent = {
    Text = "First Their bearing, then Their shape, until They also possessed a pair of... or rather, until all that remained memorable was a pair of beautiful, Soul-Capturing Eyes—eyes just like mine."
  },
  Voice_126964_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_126964_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_126965_AwakerVoiceContent = {
    Text = [[
I am utterly bored this day. Is there no wish you require me to make manifest?

A pity you don't. So many are willing to wield the scythe and offer me sweetmeat for far more trifling ends.
But if it's you asking...]]
  },
  Voice_126965_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_126965_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_126966_AwakerVoiceContent = {
    Text = "Why does the Order of the Swelling Grace follow me, and what was its genesis? An amusing query. Have you, too, known the person unattainable, or the regret of failed struggle?\nHmm, it seems not. What a waste. That look of desperate struggle—it would be so very amusing to behold on your face."
  },
  Voice_126966_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_126966_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_126967_AwakerVoiceContent = {
    Text = "...If you continue to trespass thus, the guise I adopt for you may not remain so agreeable."
  },
  Voice_126967_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_126968_AwakerVoiceContent = {
    Text = "I have almost forgotten her tale entirely, but it was one of Rapture, one of Cruelty, one that began with Abandonment and Retribution, and concluded with Sacrifice and Blind Obedience."
  },
  Voice_126968_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_126968_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_126969_AwakerVoiceContent = {
    Text = "Amuse me. Slay one another in pain and dread!"
  },
  Voice_126969_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_126970_AwakerVoiceContent = {
    Text = "...This, at least, grants me a slight spark of interest."
  },
  Voice_126970_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_126971_AwakerVoiceContent = {
    Text = "Beneath my fan, every soul sees the face of their most cherished. I lend this power to the weak, that they may wield it as a blade for my own amusement.\n\nBut perhaps—I only say, perhaps. If you were to be enthralled by it, I would know a true, unsullied Ecstasy."
  },
  Voice_126971_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_126971_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_126972_AwakerVoiceContent = {
    Text = [[
Do not trouble yourself; you are not like those common multitude. 
Hush. Do not look behind me. Pay no mind to the unseen caress. Look into my eyes, and my eyes alone.]]
  },
  Voice_126972_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_126972_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_126973_AwakerVoiceContent = {
    Text = "Hehe... Do any of you dare to behold my true form?"
  },
  Voice_126973_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_126975_AwakerVoiceContent = {Text = "Noisy."},
  Voice_126975_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_126976_AwakerVoiceContent = {
    Text = "Ah, you stare, enraptured by my fan again? Hehe. No matter whose face you desire, I shall let you have it. Come, draw closer—\nOh? You refuse? Such cold words, yet such an adorable expression..."
  },
  Voice_126976_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_126976_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_126977_AwakerVoiceContent = {
    Text = "What is it you are looking for in my Dreamless Land?"
  },
  Voice_126977_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_126978_AwakerVoiceContent = {
    Text = "Suffer no Fury, know no Resentment, for All is Nullity."
  },
  Voice_126978_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_126979_AwakerVoiceContent = {
    Text = "Hold your impudence."
  },
  Voice_126979_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_126980_AwakerVoiceContent = {Text = "Sure."},
  Voice_126980_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_126981_AwakerVoiceContent = {
    Text = "I, too, once had such a pretty, compliant girl. A tempting flower-bud, of course she needed a few thorns—she could not simply be placed in a vase."
  },
  Voice_126981_AwakerVoiceTitle = {
    Text = "Chat: About Lily"
  },
  Voice_126981_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Lily\""
  },
  Voice_126982_AwakerVoiceContent = {
    Text = "The University so firmly rejected my application for the psychological therapy office. How strange; what objection could they possibly hold?"
  },
  Voice_126982_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_126983_AwakerVoiceContent = {
    Text = [[
All things end in the Void. Why not seek some further pleasure with me before then?

Rest assured, should the day come that you cannot resist the Dissolution further, I shall not allow It to claim you first.]]
  },
  Voice_126983_AwakerVoiceTitle = {
    Text = "Chat: About the Crisis"
  },
  Voice_126984_AwakerVoiceContent = {Text = "Boring."},
  Voice_126984_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_126985_AwakerVoiceContent = {
    Text = [[
You are truly a marvel, so preoccupied with the trivialities of the corporeal, in a world already marked for ruin.

It compels me to take an interest myself.]]
  },
  Voice_126985_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_126985_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_126986_AwakerVoiceContent = {
    Text = "Advance not!"
  },
  Voice_126986_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_126988_AwakerVoiceContent = {
    Text = "I am Xu, the Mistress of the Dreamless Land. If, in your heart, there is one you ache to see, yet cannot attain, I shall lower my fan and grant you a glimpse."
  },
  Voice_126988_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_127088_AwakerVoiceContent = {
    Text = [[
All nascent beings are a bother. Small, soft, loud, they unconsciously command all things around them.

I enjoy a spectacle, but decidedly not that sort. Pray, ensure they remain far, far away.]]
  },
  Voice_127088_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_127089_AwakerVoiceContent = {
    Text = [[
You? You are my little Jasmine, my obedient darling, the delightful game of playhouse I so willingly participate in...
Ah, mere happy ravings. Please pay them no mind.]]
  },
  Voice_127089_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_127090_AwakerVoiceContent = {
    Text = "In the legends of the Panlong Empire, the peacock is a handsome, flamboyant, and malicious beast. Beautiful and viscious—it makes the heart race. Ugly and kind, however, is rather boring."
  },
  Voice_127090_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_129651_AwakerVoiceContent = {
    Text = "Gobble up! Yum yum!"
  },
  Voice_129651_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_129652_AwakerVoiceContent = {
    Text = "Gurgle gurgle~"
  },
  Voice_129652_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_129653_AwakerVoiceContent = {
    Text = "Coalsie, I, eat, together? Together!"
  },
  Voice_129653_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_129653_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_129654_AwakerVoiceContent = {
    Text = "Vortice! Very strong!"
  },
  Voice_129654_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_129655_AwakerVoiceContent = {
    Text = "Abyss! Spiral! Gone, everything—all become whirlpool!"
  },
  Voice_129655_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_129656_AwakerVoiceContent = {Text = "Ow!"},
  Voice_129656_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_129657_AwakerVoiceContent = {
    Text = "No touch! You break!"
  },
  Voice_129657_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_129657_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_129658_AwakerVoiceContent = {
    Text = "Shell, shiny! Pretty! Give you!"
  },
  Voice_129658_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_129658_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_129659_AwakerVoiceContent = {
