  Voice_129668_AwakerVoiceContent = {Text = "Bang!"},
  Voice_129668_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_129669_AwakerVoiceContent = {Text = "Ow!"},
  Voice_129669_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_129670_AwakerVoiceContent = {Text = "Eek!"},
  Voice_129670_AwakerVoiceTitle = {Text = "Hit: I"},
