  },
  Voice_129679_AwakerVoiceContent = {Text = "Yahoo!"},
  Voice_129679_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_129680_AwakerVoiceContent = {Text = "Eek!"},
  Voice_129680_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_129681_AwakerVoiceContent = {
