  },
  Voice_129682_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_129683_AwakerVoiceContent = {
    Text = "Nautilus, Nautila, Coalsie! Shinies!"
  },
  Voice_129683_AwakerVoiceTitle = {
