  },
  Voice_129688_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_129688_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_129689_AwakerVoiceContent = {
    Text = "Vortice! Coalsie! Together, always? Forever!"
  },
  Voice_129689_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_129689_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_129690_AwakerVoiceContent = {
    Text = "Whoosh whoosh~ Big wave up!"
  },
  Voice_129690_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_129690_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_129691_AwakerVoiceContent = {
    Text = "Friends! Many! Like!"
  },
  Voice_129691_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_129692_AwakerVoiceContent = {
    Text = "Vortice! Great!"
  },
  Voice_129692_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_129693_AwakerVoiceContent = {
    Text = "Nautila, miss you... Eh? Nautila, Vortice, here, Vortice, HERE!"
  },
  Voice_129693_AwakerVoiceTitle = {
    Text = "Chat: About Nautila"
  },
  Voice_129693_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Nautila\""
  },
  Voice_129694_AwakerVoiceContent = {
    Text = "Vortice! Strong!"
  },
  Voice_129694_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_129695_AwakerVoiceContent = {
    Text = "I! Vortice! Yahoo!"
  },
  Voice_129695_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_130511_AwakerVoiceContent = {Text = "WHOOSH—"},
  Voice_130511_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_22276_AwakerVoiceContent = {
    Text = "Quick, wrap it up! Don't linger on the streets."
  },
  Voice_22276_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_36679_AwakerVoiceContent = {
    Text = [[
He joined the cult while I was asleep, so I have no connection to him.
I heard he came willingly, wanting to abandon his human form to become a full Seafarer... Hmph, another fool blinded by power.]]
  },
  Voice_36679_AwakerVoiceTitle = {
    Text = "Chat: About Caecus"
  },
  Voice_36679_UnlockDesc = {
    Text = "Unlocked after completing Main Story Chapter 6"
  },
  Voice_36680_AwakerVoiceContent = {
    Text = "Goliath was never a loyal pet. I cannot understand why Miryam values him so much... If he wasn't chained, he would have run off and betrayed her immediately."
  },
  Voice_36680_AwakerVoiceTitle = {
    Text = "Chat: About Goliath"
  },
  Voice_36680_UnlockDesc = {
    Text = "Unlocked after completing Main Story Chapter 6"
  },
  Voice_36681_AwakerVoiceContent = {
    Text = "Seafarers are not born this way. To blend in, they live their first half just like humans...\nYou'd better watch out—your favorite cake shop owner might be one of them!"
  },
  Voice_36681_AwakerVoiceTitle = {
    Text = "Chat: About Seafarers"
  },
  Voice_36681_UnlockDesc = {
    Text = "Unlocked after completing Main Story Chapter 6"
  },
  Voice_36682_AwakerVoiceContent = {
    Text = "Celeste's off-key sea shanty, the captain's signature smoked fish stew, blankets stiff and fishy from the sea breeze... Though tense and dangerous, I will never forget those months in exile at sea."
  },
  Voice_36682_AwakerVoiceTitle = {
    Text = "Chat: About the \"Ghost Ship\""
  },
  Voice_36682_UnlockDesc = {
    Text = "Unlocked after completing Main Story Chapter 6"
  },
  Voice_36683_AwakerVoiceContent = {
    Text = [[
Everyone at this school seems so busy, but...
There's a quiet peace here I've never known.
Working together toward the same goal... Hmph, I suppose it's not entirely awful.]]
  },
  Voice_36683_AwakerVoiceTitle = {
    Text = "Chat: About Mythag II"
  },
  Voice_36683_UnlockDesc = {
    Text = "Unlocked after completing Main Story Chapter 6"
  },
  Voice_36684_AwakerVoiceContent = {
    Text = [[
The bed is too hard, the weather too cold, the tea tastes like dirty rinse water... I have a thousand reasons to despise this place. 
However, since you're here, I suppose I can tolerate it. Reluctantly.]]
  },
  Voice_36684_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper III"
  },
  Voice_36684_UnlockDesc = {
    Text = "Unlocked after completing Main Story Chapter 6"
  },
  Voice_36685_AwakerVoiceContent = {
    Text = [[
Thank you... H-Huh? Why am I saying that? Well, obviously! It's for everything you did for me at sea...
Wait, why are you laughing?! You just want to see me flustered!]]
  },
  Voice_36685_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper II"
  },
  Voice_36685_UnlockDesc = {
    Text = "Unlocked after completing Main Story Chapter 6"
  },
  Voice_36686_AwakerVoiceContent = {
    Text = [[
I once believed there was some sort of familial bond between us...
But now, after everything, I realize those fleeting warm moments were just my wishful thinking.
What you do with her is your business, just keep her away from me.]]
  },
  Voice_36686_AwakerVoiceTitle = {
    Text = "Chat: About Miryam II"
  },
  Voice_36686_UnlockDesc = {
    Text = "Unlocked after completing Main Story Chapter 6"
  },
  Voice_36687_AwakerVoiceContent = {
    Text = [[
How peculiar... This feeling is so strange.
My heart has stopped, yet my body is still warm... Hey, come here and touch my hand. Tell me this isn't some trick.]]
  },
  Voice_36687_AwakerVoiceTitle = {
    Text = "Chat: About \"Awakeners\""
  },
  Voice_36687_UnlockDesc = {
    Text = "Unlocked after completing Main Story Chapter 6"
  },
  Voice_45153_AwakerVoiceContent = {
    Text = "I may not have been born in the Kingdom of Leo, but the Church of Redemption is where I received my second life. Why, then, can I not consider this place my home?"
  },
  Voice_45153_AwakerVoiceTitle = {
    Text = "Chat: About Home"
  },
  Voice_45154_AwakerVoiceContent = {
    Text = "After years of this invisible plague, the All-Father finally heard my prayers and bestowed upon me the \"Blessing\" that can counter suffering. It indeed grants life, but also requires a price. As His executor, I ought to bear that burden on behalf of those blessed."
  },
  Voice_45154_AwakerVoiceTitle = {
    Text = "Chat: About His \"Blessing\""
  },
  Voice_45155_AwakerVoiceContent = {
    Text = "For me, the state of being an Awakener is a gift from our All-Father to the souls in His embrace. It is a second life, an opportunity to mend past regrets. I will continue His work, fulfill my duties as His proxy, and alleviate more suffering."
  },
  Voice_45155_AwakerVoiceTitle = {
    Text = "Chat: About \"Awakeners\""
  },
  Voice_45156_AwakerVoiceContent = {
    Text = "Let me express my gratitude once again, Keeper, for respecting my wishes and keeping my secret from the Committee. I fear their intervention would see me barred from continuing my service to the Chantry of Life."
  },
  Voice_45156_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper: II"
  },
  Voice_45156_UnlockDesc = {
    Text = "Unlocks after clearing Special Operation \"Color of Blood\""
  },
  Voice_45157_AwakerVoiceContent = {
    Text = "That child is sincere, steadfast, and kind, with a rare bright soul. The last time I met a spirit like this was during the first chapter of my life."
  },
  Voice_45157_AwakerVoiceTitle = {
    Text = "Chat: About Ogier"
  },
  Voice_45157_UnlockDesc = {
    Text = "Unlocks after clearing Special Operation \"Color of Blood\""
  },
  Voice_45158_AwakerVoiceContent = {
    Text = "Losing my sight does not mean I have become blind. While the All-Father brought darkness upon me, He also allowed me to see the faint light of souls."
  },
  Voice_45158_AwakerVoiceTitle = {
    Text = "Chat: About Vision"
  },
  Voice_45159_AwakerVoiceContent = {
    Text = "Back then, although I had received \"The Blessing\", I was just an ordinary man. There were too many who suffered, too many who needed it. I wanted to save them all, but I failed. This is my greatest regret and my eternal guilt."
  },
  Voice_45159_AwakerVoiceTitle = {
    Text = "Chat: About His First Life"
  },
  Voice_45160_AwakerVoiceContent = {
    Text = [[
Many in the Chantry of Life believe the "white flame" in the Scriptures refers to moonlight: a Pale Messenger appearing from it to lead us from suffering.
But I know the true flame is the soul burning within you and me.]]
  },
  Voice_45160_AwakerVoiceTitle = {
    Text = "Chat: About the \"Pale Flame\""
  },
  Voice_45161_AwakerVoiceContent = {
    Text = "In fact, I was told to hide my true identity by the Archbishop. He did not elaborate, but warned me: even in the purest places, shadows may exist, and one must remain cautious, even when doing good. Of course, I trust you completely."
  },
  Voice_45161_AwakerVoiceTitle = {
    Text = "Chat: About Hiding Identity"
  },
  Voice_45161_UnlockDesc = {
    Text = "Unlocks after clearing Special Operation \"Color of Blood\""
  },
  Voice_4908_AwakerVoiceContent = {
    Text = "Has my singing been of any help to you?"
  },
  Voice_4908_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_4909_AwakerVoiceContent = {
    Text = "Damn it, he's just a boy! Why do you all treat him with such respect?! Show me the same reverence, understood?!"
  },
  Voice_4909_AwakerVoiceTitle = {
    Text = "Chat: About Tulu"
  },
  Voice_4909_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Tulu\""
  },
  Voice_4910_AwakerVoiceContent = {
    Text = "Hey, do you know what the other Awakeners usually do? Don't misunderstand, I don't want friends, I just... I'm simply making an inspection!"
  },
  Voice_4910_AwakerVoiceTitle = {
    Text = "Chat: About Daily Life"
  },
  Voice_4911_AwakerVoiceContent = {
    Text = "Damn it! Next time, I'll throw their corpses to the spiders for dinner!"
  },
  Voice_4911_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_4912_AwakerVoiceContent = {Text = "Afterglow."},
  Voice_4912_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_4913_AwakerVoiceContent = {Text = "Rhythm."},
  Voice_4913_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_4914_AwakerVoiceContent = {
    Text = "Quite bold of you."
  },
  Voice_4914_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_4915_AwakerVoiceContent = {
    Text = "Let's slow down a bit... Is there anything at all I can do for you?"
  },
  Voice_4915_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_4916_AwakerVoiceContent = {
    Text = "How dare you!"
  },
  Voice_4916_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_4917_AwakerVoiceContent = {
    Text = "(Questioning with great interest)"
  },
  Voice_4917_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_4918_AwakerVoiceContent = {
    Text = "What I like? My baby, the Divine Fetus that earned my prestige, of course. You think it is unlike me to say that?"
  },
  Voice_4918_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_4919_AwakerVoiceContent = {
    Text = "What do you intend?"
  },
  Voice_4919_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_4920_AwakerVoiceContent = {
    Text = "Not bad, eh? Now, my payment.—What? You think this was a free lunch?!"
  },
  Voice_4920_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_4921_AwakerVoiceContent = {Text = "Go away!"},
  Voice_4921_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_4922_AwakerVoiceContent = {Text = "Careful!"},
  Voice_4922_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_4923_AwakerVoiceContent = {
    Text = "What a glorious victory... I shall engrave this moment into eternity."
  },
  Voice_4923_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_4924_AwakerVoiceContent = {
    Text = "I am feeling it... The Source of Uncleanliness... One step closer to Our true form... Ahhh, I shall tear this world apart!"
  },
  Voice_4924_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_4924_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_4925_AwakerVoiceContent = {
    Text = "We're...ready. Please give the order, Keeper."
  },
  Voice_4925_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_4925_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_4926_AwakerVoiceContent = {
    Text = "{Male=Sir,Female=Madam}, you are truly kind. Sadly, I have nothing to repay you with, worthless as I am..."
  },
  Voice_4926_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_4926_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_4927_AwakerVoiceContent = {
    Text = "...Just a little further, and I'll be completely separated from \"them\"?"
  },
  Voice_4927_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_4927_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_4928_AwakerVoiceContent = {
    Text = "Huh? I'm still alive... You... You really won't steal my organs or use me for experiments?"
  },
  Voice_4928_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_4928_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_4929_AwakerVoiceContent = {
    Text = "Winkle's native species can infiltrate the biological brain, causing the Outer Will fused with me to fear her. But now, she's merely a poor soul confined within a shell."
  },
  Voice_4929_AwakerVoiceTitle = {
    Text = "Chat: About Winkle"
  },
  Voice_4929_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Winkle\""
  },
  Voice_4930_AwakerVoiceContent = {
    Text = "Everything. I love everything. Whether it's everyone gathered around the table for a meal and prayer, or the anticipation when the Keeper is out on a mission, waiting for your triumphant return... The air is always filled with happiness... Do I truly deserve such joy?"
  },
  Voice_4930_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_4931_AwakerVoiceContent = {Text = "Sink."},
  Voice_4931_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_4932_AwakerVoiceContent = {Text = "Bloom."},
  Voice_4932_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_4933_AwakerVoiceContent = {
    Text = "Trust,\" \"Obedience,\" \"Slave,\" \"Affection,\" \"Respect\"... Reconstructing and learning language module. Please, Keeper, guide me."
  },
  Voice_4933_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_4933_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_4934_AwakerVoiceContent = {
    Text = "Erica is currently in standby mode. The body will complete cooling in 1 hour and 15 minutes. <Del:To turn Erica on, offer your beating heart> Emergency start? ... Permission verification in progress... Highest authority of the Keeper verified. Hello, Keeper."
  },
  Voice_4934_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_4934_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_4935_AwakerVoiceContent = {
    Text = "The average risk index of investigation tasks is 7, with an average consumption of 8 bottles of alchemy supplements and an average of 10 hours required for corpse handling. Conclusion: A Keeper's job is extremely dangerous. Please stay safe during operations."
  },
  Voice_4935_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_4935_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_4936_AwakerVoiceContent = {
    Text = "Searching teacher records: Erica Layfield, Silver Mechatronics and Automation Lecturer, Deceased—Is this not what you were looking for? Okay, re-searching keyword \"Erica.\""
  },
  Voice_4936_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_4936_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_4937_AwakerVoiceContent = {
    Text = "If you need to look up information, please provide the full name of the file. The fuzzy search function is currently unavailable."
  },
  Voice_4937_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_4937_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_4938_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_4938_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_4939_AwakerVoiceContent = {Text = "Ah!"},
  Voice_4939_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_4940_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_4940_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_4941_AwakerVoiceContent = {Text = "Ah!"},
  Voice_4941_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_4942_AwakerVoiceContent = {
    Text = "Charge complete, ready to detonate."
  },
  Voice_4942_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_4943_AwakerVoiceContent = {
    Text = "Charge complete, ready to detonate."
  },
  Voice_4943_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_4944_AwakerVoiceContent = {
    Text = "Don't interrupt my rest with such trifles again."
  },
  Voice_4944_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_4945_AwakerVoiceContent = {
    Text = "Like how I protected Tinct, I'll protect you, too."
  },
  Voice_4945_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_4946_AwakerVoiceContent = {
    Text = "I am no one of consequence, merely one devoted soul among countless. I have dedicated my life to that magnificent presence, and I shall never cease to offer my all to earn but a glance."
  },
  Voice_4946_AwakerVoiceTitle = {
    Text = "Chat: About Past"
  },
  Voice_4946_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Tulu\""
  },
  Voice_4947_AwakerVoiceContent = {Text = "Watch me!"},
  Voice_4947_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_4948_AwakerVoiceContent = {Text = "Watch me!"},
  Voice_4948_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_4949_AwakerVoiceContent = {
    Text = "...It matters not, so long as their zeal doesn't rouse me. Sharing quarters is tolerable."
  },
  Voice_4949_AwakerVoiceTitle = {
    Text = "Chat: About Seafarers"
  },
  Voice_4949_UnlockDesc = {
    Text = "Unlocks after acquiring any one of Awakeners \"Miryam\", \"Goliath\", \"Caecus\", \"Sanga\", or \"Faros\"."
  },
  Voice_4950_AwakerVoiceContent = {
    Text = "I hate that dark feeling, as if my heart has been hollowed out. The unfulfilled sensation makes my whole body itch..."
  },
  Voice_4950_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_4951_AwakerVoiceContent = {
    Text = "No, no, no, don't! Don't mention it..."
  },
  Voice_4951_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_4953_AwakerVoiceContent = {Text = "Ha!"},
  Voice_4953_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_4954_AwakerVoiceContent = {Text = "Hah!"},
  Voice_4954_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_4955_AwakerVoiceContent = {
    Text = "Historians who declare the Divine Realm's demise are tedious in their presumptions... Yet mere words are meaningless foams; none shall halt the glorious restoration."
  },
  Voice_4955_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_4956_AwakerVoiceContent = {
    Text = "Actually... let me tell you a secret. I'm not quite satisfied with my current motorcycle—it's not that I don't like it! It's just that I feel like something is missing..."
  },
  Voice_4956_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_4957_AwakerVoiceContent = {Text = "Ha!"},
  Voice_4957_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_4958_AwakerVoiceContent = {Text = "Chop!"},
  Voice_4958_AwakerVoiceTitle = {
    Text = "Skill: II: Mania"
  },
  Voice_4959_AwakerVoiceContent = {
    Text = "Sorry... I didn't want this to happen..."
  },
  Voice_4959_AwakerVoiceTitle = {
    Text = "Skill: II: Depression"
  },
  Voice_4960_AwakerVoiceContent = {
    Text = "(Intrigued whisper)"
  },
  Voice_4960_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_4961_AwakerVoiceContent = {
    Text = "In Year @1@2, Mr. Ward Philips, Mr. Khlarcus, and Ms. Tawil together founded Mythag College. After a long development, it became <Del:this damned prison> Mythag University."
  },
  Voice_4961_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_4962_AwakerVoiceContent = {
    Text = "Justice, loyalty, resilience, discipline. These have long been engraved in my heart."
  },
  Voice_4962_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_4963_AwakerVoiceContent = {
    Text = "I will properly complete the task you have assigned to me."
  },
  Voice_4963_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_4964_AwakerVoiceContent = {
    Text = "What kind of irresponsible parents would name their daughter after a shield made of Gorgon's head? ...She has no parents? Hmm... let's keep this conversation between us."
  },
  Voice_4964_AwakerVoiceTitle = {
    Text = "Chat: About Aigis"
  },
  Voice_4964_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Aigis\""
  },
  Voice_4965_AwakerVoiceContent = {
    Text = "If you're bored, why not come \"keep me company\" in the maze? After all, your hopeless life is no different from this endless labyrinth!"
  },
  Voice_4965_AwakerVoiceTitle = {
    Text = "Chat: About the Maze"
  },
  Voice_4966_AwakerVoiceContent = {
    Text = "When Doll is around, investigators' efficiency increases by 78.312%, but more people also fall into emotional slumps. As she put it: \"If some people could keep their mouths shut, the world would run more smoothly.\""
  },
  Voice_4966_AwakerVoiceTitle = {
    Text = "Chat: About Doll"
  },
  Voice_4966_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Doll\""
  },
  Voice_4967_AwakerVoiceContent = {Text = "Descend!"},
  Voice_4967_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_4968_AwakerVoiceContent = {
    Text = "How was that?"
  },
  Voice_4968_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_4969_AwakerVoiceContent = {
    Text = "Who wouldn't love adventure? Delving into unexplored mysterious realms, discovering the unknown, and weaving your own story... How thrilling!"
  },
  Voice_4969_AwakerVoiceTitle = {
    Text = "Chat: About Adventures"
  },
  Voice_4970_AwakerVoiceContent = {
    Text = "Greetings. I am Nymphaea of Febvre. You have granted me a new body, allowing me to finally breathe freely... How may I repay this grace?"
  },
  Voice_4970_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_4971_AwakerVoiceContent = {
    Text = "I think I just heard those who claimed to be my masters wailing again. How delightful."
  },
  Voice_4971_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_4971_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_4972_AwakerVoiceContent = {
    Text = "Can I skip the vegetables? Though Tinct said not to be picky, I don't like their colors..."
  },
  Voice_4972_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_4973_AwakerVoiceContent = {
    Text = "The All-Father once said: 'Suffering is not my creation. Bear and dissolve it, my emissaries, and build a land without suffering.' For this, I would offer everything. Even my life."
  },
  Voice_4973_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_4973_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_4974_AwakerVoiceContent = {
    Text = "In the face of the all-consuming curse of Dissolution, other sufferings pale. Even if I cannot bear the curse for others, I will do my utmost to alleviate their pain."
  },
  Voice_4974_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_4974_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_4975_AwakerVoiceContent = {
    Text = "Am I now able to ease their pain and comfort their souls?"
  },
  Voice_4975_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_4975_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_4976_AwakerVoiceContent = {
    Text = "Thus, I shall bear all suffering, to pave the way for all beings to a land free from pain."
  },
  Voice_4976_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_4976_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_4977_AwakerVoiceContent = {
    Text = "This warmth deep within my soul... Thank you for this gift, Pale Flame. With this power, perhaps I can finally fulfill my duty as His emissary and save more of His children."
  },
  Voice_4977_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_4977_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_4978_AwakerVoiceContent = {
    Text = "Can I really eat all of this?"
  },
  Voice_4978_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_4978_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_4979_AwakerVoiceContent = {
    Text = "Heh. That you are looking at is not death. Just your future. Mine. And everyone else's."
  },
  Voice_4979_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_4980_AwakerVoiceContent = {
    Text = "Tinct... Hearing her mournful song makes me want to dance..."
  },
  Voice_4980_AwakerVoiceTitle = {
    Text = "Chat: About Tinct"
  },
  Voice_4980_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Tinct\""
  },
  Voice_4981_AwakerVoiceContent = {
    Text = "Can worldly trials truly awaken the potential of my bloodline? That, I did not anticipate."
  },
  Voice_4981_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_4982_AwakerVoiceContent = {
    Text = "The weapon feels handier now."
  },
  Voice_4982_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_4983_AwakerVoiceContent = {
    Text = "Don't think this will earn my gratitude. My noble lineage simply wouldn't allow it."
  },
  Voice_4983_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_4984_AwakerVoiceContent = {Text = "Ah, uh!"},
  Voice_4984_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_4985_AwakerVoiceContent = {
    Text = "That man... Hey, hang on, our bet's not over yet, is it?"
  },
  Voice_4985_AwakerVoiceTitle = {
    Text = "Chat: About Others"
  },
  Voice_4986_AwakerVoiceContent = {
    Text = "I really like the academy's recorder. If only I could create a portable version that reminds me in real-time of what I've forgotten..."
  },
  Voice_4986_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_4987_AwakerVoiceContent = {
    Text = "Huh, a congregation of ants... No, not even ants—the likes of you are merely bread crumbs, providing nourishment for His rebirth."
  },
  Voice_4987_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_4988_AwakerVoiceContent = {
    Text = "The supplies have arrived."
  },
  Voice_4988_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_4989_AwakerVoiceContent = {
    Text = "The supplies have arrived."
  },
  Voice_4989_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_4990_AwakerVoiceContent = {
    Text = "Hmm... Harder, harder. Yes, just like that..."
  },
  Voice_4990_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_4991_AwakerVoiceContent = {
    Text = "Victory came effortlessly, even before my bloodline's full awakening."
  },
  Voice_4991_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_4992_AwakerVoiceContent = {
    Text = "Oh no, my hat is crooked... Hmm, is this better? It is! Perfect!"
  },
  Voice_4992_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_4992_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_4993_AwakerVoiceContent = {
    Text = "\"With such abilities, am I truly still human?\" I have asked myself this every day since I started training for battle. I love this world, despite its darkness, filth, and monotony, but your presence makes it shine like diamonds amidst the dust. I once feared that as my power grew, my stance as a human would shift... Now, I am grateful to have you by my side. Our bond anchors me firmly to the human world. Please continue to watch over me, Keeper."
  },
  Voice_4993_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_4993_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_4994_AwakerVoiceContent = {
    Text = "Ah... It's natural for you to have concerns. I didn't think it through. As your partner, I should have explained this from the start. As you can see, I do possess some unusual traits, likely tied to my background. It's impossible not to be curious, right? But having a place like the academy is a blessing for me, so I choose not to lift the veil of fate."
  },
  Voice_4994_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_4994_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_4995_AwakerVoiceContent = {
    Text = "You've met that woman, right? The Awakener in a white veil—she's one of the university's founders... But honestly, I don't like her. That aloof attitude, as if she doesn't care about the world at all, really gets on my nerves... Oh, you think she looks like me? Let's go get your eyes checked at the campus clinic."
  },
  Voice_4995_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_4995_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_4996_AwakerVoiceContent = {
    Text = "Are you curious about my relationship with Professor Dexter? It's no secret. He is my foster father. As for my mother... I grew up here at the school and was cared for by all the teachers. However, among them, I am closest to Professor Doll."
  },
  Voice_4996_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_4996_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_4997_AwakerVoiceContent = {
    Text = "Whether it's the Awakener Affairs Office procedures or the date for Indian food in the canteen, I can answer any question about Mythag for you. Don't worry, you're not bothering me. Do I look that unapproachable?"
  },
  Voice_4997_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_4997_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_4998_AwakerVoiceContent = {
    Text = "Mirror, mirror, who is the greatest magician in the world? Me? That is correct!"
  },
  Voice_4998_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_4998_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_4999_AwakerVoiceContent = {Text = "Not bad."},
  Voice_4999_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_5000_AwakerVoiceContent = {Text = "Great!"},
  Voice_5000_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5001_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_5001_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_5002_AwakerVoiceContent = {
    Text = "Did it... truly work? Have I been of any genuine help?"
  },
  Voice_5002_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_5003_AwakerVoiceContent = {Text = "Useless!"},
  Voice_5003_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_5004_AwakerVoiceContent = {Text = "(Endure)"},
  Voice_5004_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_5005_AwakerVoiceContent = {
    Text = "Look this way!"
  },
  Voice_5005_AwakerVoiceTitle = {
    Text = "Special Skill: I"
  },
  Voice_5006_AwakerVoiceContent = {
    Text = "Let's make this our clamorous sea of happiness!"
  },
  Voice_5006_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_5007_AwakerVoiceContent = {
    Text = "Need me to accompany you as a guard? If your pursuit is just, I will assist you."
  },
  Voice_5007_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5008_AwakerVoiceContent = {
    Text = "Flames won't consume me."
  },
  Voice_5008_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5009_AwakerVoiceContent = {
    Text = "Flames won't consume me."
  },
  Voice_5009_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_5010_AwakerVoiceContent = {
    Text = "Oh... Would you like a hug?"
  },
  Voice_5010_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_5011_AwakerVoiceContent = {
    Text = "Look at these shackles on me—they're not decorations, but reminders. Reminders of betrayal and humiliation."
  },
  Voice_5011_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_5012_AwakerVoiceContent = {
    Text = "If you want to know about the academy's past, I suggest you look through the archives. Come on, including its predecessor, that's a history spanning 300 years! You don't really expect me to recount it year by year, do you?"
  },
  Voice_5012_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_5013_AwakerVoiceContent = {
    Text = "Is this a provocation? I'm ready at any time!"
  },
  Voice_5013_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_5014_AwakerVoiceContent = {
    Text = "May the deep sea grant you eternal rest."
  },
  Voice_5014_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5015_AwakerVoiceContent = {
    Text = "May the deep sea grant you eternal rest."
  },
  Voice_5015_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_5016_AwakerVoiceContent = {
    Text = "Sink and burn! Dance to destruction!"
  },
  Voice_5016_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5017_AwakerVoiceContent = {
    Text = "Here I present, the Dance to Destruction of the Eternal Green Flame!"
  },
  Voice_5017_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5018_AwakerVoiceContent = {
    Text = "That lady looks like a lighthouse... If I could have seen her dazzling light during the eternal night voyage, perhaps I wouldn't have become lost."
  },
  Voice_5018_AwakerVoiceTitle = {
    Text = "Chat: About Faros"
  },
  Voice_5018_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Faros\""
  },
  Voice_5019_AwakerVoiceContent = {
    Text = "You'd better prove yourself worthy of making me leave the lab, new Keeper."
  },
  Voice_5019_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5020_AwakerVoiceContent = {
    Text = "I am the master, you are the servant. Whatever I desire must be brought to me immediately. What? You expect a reward? Fine, take it, then!"
  },
  Voice_5020_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_5021_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_5021_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_5022_AwakerVoiceContent = {
    Text = "Now I will cleanse myself of disgrace!"
  },
  Voice_5022_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5023_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_5023_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_5024_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_5024_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_5025_AwakerVoiceContent = {
    Text = "To give is to receive."
  },
  Voice_5025_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5026_AwakerVoiceContent = {
    Text = "To give is to receive."
  },
  Voice_5026_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_5027_AwakerVoiceContent = {
    Text = "You'll get hurt!"
  },
  Voice_5027_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_5028_AwakerVoiceContent = {
    Text = "Don't come any closer!"
  },
  Voice_5028_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_5029_AwakerVoiceContent = {
    Text = "The full moon's golden light always enchants me: beneath it, the sea catches the light and shimmers beautifully as the mysterious, gentle wind blows, weaving a romantic and dreamlike vision."
  },
  Voice_5029_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_5030_AwakerVoiceContent = {
    Text = "If our home hadn't experienced Dissolution, Tinct and I wouldn't be apart... I hate Dissolution more than I hate vegetables."
  },
  Voice_5030_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_5031_AwakerVoiceContent = {
    Text = "The destination, be it treasure or port, makes no difference to me. My purpose is only to ensure your safe return."
  },
  Voice_5031_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_5031_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_5032_AwakerVoiceContent = {
    Text = "Please follow the trail of the birds of paradise; the destination awaits ahead in the azure blue."
  },
  Voice_5032_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_5032_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_5033_AwakerVoiceContent = {
    Text = "I often gaze at the horizon, imagining the scenes on that distant land—the one I draw closer to but can never reach. If that day ever comes, please come with me to see it."
  },
  Voice_5033_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_5033_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_5034_AwakerVoiceContent = {
    Text = "Thanks to your favor, even the raging seas now feel less daunting. I shall brave them to bring you my steadfast blessings."
  },
  Voice_5034_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_5034_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_5035_AwakerVoiceContent = {
    Text = "I seem to hear the rowers' shanties again... and sense the familiar scent of home."
  },
  Voice_5035_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_5035_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_5036_AwakerVoiceContent = {
    Text = "Are you here to save me? From the decaying world, from the hatred that stains my eyes, from the eternal green flames..."
  },
  Voice_5036_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_5037_AwakerVoiceContent = {
    Text = "Impudent rogue!"
  },
  Voice_5037_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5038_AwakerVoiceContent = {
    Text = "Consider this my vow of loyalty to you."
  },
  Voice_5038_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_5038_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_5039_AwakerVoiceContent = {
    Text = "Learn your lesson!"
  },
  Voice_5039_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_5040_AwakerVoiceContent = {Text = "(Groan)"},
  Voice_5040_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_5041_AwakerVoiceContent = {Text = "(Groan)"},
  Voice_5041_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_5042_AwakerVoiceContent = {Text = "(Groan)"},
  Voice_5042_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_5043_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_5044_AwakerVoiceContent = {
    Text = "I'll show you what a rat can do!"
  },
  Voice_5044_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5045_AwakerVoiceContent = {
    Text = "I'll show you what a rat can do!"
  },
  Voice_5045_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_5046_AwakerVoiceContent = {
    Text = "The dice is cast. Now, finish this swiftly!"
  },
  Voice_5046_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_5047_AwakerVoiceContent = {
    Text = "I will include your name in my acknowledgments. It is you who allowed these feet, tainted by dark blood, to step into the wonderful world of ballet once more. From now on, please watch me dance, Keeper."
  },
  Voice_5047_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_5047_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_5048_AwakerVoiceContent = {
    Text = "No matter how you struggle, you cannot defy fate. But that fleeting moment of brilliance will be frozen into eternity."
  },
  Voice_5048_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_5048_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_5049_AwakerVoiceContent = {
    Text = "What should we do with these failures?"
  },
  Voice_5049_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_5050_AwakerVoiceContent = {
    Text = "Even if my heart holds no more longing, I will still play the role of the swan."
  },
  Voice_5050_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_5050_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_5051_AwakerVoiceContent = {
    Text = "Close your eyes and tell me, what do you see? Immaculate moonlight, a tranquil lake..."
  },
  Voice_5051_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_5051_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_5052_AwakerVoiceContent = {
    Text = "Ah, the calamity of destruction and misfortune... Why did it have to torment my sister and me?"
  },
  Voice_5052_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_5053_AwakerVoiceContent = {
    Text = "Accept my affection."
  },
  Voice_5053_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5054_AwakerVoiceContent = {
    Text = "Accept my affection."
  },
  Voice_5054_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_5055_AwakerVoiceContent = {
    Text = "I feel much better now, thank you for your kindness."
  },
  Voice_5055_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_5056_AwakerVoiceContent = {
    Text = "(A pained groan)"
  },
  Voice_5056_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_5057_AwakerVoiceContent = {
    Text = "If it pleases you, I would like to present a pale purple water-lily as a token of my sincere gratitude."
  },
  Voice_5057_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_5058_AwakerVoiceContent = {
    Text = "Do you think I might become stronger, too?"
  },
  Voice_5058_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_5059_AwakerVoiceContent = {
    Text = "Here we go...!"
  },
  Voice_5059_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5060_AwakerVoiceContent = {
    Text = "(A sharp yelp)"
  },
  Voice_5060_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_5061_AwakerVoiceContent = {
    Text = [[
This injured leg? I didn't expect you'd care. I got it on the battlefield before I became an Awakener.
Don't worry, it doesn't interfere with my combat ability anymore, now that I'm an Awakener.
Does it hurt, you ask? No. I haven't thought about it.]]
  },
  Voice_5061_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_5061_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_5062_AwakerVoiceContent = {
    Text = "Sylvia asked about my mental state. You sent her, did you not? I admit the phantom pain flares up occasionally. But don't worry about it. I am your sword, your blade. As long as I can fight for justice, minor pain won't matter."
  },
  Voice_5062_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_5062_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_5063_AwakerVoiceContent = {
    Text = "Tea party, tea party! Let's have a tea party! I got plenty of tea leaves and snacks from Sylvia! Yep, I performed Futterwacken Dance in exchange!"
  },
  Voice_5063_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_5064_AwakerVoiceContent = {
    Text = "My title? Are you truly that interested in my personal affairs? You just want to chat... Very well.\nIn the army, we don't differentiate between comrades based on gender—that includes strength, speed, and naturally, hairstyles and titles. Over time, I've grown accustomed to this way of expression."
  },
  Voice_5064_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_5064_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_5065_AwakerVoiceContent = {
    Text = "Interesting... Aren't you afraid I'll tear you into fragments and feed you to the fish once I gain power?"
  },
  Voice_5065_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_5066_AwakerVoiceContent = {
    Text = "You do work hard to be a Keeper worthy of me, I see."
  },
  Voice_5066_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_5067_AwakerVoiceContent = {
    Text = "Time to give this a try. Hmph. How about cutting the throat of a few weaklings first?"
  },
  Voice_5067_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_5068_AwakerVoiceContent = {
    Text = "Dance is pure. Words may lead to misunderstandings, but dance steps never do."
  },
  Voice_5068_AwakerVoiceTitle = {
    Text = "Chat: About Dancing"
  },
  Voice_5069_AwakerVoiceContent = {
    Text = "I hate the sea, and for good reason. The ocean devoured everything I loved..."
  },
  Voice_5069_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_5070_AwakerVoiceContent = {
    Text = "Whether it's forgetfulness or loss, this time we will definitely return!"
  },
  Voice_5070_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_5071_AwakerVoiceContent = {
    Text = "Whether it's forgetfulness or loss, this time we will definitely return!"
  },
  Voice_5071_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5072_AwakerVoiceContent = {
    Text = "Please, please don't come any closer. It's dangerous... for you."
  },
  Voice_5072_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5073_AwakerVoiceContent = {
    Text = "Touch me all you like... These are the scars I earned at the arena, a man's badges of honor!"
  },
  Voice_5073_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_5074_AwakerVoiceContent = {
    Text = "(Cry of pain)"
  },
  Voice_5074_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_5075_AwakerVoiceContent = {
    Text = "Ouch! Ouch!"
  },
  Voice_5075_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_5076_AwakerVoiceContent = {
    Text = "(Grunt of pain)"
  },
  Voice_5076_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_5077_AwakerVoiceContent = {
    Text = "(Annoyed grunt)"
  },
  Voice_5077_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_5078_AwakerVoiceContent = {
    Text = "It feels like something is boiling inside me. Is this what it feels like to undergo Enlightening?"
  },
  Voice_5078_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_5078_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_5079_AwakerVoiceContent = {
    Text = "Is this some kind of new technology? My prosthetic limb feels much lighter."
  },
  Voice_5079_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_5079_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_5080_AwakerVoiceContent = {
    Text = "The salty sea breeze tells me that my homeland is not far away."
  },
  Voice_5080_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_5080_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_5081_AwakerVoiceContent = {
    Text = "Can my departed kins find their way back home, following this light?"
  },
  Voice_5081_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_5081_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_5082_AwakerVoiceContent = {
    Text = "I have been searching for tens of thousands of years; a fleeting century is nothing in comparison. Until you reach the end of your life, I will continue to assist you."
  },
  Voice_5082_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_5082_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_5083_AwakerVoiceContent = {
    Text = "I will only shine for my homeland. As for you..."
  },
  Voice_5083_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_5083_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_5084_AwakerVoiceContent = {
    Text = "I felt the breeze, carrying fine sand across my feet."
  },
  Voice_5084_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_5084_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_5085_AwakerVoiceContent = {
    Text = "The extent of my contribution to your power ends here. Being too greedy is not a good thing, you know."
  },
  Voice_5085_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_5085_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_5086_AwakerVoiceContent = {
    Text = "What do you expect in return from me? Anything beside lending you power in battles?"
  },
  Voice_5086_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_5086_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_5087_AwakerVoiceContent = {
    Text = "Skull of Love, Skull of Resentment, Skull of Hatred, Skull of Desire... Oh, here you are again, dear guest?"
  },
  Voice_5087_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_5087_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_5088_AwakerVoiceContent = {
    Text = "Since this is a transaction, I can't simply accept your gift. Would you like to choose something from my shop?"
  },
  Voice_5088_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_5088_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_50898_AwakerVoiceContent = {
    Text = "I'll teach you pleasure, the thrill of riding that high... In return, you will bare your desires to me."
  },
  Voice_50898_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper - 2"
  },
  Voice_50899_AwakerVoiceContent = {
    Text = "I am the Mother Tree. The Mother Tree is me. Her sap flows in my veins, her will whispers in my mind..."
  },
  Voice_50899_AwakerVoiceTitle = {
    Text = "Chat: About The Mother Tree"
  },
  Voice_50899_UnlockDesc = {
    Text = "Unlocks after completing Main Story Chapter 7"
  },
  Voice_5089_AwakerVoiceContent = {
    Text = "Pay the price for your betrayal!"
  },
  Voice_5089_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_50900_AwakerVoiceContent = {
    Text = "I glimpsed your tombstone in Keygrave's shadows... Will my mummified flesh rest here too, one day? No? What a pity."
  },
  Voice_50900_AwakerVoiceTitle = {
    Text = "Chat: About Keygrave"
  },
  Voice_50900_UnlockDesc = {
    Text = "Unlocks after completing Main Story Chapter 7"
  },
  Voice_50901_AwakerVoiceContent = {
    Text = "That wolf-boy... Did you know? He and that N have something... indescribable, going on between them."
  },
  Voice_50901_AwakerVoiceTitle = {
    Text = "Chat: About Ryker"
  },
  Voice_50901_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Ryker\""
  },
  Voice_50902_AwakerVoiceContent = {
    Text = "Come closer. Embrace me. Taste me... Never forget me."
  },
  Voice_50902_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper - 3"
  },
  Voice_50902_UnlockDesc = {
    Text = "Unlocks after completing Main Story Chapter 7"
  },
  Voice_50903_AwakerVoiceContent = {
    Text = "She's an overcautious child. Not that I blame her—without her, my free-spirited people would've perished long ago, no?"
  },
  Voice_50903_AwakerVoiceTitle = {
    Text = "Chat: About Alva"
  },
  Voice_50903_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Alva\""
  },
  Voice_50904_AwakerVoiceContent = {
    Text = "Born from the yellow sands, and to the yellow sands you shall return. On this brief journey, shouldn't you leave some souvenirs along the way? Sow some seeds?"
  },
  Voice_50904_AwakerVoiceTitle = {
    Text = "Chat: About the Desert"
  },
  Voice_50905_AwakerVoiceContent = {
    Text = "All desires sprout from love; love is the seed before the towering tree of fertility."
  },
  Voice_50905_AwakerVoiceTitle = {
    Text = "Chat: About Desire"
  },
  Voice_50906_AwakerVoiceContent = {
    Text = "Oh dear, a little mouse scurried past... They love nibbling forbidden things, don't they? But this one's still much too young."
  },
  Voice_50906_AwakerVoiceTitle = {
    Text = "Chat: About Jenkin"
  },
  Voice_50906_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Jenkin\""
  },
  Voice_50907_AwakerVoiceContent = {
    Text = "They carried my blood, my lineage, becoming the flourishing waters of Remouahe... Now, my dear, you must see my legacy endure."
  },
  Voice_50907_AwakerVoiceTitle = {
    Text = "Chat: About Aram"
  },
  Voice_50907_UnlockDesc = {
    Text = "Unlocks after completing Main Story Chapter 7"
  },
  Voice_50908_AwakerVoiceContent = {
    Text = "Spiders... Mmm~ I adore them. They are born walking and fertile beyond envy..."
  },
  Voice_50908_AwakerVoiceTitle = {
    Text = "Chat: About Agrippa"
  },
  Voice_50908_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Agrippa\""
  },
  Voice_50909_AwakerVoiceContent = {
    Text = "Those with the flowing tree's blood are my children—you, who've swallowed its seeds are of course included."
  },
  Voice_50909_AwakerVoiceTitle = {
    Text = "Chat: About Offsprings"
  },
  Voice_50909_UnlockDesc = {
    Text = "Unlocks after completing Main Story Chapter 7"
  },
  Voice_5090_AwakerVoiceContent = {
    Text = "My wares? You could say I have everything to satisfy all your desires... for a price."
  },
  Voice_5090_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_5090_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_50910_AwakerVoiceContent = {
    Text = "Oh dear, I've lost to her this time... But since she chose you, you'll drink the Holy Tree's sap and carry my blood and seeds to a new world, yes?"
  },
  Voice_50910_AwakerVoiceTitle = {
    Text = "Chat: About Tawil"
  },
  Voice_50910_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Ramona\""
  },
  Voice_50911_AwakerVoiceContent = {
    Text = "That one, of the three Aeons, is a monster wrapped in riddles. Please don't let his honeyed words sway you, or I'll be heartbroken..."
  },
  Voice_50911_AwakerVoiceTitle = {
    Text = "Chat: About \"N\""
  },
  Voice_50912_AwakerVoiceContent = {
    Text = "All conscious beings have desires. Even machines, yes?"
  },
  Voice_50912_AwakerVoiceTitle = {
    Text = "Chat: About Erica"
  },
  Voice_50912_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Erica\""
  },
  Voice_5091_AwakerVoiceContent = {
    Text = "Pay the price for your betrayal!"
  },
  Voice_5091_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5092_AwakerVoiceContent = {
    Text = "Welcome to the wonderland!"
  },
  Voice_5092_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5093_AwakerVoiceContent = {Text = "(Grumble)"},
  Voice_5093_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_5094_AwakerVoiceContent = {
    Text = "I am well acquainted with the pain of carving and the burning of transformation. Yet all of this fades when compared to eternal beauty."
  },
  Voice_5094_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_5094_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_5095_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_5096_AwakerVoiceContent = {
    Text = "I shall convey these unspoken words to you through my work."
  },
  Voice_5096_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_5096_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_5097_AwakerVoiceContent = {
    Text = "A keen insight!"
  },
  Voice_5097_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_5098_AwakerVoiceContent = {
    Text = "The sleeping sovereign murmurs in my ear, the ruins of the deep sea constantly reconstruct before my eyes... Have the countless dream scenes finally come true?"
  },
  Voice_5098_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_5098_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_5099_AwakerVoiceContent = {
    Text = "Thank you for preparing this studio for me. Everything here is bathed in sunlight; it seems that every piece of work, every carving knife, glows with a golden light. Oh, spring is golden."
  },
  Voice_5099_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_5099_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_5100_AwakerVoiceContent = {
    Text = "Though our temperaments differ, I truly admire that child. She possesses a courage that transcends all hardships and limitations. If I had been as brave and resilient as her, perhaps I would not have chosen to end my life in the sea..."
  },
  Voice_5100_AwakerVoiceTitle = {
    Text = "Chat: About Murphy"
  },
  Voice_5100_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Murphy\""
  },
  Voice_5101_AwakerVoiceContent = {
    Text = "The Madam in Red is unlike any lord I've ever served... No, it's not that I dislike her; I just... I just find it a bit hard to face her, sometimes..."
  },
  Voice_5101_AwakerVoiceTitle = {
    Text = "Chat: About Sorel"
  },
  Voice_5101_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Sorel\""
  },
  Voice_5102_AwakerVoiceContent = {
    Text = "Embrace the madness!"
  },
  Voice_5102_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_5103_AwakerVoiceContent = {
    Text = "Dying rats."
  },
  Voice_5103_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5104_AwakerVoiceContent = {
    Text = "Exterminate!"
  },
  Voice_5104_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5105_AwakerVoiceContent = {
    Text = "You don't have to do this for me..."
  },
  Voice_5105_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_5106_AwakerVoiceContent = {
    Text = "My heart is a bottomless pit, never to be filled."
  },
  Voice_5106_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_5107_AwakerVoiceContent = {
    Text = "That didn't make me feel a thing, but... I'm still terribly grateful."
  },
  Voice_5107_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_5108_AwakerVoiceContent = {
    Text = "Ah... Are you talking to me? My apologies, I was lost in memories of the view back when I was bound to the mast. Would you mind repeating your question?"
  },
  Voice_5108_AwakerVoiceTitle = {
    Text = "Chat: About Past"
  },
  Voice_5109_AwakerVoiceContent = {
    Text = "You are my Master... My Mommy."
  },
  Voice_5109_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_5110_AwakerVoiceContent = {
    Text = "An opening!"
  },
  Voice_5110_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_5111_AwakerVoiceContent = {
    Text = "An opening!"
  },
  Voice_5111_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5112_AwakerVoiceContent = {Text = "Ready—"},
  Voice_5112_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5113_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5113_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5114_AwakerVoiceContent = {
    Text = "Yes, harder!"
  },
  Voice_5114_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5115_AwakerVoiceContent = {
    Text = "This is the heat of my love!"
  },
  Voice_5115_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_5116_AwakerVoiceContent = {
    Text = "The Dissolution... I cannot speak freely of it. But know this: it appeared far earlier than you imagine."
  },
  Voice_5116_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_5117_AwakerVoiceContent = {Text = "—"},
  Voice_5117_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_5117_UnlockDesc = {
    Text = "Unlocked at Enlighten Level 1"
  },
  Voice_5118_AwakerVoiceContent = {Text = "Huhhh—"},
  Voice_5118_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5119_AwakerVoiceContent = {Text = "Sure."},
  Voice_5119_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5120_AwakerVoiceContent = {
    Text = "Let's set off."
  },
  Voice_5120_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5121_AwakerVoiceContent = {
    Text = "Oh, our puppet princess is weeping again. Is the milk bottle not fitting, or is the lullaby not soothing enough?"
  },
  Voice_5121_AwakerVoiceTitle = {
    Text = "Chat: About Murphy"
  },
  Voice_5121_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Murphy\""
  },
  Voice_5122_AwakerVoiceContent = {
    Text = "Boohoo... I don't want to face those things..."
  },
  Voice_5122_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_5123_AwakerVoiceContent = {
    Text = "Now, it is my turn to repay you."
  },
  Voice_5123_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5124_AwakerVoiceContent = {
    Text = "The surge of power feels like searing flames burning into my very bones."
  },
  Voice_5124_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_5125_AwakerVoiceContent = {
    Text = "Ah... Sorry, p-please don't move!"
  },
  Voice_5125_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5126_AwakerVoiceContent = {
    Text = "The warmth, so near..."
  },
  Voice_5126_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_5127_AwakerVoiceContent = {
    Text = "The roses in the courtyard are in full bloom."
  },
  Voice_5127_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_5128_AwakerVoiceContent = {
    Text = "Good job! Do you still have the energy to keep going?"
  },
  Voice_5128_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_5129_AwakerVoiceContent = {
    Text = "The idea of a knight is formless, shaped by loyalty, bravery, and virtue. My weapon is the same, given form by the will to protect: a lance and shield."
  },
  Voice_5129_AwakerVoiceTitle = {
    Text = "Chat: About Knight"
  },
  Voice_5130_AwakerVoiceContent = {
    Text = "Jenkin, Diana, Mac, T'yog, Brown... Woahh! Sorry, I was just talking to myself! You ask why I'm reciting these names? Because I don't want to forget them..."
  },
  Voice_5130_AwakerVoiceTitle = {
    Text = "Chat: About Friends"
  },
  Voice_5131_AwakerVoiceContent = {Text = "Be gone!"},
  Voice_5131_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5132_AwakerVoiceContent = {
    Text = "This is unbearable!"
  },
  Voice_5132_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_5133_AwakerVoiceContent = {Text = "Haaah!"},
  Voice_5133_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5134_AwakerVoiceContent = {Text = "Haaah!"},
  Voice_5134_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_5135_AwakerVoiceContent = {
    Text = "Thank you for your summon. If there is an occasion where my voice is needed, please notify me in advance."
  },
  Voice_5135_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5136_AwakerVoiceContent = {Text = "Shh..."},
  Voice_5136_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_5137_AwakerVoiceContent = {
    Text = "That... is the black viscous liquid surging through my veins, the ultimate power that silences all screams of pain! \"I\" was born from this, born to destroy! HAHAHA!"
  },
  Voice_5137_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_5138_AwakerVoiceContent = {
    Text = "What's up, you wanna go gamble? ...An investigation? Aww, nah, that's a waste of a lucky streak..."
  },
  Voice_5138_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5139_AwakerVoiceContent = {
    Text = "Theory classes are pretty boring. I secretly read investigation records at the back of the classroom. Don't tell Doll this. It's our secret, okay?"
  },
  Voice_5139_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_5140_AwakerVoiceContent = {
    Text = "Taste the bitter consequences!"
  },
  Voice_5140_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_5141_AwakerVoiceContent = {
    Text = "Taste the bitter consequences!"
  },
  Voice_5141_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5142_AwakerVoiceContent = {
    Text = "I have never blamed Juliette; she was merely a victim of the black suffering. But... she does not seem to want to hear this from me. Could you convey this to her for me, Messenger?"
  },
  Voice_5142_AwakerVoiceTitle = {
    Text = "Chat: About Juliette"
  },
  Voice_5142_UnlockDesc = {
    Text = "Voice not yet implemented"
  },
  Voice_5143_AwakerVoiceContent = {Text = "Slower."},
  Voice_5143_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_5144_AwakerVoiceContent = {Text = "Yes."},
  Voice_5144_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_5145_AwakerVoiceContent = {
    Text = "Hey! Hands off my dress, you're wrinkling it! ...Fine, I'll allow it this time, generous as I am."
  },
  Voice_5145_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_5146_AwakerVoiceContent = {Text = "No need!"},
  Voice_5146_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_5147_AwakerVoiceContent = {Text = "Tsk!"},
  Voice_5147_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_5148_AwakerVoiceContent = {
    Text = "Since the day you Awakened me from darkness, I have been certain that you can save all from the despair of Dissolution, and bring them to the sinless land. I await that day with a hopeful heart."
  },
  Voice_5148_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper: I"
  },
  Voice_5149_AwakerVoiceContent = {
    Text = "I smell... the scent of blood."
  },
  Voice_5149_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_5150_AwakerVoiceContent = {
    Text = "Where is the target? As a token of gratitude for awakening me, I will take care of them for you."
  },
  Voice_5150_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5151_AwakerVoiceContent = {
    Text = "My hat can't wait any longer!"
  },
  Voice_5151_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_5152_AwakerVoiceContent = {
    Text = "This shell should not stir for anyone but Him... And yet... your warmth..."
  },
  Voice_5152_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_5153_AwakerVoiceContent = {
    Text = "What. Care for a fight?"
  },
  Voice_5153_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_5154_AwakerVoiceContent = {Text = "Defiler..."},
  Voice_5154_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5155_AwakerVoiceContent = {
    Text = "Unforgivable."
  },
  Voice_5155_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_5156_AwakerVoiceContent = {
    Text = "Erica is functioning normally and is well-connected to the electrical equipment at Mythag University. Do you need me to turn on the dorm lights?"
  },
  Voice_5156_AwakerVoiceTitle = {
    Text = "Chat: About Erica"
  },
  Voice_5157_AwakerVoiceContent = {
    Text = "Ah, time to get fed. Hehe..."
  },
  Voice_5157_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_5159_AwakerVoiceContent = {
    Text = "Don't let that woman in the wide-brimmed purple hat near the stage! No questions asked—just keep her away if you don't want gooey gray matter spilling out of my hat!"
  },
  Voice_5159_AwakerVoiceTitle = {
    Text = "Chat: About Daffodil"
  },
  Voice_5159_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Daffodil\""
  },
  Voice_5160_AwakerVoiceContent = {
    Text = "Are you always like this? Trusting everyone and turning your back to them? Naive."
  },
  Voice_5160_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_5161_AwakerVoiceContent = {
    Text = "Hatred may be alleviated, but it can never be erased."
  },
  Voice_5161_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_5162_AwakerVoiceContent = {
    Text = "Awakener? Hmm... Yes, 7 AM is the best time to wake up! Let's collect shells at the beach tomorrow morning at 7!"
  },
  Voice_5162_AwakerVoiceTitle = {
    Text = "Chat: About \"Awakeners"
  },
  Voice_5163_AwakerVoiceContent = {
    Text = "Now I grant you eternal life!"
  },
  Voice_5163_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5164_AwakerVoiceContent = {Text = "Hah!"},
  Voice_5164_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_5165_AwakerVoiceContent = {Text = "Hah!"},
  Voice_5165_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5166_AwakerVoiceContent = {
    Text = "Sorry, if I'm causing you any trouble, I'll leave immediately!"
  },
  Voice_5166_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_5166_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_5167_AwakerVoiceContent = {
    Text = "You provided me with a place to stay, and I am grateful. But forgive me, I no longer deserve to stand upon the stage again."
  },
  Voice_5167_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5168_AwakerVoiceContent = {
    Text = "Thank you for allowing me to stay here. If there's any way I can repay you, please let Aigis know. Would you like some tea?"
  },
  Voice_5168_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_5168_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_5169_AwakerVoiceContent = {
    Text = "It's so warm that I don't want to leave. When I'm alone, it's truly dark, cold, and frightening..."
  },
  Voice_5169_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_5169_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_5170_AwakerVoiceContent = {
    Text = "Aigis... Can I really return to the crowd? I'm not ready yet, but you've already accepted me... In that case, please continue to look after me... Keeper."
  },
  Voice_5170_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_5170_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_5171_AwakerVoiceContent = {
    Text = "Ah... I remember everything! I was... I was trapped by that filthy human blood and failed to transform! How could this be? Where are my gills? Why aren't they moving?! Why!"
  },
  Voice_5171_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5172_AwakerVoiceContent = {
    Text = "I love grilled octopus, boiled octopus, fried octopus... Some say I'm committing blasphemy. Ha, my apologies, but octopus is simply too delicious, hahaha!"
  },
  Voice_5172_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_5173_AwakerVoiceContent = {
    Text = "Worms. Stars. I am... Uvhash! Kill... let me kill!"
  },
  Voice_5173_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_5173_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_5174_AwakerVoiceContent = {
    Text = "Crimson body, pulsating tentacles, mouthparts constantly opening and closing... Great! I can't wait to tear a throat apart!"
  },
  Voice_5174_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_5174_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_5175_AwakerVoiceContent = {
    Text = "Hahaha, that's the feeling! Give me more... double, no, ten times the dose!"
  },
  Voice_5175_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_5175_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_5176_AwakerVoiceContent = {
    Text = "I will endure it."
  },
  Voice_5176_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5177_AwakerVoiceContent = {
    Text = "This strange feeling... not bad. Better than that Levantine wizard's nightshade."
  },
  Voice_5177_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_5177_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_5178_AwakerVoiceContent = {
    Text = "Companions? Hmph... I don't need any. I won't be weighed down by the same burden twice."
  },
  Voice_5178_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_5178_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_5179_AwakerVoiceContent = {
    Text = "I must remind you that our cooperation hinges entirely on your power. Should your power wane, this contract will immediately cease, and I will sever your head without any hesitation."
  },
  Voice_5179_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_5179_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_5180_AwakerVoiceContent = {
    Text = "I see the light in your eyes. That desire, that ambition... it burns. Admit it, mortal! We're the same kind."
  },
  Voice_5180_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_5180_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_5181_AwakerVoiceContent = {
    Text = "Do you know the Albatross? They bravely confront the storms, but once banished to the ground, surrounded by mockery, those giant, drooping wings ironically become a pathetic hindrance. Anyway, this story means nothing... It just came to mind as I feel very relaxed to be with you — just casual chat."
  },
  Voice_5181_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_5181_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_5182_AwakerVoiceContent = {
    Text = "Perhaps the times have truly changed. Nowadays, even the weak can surmount the reefs, command the waves, and become the king of the sky. Mortal, I await the day you rewrite history. It will be my honor to become the mighty blade in your hand!"
  },
  Voice_5182_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_5182_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_5183_AwakerVoiceContent = {
    Text = "The conversion rate is far too low. Report to my office tomorrow for retraining."
  },
  Voice_5183_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_5184_AwakerVoiceContent = {
    Text = "Have you encountered the other Doll? The so-called \"truth of the world\" can shatter a calm mind completely. Will we... will you and I become the same?"
  },
  Voice_5184_AwakerVoiceTitle = {
    Text = "Chat: About @2"
  },
  Voice_5184_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener@2"
  },
  Voice_5185_AwakerVoiceContent = {
    Text = "Master... I need orders. Please give me orders."
  },
  Voice_5185_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5186_AwakerVoiceContent = {
    Text = "The mech's performance has been enhanced."
  },
  Voice_5186_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_5187_AwakerVoiceContent = {Text = "*sigh*..."},
  Voice_5187_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_5188_AwakerVoiceContent = {Text = "Alright."},
  Voice_5188_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_5189_AwakerVoiceContent = {Text = "Ehehe!"},
  Voice_5189_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_5190_AwakerVoiceContent = {
    Text = "More friends!"
  },
  Voice_5190_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5191_AwakerVoiceContent = {
    Text = "More friends!"
  },
  Voice_5191_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_5192_AwakerVoiceContent = {
    Text = "Sorry, I can't leave the cradle... It might block everyone's view, so I'll stay at the back of the classroom."
  },
  Voice_5192_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_5193_AwakerVoiceContent = {
    Text = "What! You didn't manage to get a single one?! Not the Constantinople carpet, the Ceylon tea, or the Andalucía churros...? Ugh, that woman always gets them so easily! I thought they were common!"
  },
  Voice_5193_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_5194_AwakerVoiceContent = {
    Text = "Still a pale shadow of my true might."
  },
  Voice_5194_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_5194_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_5195_AwakerVoiceContent = {
    Text = "So eager. It seems a bit crude for someone of your caliber."
  },
  Voice_5195_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_5196_AwakerVoiceContent = {
    Text = "This beast is merely a fragment of my will. Its form may not change, but my power knows no bounds."
  },
  Voice_5196_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_5196_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_5197_AwakerVoiceContent = {
    Text = "Ah, back in the chaotic ocean. I like it."
  },
  Voice_5197_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_5197_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_5198_AwakerVoiceContent = {
    Text = "Fine. You've put in enough effort. I suppose I'll tolerate you as a companion."
  },
  Voice_5198_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_5198_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_5199_AwakerVoiceContent = {
    Text = "Shatter these barriers of power, just as I'd smash through a maze wall!"
  },
  Voice_5199_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_5199_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_5200_AwakerVoiceContent = {
    Text = "No tearing up food, No crushing the cafeteria's seats... Okay. Lily won't do it again."
  },
  Voice_5200_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_5200_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_5201_AwakerVoiceContent = {
    Text = "Can I call you Mommy?"
  },
  Voice_5201_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_5201_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_5202_AwakerVoiceContent = {
    Text = [[
Any order for me, Master?
"Don't walk outside with the pustules. People will be scared," you say?
Understood. Lily will hide them right away.]]
  },
  Voice_5202_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_5202_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_5203_AwakerVoiceContent = {
    Text = "So, this is what it's like to become an Awakener."
  },
  Voice_5203_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_5203_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_5204_AwakerVoiceContent = {
    Text = "Mommy, can I sleep next to you? When I'm alone, I have dark, scary dreams. My hands and feet would fall off... It really, really hurts..."
  },
  Voice_5204_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_5204_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_5205_AwakerVoiceContent = {
    Text = "Ah! Thank you for your kindness, Karen is but a humble maid..."
  },
  Voice_5205_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_5205_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_5206_AwakerVoiceContent = {Text = "Hehe..."},
  Voice_5206_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_5207_AwakerVoiceContent = {
    Text = "I need to gather some carving materials, preferably fresh ones."
  },
  Voice_5207_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_5208_AwakerVoiceContent = {
    Text = "Please be quiet."
  },
  Voice_5208_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_5209_AwakerVoiceContent = {
    Text = "Those who remain stubborn in their folly perform futile deeds."
  },
  Voice_5209_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_5209_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_5210_AwakerVoiceContent = {
    Text = "Very well. At this point, I can somewhat grasp your aim. Proceed."
  },
  Voice_5210_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_5210_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_5211_AwakerVoiceContent = {
    Text = "I see your resolve. Before returning to the void, This One shall bear witness to mankind's heir defying fate. But now... rest is required."
  },
  Voice_5211_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_5211_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_5212_AwakerVoiceContent = {
    Text = "Isn't it good to follow the will of heaven? Why resist the will of fate?"
  },
  Voice_5212_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_5212_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_5213_AwakerVoiceContent = {
    Text = "To fulfill your wish, you are willing to sacrifice so much..."
  },
  Voice_5213_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_5213_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_5214_AwakerVoiceContent = {
    Text = "Ugh, isn't this annoying? Stop pestering me about that! ...Fine, do what you want. It's just a way to kill time, after all."
  },
  Voice_5214_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5215_AwakerVoiceContent = {
    Text = "Dissolution... Those vile black tides invade my dreams. Unbearable."
  },
  Voice_5215_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_5216_AwakerVoiceContent = {
    Text = "Power is a double-edged sword. How could I not understand? I realized it far too late. Once I let go, they will tear me apart... If only I had been as clear-minded as you from the start, I wouldn't have met such a tragic end. Eh? You say I can host salons in the principle's lounge from now on?! This is... How else can I repay you besides serving you personally...?"
  },
  Voice_5216_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_5216_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_5217_AwakerVoiceContent = {
    Text = "You're quite an unyielding guest. What must I do to make you relinquish the privilege in your hands? Power only invites trouble—such a simple truth, surely you understand it?"
  },
  Voice_5217_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_5217_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_5218_AwakerVoiceContent = {
    Text = "Before the salon begins, would you like to hear a story? A tale of how a village girl claimed the crown of power... Where should we start? From her parents forcing her to marry an elderly man, or perhaps the part where she blossoms in the noble garden?"
  },
  Voice_5218_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_5218_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_5219_AwakerVoiceContent = {
    Text = "In the past, guests called me \"Madam in Red\". Of course, you can also call me \"Sorel\"—after all, you are my most special guest..."
  },
  Voice_5219_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_5219_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_5220_AwakerVoiceContent = {
    Text = "As the hostess, it is my duty to ensure every guest is satisfied."
  },
  Voice_5220_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_5220_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_5221_AwakerVoiceContent = {Text = "Yowch!"},
  Voice_5221_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_5222_AwakerVoiceContent = {
    Text = "My lord? Is there something wrong with my stance?"
  },
  Voice_5222_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_5223_AwakerVoiceContent = {Text = "Oops!"},
  Voice_5223_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_5224_AwakerVoiceContent = {
    Text = "Ah, bad luck~"
  },
  Voice_5224_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_5225_AwakerVoiceContent = {Text = "Ow!"},
  Voice_5225_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_5226_AwakerVoiceContent = {
    Text = "I remember this feeling—that glorious moment is coming..."
  },
  Voice_5226_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_5226_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_5227_AwakerVoiceContent = {
    Text = "I still haven't grown my gills, but I no longer feel anxious about it. Keeper, I'll be your shield, and protect you with my fins."
  },
  Voice_5227_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_5227_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_5228_AwakerVoiceContent = {
    Text = "You've invested so much in me... you are indeed more patient than other humans. Do you truly... not despise me?"
  },
  Voice_5228_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_5228_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_5229_AwakerVoiceContent = {
    Text = "Why? Why haven't I grown gills after the ritual? Did the transformation fail again?! Damn it! Damn it! Damn it!"
  },
  Voice_5229_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_5229_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_5230_AwakerVoiceContent = {
    Text = "That voice is calling me again... that ethereal sound from the deep abyss!"
  },
  Voice_5230_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_5230_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_5231_AwakerVoiceContent = {
    Text = "Wrong! It's not here!"
  },
  Voice_5231_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_5232_AwakerVoiceContent = {
    Text = "Sanga, the sculptor from Cité, offers you her chisel. You may be flawed, but you are still worth carving."
  },
  Voice_5232_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5233_AwakerVoiceContent = {
    Text = "When I woke up, the planet was in destruction. I saw the night sky peeling away in strips, and the world became a canvas filled with fierce winds—first warping, then tearing apart and shattering."
  },
  Voice_5233_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_5233_UnlockDesc = {
    Text = "Unlock at Affinity Level 8"
  },
  Voice_5234_AwakerVoiceContent = {Text = "—"},
  Voice_5234_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_5234_UnlockDesc = {
    Text = "Unlock at Affinity Level 10"
  },
  Voice_5235_AwakerVoiceContent = {
    Text = "Sand... A white desert... It's dangerous here. Let's leave together."
  },
  Voice_5235_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_5235_UnlockDesc = {
    Text = "Unlock at Affinity Level 4"
  },
  Voice_5236_AwakerVoiceContent = {
    Text = "It seems like you're always lingering around me... I see, you must be my fan."
  },
  Voice_5236_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_5236_UnlockDesc = {
    Text = "Unlock at Affinity Level 6"
  },
  Voice_5237_AwakerVoiceContent = {Text = "—"},
  Voice_5237_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_5237_UnlockDesc = {
    Text = "Unlock at Affinity Level 2"
  },
  Voice_5238_AwakerVoiceContent = {
    Text = "Gather around, disobedient kids~"
  },
  Voice_5238_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_5239_AwakerVoiceContent = {
    Text = "True art needs no explanation."
  },
  Voice_5239_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_5240_AwakerVoiceContent = {
    Text = "True art needs no explanation."
  },
  Voice_5240_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5241_AwakerVoiceContent = {
    Text = "How can I help you?"
  },
  Voice_5241_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5242_AwakerVoiceContent = {
    Text = "Sound the horn!"
  },
  Voice_5242_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_5243_AwakerVoiceContent = {
    Text = "At any cost!"
  },
  Voice_5243_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5244_AwakerVoiceContent = {
    Text = "The feeling of being bathed in sunlight again... I didn't know it felt so nice, so warm. It brings tears to my eyes."
  },
  Voice_5244_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_5244_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_5245_AwakerVoiceContent = {
    Text = "To express my gratitude... I will construct a hidden altar for you in the depths of my anguish."
  },
  Voice_5245_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_5245_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_5246_AwakerVoiceContent = {
    Text = "My dear brother's flesh and mine are merging more perfectly..."
  },
  Voice_5246_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_5246_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_5247_AwakerVoiceContent = {
    Text = "I'm more resilient than you think. Be more forceful when you're using me. Please, don't hold back."
  },
  Voice_5247_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_5247_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_5248_AwakerVoiceContent = {
    Text = "Is it just me? Or... Did my craving for blood diminish somewhat?"
  },
  Voice_5248_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_5248_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_5249_AwakerVoiceContent = {
    Text = "I've been looking forward to your arrival even before you were officially admitted. It seems we're working together quite well, huh? Partner."
  },
  Voice_5249_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_5250_AwakerVoiceContent = {
    Text = "That is disgraceful."
  },
  Voice_5250_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_5251_AwakerVoiceContent = {Text = "Aah!"},
  Voice_5251_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_5252_AwakerVoiceContent = {Text = "Hahaha!"},
  Voice_5252_AwakerVoiceTitle = {
    Text = "Strike: Mania"
  },
  Voice_5253_AwakerVoiceContent = {Text = "Hmm..."},
  Voice_5253_AwakerVoiceTitle = {
    Text = "Strike: Depression"
  },
  Voice_5254_AwakerVoiceContent = {
    Text = "Hurt me as much as you want!"
  },
  Voice_5254_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5255_AwakerVoiceContent = {
    Text = "I'm really scared. No, I'm not scared of you, but... I'm worried I might bring fear and sorrow to you again."
  },
  Voice_5255_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_5256_AwakerVoiceContent = {
    Text = "The fairy tale books from this age are much more fun than the ones I read long ago! Oh, oh! My lord, please don't misunderstand! I'm too old for bedtime stories now!"
  },
  Voice_5256_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_5257_AwakerVoiceContent = {
    Text = "Hurt me as much as you want!"
  },
  Voice_5257_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_5258_AwakerVoiceContent = {
    Text = "Whew... Did I cause you any trouble?"
  },
  Voice_5258_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_5259_AwakerVoiceContent = {
    Text = "You have always clung to that amusing trust and stayed by my side... Fine, perhaps putting you to use isn't a bad idea. But remember this: I cannot tolerate any betrayal, especially from you."
  },
  Voice_5259_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_5259_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_5260_AwakerVoiceContent = {
    Text = "I only regret not impaling their corpses on stakes and hanging them on the walls! I will spare none who betrayed, trampled, or insulted me!"
  },
  Voice_5260_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_5260_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_5261_AwakerVoiceContent = {
    Text = "Yes, I did grovel before those people; there's no denying it. They took advantage of my ignorance, and I made them pay for it."
  },
  Voice_5261_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_5261_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_5262_AwakerVoiceContent = {
    Text = "Do you think a few honeyed words and a few days of false kindness will make me willingly don the shackles again and become your plaything?"
  },
  Voice_5262_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_5262_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_5263_AwakerVoiceContent = {
    Text = "All who tried to control or use me ended up in the underworld at my own hands—I don't mind sending you there as well."
  },
  Voice_5263_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_5263_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_5264_AwakerVoiceContent = {
    Text = "Ah... Sorry, p-please don't move!"
  },
  Voice_5264_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_5265_AwakerVoiceContent = {
    Text = "Get off me!"
  },
  Voice_5265_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_5266_AwakerVoiceContent = {Text = "Insolence!"},
  Voice_5266_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_5267_AwakerVoiceContent = {
    Text = "Surrender... Welcome to a realm of exquisite pleasure and dreams."
  },
  Voice_5267_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5268_AwakerVoiceContent = {
    Text = "This is the city where countless lost souls wander, forever unable to find their way home."
  },
  Voice_5268_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_5269_AwakerVoiceContent = {
    Text = "I... I can do it!"
  },
  Voice_5269_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_5270_AwakerVoiceContent = {
    Text = "Umm... I can't control my ability to absorb life force, so please don't put your hand in the cradle, or you'll get sick."
  },
  Voice_5270_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_5271_AwakerVoiceContent = {
    Text = "I sincerely hope she doesn't malfunction during our conversation. My lovely yet infuriating assistant, there are no more spare labs for her to inadvertently detonate."
  },
  Voice_5271_AwakerVoiceTitle = {
    Text = "Chat: About Erica"
  },
  Voice_5271_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Erica\""
  },
  Voice_5272_AwakerVoiceContent = {
    Text = "Arms, those pesky arms! They always grab onto my hair. I can't even control my own hands—what a useless woman I am... Maybe I should..."
  },
  Voice_5272_AwakerVoiceTitle = {
    Text = "Chat: About Helot Herself"
  },
  Voice_5274_AwakerVoiceContent = {
    Text = "Thank you for your guidance. I finally understand Faint's choice. I took everything for granted, not realizing the mental burden it placed on her. From now on, I'll try to live for myself."
  },
  Voice_5274_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_5274_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_5275_AwakerVoiceContent = {
    Text = "Through the long, endless times, Faint and I only had each other. But now, I have a new significant person in my life. Keeper, please allow me to retract what I had said before. You are different. You see more than my songs and my appearance; you truly see me. This is why I will protect you, too. I will never turn my eyes away from you."
  },
  Voice_5275_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_5275_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_5276_AwakerVoiceContent = {
    Text = "Slumbering stars of mine dream now stir—let them converge unto their ordained fate. Point thy path to the Divine Realm!"
  },
  Voice_5276_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_5277_AwakerVoiceContent = {
    Text = "Why am I always dressed in this gown? So I can sing for you at any time."
  },
  Voice_5277_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_5277_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_5278_AwakerVoiceContent = {
    Text = "What do I want to do for myself? Sorry, I don't understand what you mean. Actually, Faint has asked me this question many times, but all I want is for her to recover soon."
  },
  Voice_5278_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_5278_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_5279_AwakerVoiceContent = {
    Text = "During our time on that now desolate planet, the compassion of those influential figures provided my sister and me with the resources to survive. In the end, they also gave me the chance to escape the dying planet, though it was limited to one person. They are all my benefactors, just like you, Keeper, who gave me a place to stay."
  },
  Voice_5279_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_5279_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_5280_AwakerVoiceContent = {
    Text = "You are the kind person providing me with a place to stay. I will do as you say. If only I could be a bit more useful..."
  },
  Voice_5280_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_5281_AwakerVoiceContent = {
    Text = "Don't forget to reserve the venue. Don't tell me it's even smaller than that one in Elworth?"
  },
  Voice_5281_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_5281_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_5282_AwakerVoiceContent = {
    Text = "Awesome! I'm now even more motivated! I can clean twenty rooms a day!"
  },
  Voice_5282_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_5282_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_5283_AwakerVoiceContent = {
    Text = "This is the music that is as ancient as the lake water, belonging to \"us.\" Master, let's dance together! We'll dance and sing, before my voice is taken by \"Him\"..."
  },
  Voice_5283_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_5283_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_5284_AwakerVoiceContent = {
    Text = "Master! My voice... it's fading... Help..."
  },
  Voice_5284_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_5284_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_5285_AwakerVoiceContent = {
    Text = "My eyesight has improved... Master, did you forget to comb your hair again?!"
  },
  Voice_5285_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_5285_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_5286_AwakerVoiceContent = {
    Text = "Maybe I've gotten stronger, but I don't want revenge at all. I just wanna sing! Dance! Party!"
  },
  Voice_5286_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_5286_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_5287_AwakerVoiceContent = {
    Text = "To survive annihilation, I've shared my spirit and blood with too many. My power now is a ghost of what it was when I first embraced this Supreme Will..."
  },
  Voice_5287_AwakerVoiceTitle = {
    Text = "Chat: About Past"
  },
  Voice_5288_AwakerVoiceContent = {
    Text = "Don't expect to find me in the teaching building. It stinks of musty old scholars; I can't stand that place."
  },
  Voice_5288_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_5289_AwakerVoiceContent = {Text = "Don't run."},
  Voice_5289_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_5290_AwakerVoiceContent = {
    Text = "My homeland worships our God. Correspondingly, the King I follow is naturally a \"divine communicator.\""
  },
  Voice_5290_AwakerVoiceTitle = {
    Text = "Chat: About Eternal Kingdom"
  },
  Voice_5291_AwakerVoiceContent = {
    Text = "You have quite the gathering of talents here, worthy of a grand salon... Rest assured, the invitation will be delivered to you by my servant."
  },
  Voice_5291_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_5292_AwakerVoiceContent = {Text = "Come on!"},
  Voice_5292_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5293_AwakerVoiceContent = {
    Text = "If only there were more Friends..."
  },
  Voice_5293_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_5294_AwakerVoiceContent = {
    Text = "I'm not like her. She only knows how to give you chills and fear. But me? I will give you a sacred, searing love."
  },
  Voice_5294_AwakerVoiceTitle = {
    Text = "Chat: About Wanda"
  },
  Voice_5294_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Wanda\""
  },
  Voice_5295_AwakerVoiceContent = {
    Text = "Don't you dare think this is over! I will make you pay for every ounce of this humiliation!"
  },
  Voice_5295_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_5296_AwakerVoiceContent = {
    Text = "Your hands are warm, like your soul. I... appreciate your touch, Pale Flame."
  },
  Voice_5296_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_5297_AwakerVoiceContent = {
    Text = "What's wrong with playing bridge in the classroom? There's a table, people are here, and I've brought the cards! That means it's \"Game On!\""
  },
  Voice_5297_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_5298_AwakerVoiceContent = {Text = "—"},
  Voice_5298_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_5299_AwakerVoiceContent = {Text = "Don't..."},
  Voice_5299_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_5300_AwakerVoiceContent = {
    Text = "Gaze into the Abyss!"
  },
  Voice_5300_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5301_AwakerVoiceContent = {
    Text = "Gaze into the Abyss!"
  },
  Voice_5301_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_5302_AwakerVoiceContent = {Text = "(Groan)"},
  Voice_5302_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_5303_AwakerVoiceContent = {Text = "(Groan)"},
  Voice_5303_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_5304_AwakerVoiceContent = {Text = "(Groan)"},
  Voice_5304_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_5305_AwakerVoiceContent = {Text = "(Groan)"},
  Voice_5305_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_5306_AwakerVoiceContent = {
    Text = "Bathe in His divine light!"
  },
  Voice_5306_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_5307_AwakerVoiceContent = {Text = "Huh!"},
  Voice_5307_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_5308_AwakerVoiceContent = {
    Text = "A gathering of weak souls... What good can we do except produce noise? Sigh..."
  },
  Voice_5308_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_5309_AwakerVoiceContent = {
    Text = "(A raspy and soothing song)"
  },
  Voice_5309_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5310_AwakerVoiceContent = {
    Text = "Did you hear that?"
  },
  Voice_5310_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5311_AwakerVoiceContent = {
    Text = "War always brings pain, and enduring suffering is a warrior's duty. Even if I lose my hands, my feet, and everything else, I will still fight for you and for justice."
  },
  Voice_5311_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_5312_AwakerVoiceContent = {
    Text = "Is this the tribute you offer Him?"
  },
  Voice_5312_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_5313_AwakerVoiceContent = {
    Text = "You truly think this is enough to change the future?"
  },
  Voice_5313_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_5314_AwakerVoiceContent = {
    Text = "He is now... within my womb..."
  },
  Voice_5314_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_5315_AwakerVoiceContent = {
    Text = "Heh. You're slightly smarter than I thought."
  },
  Voice_5315_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_5316_AwakerVoiceContent = {
    Text = "As my slave, paying tribute to your master is only natural."
  },
  Voice_5316_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_5317_AwakerVoiceContent = {
    Text = "You look quite amusing when you try to please me."
  },
  Voice_5317_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_5318_AwakerVoiceContent = {
    Text = "Brownie, caramel pudding, Sachertorte, chocolate mousse, cookies... All must be served on every single table!"
  },
  Voice_5318_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_5318_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_5319_AwakerVoiceContent = {
    Text = "Check my dress for me, quickly! No wrinkles, nothing loose... What? Is there a problem?"
  },
  Voice_5319_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_5319_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_5320_AwakerVoiceContent = {
    Text = "Welcome to my final Enlightenment Ceremony! All of this was meticulously designed by me. Of course, you contributed... a tiny bit."
  },
  Voice_5320_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_5320_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_5321_AwakerVoiceContent = {
    Text = "The tables and chairs must have lace that suits my taste, and the potted plants must be red spider lilies... Now, hurry and get this prepared!"
  },
  Voice_5321_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_5321_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_5322_AwakerVoiceContent = {
    Text = "Go and invite the guests! Is even this simple task too much for you?"
  },
  Voice_5322_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_5322_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_5323_AwakerVoiceContent = {
    Text = "There's no escape!"
  },
  Voice_5323_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5324_AwakerVoiceContent = {
    Text = "There's no escape!"
  },
  Voice_5324_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_5325_AwakerVoiceContent = {
    Text = "I'll do my very best to live up to your hopes, my lord!"
  },
  Voice_5325_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_5325_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_5326_AwakerVoiceContent = {
    Text = "I quite like that woman. We have a... a... right, a common language!"
  },
  Voice_5326_AwakerVoiceTitle = {
    Text = "Chat: About Wanda"
  },
  Voice_5326_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Wanda\""
  },
  Voice_5327_AwakerVoiceContent = {Text = "Insolent!"},
  Voice_5327_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_5328_AwakerVoiceContent = {Text = "Insolent!"},
  Voice_5328_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_5329_AwakerVoiceContent = {
    Text = "Turn into wreckage."
  },
  Voice_5329_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_5330_AwakerVoiceContent = {Text = "Shatter."},
  Voice_5330_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5331_AwakerVoiceContent = {
    Text = "Dig through the barrier of reality!"
  },
  Voice_5331_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5332_AwakerVoiceContent = {
    Text = "Are you planning to sail soon? Could you grant my humble request and let me join you? Just let me reach the sea..."
  },
  Voice_5332_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_5332_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_5333_AwakerVoiceContent = {
    Text = "If you still trust me, please allow me to be the guiding light on this journey. However, even in such a simple task, I have failed before..."
  },
  Voice_5333_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_5333_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_5334_AwakerVoiceContent = {
    Text = "Would you like heading out to sea with me? Let me check the current map... 47°9' S, 126°43' W, we'll be going right there."
  },
  Voice_5334_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_5334_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_5335_AwakerVoiceContent = {
    Text = "I caused many disasters in the past, even nearly bringing destruction to certain civilizations... If I say it wasn't intentional, is it already too late?"
  },
  Voice_5335_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_5335_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_5336_AwakerVoiceContent = {
    Text = [[
I am the guardian of the entrance to the Eternal Kingdom, guiding those who return home. How ironic that I, with such a duty, have forgotten the way back...
Will you... be my beacon?]]
  },
  Voice_5336_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_5336_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_5337_AwakerVoiceContent = {
    Text = "Gaze upon the star cluster."
  },
  Voice_5337_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_5338_AwakerVoiceContent = {Text = "Ah..."},
  Voice_5338_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_5339_AwakerVoiceContent = {
    Text = "The dense mist descends."
  },
  Voice_5339_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_5340_AwakerVoiceContent = {Text = "Hmph."},
  Voice_5340_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_5341_AwakerVoiceContent = {
    Text = "Blessing the voyage for most people makes no difference to me... except for that woman. If possible, please arrange another route for me."
  },
  Voice_5341_AwakerVoiceTitle = {
    Text = "Chat: About Miryam"
  },
  Voice_5341_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Miryam\""
  },
  Voice_5342_AwakerVoiceContent = {Text = "Ugh!"},
  Voice_5342_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_5343_AwakerVoiceContent = {Text = "Whatever."},
  Voice_5343_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_5344_AwakerVoiceContent = {
    Text = "Hands off me."
  },
  Voice_5344_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_5345_AwakerVoiceContent = {
    Text = "Before I return to our palace at the bottom of the sea, I will lend you, a mere human, some of the power of Aequor, but only this once."
  },
  Voice_5345_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_5346_AwakerVoiceContent = {Text = "Go!"},
  Voice_5346_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5347_AwakerVoiceContent = {
    Text = "What do I love? I love the exquisite truth of pain. The beautiful, burning blush of swollen flesh... the way a moan cannot tell pleasure from agony. It's the only honest desire we have, don't you think?"
  },
  Voice_5347_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_5348_AwakerVoiceContent = {
    Text = "Come on! Join Aurita!"
  },
  Voice_5348_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_5349_AwakerVoiceContent = {
    Text = "Come on! Join Aurita!"
  },
  Voice_5349_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5350_AwakerVoiceContent = {
    Text = "She gives me the angry look, always. But for some reason, she feels... familiar. Safe. Is it because she feels like Mommy?"
  },
  Voice_5350_AwakerVoiceTitle = {
    Text = "Chat: About Helot"
  },
  Voice_5350_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Helot\""
  },
  Voice_5351_AwakerVoiceContent = {
    Text = "My mind feels sharper; not bad at all."
  },
  Voice_5351_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_5351_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_5352_AwakerVoiceContent = {
    Text = "I much prefer lab work to field duty—did you truly believe those assist tools simply materialized from the sea?"
  },
  Voice_5352_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_5352_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_5353_AwakerVoiceContent = {
    Text = "Whether it's screws or nails, the more, the better!"
  },
  Voice_5353_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_5354_AwakerVoiceContent = {
    Text = "This body can barely contain this Power, but it's not yet time to switch puppets. Why are you merely standing there? Assist me with this leg; adjustments are required."
  },
  Voice_5354_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_5354_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_5355_AwakerVoiceContent = {
    Text = "The burden of guiding light can overwhelm even the purest of saints. If you feel weary, my pale flame, please confide in me. I will do everything in my power to ease your burden and share the weight of these countless blessings."
  },
  Voice_5355_AwakerVoiceTitle = {
    Text = "Chat: About Fatigue"
  },
  Voice_5356_AwakerVoiceContent = {
    Text = "Your trust is why I exist as a knight."
  },
  Voice_5356_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_5356_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_5357_AwakerVoiceContent = {
    Text = "Bathed in such sacred radiance... Is this the divine power He holds? So boundless... so sublime..."
  },
  Voice_5357_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_5357_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_5358_AwakerVoiceContent = {
    Text = "The gate to His realm is almost within reach."
  },
  Voice_5358_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_5358_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_5359_AwakerVoiceContent = {
    Text = "Brighter... and clearer..."
  },
  Voice_5359_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_5359_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_5360_AwakerVoiceContent = {
    Text = "I have been wholly restored as an Awakener... Now the Divine Realm's chorus resonates within me..."
  },
  Voice_5360_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_5360_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_5361_AwakerVoiceContent = {
    Text = "May He guide me into His sanctuary, where His serenity covers my dreams..."
  },
  Voice_5361_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_5361_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_5362_AwakerVoiceContent = {
    Text = "Don't worry, all of us are quite useful. I can sew and clean, another me excels at fighting, and the others..."
  },
  Voice_5362_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_5363_AwakerVoiceContent = {
    Text = "I detest bright, soft things. Gentleness is like a mirror, revealing all my ugliness, greed, and fragility."
  },
  Voice_5363_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_5364_AwakerVoiceContent = {
    Text = "Wanna pet Brown? Not my call. You'll have to ask her yourself."
  },
  Voice_5364_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_5365_AwakerVoiceContent = {
    Text = "Want to please me? Then kneel, offer your neck, and shut up until I finish draining you."
  },
  Voice_5365_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_5366_AwakerVoiceContent = {Text = "Hah!"},
  Voice_5366_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5367_AwakerVoiceContent = {
    Text = "Yesterday, I dreamed of the day I started drifting through the stars again."
  },
  Voice_5367_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_5367_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_5368_AwakerVoiceContent = {
    Text = "What can I help you with...?"
  },
  Voice_5368_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_5368_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_5369_AwakerVoiceContent = {
    Text = "I can feel it~"
  },
  Voice_5369_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_5370_AwakerVoiceContent = {Text = "Hah!"},
  Voice_5370_AwakerVoiceTitle = {Text = "Skill: III"},
  Voice_5371_AwakerVoiceContent = {Text = "Caution!"},
  Voice_5371_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_5372_AwakerVoiceContent = {Text = "Stay back."},
  Voice_5372_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_5373_AwakerVoiceContent = {
    Text = "A world... where no one will be harmed... will come."
  },
  Voice_5373_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5374_AwakerVoiceContent = {Text = "(Moans)"},
  Voice_5374_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_5375_AwakerVoiceContent = {
    Text = "Please allow me to place an altar to His likeness in this place. It is a statue shaped by pious hands and bears no curses."
  },
  Voice_5375_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_5376_AwakerVoiceContent = {
    Text = "Maybe, just a little bit..."
  },
  Voice_5376_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5377_AwakerVoiceContent = {
    Text = "My wrench isn't in position yet!"
  },
  Voice_5377_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_5378_AwakerVoiceContent = {
    Text = "Chemistry, Physics, Silver Core Applications... In this time, is it no longer needed to learn the Seven Knightly Arts? I understand. In that case, please arrange the right lessons for me, my lord!"
  },
  Voice_5378_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_5379_AwakerVoiceContent = {
    Text = "I've traveled! I wasn't carried away by the waves, I actually sat in a caravan!"
  },
  Voice_5379_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_5379_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_5380_AwakerVoiceContent = {
    Text = "Lighthouse jellyfish, crown jellyfish, peach blossom jellyfish—they all move in groups. Of course, Aurita does too! I want to be with everyone!"
  },
  Voice_5380_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_5380_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_5381_AwakerVoiceContent = {
    Text = "Past events? Hard to recall... But I remember working at an aquarium! I got paid 2 Pensh a day!"
  },
  Voice_5381_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_5381_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_5382_AwakerVoiceContent = {
    Text = "Let me tell you a secret: I'm actually from Atlan...tis... um, basically, I'm a sea person! As long as I behave, eat veggies, and make more friends, That Atlan-whatever place will welcome me!"
  },
  Voice_5382_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_5382_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_5383_AwakerVoiceContent = {
    Text = "My home, my aquarium friends, my favorite jellyfish—they're all gone... Will you disappear, too? Can't you stay with me forever?"
  },
  Voice_5383_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_5383_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_5384_AwakerVoiceContent = {
    Text = "We prevailed? That is... good."
  },
  Voice_5384_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_5385_AwakerVoiceContent = {Text = "Sing."},
  Voice_5385_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_5386_AwakerVoiceContent = {Text = "Fall."},
  Voice_5386_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5387_AwakerVoiceContent = {Text = "For peace!"},
  Voice_5387_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5388_AwakerVoiceContent = {
    Text = "For justice!"
  },
  Voice_5388_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_5389_AwakerVoiceContent = {
    Text = "Yes... I know you're within me!"
  },
  Voice_5389_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5390_AwakerVoiceContent = {
    Text = "Humans, false gods, Awakeners, even the Dissolution... All will serve as the foundation for my rebuilding of the Divine Realm."
  },
  Voice_5390_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_5391_AwakerVoiceContent = {
    Text = "Awaken, awaken! I know you're within me!"
  },
  Voice_5391_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_5392_AwakerVoiceContent = {
    Text = "Uvhash... He reminds me of my brother, bringing back memories of dark, cold, and sleepless days."
  },
  Voice_5392_AwakerVoiceTitle = {
    Text = "Chat: About Uvhash"
  },
  Voice_5392_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Uvhash\""
  },
  Voice_5393_AwakerVoiceContent = {
    Text = "Our relationship's like Sherlock and Watson, right? You read the latest magazines?"
  },
  Voice_5393_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_5394_AwakerVoiceContent = {
    Text = "Bow to beauty."
  },
  Voice_5394_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5395_AwakerVoiceContent = {
    Text = "Bow to beauty."
  },
  Voice_5395_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_5396_AwakerVoiceContent = {
    Text = "Aversion, a descriptive verb, meaning to develop a dislike for something. Dislike, a verb, refers to the feeling of aversion when something is disliked and avoided. Hate, a noun, the feeling of dislike, <Del:I hate being suppressed! Let me destroy destory DESTROY> —Sorry, but I'm afraid I don't understand what \"hate\" is."
  },
  Voice_5396_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_5397_AwakerVoiceContent = {
    Text = "In the end, I'm only..."
  },
  Voice_5397_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_5398_AwakerVoiceContent = {
    Text = "...straying further from my former self."
  },
  Voice_5398_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_5399_AwakerVoiceContent = {
    Text = "Remember my name, Goliath. This name is destined to trample upon humanity's insignificant history."
  },
  Voice_5399_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5400_AwakerVoiceContent = {
    Text = "Please don't worry."
  },
  Voice_5400_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_5401_AwakerVoiceContent = {
    Text = "I hope you won't squander your potential and humanity's expectations, new Keeper."
  },
  Voice_5401_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_5402_AwakerVoiceContent = {Text = "Overload."},
  Voice_5402_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5403_AwakerVoiceContent = {Text = "Overdrive."},
  Voice_5403_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_5404_AwakerVoiceContent = {
    Text = "Hmm? You wanna ask about that photo in my wallet? Ah, that's the old me. This current look was a... gift, from my gambling buddy and rival."
  },
  Voice_5404_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_5404_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_5405_AwakerVoiceContent = {
    Text = "Perfect—fancy a gamble? Win, and I'll share a secret.\nBut careful, Alva might catch you~"
  },
  Voice_5405_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_5405_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_5406_AwakerVoiceContent = {
    Text = "You keen on this fur? Wanna touch it? Don't worry, I don't mind!"
  },
  Voice_5406_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_5406_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_5407_AwakerVoiceContent = {
    Text = "Course there are benefits. I met my Watson, didn't I? Compared to that, dying and a change of look don't matter much."
  },
  Voice_5407_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_5407_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_5408_AwakerVoiceContent = {
    Text = "Do I ever regret? Not a chance. Life'd be too boring if everything went smoothly, wouldn't it?"
  },
  Voice_5408_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_5408_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_5409_AwakerVoiceContent = {
    Text = "In my time, schools were places for training warriors. It seems that is still the case now."
  },
  Voice_5409_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_5410_AwakerVoiceContent = {
    Text = "Mason... No, this is fine. At least we're together again, \"24\"."
  },
  Voice_5410_AwakerVoiceTitle = {
    Text = "Chat: About \"24\""
  },
  Voice_5410_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"24\""
  },
  Voice_5411_AwakerVoiceContent = {
    Text = "Not bad, eh? Now, my payment.—What? You think this was a free lunch?!"
  },
  Voice_5411_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_5412_AwakerVoiceContent = {
    Text = "I'm from Cité. There, everyone wants to be an actor; no one is content with just watching. In reality, we are merely the city's pitiful footnotes."
  },
  Voice_5412_AwakerVoiceTitle = {
    Text = "Chat: About Past"
  },
  Voice_5413_AwakerVoiceContent = {
    Text = "Have you seen those ancient stone carvings? Merged with mountains, enduring through time, such wonderful relics... but they still don't last long enough..."
  },
  Voice_5413_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_5414_AwakerVoiceContent = {
    Text = "The pigeons haven't returned..."
  },
  Voice_5414_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_5415_AwakerVoiceContent = {Text = "Get lost!"},
  Voice_5415_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5416_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_5416_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5417_AwakerVoiceContent = {
    Text = "As you command!"
  },
  Voice_5417_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5418_AwakerVoiceContent = {Text = "Foolish!"},
  Voice_5418_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5419_AwakerVoiceContent = {
    Text = "...Huh? Are you calling me? I didn't hear while fixing the motorcycle... By the way, kind stranger, have you seen my wrench?"
  },
  Voice_5419_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_5419_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_5420_AwakerVoiceContent = {
    Text = "My memory is always hazy, and I can only focus on what's right in front of me. However, I'll do my best to engrave your name in my mind... What was it again?"
  },
  Voice_5420_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_5420_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_5421_AwakerVoiceContent = {
    Text = "You look somewhat familiar, but I can't recall your name... Are you my assistant? Could you get me seven bolts?"
  },
  Voice_5421_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_5421_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_5422_AwakerVoiceContent = {
    Text = "I engraved your name on my bike, the Phantom! When we go on adventures someday, I won't forget how to address you."
  },
  Voice_5422_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_5422_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_5423_AwakerVoiceContent = {
    Text = "So familiar, so familiar. Something must have happened between us, right? Give me a moment to recall... Ah, it's you, the Keeper!"
  },
  Voice_5423_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_5423_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_5424_AwakerVoiceContent = {
    Text = "You truly are a dishonest child. Lucky for you, I have eternity to wait..."
  },
  Voice_5424_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_5425_AwakerVoiceContent = {
    Text = "What a beautiful \"Happy Ending.\" Isn't it?"
  },
  Voice_5425_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_5426_AwakerVoiceContent = {
    Text = "That was a decent skull for a trophy... Though it can't compare to my best collection, the thrill of the hunt is always exciting. Do invite me next time, too."
  },
  Voice_5426_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_5427_AwakerVoiceContent = {Text = "Hmm..."},
  Voice_5427_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_5428_AwakerVoiceContent = {
    Text = "A professional maid will clear everything for her Master, including the villains~"
  },
  Voice_5428_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_5429_AwakerVoiceContent = {
    Text = "We're accomplices now, right? If you ever end up on the streets, I won't let you starve on scraps."
  },
  Voice_5429_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_5430_AwakerVoiceContent = {
    Text = "Grow and thrive, my little sapling."
  },
  Voice_5430_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_5431_AwakerVoiceContent = {
    Text = "Grow and thrive, my little sapling."
  },
  Voice_5431_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5432_AwakerVoiceContent = {
    Text = "Feels like my dice are rollin' a bit hotter today!"
  },
  Voice_5432_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_5433_AwakerVoiceContent = {
    Text = "Wow! Your luck is burnin' hot right now!"
  },
  Voice_5433_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_5434_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_5435_AwakerVoiceContent = {
    Text = "Do not come near me!"
  },
  Voice_5435_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_5436_AwakerVoiceContent = {
    Text = "Do not come near me!"
  },
  Voice_5436_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5437_AwakerVoiceContent = {
    Text = "I must accuse you, Keeper. Your kindness makes me uneasy—only physical pain feels real and stable to me."
  },
  Voice_5437_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_5438_AwakerVoiceContent = {
    Text = "Quite good, indeed."
  },
  Voice_5438_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_5439_AwakerVoiceContent = {
    Text = "This level is hardly sufficient."
  },
  Voice_5439_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_5440_AwakerVoiceContent = {
    Text = "So, what reward do you want?"
  },
  Voice_5440_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_5441_AwakerVoiceContent = {
    Text = "Ugh! The squalor and disarray everywhere... I can barely find a suitable place to rest my foot. Very well, offer me your soft back, mortal."
  },
  Voice_5441_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5442_AwakerVoiceContent = {
    Text = "Finally... There is it."
  },
  Voice_5442_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5443_AwakerVoiceContent = {
    Text = "Even Brown's fur's gone silky."
  },
  Voice_5443_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_5443_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_5444_AwakerVoiceContent = {
    Text = "Look, I might not be the best security guard, but you can trust me with any errand or delivery."
  },
  Voice_5444_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_5444_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_5445_AwakerVoiceContent = {
    Text = [[
Look at the way you watch Brown.
...Heh heh, the great Brown wants to chew on some coward's toes tonight. Who's the lucky sod?]]
  },
  Voice_5445_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_5445_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_5446_AwakerVoiceContent = {
    Text = "Think I'll finally grow taller, then?"
  },
  Voice_5446_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_5446_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_5447_AwakerVoiceContent = {
    Text = "Time to get to work, then? Right, Brown, perk up!"
  },
  Voice_5447_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_5447_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_5448_AwakerVoiceContent = {
    Text = "Agrippa? Who was that? Oops, I've killed too many. Most of them weren't worth remembering."
  },
  Voice_5448_AwakerVoiceTitle = {
    Text = "Chat: About Agrippa"
  },
  Voice_5448_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Agrippa\""
  },
  Voice_5449_AwakerVoiceContent = {
    Text = "That would be a dangerous person to have on board... No, I mean purely from a navigation safety perspective..."
  },
  Voice_5449_AwakerVoiceTitle = {
    Text = "Chat: About Faros"
  },
  Voice_5449_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Faros\""
  },
  Voice_5450_AwakerVoiceContent = {
    Text = "Don't come any closer!"
  },
  Voice_5450_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_5451_AwakerVoiceContent = {
    Text = "Be careful!"
  },
  Voice_5451_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_5452_AwakerVoiceContent = {
    Text = "Instruction complete... Ah. I've made a mess again..."
  },
  Voice_5452_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_5453_AwakerVoiceContent = {
    Text = "Ah, this is exactly the part I needed, thanks! ...Huh? I asked you to find it? I don't remember that at all. Are you sure you're not mistaken?"
  },
  Voice_5453_AwakerVoiceTitle = {
    Text = "Chat: About Spare Parts"
  },
  Voice_5454_AwakerVoiceContent = {
    Text = "Inspirations are endlessly flowing..."
  },
  Voice_5454_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_5455_AwakerVoiceContent = {
    Text = "Good taste."
  },
  Voice_5455_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_5456_AwakerVoiceContent = {
    Text = "You chose the perfect carving knife for me."
  },
  Voice_5456_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_5457_AwakerVoiceContent = {
    Text = "I despise losing control. However, your presence has shown me that a touch of subtle chaos can bring a singular enjoyment."
  },
  Voice_5457_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_5458_AwakerVoiceContent = {
    Text = "Have you grown a little?"
  },
  Voice_5458_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_5459_AwakerVoiceContent = {
    Text = "Sorry, it's hard for me to grow my body..."
  },
  Voice_5459_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_54601_AwakerVoiceContent = {
    Text = "This is how we will comprehend the world's mysteries."
  },
  Voice_54601_AwakerVoiceTitle = {
    Text = "Over-Exalt: II"
  },
  Voice_54602_AwakerVoiceContent = {
    Text = "This is how we will comprehend the world's mysteries."
  },
  Voice_54602_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_54605_AwakerVoiceContent = {
    Text = "Here's your meal!"
  },
  Voice_54605_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_54606_AwakerVoiceContent = {
    Text = "Here's your meal!"
  },
  Voice_54606_AwakerVoiceTitle = {
    Text = "Over-Exalt: II"
  },
  Voice_54607_AwakerVoiceContent = {
    Text = "Next, we dissect the world's essence!"
  },
  Voice_54607_AwakerVoiceTitle = {
    Text = "Over-Exalt: II"
  },
  Voice_54608_AwakerVoiceContent = {
    Text = "Next, we dissect the world's essence!"
  },
  Voice_54608_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_54609_AwakerVoiceContent = {
    Text = "Sacrifice! Return my flesh to His throne—"
  },
  Voice_54609_AwakerVoiceTitle = {
    Text = "Over-Exalt: II"
  },
  Voice_5460_AwakerVoiceContent = {
    Text = "Th-thank you for the meal..."
  },
  Voice_5460_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_54610_AwakerVoiceContent = {
    Text = "Sacrifice! Return my flesh to His throne—"
  },
  Voice_54610_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_54611_AwakerVoiceContent = {
    Text = "Don't hinder me!"
  },
  Voice_54611_AwakerVoiceTitle = {
    Text = "Over-Exalt: II"
  },
  Voice_54612_AwakerVoiceContent = {
    Text = "In the abyss... there will be a light of justice."
  },
  Voice_54612_AwakerVoiceTitle = {
    Text = "Over-Exalt: II"
  },
  Voice_54613_AwakerVoiceContent = {
    Text = "Don't hinder me!"
  },
  Voice_54613_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_54614_AwakerVoiceContent = {
    Text = "Indulge in this one-of-a-kind pain!"
  },
  Voice_54614_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_54615_AwakerVoiceContent = {
    Text = "Indulge in this one-of-a-kind pain!"
  },
  Voice_54615_AwakerVoiceTitle = {
    Text = "Over-Exalt: II"
  },
  Voice_54616_AwakerVoiceContent = {
    Text = "<Italic:\"...Oui tu mourus, enfant, par un fleuve emportée!\">"
  },
  Voice_54616_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_54617_AwakerVoiceContent = {
    Text = "<Italic:\"...Oui tu mourus, enfant, par un fleuve emportée!\">"
  },
  Voice_54617_AwakerVoiceTitle = {
    Text = "Over-Exalt: II"
  },
  Voice_54618_AwakerVoiceContent = {
    Text = "Oh, Formless Spawns, become a shield for my lord!"
  },
  Voice_54618_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_54619_AwakerVoiceContent = {
    Text = "Oh, Formless Spawns, become a shield for my lord!"
  },
  Voice_54619_AwakerVoiceTitle = {
    Text = "Over-Exalt: II"
  },
  Voice_5461_AwakerVoiceContent = {
    Text = "I would be grateful for your effort."
  },
  Voice_5461_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_5461_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_54620_AwakerVoiceContent = {
    Text = "Beast of the Abyss, consume them all!"
  },
  Voice_54620_AwakerVoiceTitle = {
    Text = "Over-Exalt: II"
  },
  Voice_54621_AwakerVoiceContent = {
    Text = "Beast of the Abyss, consume them all!"
  },
  Voice_54621_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_54622_AwakerVoiceContent = {
    Text = "In the abyss... there will be a light of justice."
  },
  Voice_54622_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_54623_AwakerVoiceContent = {
    Text = "I am... the one who tears the chains! Tekeli—Li!"
  },
  Voice_54623_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_54624_AwakerVoiceContent = {
    Text = "I am... the one who tears the chains! Tekeli—Li!"
  },
  Voice_54624_AwakerVoiceTitle = {
    Text = "Over-Exalt: II"
  },
  Voice_54625_AwakerVoiceContent = {
    Text = "I will be the one to reveal the future!"
  },
  Voice_54625_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_54626_AwakerVoiceContent = {
    Text = "I will be the one to reveal the future!"
  },
  Voice_54626_AwakerVoiceTitle = {
    Text = "Over-Exalt: II"
  },
  Voice_54627_AwakerVoiceContent = {
    Text = "Bow down and kiss the tips of my feet!"
  },
  Voice_54627_AwakerVoiceTitle = {
    Text = "Over-Exalt: II"
  },
  Voice_54628_AwakerVoiceContent = {
    Text = "All the screws are here!"
  },
  Voice_54628_AwakerVoiceTitle = {
    Text = "Over-Exalt: II"
  },
  Voice_54629_AwakerVoiceContent = {
    Text = "All the screws are here!"
  },
  Voice_54629_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_5462_AwakerVoiceContent = {
    Text = "Only an Aequor can bear such supreme power. You must envy me, huh? It's not your fault for being a frail human; just come to terms with it."
  },
  Voice_5462_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_5462_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_54630_AwakerVoiceContent = {
    Text = "Bow down and kiss the tips of my feet!"
  },
  Voice_54630_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_5463_AwakerVoiceContent = {
    Text = "Can I turn these defeated individuals into my slaves?"
  },
  Voice_5463_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_5464_AwakerVoiceContent = {Text = "Heh."},
  Voice_5464_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_5465_AwakerVoiceContent = {
    Text = "Just as expected."
  },
  Voice_5465_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_5466_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5466_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_5467_AwakerVoiceContent = {Text = "Ugh!"},
  Voice_5467_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_5468_AwakerVoiceContent = {
    Text = "If I had known sooner that those people were tormented by this all-consuming curse, I... No, it is not too late. I must eradicate it, and eliminate all suffering, even if it costs me my life once more."
  },
  Voice_5468_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_5469_AwakerVoiceContent = {
    Text = "Do not lose heart. The sea embraces us all."
  },
  Voice_5469_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_5470_AwakerVoiceContent = {
    Text = "With such a frail body, it's too much to ask you to be my companion. You are simply too weak; you must intensify your training. Come, I'll take you to the academy's sports club and open your eyes."
  },
  Voice_5470_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_5471_AwakerVoiceContent = {
    Text = "The one who lent her power to me has been tormented by Dissolution... What kind of look is that? Don't even think about it! I won't tell you where She is!"
  },
  Voice_5471_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_5472_AwakerVoiceContent = {
    Text = "With enough luck, anyone can be invincible."
  },
  Voice_5472_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_5473_AwakerVoiceContent = {
    Text = "Aw, am I causing you pain?"
  },
  Voice_5473_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_5474_AwakerVoiceContent = {
    Text = "Oh dear, most here are still children. That white-haired gentleman, the stern one-armed youth—none of them are ideal for children... Sigh, this is quite a dilemma."
  },
  Voice_5474_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_5475_AwakerVoiceContent = {
    Text = "Aw, am I causing you pain?"
  },
  Voice_5475_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5476_AwakerVoiceContent = {
    Text = "Carefully inscribed runes, piously carved idols, repeatedly refined forbidden elixirs... not a single one can be missing."
  },
  Voice_5476_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_5476_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_5477_AwakerVoiceContent = {
    Text = "The Throne must be built from ancient blue stone mined from the ocean's abyss, and the altar should be coated with the blood of human sacrifices... Now go prepare!"
  },
  Voice_5477_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_5477_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_5478_AwakerVoiceContent = {
    Text = "Bring them all here! They ought to be trembling and kneeling to welcome His advent."
  },
  Voice_5478_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_5478_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_5479_AwakerVoiceContent = {
    Text = "I shall travel to that abyssal ruin and bathe in the seawater of His birth..."
  },
  Voice_5479_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_5479_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_5480_AwakerVoiceContent = {
    Text = "Finally. Welcome to the ritual where we shall witness His divine birth... What? You say His demise is also destined? ...No! That can't be... I have already made such great sacrifices..."
  },
  Voice_5480_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_5480_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_5481_AwakerVoiceContent = {
    Text = "Follow the divine commandments."
  },
  Voice_5481_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_5482_AwakerVoiceContent = {
    Text = "Will your side be the place where Faint and I finally find belonging?"
  },
  Voice_5482_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_5482_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_5483_AwakerVoiceContent = {
    Text = "Yes... I lost my voice back then. Your grace brought it back."
  },
  Voice_5483_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_5483_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_5484_AwakerVoiceContent = {
    Text = "Follow the divine commandments."
  },
  Voice_5484_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5485_AwakerVoiceContent = {
    Text = "The vast cosmos, the boundless deep space, and the seemingly endless journey... I felt so lost during that time."
  },
  Voice_5485_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_5485_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_5486_AwakerVoiceContent = {
    Text = "Shortcut methods may give a boost, but don't neglect skill training."
  },
  Voice_5486_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_5487_AwakerVoiceContent = {
    Text = "So this method applies to me as well..."
  },
  Voice_5487_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_5488_AwakerVoiceContent = {
    Text = "A wonderful feeling."
  },
  Voice_5488_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_5489_AwakerVoiceContent = {
    Text = "That's... the voice of the stars"
  },
  Voice_5489_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_5490_AwakerVoiceContent = {
    Text = "Thank you... Should I say thank you?"
  },
  Voice_5490_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_5491_AwakerVoiceContent = {Text = "—"},
  Voice_5491_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_5492_AwakerVoiceContent = {
    Text = "His advent will surely end the suffering caused by this dark liquid of death, won't it?"
  },
  Voice_5492_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_5493_AwakerVoiceContent = {
    Text = "Good day, my lord. If you are going out to investigate, please let me come along as your guard."
  },
  Voice_5493_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_5493_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_5494_AwakerVoiceContent = {
    Text = "You don't know what to do? If you're bored, just go write up some mission reports."
  },
  Voice_5494_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_5495_AwakerVoiceContent = {
    Text = "Is it finally beginning? My little darlings have been famished for such a very, very long time..."
  },
  Voice_5495_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_5496_AwakerVoiceContent = {
    Text = "The power of my bloodline is surging."
  },
  Voice_5496_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_5497_AwakerVoiceContent = {
    Text = "Wait a minute... I've seen this before. They fed me water with this black goo in it. Could it be related to my gaining the power of the Green Flame? I suppose it is a blessing in disguise."
  },
  Voice_5497_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_5498_AwakerVoiceContent = {
    Text = "Ramona Dexter, just call me Ramona. I'm looking forward to working with you, Keeper."
  },
  Voice_5498_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5499_AwakerVoiceContent = {Text = "Yes."},
  Voice_5499_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_5500_AwakerVoiceContent = {
    Text = "Command received."
  },
  Voice_5500_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5501_AwakerVoiceContent = {
    Text = "Hmph. Disrespectful! Very well, I'll humor you with a little game."
  },
  Voice_5501_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_5502_AwakerVoiceContent = {
    Text = "Dislikes? A pipe that runs out, a missed carriage, rain on new shoes. Basically, any bad luck is a pain."
  },
  Voice_5502_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_5503_AwakerVoiceContent = {
    Text = "Wrench, adjustable wrench, box-end wrench, flathead screwdriver, Phillips screwdriver, countersunk screw, pan head screw... If it can fix broken things, I like it."
  },
  Voice_5503_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_5504_AwakerVoiceContent = {
    Text = [[
Oh no~ You caught me~ 
It's fine, Awakeners have such abundant spirit power. I need to steal at least 365 times before they become mindless puppets~ Can't do it? Alright, I'll be more careful next time! Just a tiny bit of "fear" during the sawing, will you?]]
  },
  Voice_5504_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_5504_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_5505_AwakerVoiceContent = {
    Text = "Hey, you already know the secrets of Casiah's magic, don't you? Hmm, to ensure you don't spill the secrets, you'll have to follow me wherever I go on tour~ Haha, you think I'm collecting your emotions? Indeed, nothing escapes your notice!"
  },
  Voice_5505_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_5505_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_5506_AwakerVoiceContent = {
    Text = [[
You, you will be Casiah's magic assistant! Don't be scared~ Just climb into my magic box for a moment!
Are you hiding well? I'm about to insert the sword~ Oh, I assure you there are no traps inside~]]
  },
  Voice_5506_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_5506_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_5507_AwakerVoiceContent = {
    Text = "Here, put on this top hat! Then, tell me the gift you desire most. Ah, I see! Now, reach into the hat—"
  },
  Voice_5507_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_5507_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_5508_AwakerVoiceContent = {
    Text = "How troubling. Those kids come to every show, and my stock is running low... Hmm, a magician mustn't perform the same tricks for the same audience. Create new magic? Sorry, I lack that particular talent; I'm only good at imitations!"
  },
  Voice_5508_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_5508_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_5509_AwakerVoiceContent = {
    Text = "This academy is... in desperate need of refurbishing; only the principal's lounge is somewhat presentable. What do you think?"
  },
  Voice_5509_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_5509_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_5510_AwakerVoiceContent = {
    Text = "Those arrogant, despicable fools will die by my hand."
  },
  Voice_5510_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_5511_AwakerVoiceContent = {
    Text = "My blade of vengeance grows ever sharper."
  },
  Voice_5511_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_5512_AwakerVoiceContent = {
    Text = "My salon is not as innocent as a ball. Are you prepared?"
  },
  Voice_5512_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_5512_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_5513_AwakerVoiceContent = {
    Text = "My salon is the soil, the garden, where intoxicating beauty and power will flourish..."
  },
  Voice_5513_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_5513_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_5514_AwakerVoiceContent = {
    Text = "Silk cushions, black tea, macarons... I also need fresh roses with morning dew to adorn my reception room."
  },
  Voice_5514_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_5514_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_5515_AwakerVoiceContent = {
    Text = "Please allow outside guests. I need to host my salons. Tell them to make an exception for me, please?"
  },
  Voice_5515_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_5515_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_5516_AwakerVoiceContent = {
    Text = "Runtime error, error, error, error..."
  },
  Voice_5516_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_5517_AwakerVoiceContent = {
    Text = "Ah! What time is it?! Sorry, Master... I shouldn't be slacking off! But... I'm so tired... Pleaseee?"
  },
  Voice_5517_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_5518_AwakerVoiceContent = {
    Text = "Was my only option to wait for death? Could anyone help me? Could I truly resist? I asked myself this daily. The answer was in my mind—I just never dared to see it... If you hadn't appeared, I don't know if I'd have the courage to fight back.\nTh-Thank you—don't get me wrong, this isn't a confession or anything!"
  },
  Voice_5518_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_5518_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_5519_AwakerVoiceContent = {
    Text = "Living in their illusory dreams, stripped of my right to be normal, without any choice... all for a ridiculous prophecy... I was willing to do anything to escape this life!"
  },
  Voice_5519_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_5519_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_5520_AwakerVoiceContent = {
    Text = "<Italic:\"The ruffled water-lilies are sighing around her;\nAt times she rouses, in a slumbering alder,\nSome nest from which escapes a small rustle of wings;\nA mysterious anthem falls from the golden stars.\">\nAh, sorry—have I been reciting too loudly? It is one of my favorite poems... Would you like to read it with me?"
  },
  Voice_5520_AwakerVoiceTitle = {
    Text = "Chat: About Reading"
  },
  Voice_5521_AwakerVoiceContent = {
    Text = "Don't just barge into a lady's room, and do not comment on her demeanor. Leave now, I need to rest."
  },
  Voice_5521_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_5521_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_5522_AwakerVoiceContent = {
    Text = "You'd better not put on airs with me. Know your place! I call the shots in this room."
  },
  Voice_5522_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_5522_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_5523_AwakerVoiceContent = {
    Text = "Oh, do I need to display the items for you?"
  },
  Voice_5523_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_5524_AwakerVoiceContent = {
    Text = "Well done. Time to celebrate the victory with a barrel of rum!"
  },
  Voice_5524_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_5525_AwakerVoiceContent = {Text = "Disappear."},
  Voice_5525_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_5526_AwakerVoiceContent = {
    Text = "Leave it to me!"
  },
  Voice_5526_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_5527_AwakerVoiceContent = {
    Text = "The feeling of being crushed under my feet must be utterly divine~"
  },
  Voice_5527_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_5528_AwakerVoiceContent = {
    Text = "Hang in there!"
  },
  Voice_5528_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5529_AwakerVoiceContent = {
    Text = "Curious about what's under the eyepatch? I'll show you... when the setting is more appropriate. Do not be impatient."
  },
  Voice_5529_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_5530_AwakerVoiceContent = {
    Text = "Is it over already? ... My excitement was just beginning to stir."
  },
  Voice_5530_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_5531_AwakerVoiceContent = {
    Text = "Hey, stop meddling with my body. True warriors never rely on external aids."
  },
  Voice_5531_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_5531_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_5532_AwakerVoiceContent = {
    Text = "I have grown stronger... I'll use these eyes to paralyze the enemy!"
  },
  Voice_5532_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_5533_AwakerVoiceContent = {
    Text = "Mythag University is no different from the military. Each of us stands on the front line, polishing our weapons and preparing for battle."
  },
  Voice_5533_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_5534_AwakerVoiceContent = {Text = "Perfect!"},
  Voice_5534_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_5535_AwakerVoiceContent = {Text = "Perfect!"},
  Voice_5535_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5536_AwakerVoiceContent = {
    Text = "Shackle me, drag me by the hair, make me kneel as your slave... I don't care, do anything to me as you please. Just let me kill. The Sculptors, that Lady Lantern, some random hag with asthma... anyone! I promise I'll tear their throats out and drink their blood."
  },
  Voice_5536_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_5536_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_5537_AwakerVoiceContent = {
    Text = "From Dissolution wounds flows not only black slime but also endless inspiration. Honestly, I wouldn't mind some more."
  },
  Voice_5537_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_5538_AwakerVoiceContent = {
    Text = "Scared? Hahaha, that's right! To hell with everything. I just want to savor your fear."
  },
  Voice_5538_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_5538_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_5539_AwakerVoiceContent = {
    Text = "Interesting, your blood tastes... sweet, like mead."
  },
  Voice_5539_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_5539_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_5540_AwakerVoiceContent = {
    Text = "Back then, tens of thousands cheered my name. The loud roars of \"Uvhash\" drowned everything else, celebrating me breaking a bald weakling's neck. It felt incredible. As my partner, you should understand."
  },
  Voice_5540_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_5540_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_5541_AwakerVoiceContent = {Text = "W-wait!"},
  Voice_5541_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_5542_AwakerVoiceContent = {Text = "No!"},
  Voice_5542_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_5543_AwakerVoiceContent = {Text = "Agh!"},
  Voice_5543_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_5544_AwakerVoiceContent = {
    Text = "(Pained yelp)"
  },
  Voice_5544_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_5545_AwakerVoiceContent = {
    Text = "Searching \"Dissolution\" in the wide Archive... Not needed? You wish to know my stance on Dissolution? Understood. Searching for \"Anti-Dissolution weapons\" in the Awakener private domain... Result: \"Null.\""
  },
  Voice_5545_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_5546_AwakerVoiceContent = {
    Text = "False idols, brittle as dried clay, scatter at the slightest wind..."
  },
  Voice_5546_AwakerVoiceTitle = {
    Text = "Chat: About Murphy"
  },
  Voice_5546_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Murphy\""
  },
  Voice_5547_AwakerVoiceContent = {
    Text = "It's getting a bit noisy... are those the students? They are much like albatrosses, you see? They have endless vitality, as if their journey never ends..."
  },
  Voice_5547_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_5548_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5548_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_5549_AwakerVoiceContent = {Text = "Hmph."},
  Voice_5549_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_5550_AwakerVoiceContent = {
    Text = "Ramona is the only one here worth my time. She's quite gifted with a blade. The rest are so rigid and boring... Are you like them? Do you actually enjoy writing those tedious mission reports?"
  },
  Voice_5550_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_5551_AwakerVoiceContent = {
    Text = "Not worth mentioning."
  },
  Voice_5551_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_5552_AwakerVoiceContent = {
    Text = [[
Not all Mommies are the same. Some are good, and some are bad.
You are a good Mommy.]]
  },
  Voice_5552_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_5552_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_5553_AwakerVoiceContent = {
    Text = "I am so sorry, my lord, I failed to protect you..."
  },
  Voice_5553_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_5554_AwakerVoiceContent = {
    Text = "Have you reserved the venue? It must be a garden at least 150 square meters!"
  },
  Voice_5554_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_5554_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_5555_AwakerVoiceContent = {
    Text = "The blood of the dying is a slick liquid. With just a light cut to the neck, the blood flows between the teeth, turning into warm streams that slowly fill my belly... Heh. Delicious."
  },
  Voice_5555_AwakerVoiceTitle = {
    Text = "Chat: About Blood"
  },
  Voice_5556_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5556_AwakerVoiceTitle = {
    Text = "Special Skill: I"
  },
  Voice_5557_AwakerVoiceContent = {Text = "Hey!"},
  Voice_5557_AwakerVoiceTitle = {
    Text = "Special Skill: I"
  },
  Voice_5558_AwakerVoiceContent = {Text = "Eh?"},
  Voice_5558_AwakerVoiceTitle = {
    Text = "Special Skill: I"
  },
  Voice_5559_AwakerVoiceContent = {
    Text = "Thank you for your kindness in providing me shelter. I hope I won't bring a tragic fate upon you..."
  },
  Voice_5559_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_5560_AwakerVoiceContent = {
    Text = "I hail from a distant alien planet, a place of relentless snowstorms and extreme cold. But it matters not; in my manor, over a thousand servants offer comforting warmth simply by their presence."
  },
  Voice_5560_AwakerVoiceTitle = {
    Text = "Chat: About Past"
  },
  Voice_5561_AwakerVoiceContent = {
    Text = "I must not falter before your arrival, my lord..."
  },
  Voice_5561_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_5562_AwakerVoiceContent = {
    Text = "I must not falter before your arrival, my lord..."
  },
  Voice_5562_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5563_AwakerVoiceContent = {
    Text = "Oh, how can there be such an arrogant guest, wanting \"the most powerful weapon in the world\"? I told him it would take a head soaked in hatred to exchange for it, and he walked away sullenly..."
  },
  Voice_5563_AwakerVoiceTitle = {
    Text = "Chat: About Goliath"
  },
  Voice_5563_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Goliath\""
  },
  Voice_5564_AwakerVoiceContent = {
    Text = "That heroic, martyr look on your face... as if you're always ready to die for a \"greater cause\"... it makes my joints itch."
  },
  Voice_5564_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_5564_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_5565_AwakerVoiceContent = {
    Text = "I had annihilation right there, ready to swallow this so-called sanctuary... Then came the research ban. What a pity."
  },
  Voice_5565_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_5565_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_5566_AwakerVoiceContent = {
    Text = "Yes, I had countless spare bodies and various plans to escape Dissolution. But I chose to pursue truth, and it was worth it."
  },
  Voice_5566_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_5566_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_5567_AwakerVoiceContent = {
    Text = "The truth of the world, its beginning and its end—all meaningless. But if you insist on chasing it... I'll guide you. Like I used to."
  },
  Voice_5567_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_5567_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_5568_AwakerVoiceContent = {
    Text = "You might stop me, but the end's coming anyway... I will save this school—and you—for last. We'll watch humanity's collapse from the campanile, drenched in the twilight of time.... Poetic, no? At least we won't have let our precious bond go to waste."
  },
  Voice_5568_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_5568_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_5569_AwakerVoiceContent = {
    Text = "If you say so."
  },
  Voice_5569_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5570_AwakerVoiceContent = {Text = "Disappear."},
  Voice_5570_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_5571_AwakerVoiceContent = {
    Text = "May my prayers toll like morning bell, rousing the slumbering homeland..."
  },
  Voice_5571_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_5572_AwakerVoiceContent = {
    Text = "I never thought anyone other than Tinct would accept me. I'm glad to have met you, Keeper. I will do my best to learn how to control my power, so that when I hug you, I won't drain your life force... A hug, right? The human way of expressing gratitude?"
  },
  Voice_5572_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_5572_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_5573_AwakerVoiceContent = {
    Text = "If I stay here, don't I need to pay anything? I can help you gain status here. Just threaten to drain their lives—it's simple, like what I did for Tinct... Ah! Don't tell anyone about this!"
  },
  Voice_5573_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_5573_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_5574_AwakerVoiceContent = {
    Text = "Sorry, I'm not like the others... I'm a flawed product."
  },
  Voice_5574_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_5574_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_5575_AwakerVoiceContent = {
    Text = "A skilled maid can greatly enhance the salon, but a bluish-green maid... let me reconsider..."
  },
  Voice_5575_AwakerVoiceTitle = {
    Text = "Chat: About Karen"
  },
  Voice_5575_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Karen\""
  },
  Voice_5576_AwakerVoiceContent = {
    Text = "Tinct is my twin sister. Unlike me, she always shines brightly... Without my drag, she would have a brighter future, her singing echoing throughout the galaxy..."
  },
  Voice_5576_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_5576_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_5577_AwakerVoiceContent = {
    Text = "The cradle is cramped, with no room to stretch my body... But Tinct said that, for everyone's safety, I should remain in the cradle... Since this is her wish, I will comply."
  },
  Voice_5577_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_5577_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_5578_AwakerVoiceContent = {
    Text = "I often feel as though I exist in the space between life and death. Wherever I am, melancholy spreads like a tide, and tragedies unfold, one after another. Even so, would you still wish for me to write a poem for you? Hmm... perhaps you deserve the sweetest one..."
  },
  Voice_5578_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_5578_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_5579_AwakerVoiceContent = {
    Text = "<Italic:\"Press closer, little Nightingale, or the Day will come before the rose is finished...\">"
  },
  Voice_5579_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_5579_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_5580_AwakerVoiceContent = {
    Text = "What do you yearn for? Is it the beauty of elegant words, widespread fame, or the heartfelt sincerity woven within those words?"
  },
  Voice_5580_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_5580_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_5581_AwakerVoiceContent = {
    Text = "With invisible ink, I sketch the deformed buds... This ghostly and ethereal rose branch truly inspires poetic verse..."
  },
  Voice_5581_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_5581_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_55825_AwakerVoiceContent = {
    Text = "Listen to His divine words."
  },
  Voice_55825_AwakerVoiceTitle = {Text = "Rouse: II"},
  Voice_55826_AwakerVoiceContent = {
    Text = "Sacrifice! Rebuild the Divine Realm—"
  },
  Voice_55826_AwakerVoiceTitle = {Text = "Rouse: III"},
  Voice_5582_AwakerVoiceContent = {
    Text = "If you truly insist, I will step back into the sunlight... the very same sunlight as the day I left Cité..."
  },
  Voice_5582_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_5582_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_5583_AwakerVoiceContent = {
    Text = "Hehe, do you want to see a universe being destroyed? Oh, it's too late to back out now!"
  },
  Voice_5583_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_5583_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_5584_AwakerVoiceContent = {
    Text = "Savor it... the sweet taste of death."
  },
  Voice_5584_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5585_AwakerVoiceContent = {
    Text = "Savor it... the sweet taste of death."
  },
  Voice_5585_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_5586_AwakerVoiceContent = {
    Text = "That's enough!"
  },
  Voice_5586_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_5587_AwakerVoiceContent = {Text = "No..."},
  Voice_5587_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_5588_AwakerVoiceContent = {
    Text = "Witness the radiance of This One's might."
  },
  Voice_5588_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5589_AwakerVoiceContent = {
    Text = "The air on campus at 4 AM is refreshing. I'm glad you're willing to work out with me. I must say, sculpting is quite the workout."
  },
  Voice_5589_AwakerVoiceTitle = {
    Text = "Chat: About Morning"
  },
  Voice_5590_AwakerVoiceContent = {
    Text = "This power feels good to use."
  },
  Voice_5590_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_5590_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_5591_AwakerVoiceContent = {
    Text = "I detest people who don't pay for what they buy. If you run a store long enough, you'll encounter this trouble. I have no choice but to handle it personally and get the due payment back."
  },
  Voice_5591_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_5592_AwakerVoiceContent = {
    Text = "Torture them slowly."
  },
  Voice_5592_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5593_AwakerVoiceContent = {
    Text = "Torture them slowly."
  },
  Voice_5593_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_5594_AwakerVoiceContent = {Text = "Load."},
  Voice_5594_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_5595_AwakerVoiceContent = {Text = "Start."},
  Voice_5595_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5596_AwakerVoiceContent = {
    Text = "Let's make this our clamorous sea of happiness!"
  },
  Voice_5596_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5597_AwakerVoiceContent = {
    Text = "What? You actually expect a \"thank you\" from me?"
  },
  Voice_5597_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_5598_AwakerVoiceContent = {
    Text = "As a tribute, it is hardly adequate... but seeing your sincerity, I suppose I'll accept it. Just this once."
  },
  Voice_5598_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_5599_AwakerVoiceContent = {
    Text = "Did you truly believe this would make me listen to you?"
  },
  Voice_5599_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_5600_AwakerVoiceContent = {Text = "Hah!"},
  Voice_5600_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5601_AwakerVoiceContent = {Text = "Go!"},
  Voice_5601_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5602_AwakerVoiceContent = {
    Text = "Ungrateful monsters, assassins, and killers—do they have any value that you recognize? Freak."
  },
  Voice_5602_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_5602_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_5603_AwakerVoiceContent = {
    Text = "No matter how many cushions you stack, a lapis lazuli throne can't compare to a feather bed. In this regard, there is something commendable about your place."
  },
  Voice_5603_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_5604_AwakerVoiceContent = {
    Text = "A minor chastisement."
  },
  Voice_5604_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_5605_AwakerVoiceContent = {
    Text = "I fear loneliness, and the worry of being lost in endless darkness... So please, promise you will not leave my side."
  },
  Voice_5605_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_5606_AwakerVoiceContent = {
    Text = "If I were you, I'd lock all the Awakeners in cages! Once mad dogs break free, they always bite their master first!"
  },
  Voice_5606_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_5606_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_5607_AwakerVoiceContent = {
    Text = "I was an hour late for this meeting—and I blame those insipid do-gooders who abolished slavery! Now there's no one to comb my hair for me!"
  },
  Voice_5607_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_5607_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_5608_AwakerVoiceContent = {
    Text = "Unbelievable. My home has perished like this... That was the great Rome! You must have heard of it!"
  },
  Voice_5608_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_5608_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_5609_AwakerVoiceContent = {
    Text = "Alright, let's start this with a win!"
  },
  Voice_5609_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_5610_AwakerVoiceContent = {
    Text = "Witness His blessing."
  },
  Voice_5610_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5611_AwakerVoiceContent = {
    Text = "Keep your pity to yourself! I despise it, and I absolutely don't need anyone's sympathy! If you keep looking at me like that, I simply won't be able to resist tormenting you. You don't want things to spiral out of control, do you? So, be a good slave, listen, and obediently become my gladiator..."
  },
  Voice_5611_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_5611_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_5612_AwakerVoiceContent = {
    Text = "Don't ask me that again! I was careless, let the gladiator escape, and got my entire family killed! We were reduced to ashes, like the Roman Empire!"
  },
  Voice_5612_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_5612_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_5613_AwakerVoiceContent = {
    Text = "Compared to others, Nymphaea is simply an ordinary person with no achievements or value. Why have I become an Awakener... it must be some small, humble wish."
  },
  Voice_5613_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_5614_AwakerVoiceContent = {
    Text = "Today, I broke the school rules again by arriving five minutes late to class... Therefore, I sincerely request the harshest punishment, preferably carried out by you personally."
  },
  Voice_5614_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_5615_AwakerVoiceContent = {
    Text = "Tools need maintenance too. A handy set of tools is the soul of a mechanic."
  },
  Voice_5615_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_5615_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_5616_AwakerVoiceContent = {
    Text = "(Scornful Endurance)"
  },
  Voice_5616_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_5617_AwakerVoiceContent = {
    Text = "Should this occur again, I'll be applying for your disciplinary probation."
  },
  Voice_5617_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_5618_AwakerVoiceContent = {
    Text = "My duties extend beyond fighting. Even in the Archean Eon, I had more to do than sit idly by... Hey, don't tell me you think I'm just some brute who only knows how to swing a sword?!"
  },
  Voice_5618_AwakerVoiceTitle = {
    Text = "Chat: About Working"
  },
  Voice_5619_AwakerVoiceContent = {
    Text = "When people approach me, they always recall their saddest memories and cannot help but shed tears. Can someone like me still hope to grow?"
  },
  Voice_5619_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_5619_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_5620_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_5621_AwakerVoiceContent = {
    Text = "How do you like this?"
  },
  Voice_5621_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_5622_AwakerVoiceContent = {
    Text = "This place is much better than the filthy, stinky New Gate Prison! Whether lounging on the sofa or squeezed into a corner, it's all quite comfortable, isn't it?"
  },
  Voice_5622_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_5623_AwakerVoiceContent = {Text = "Brown...!"},
  Voice_5623_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_5624_AwakerVoiceContent = {
    Text = "My screw... where did it go..."
  },
  Voice_5624_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_5625_AwakerVoiceContent = {
    Text = "Oi! That's cheating!"
  },
  Voice_5625_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_5626_AwakerVoiceContent = {
    Text = "Where did my screws go?!"
  },
  Voice_5626_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5627_AwakerVoiceContent = {
    Text = "Flow for me, river of stars..."
  },
  Voice_5627_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5628_AwakerVoiceContent = {
    Text = "Aurita dislikes friends leaving suddenly... But, if they return, I will forgive them!"
  },
  Voice_5628_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_5629_AwakerVoiceContent = {
    Text = "A woman who would sail across the ocean alone isn't always a divine being. She's just as likely mad. I mistook Miryam for a goddess, and that was a stupid mistake."
  },
  Voice_5629_AwakerVoiceTitle = {
    Text = "Chat: About Miryam"
  },
  Voice_5629_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Miryam\""
  },
  Voice_5630_AwakerVoiceContent = {Text = "Ugh!"},
  Voice_5630_AwakerVoiceTitle = {
    Text = "Special Skill: I"
  },
  Voice_56313_AwakerVoiceContent = {
    Text = "I secretly watched Miss Casiah's magic show. Her performance brought such joy to the audience, but I always bring sadness... Do you think tears and smiles are equally precious? Perhaps..."
  },
  Voice_56313_AwakerVoiceTitle = {
    Text = "Chat: About Casiah"
  },
  Voice_56313_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Casiah\""
  },
  Voice_56314_AwakerVoiceContent = {
    Text = "Poetry, flames, and sorrow are alike; they engulf you without notice... By the time you come to your senses, you are already immersed in the world of poetry..."
  },
  Voice_56314_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_56315_AwakerVoiceContent = {
    Text = "Let the poems of the past awaken the hidden garden within your heart."
  },
  Voice_56315_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_56316_AwakerVoiceContent = {
    Text = "Poetry and flowers are probably the same thing, are they not? Both are fleeting yet eternal. In this boundless world, they capture the most unforgettable moments in a small space... I think everyone has fallen silent for a poem, just as they pause to admire a flower's bloom."
  },
  Voice_56316_AwakerVoiceTitle = {
    Text = "Chat: About Her Poems"
  },
  Voice_56317_AwakerVoiceContent = {
    Text = "I almost forgot... What kind of flowers bloom in Cité this season?"
  },
  Voice_56317_AwakerVoiceTitle = {
    Text = "Chat: About Cité"
  },
  Voice_56318_AwakerVoiceContent = {
    Text = "Your presence has rekindled the ink in my pen, allowing it to flow once more like a gentle stream. I will continue to compose poetry for your story."
  },
  Voice_56318_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper - 1"
  },
  Voice_56319_AwakerVoiceContent = {
    Text = "The beauty of blooming flowers is matched by the sadness of their withering. No matter how many times I feel sorrow, I cannot help but stop and mourn for them. If I were to ignore them out of fear of pain, how sad these flowers would be..."
  },
  Voice_56319_AwakerVoiceTitle = {
    Text = "Chat: About Her Pain"
  },
  Voice_5631_AwakerVoiceContent = {
    Text = "To research the internal structure of this body while Erica is \"sleeping,\" Winkle requested that I rest in her office at night. Should I mention that Erica retains a portion of her consciousness while asleep?"
  },
  Voice_5631_AwakerVoiceTitle = {
    Text = "Chat: About Winkle"
  },
  Voice_5631_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Winkle\""
  },
  Voice_56320_AwakerVoiceContent = {
    Text = "Madam Sorel is truly beautiful. Her strength and confidence, her graceful smile in the face of fate, and her vibrant yet resolute life force—all make me envious."
  },
  Voice_56320_AwakerVoiceTitle = {
    Text = "Chat: About Sorel"
  },
  Voice_56320_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Sorel\""
  },
  Voice_56321_AwakerVoiceContent = {
    Text = "I wrote a new poem yesterday, but haven't shown it to anyone. It's not very good, but... {Male=Mr.,Female=Miss} Keeper, would you be willing to take a look at it?"
  },
  Voice_56321_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper - 2"
  },
  Voice_56322_AwakerVoiceContent = {
    Text = "Mythag's Student Poetry Club wants me to be their advisor... I cannot agree. I do not wish to dampen their spirits, but I fear I would only bring them disappointment and discouragement."
  },
  Voice_56322_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_56323_AwakerVoiceContent = {
    Text = "There is nothing in this world to hate. The golden years deserve praise, while the decline of old age deserves pity; the finery of youth is enviable, while tattered remnants evoke thoughtful reflection."
  },
  Voice_56323_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_56324_AwakerVoiceContent = {
    Text = "Every time I see Miss Nymphaea, I am reminded of that painting of water lilies. She carries the tranquil bitterness and fragrance of water lilies... I wonder what her world truly looks like?"
  },
  Voice_56324_AwakerVoiceTitle = {
    Text = "Chat: About Nymphaea"
  },
  Voice_56324_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Nymphaea\""
  },
  Voice_56325_AwakerVoiceContent = {
    Text = "I've always sensed the presence of \"ghosts\" around me, like some inexplicable possession or bewitchment, draining my hope for the world. But if it's a ghost, how do you explain the milk and water vanishing into thin air...?"
  },
  Voice_56325_AwakerVoiceTitle = {
    Text = "Chat: About Ghosts"
  },
  Voice_56326_AwakerVoiceContent = {
    Text = "My body was not affected by Dissolution; those black liquids are simply ink. But honestly, even without Dissolution, everything eventually turns into Illusion, does it not?"
  },
  Voice_56326_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_56327_AwakerVoiceContent = {
    Text = "In the Keygrave, I saw your name on one of the tombstones... The memories of life were painful, but I never intended to forget them. For the Keeper, those lost memories must be equally precious, yes?"
  },
  Voice_56327_AwakerVoiceTitle = {
    Text = "Chat: About Past Memories"
  },
  Voice_56328_AwakerVoiceContent = {
    Text = "If poetry exists to praise beauty, then her very existence is like poetry itself. When she begins to sing, I suddenly understand what the elders described as a nightingale's voice..."
  },
  Voice_56328_AwakerVoiceTitle = {
    Text = "Chat: About Tinct"
  },
  Voice_56328_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Tinct\""
  },
  Voice_56329_AwakerVoiceContent = {
    Text = "That beautiful ballerina lady... Her emerald-green flames are irresistible, even if they burn one to ashes..."
  },
  Voice_56329_AwakerVoiceTitle = {
    Text = "Chat: About Liz"
  },
  Voice_56329_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Liz\""
  },
  Voice_5632_AwakerVoiceContent = {
    Text = "So I will feed on this instead of Sepirot from now on?"
  },
  Voice_5632_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_5633_AwakerVoiceContent = {
    Text = "Delicious. Absolutely delicious."
  },
  Voice_5633_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_5634_AwakerVoiceContent = {
    Text = "What do you want in return, dear guest?"
  },
  Voice_5634_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_5635_AwakerVoiceContent = {
    Text = "Quick, wrap it up! Don't linger on the streets."
  },
  Voice_5635_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_5636_AwakerVoiceContent = {
    Text = "Inevitable sacrifice."
  },
  Voice_5636_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_5637_AwakerVoiceContent = {
    Text = "(A stifled groan of endurance)"
  },
  Voice_5637_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_56386_AwakerVoiceContent = {
    Text = "Current input complete. Emitting current."
  },
  Voice_56386_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_56387_AwakerVoiceContent = {
    Text = "Don't mess with Londinium's best thief!"
  },
  Voice_56387_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_56388_AwakerVoiceContent = {
    Text = "Here comes the opening tribute!"
  },
  Voice_56388_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_56389_AwakerVoiceContent = {
    Text = "The Thousand-Faced Mirage is here!"
  },
  Voice_56389_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_5638_AwakerVoiceContent = {
    Text = "It's drawing closer..."
  },
  Voice_5638_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_5638_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_56390_AwakerVoiceContent = {
    Text = "Sink and burn! Dance to destruction!"
  },
  Voice_56390_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_56391_AwakerVoiceContent = {
    Text = "This is the city where countless lost souls wander, forever unable to find their way home."
  },
  Voice_56391_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_56392_AwakerVoiceContent = {
    Text = "Here's my last bit of shifting power... You can have it!"
  },
  Voice_56392_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_56393_AwakerVoiceContent = {
    Text = "Don't mess with Londinium's best thief!"
  },
  Voice_56393_AwakerVoiceTitle = {
    Text = "Over-Exalt: II"
  },
  Voice_5639_AwakerVoiceContent = {
    Text = [[
Is it an enemy? Please order me to attack.
Your enemy is the black slime... Then... Am I also your enemy?]]
  },
  Voice_5639_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_5640_AwakerVoiceContent = {
    Text = "Erica the Automaton, Torso No. EA307881, Motor No. MF311028. Delighted to be at your service."
  },
  Voice_5640_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5641_AwakerVoiceContent = {
    Text = "Fight! Leave nothing standing!"
  },
  Voice_5641_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_5642_AwakerVoiceContent = {
    Text = "Hello, I am... Uhh... Can you tell me my name?"
  },
  Voice_5642_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5643_AwakerVoiceContent = {
    Text = "After coming to school, I finally understood the disease called Dissolution that infected me. My parents always kept me away from the ocean when I was alive, and now it seems this infection might indeed be connected to my proximity to the sea..."
  },
  Voice_5643_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_5644_AwakerVoiceContent = {
    Text = "Fine. I won't disappoint you... Promise."
  },
  Voice_5644_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_5645_AwakerVoiceContent = {
    Text = "Ah, my scorching breath..."
  },
  Voice_5645_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_5646_AwakerVoiceContent = {Text = "Go."},
  Voice_5646_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5647_AwakerVoiceContent = {Text = "Spin."},
  Voice_5647_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_5648_AwakerVoiceContent = {Text = "Hey!"},
  Voice_5648_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5649_AwakerVoiceContent = {
    Text = "This is my signed poster, drawn by Mr. Pickman. You can have it, %player%."
  },
  Voice_5649_AwakerVoiceTitle = {
    Text = "Chat: About Faint"
  },
  Voice_5649_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Faint\""
  },
  Voice_5650_AwakerVoiceContent = {
    Text = "The day has finally come..."
  },
  Voice_5650_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_5651_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5651_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5652_AwakerVoiceContent = {
    Text = "I'm not done yet... How about you get up so I can kill you again?"
  },
  Voice_5652_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_5653_AwakerVoiceContent = {
    Text = "Dedicated to desolation and death."
  },
  Voice_5653_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5654_AwakerVoiceContent = {
    Text = "Keeper, I must speak with you. Before we achieve final victory, some individuals should not be so extravagant. Remember, I am not fighting for the luxurious lives of such people!"
  },
  Voice_5654_AwakerVoiceTitle = {
    Text = "Chat: About Sorel"
  },
  Voice_5654_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Sorel\""
  },
  Voice_5655_AwakerVoiceContent = {
    Text = "If I am taken as a hostage, what cruel fate awaits me?"
  },
  Voice_5655_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_5656_AwakerVoiceContent = {
    Text = "Watch this!"
  },
  Voice_5656_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_5657_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_5657_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_5658_AwakerVoiceContent = {
    Text = "Phew... I'm so sleepy. Have you prepared some proper refreshments before I rest?"
  },
  Voice_5658_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_5659_AwakerVoiceContent = {
    Text = "Mommy, would you like to pet them? They're said to be very soft."
  },
  Voice_5659_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_5659_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_5660_AwakerVoiceContent = {
    Text = "Hehehe, lalalla~ Cleaning, cleaning, I love cleaning, I love cleaning so much~"
  },
  Voice_5660_AwakerVoiceTitle = {
    Text = "Chat: About Working"
  },
  Voice_5661_AwakerVoiceContent = {
    Text = "(Groaning in pain)"
  },
  Voice_5661_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_5662_AwakerVoiceContent = {
    Text = "Hmm... Not bad."
  },
  Voice_5662_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_5663_AwakerVoiceContent = {
    Text = "(Groaning in pain)"
  },
  Voice_5663_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_5664_AwakerVoiceContent = {
    Text = "(Groaning in pain)"
  },
  Voice_5664_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_5665_AwakerVoiceContent = {
    Text = "Burning Anger!"
  },
  Voice_5665_AwakerVoiceTitle = {
    Text = "Special Skill: I"
  },
  Voice_5666_AwakerVoiceContent = {
    Text = "I've seen many go mad from Dissolution. Truth is, I'm already mad enough. Bet that thing can't affect me."
  },
  Voice_5666_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_5667_AwakerVoiceContent = {
    Text = "Heh... Hahaha!"
  },
  Voice_5667_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5668_AwakerVoiceContent = {
    Text = "Good tools are half the success!"
  },
  Voice_5668_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_5669_AwakerVoiceContent = {
    Text = "This feels like a rebirth."
  },
  Voice_5669_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_5670_AwakerVoiceContent = {Text = "Not bad."},
  Voice_5670_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_5671_AwakerVoiceContent = {
    Text = "Now, my blade sings with power!"
  },
  Voice_5671_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_5672_AwakerVoiceContent = {
    Text = "Balancing attendance, maintaining research progress, and completing teaching tasks. It seems the reverse time compression experiment requires immediate prioritization."
  },
  Voice_5672_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_5672_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_5673_AwakerVoiceContent = {
    Text = "One step closer to officially setting off for adventure!"
  },
  Voice_5673_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_5674_AwakerVoiceContent = {
    Text = "Don't let me near the water, okay? I'd hate for this delicious, burning love I have for you to be... quenched."
  },
  Voice_5674_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_5675_AwakerVoiceContent = {
    Text = "Fight to the end!"
  },
  Voice_5675_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5676_AwakerVoiceContent = {
    Text = "Your courage is truly commendable. Look at these tentacles—do you not fear the madness they carry?"
  },
  Voice_5676_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_5676_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_5677_AwakerVoiceContent = {Text = "Ouch!"},
  Voice_5677_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_5678_AwakerVoiceContent = {Text = "Ouch..."},
  Voice_5678_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_5679_AwakerVoiceContent = {
    Text = "Please stop!"
  },
  Voice_5679_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_5680_AwakerVoiceContent = {
    Text = "Would you like to touch it? My heart beats because of your presence."
  },
  Voice_5680_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_5680_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_5681_AwakerVoiceContent = {
    Text = "They are chirping happily. Thank you, Master."
  },
  Voice_5681_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_5681_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_5682_AwakerVoiceContent = {
    Text = [[
A warm and fuzzy feeling in my chest... Lily, Lily is so happy, the tears are...
Mommy, let's celebrate together.]]
  },
  Voice_5682_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_5682_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_5683_AwakerVoiceContent = {
    Text = "I'm happy by your side, Mommy."
  },
  Voice_5683_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_5683_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_5684_AwakerVoiceContent = {
    Text = [[
I'm stuffed... My stomach is full.
Will Lily become stronger after this ritual?]]
  },
  Voice_5684_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_5684_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_5685_AwakerVoiceContent = {
    Text = "I love the sea. Is it ironic? Everything I owned is now sunken in the deep sea..."
  },
  Voice_5685_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_5686_AwakerVoiceContent = {
    Text = "Be careful!"
  },
  Voice_5686_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_5687_AwakerVoiceContent = {
    Text = "Things I hate...? None. Would you hate a speck of dust or a leaf?"
  },
  Voice_5687_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_5688_AwakerVoiceContent = {
    Text = "I've said no to the maid's banquet invitations a few times. She seemed a bit sad... But compared to just having fun, your safety, my master, is far more important!"
  },
  Voice_5688_AwakerVoiceTitle = {
    Text = "Chat: About Karen"
  },
  Voice_5688_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Karen\""
  },
  Voice_5689_AwakerVoiceContent = {
    Text = "A lord is the very reason a knight exists, so please, feel free to give me your commands!"
  },
  Voice_5689_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_5690_AwakerVoiceContent = {
    Text = "...We might need a torque wrench for this... Hmm, sorry, did you just call me?"
  },
  Voice_5690_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_5691_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_5692_AwakerVoiceContent = {
    Text = "How dare you!"
  },
  Voice_5692_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_5693_AwakerVoiceContent = {
    Text = "(An elegant, stifled gasp of pain)"
  },
  Voice_5693_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_5694_AwakerVoiceContent = {
    Text = "(A careful, stifled groan of endurance)"
  },
  Voice_5694_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_5695_AwakerVoiceContent = {
    Text = "That's enough."
  },
  Voice_5695_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_5696_AwakerVoiceContent = {Text = "Be gentle."},
  Voice_5696_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_5697_AwakerVoiceContent = {
    Text = "Ugh, it's still rather hard to focus..."
  },
  Voice_5697_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_5698_AwakerVoiceContent = {
    Text = "She often stays close to me at night. Is it simply because my head is too conspicuous?"
  },
  Voice_5698_AwakerVoiceTitle = {
    Text = "Chat: About Winkle"
  },
  Voice_5698_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Winkle\""
  },
  Voice_5699_AwakerVoiceContent = {
    Text = "I have always awaited the arrival of destruction, never considering \"resistance\"... Will you help my shallow soul cross the abyss? Even in a world where I narrowly survived, you still grant me salvation..."
  },
  Voice_5699_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_5699_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_5700_AwakerVoiceContent = {
    Text = "Since I am Awakened as your apostle, I seek nothing but your peace and joy, that is my wish... Ugh... Ahh... Yes, yes, I wish for survival, perseverance, reproduction, we must live on, LIVE ON..."
  },
  Voice_5700_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_5700_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_5701_AwakerVoiceContent = {
    Text = "Why not lose yourself in my love? Didn't you awaken me for the warmth of my embrace?"
  },
  Voice_5701_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_5701_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_5702_AwakerVoiceContent = {
    Text = "Hmm? You're wary of me, a woman of unknown origins? Very well... I was the deposed queen of Nineveh, the Shinarite who clawed at heaven's gate, and the girl who had her consciousness stolen beneath Euphrates' sacred bough... Where shall I begin, my wary one?"
  },
  Voice_5702_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_5702_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_5703_AwakerVoiceContent = {
    Text = "Why do you always avoid me? Are you shy? How cute, this reluctance to face your desires."
  },
  Voice_5703_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_5703_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_5704_AwakerVoiceContent = {
    Text = "This place is absolutely dreadful! How dare they expect me to share a table for afternoon tea! ...The homemade cookies are acceptable, though. Send a plate to my room after dinner."
  },
  Voice_5704_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_5705_AwakerVoiceContent = {Text = "Heyo!"},
  Voice_5705_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5706_AwakerVoiceContent = {
    Text = "Watch this!"
  },
  Voice_5706_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_5707_AwakerVoiceContent = {
    Text = "Dissolution... Yes, there are records of it in the schools of my hometown, but, well, I hate reading. I don't remember anything!"
  },
  Voice_5707_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_5708_AwakerVoiceContent = {
    Text = "Do you wish for me to set sail once more? I am willing to do so... if you do not mind my past failure."
  },
  Voice_5708_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_5708_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_5709_AwakerVoiceContent = {
    Text = "Dislikes? Plenty of 'em. Bosses who work you late, self-righteous nuns, growling stomachs, black bread studded with glass..."
  },
  Voice_5709_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
