  },
  Voice_5735_AwakerVoiceContent = {Text = "Fuck off!"},
  Voice_5735_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_5736_AwakerVoiceContent = {
    Text = "Things I despise... a disorganized desk, a messy wardrobe, dusty window sills—yes, I am describing your room. By 7 AM tomorrow, I expect it restored to its pre-occupancy state."
