  },
  Voice_5801_AwakerVoiceContent = {
    Text = "Ramona... I mean, I don't like farewells. They are too sad."
  },
  Voice_5801_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_5802_AwakerVoiceContent = {
    Text = "I'm not good at dealing with clerics. They're dull and rigid, and they've given their belts to their beloved \"God\". Such a pity, Mr. Salvador smells so sweet..."
  },
  Voice_5802_AwakerVoiceTitle = {
    Text = "Chat: About Salvador"
  },
  Voice_5802_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Salvador\""
  },
  Voice_5803_AwakerVoiceContent = {
    Text = "The thrill of battle beats everything—not even winning comes close."
  },
  Voice_5803_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_5804_AwakerVoiceContent = {
    Text = "Who doesn't like a soft bed, and a draft-free storm drain... I mean, room."
  },
  Voice_5804_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_5805_AwakerVoiceContent = {
    Text = "Do not make me remember... the days I was imprisoned in Elworth..."
  },
  Voice_5805_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_5806_AwakerVoiceContent = {
    Text = "Burn it all!"
  },
  Voice_5806_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5807_AwakerVoiceContent = {
    Text = "Burn it all!"
  },
  Voice_5807_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_5808_AwakerVoiceContent = {
    Text = "I followed the scent of blood to this place. May I ask... do you have fresh blood for me?"
  },
  Voice_5808_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5809_AwakerVoiceContent = {
    Text = "Hmm... Agrippa has many Friends, but they all seem to be afraid of her. Could it be that she steals their food?"
  },
  Voice_5809_AwakerVoiceTitle = {
    Text = "Chat: About Agrippa"
  },
  Voice_5809_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Agrippa\""
  },
  Voice_5810_AwakerVoiceContent = {
    Text = "My life revolves around dance. Learning other knowledge is difficult for me to grow. But everyone here is kind; they won't sell me out for vanity or money—I can feel it."
  },
  Voice_5810_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_5811_AwakerVoiceContent = {
    Text = "Coward! You possess a mighty power akin to mine, yet you restrain yourself. How is that any different from willingly donning a collar?"
  },
  Voice_5811_AwakerVoiceTitle = {
    Text = "Chat: About Lily"
  },
  Voice_5811_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Lily\""
  },
  Voice_5812_AwakerVoiceContent = {
    Text = "Not enough... I'm still not strong enough."
  },
  Voice_5812_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_5813_AwakerVoiceContent = {Text = "Turn back."},
  Voice_5813_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_5814_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5814_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_5815_AwakerVoiceContent = {
    Text = "Top hats, bowler hats, deerstalker hats, berets... Gotta say it's funny how those high and mighty \"gentlemen\" would do everything to hide their bald heads."
  },
  Voice_5815_AwakerVoiceTitle = {
    Text = "Chat: About Etiquette"
  },
  Voice_5816_AwakerVoiceContent = {
    Text = "I deeply admire her—the maritime goddess, as pure and elegant as a lily... You say even she could not control her fate and ultimately sank into the sea? It is truly hard to imagine..."
  },
  Voice_5816_AwakerVoiceTitle = {
    Text = "Chat: About Celeste"
  },
  Voice_5816_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Celeste\""
  },
  Voice_5817_AwakerVoiceContent = {
    Text = "Nothing compares to the power of a Giant!"
  },
  Voice_5817_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5818_AwakerVoiceContent = {
    Text = "Nothing compares to the power of a Giant!"
  },
  Voice_5818_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_5819_AwakerVoiceContent = {
    Text = "Damn it! Damn it! This power only keeps me trapped in this body!"
  },
  Voice_5819_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_5819_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_5820_AwakerVoiceContent = {
    Text = "I wish to stay in a place that's always bright... Yes, the poles. On this planet, only the poles."
  },
  Voice_5820_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_5820_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_5821_AwakerVoiceContent = {
    Text = "I... I can't bear heavy responsibilities. I can only chase the light. So, please, don't stop shining..."
  },
  Voice_5821_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_5821_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_5822_AwakerVoiceContent = {
    Text = "If I could shift dimentions again, I'd want to become a star..."
  },
  Voice_5822_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_5822_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_5823_AwakerVoiceContent = {
    Text = "No matter how I calculate, the formula for consciousness transfer remains unsolvable..."
  },
  Voice_5823_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_5823_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_5824_AwakerVoiceContent = {
    Text = "Welcome! Let's have a blast together!"
  },
  Voice_5824_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5825_AwakerVoiceContent = {
    Text = "Here's your meal!"
  },
  Voice_5825_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_5826_AwakerVoiceContent = {
    Text = "Hehe... Hi! It's me, Aurita! One, two, three... Woah! Welcome, welcome! New friends have joined us! Huh? I'm your new friend this time? Well, I guess that works too!"
  },
  Voice_5826_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5827_AwakerVoiceContent = {
    Text = "You call this little toy a handgun? Hiding in shadows to ambush enemies... Hmph. A weapon for cowards only."
  },
  Voice_5827_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_5828_AwakerVoiceContent = {
    Text = "Meaningless. All of it. Why bother?"
  },
  Voice_5828_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_5829_AwakerVoiceContent = {
    Text = "You know absolutely nothing."
  },
  Voice_5829_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_5830_AwakerVoiceContent = {
    Text = "Still counting on me to be your backup, \"Savior\"?"
  },
  Voice_5830_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_5831_AwakerVoiceContent = {
    Text = "Sorry, have you seen my screw? It's strange, but whenever that kid with the mouse ears is around, I seem to forget where I've put things more often..."
  },
  Voice_5831_AwakerVoiceTitle = {
    Text = "Chat: About Jenkin"
  },
  Voice_5831_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Jenkin\""
  },
  Voice_5832_AwakerVoiceContent = {
    Text = "I shall not forget what you've contributed for my reunion with Him..."
  },
  Voice_5832_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_5833_AwakerVoiceContent = {
    Text = "Listen to the Sculpted Cantabile!"
  },
  Voice_5833_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5834_AwakerVoiceContent = {
    Text = "Have you acknowledged my wish?"
  },
  Voice_5834_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_5835_AwakerVoiceContent = {
    Text = "I hope your command won't disappoint."
  },
  Voice_5835_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_5836_AwakerVoiceContent = {
    Text = "Has my body or my consciousness improved? An intriguing subject for analysis."
  },
  Voice_5836_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_5836_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_5837_AwakerVoiceContent = {Text = "Back off."},
  Voice_5837_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_5838_AwakerVoiceContent = {
    Text = "Move aside."
  },
  Voice_5838_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_5839_AwakerVoiceContent = {
    Text = "My veins surge with the will to survive, screaming and driving me to spill my blood on every inch of this planet... Ah, I've rambled on for too long; do forgive me. I am Thais. Have you summoned me? Are you ready to merge with me?"
  },
  Voice_5839_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5840_AwakerVoiceContent = {
    Text = "If only Aigis could bear this black liquid for everyone... After all, Aigis never existed, which might be a good thing for this world, right?"
  },
  Voice_5840_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_5841_AwakerVoiceContent = {
    Text = "My hobbies include trying to solve the Riemann Hypothesis—that, however, is our Mr. Peacock's catchphrase, not mine. Personally, I find atomic mass standards far more engaging."
  },
  Voice_5841_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_5842_AwakerVoiceContent = {
    Text = "The taste of being exiled and cast adrift at sea... Once was enough."
  },
  Voice_5842_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_5843_AwakerVoiceContent = {
    Text = "My kin have never left me; they have just gone very, very far away."
  },
  Voice_5843_AwakerVoiceTitle = {
    Text = "Chat: About Her Clansmen"
  },
  Voice_5844_AwakerVoiceContent = {
    Text = "Watch closely!"
  },
  Voice_5844_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5845_AwakerVoiceContent = {
    Text = "Watch closely!"
  },
  Voice_5845_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_5846_AwakerVoiceContent = {
    Text = "As long as you can uphold this justice, I will always shoulder the duty of the blade."
  },
  Voice_5846_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_5847_AwakerVoiceContent = {
    Text = "Did you know about the legend of that certain \"Painter\" here? From those expressionist graffiti, I sense a familiar touch..."
  },
  Voice_5847_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_5848_AwakerVoiceContent = {
    Text = "It hurts! I'm feeling so, so good!"
  },
  Voice_5848_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5849_AwakerVoiceContent = {
    Text = "Feel my wrath!"
  },
  Voice_5849_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5850_AwakerVoiceContent = {
    Text = "Let this victory be etched in poetry."
  },
  Voice_5850_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_5851_AwakerVoiceContent = {
    Text = "Grow stronger~"
  },
  Voice_5851_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5852_AwakerVoiceContent = {
    Text = "Watch this!"
  },
  Voice_5852_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_5853_AwakerVoiceContent = {Text = "Hey!"},
  Voice_5853_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_5854_AwakerVoiceContent = {
    Text = "Maybe when I grow up, I'll be able to control myself and not drain others' Life... Just a tiny bit is enough for me to survive."
  },
  Voice_5854_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_5854_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_5855_AwakerVoiceContent = {
    Text = "Seems like I've gotten heavier. Can the cradle still bear my weight?"
  },
  Voice_5855_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_5855_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_5856_AwakerVoiceContent = {
    Text = "I've eaten up so much power, it's about to overflow. My back is itching, too. Am I... growing up?"
  },
  Voice_5856_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_5856_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_5857_AwakerVoiceContent = {
    Text = "Although I still look like a child... Now I have the power to protect you."
  },
  Voice_5857_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_5857_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_5858_AwakerVoiceContent = {
    Text = "I'll do my best to grow up."
  },
  Voice_5858_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_5858_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_5859_AwakerVoiceContent = {
    Text = "You presumptuous wretch, why do you insist on awakening me?"
  },
  Voice_5859_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5860_AwakerVoiceContent = {
    Text = "I shall become the Divine Mother!"
  },
  Voice_5860_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5861_AwakerVoiceContent = {
    Text = "How many times have I been summoned... Human, you'd better have enough 'food' ready, or I can't guarantee anything."
  },
  Voice_5861_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5862_AwakerVoiceContent = {
    Text = "Beyond the Gate!"
  },
  Voice_5862_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5863_AwakerVoiceContent = {Text = "Foolish."},
  Voice_5863_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5864_AwakerVoiceContent = {Text = "Haha!"},
  Voice_5864_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5865_AwakerVoiceContent = {
    Text = "Hmph, not bad at all. Our next duel will be legendary."
  },
  Voice_5865_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_5866_AwakerVoiceContent = {Text = "Insolent!"},
  Voice_5866_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_5867_AwakerVoiceContent = {
    Text = "Sometimes, the beauty of art lies in its annihilation. But your failure... clearly doesn't fall into that category."
  },
  Voice_5867_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_5868_AwakerVoiceContent = {
    Text = "You are my most important listener. Whenever you need it, I am ready to sing and give you everything."
  },
  Voice_5868_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_5869_AwakerVoiceContent = {
    Text = "Favorite things? Seaweed, fish schools, colonnades, mazes... Of course I've seen them! They're all in Uncle Ornn's book!"
  },
  Voice_5869_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_5870_AwakerVoiceContent = {
    Text = "Is this preparation for an investigation mission? I understand."
  },
  Voice_5870_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_5870_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_5871_AwakerVoiceContent = {
    Text = "My name is Celeste. I'll always be here, as long as you still need me."
  },
  Voice_5871_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5872_AwakerVoiceContent = {
    Text = "Learn your lesson!"
  },
  Voice_5872_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5873_AwakerVoiceContent = {
    Text = "Show some respect, junior. In the army, seniority is absolute, and orders are followed without exception. Such improper behavior will be punished."
  },
  Voice_5873_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_5874_AwakerVoiceContent = {
    Text = "I'd offer repairs for those \"little trinkets\" I made, but the question is... Do you dare accept my after-sales service?"
  },
  Voice_5874_AwakerVoiceTitle = {
    Text = "Chat: About Her Inventions"
  },
  Voice_5875_AwakerVoiceContent = {
    Text = "You are the master here, but also a guest in my salon. I will prepare the finest hospitality for your visit—do you prefer a scarlet petticoat or a white rose-colored nightgown?"
  },
  Voice_5875_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_5876_AwakerVoiceContent = {
    Text = "Sorry, the sunlight here is a bit glaring... An underground mouse like me still needs time to adjust."
  },
  Voice_5876_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_5877_AwakerVoiceContent = {
    Text = "Capable of corroding everything, erasing all... It was quite a weapon. If only I had known back then... Heh."
  },
  Voice_5877_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_5878_AwakerVoiceContent = {
    Text = "Rumor has it that bodies twitching in the flames appear as if they are dancing..."
  },
  Voice_5878_AwakerVoiceTitle = {
    Text = "Chat: About the Flames"
  },
  Voice_5879_AwakerVoiceContent = {
    Text = "Here you are again. Just like before, sit by my side and wait with me. Wait for what...? Just wait."
  },
  Voice_5879_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_5880_AwakerVoiceContent = {
    Text = "Don't go out at night! Even with a 2000-lumen light, it's not completely safe... Once you step into the darkness, the evil lurking beyond your sight will chase you, devour you, chase you, devour you... until nothing is left!"
  },
  Voice_5880_AwakerVoiceTitle = {
    Text = "Chat: About Night"
  },
  Voice_5881_AwakerVoiceContent = {Text = "Cry."},
  Voice_5881_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_5882_AwakerVoiceContent = {
    Text = "I have received your payment."
  },
  Voice_5882_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5883_AwakerVoiceContent = {
    Text = "It is the yearning for life that drives the swan to struggle for its return to the distant sky."
  },
  Voice_5883_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_5883_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_5884_AwakerVoiceContent = {
    Text = "Magic time!"
  },
  Voice_5884_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5885_AwakerVoiceContent = {Text = "Help!"},
  Voice_5885_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_5886_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_5886_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_5887_AwakerVoiceContent = {Text = "(Groan)"},
  Voice_5887_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_5888_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5888_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_5889_AwakerVoiceContent = {
    Text = "Ah, it's Brown! I... I should probably back away a bit... I wanted to be her friend, but instead, I ended up becoming her nightmare... She probably doesn't want to see me anyway..."
  },
  Voice_5889_AwakerVoiceTitle = {
    Text = "Chat: About Jenkin"
  },
  Voice_5889_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Jenkin\""
  },
  Voice_5890_AwakerVoiceContent = {
    Text = "A chapel? Thank you, but I am not so old-fashioned. As long as I keep the teachings of the God of Kindness in my heart and follow His will, my soul will never stray from His glory."
  },
  Voice_5890_AwakerVoiceTitle = {
    Text = "Chat: About a Chapel"
  },
  Voice_5891_AwakerVoiceContent = {
    Text = "My name is Ogier. As our contract stands, I pledge my knightly loyalty to you, to keep you safe, and to vanquish your foes. This solemn oath I take, and I'll never forget it."
  },
  Voice_5891_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5892_AwakerVoiceContent = {
    Text = "That emaciated woman with double pupils smells exactly like a Spartan insect."
  },
  Voice_5892_AwakerVoiceTitle = {
    Text = "Chat: About Agrippa"
  },
  Voice_5892_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Agrippa\""
  },
  Voice_5893_AwakerVoiceContent = {
    Text = "Likes? Good luck, obviously. I always look for a good omen before heading out."
  },
  Voice_5893_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_5894_AwakerVoiceContent = {
    Text = "P-Please, do not tell Miss Hannah that I am hiding here. I am not ready yet..."
  },
  Voice_5894_AwakerVoiceTitle = {
    Text = "Chat: About Hanna"
  },
  Voice_5895_AwakerVoiceContent = {
    Text = "How about this?"
  },
  Voice_5895_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5896_AwakerVoiceContent = {
    Text = "You are my esteemed guest. Remember, you're the only one allowed to run a tab. After all, it's been years since I last saw such a perfect skull..."
  },
  Voice_5896_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_5897_AwakerVoiceContent = {Text = "Ouch!"},
  Voice_5897_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_5898_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_5898_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_5899_AwakerVoiceContent = {Text = "Ouch!"},
  Voice_5899_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_5900_AwakerVoiceContent = {
    Text = "Preferences? A king should not indulge... yet if I could avoid tedious rites, a soft divan might suffice."
  },
  Voice_5900_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_5901_AwakerVoiceContent = {
    Text = "Your insolence... This One shall interpret as a plea for eternal rest."
  },
  Voice_5901_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_5902_AwakerVoiceContent = {
    Text = "Hate? I hate an inescapable fate and an inevitable tragedy."
  },
  Voice_5902_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_5903_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_5903_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_5904_AwakerVoiceContent = {
    Text = "(A muffled, pained groan)"
  },
  Voice_5904_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_5905_AwakerVoiceContent = {Text = "Back off!"},
  Voice_5905_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_5906_AwakerVoiceContent = {
    Text = "Oh, curious about my secret? This name, this body, this face, this voice—they all came from a woman from San Pedro, to whom one of my skulls once belonged. She struck a deal with me... After her death, I became her. As for her whereabouts... well, that is my most exquisite collection, you know."
  },
  Voice_5906_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_5906_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_5907_AwakerVoiceContent = {
    Text = "You are a delightful guest; even I am captivated by your unique skull... If you ever consider parting with it, be sure to visit my little shop. Haha... just a jest."
  },
  Voice_5907_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_5907_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_5908_AwakerVoiceContent = {
    Text = "Curious about my true identity? It's still too early for that. Just believe this: Every lost child can find their way in my shop. Perhaps that includes you as well?"
  },
  Voice_5908_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_5908_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_5909_AwakerVoiceContent = {
    Text = "No one will be harmed."
  },
  Voice_5909_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5910_AwakerVoiceContent = {
    Text = "It's not over yet!"
  },
  Voice_5910_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_5911_AwakerVoiceContent = {
    Text = "Seeing how hard you're working, I almost feel guilty about collecting my reward too soon. So, I'll allow your head to stay where it is for now. But don't forget, it's already reserved as my personal property, okay?"
  },
  Voice_5911_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_5911_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_5912_AwakerVoiceContent = {
    Text = "I wasn't always like this; she gave me a new life. In that sense, you have also given me a second life, so I will treasure your head as well."
  },
  Voice_5912_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_5912_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_5913_AwakerVoiceContent = {
    Text = "I must escape the darkness!"
  },
  Voice_5913_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5914_AwakerVoiceContent = {
    Text = "So adventuring is this dangerous..."
  },
  Voice_5914_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_5915_AwakerVoiceContent = {
    Text = "Why does that silly girl bolt the moment she sees me? Next time, I'll step on her yarn and see where she runs."
  },
  Voice_5915_AwakerVoiceTitle = {
    Text = "Chat: About Aigis"
  },
  Voice_5915_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Aigis\""
  },
  Voice_5916_AwakerVoiceContent = {Text = "Ugh!"},
  Voice_5916_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5917_AwakerVoiceContent = {
    Text = "Heh... AHAHAHA!"
  },
  Voice_5917_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_5918_AwakerVoiceContent = {Text = "Hahaha!"},
  Voice_5918_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5919_AwakerVoiceContent = {
    Text = "That kid's sharp; you need that kind of wit on the streets. If I was still out there investigating, I'd definitely buddy up with her."
  },
  Voice_5919_AwakerVoiceTitle = {
    Text = "Chat: About Jenkin"
  },
  Voice_5919_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Jenkin\""
  },
  Voice_5920_AwakerVoiceContent = {
    Text = "That bishop cannot save everyone. He might pluck one unfortunate soul from the mire, but the rest? ...I can't wait to watch his faith shatter."
  },
  Voice_5920_AwakerVoiceTitle = {
    Text = "Chat: About Salvador"
  },
  Voice_5920_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Salvador\""
  },
  Voice_5921_AwakerVoiceContent = {
    Text = "You can find everything in Londinium's sewers: salmon, soap, half-drunk whiskey... Why do I know this, you ask? I once dragged my brother's corpse through five miles of it..."
  },
  Voice_5921_AwakerVoiceTitle = {
    Text = "Chat: About Sewer"
  },
  Voice_5922_AwakerVoiceContent = {
    Text = "Kneel before me!"
  },
  Voice_5922_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5923_AwakerVoiceContent = {
    Text = "Kneel before me."
  },
  Voice_5923_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_5924_AwakerVoiceContent = {
    Text = "After glimpsing the real world beyond the front lines, I once questioned the value of \"heroes.\" But luckily, I met you—honest, brave, and pure. Under your command, I will fight tirelessly for peace and stability. This time, I will secure my redemption."
  },
  Voice_5924_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_5924_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_5925_AwakerVoiceContent = {
    Text = "Yikes! Oh no..."
  },
  Voice_5925_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_5926_AwakerVoiceContent = {
    Text = "Unclean, filthy, chaotic—this is our power."
  },
  Voice_5926_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5927_AwakerVoiceContent = {
    Text = "I loathe your pretentious act. Think I'm mad? Pathetic? You're the Icarus here, \"Savior\". You and your little flock, eyes scorched white from staring at that glorious sun you chase."
  },
  Voice_5927_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_5928_AwakerVoiceContent = {
    Text = "Let me lead the way!"
  },
  Voice_5928_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_5929_AwakerVoiceContent = {
    Text = "They feel alien. Not native to this planet, I bet."
  },
  Voice_5929_AwakerVoiceTitle = {
    Text = "Chat: About Extraterrestrial Beings"
  },
  Voice_5929_UnlockDesc = {
    Text = "Unlocks after acquiring any one of Awakeners \"Winkle\", \"Tinct\", \"Faint\", or \"Wanda\"."
  },
  Voice_5930_AwakerVoiceContent = {Text = "—"},
  Voice_5930_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_5931_AwakerVoiceContent = {Text = "(Groan)"},
  Voice_5931_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_5932_AwakerVoiceContent = {Text = "Vanish!"},
  Voice_5932_AwakerVoiceTitle = {
    Text = "Special Skill: I"
  },
  Voice_5933_AwakerVoiceContent = {
    Text = "Please don't..."
  },
  Voice_5933_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_5934_AwakerVoiceContent = {
    Text = "Being a monster is fine. All I've ever wanted was the power for revenge."
  },
  Voice_5934_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_5934_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_5935_AwakerVoiceContent = {
    Text = "Besides eliminating your opponent, do you have any other desires? In return, I will grant your wish... within my ability, of course."
  },
  Voice_5935_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_5935_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_5936_AwakerVoiceContent = {Text = "(Groan)"},
  Voice_5936_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_5937_AwakerVoiceContent = {
    Text = "A companion? ... I'll consider it. Don't die on me before I make my decision."
  },
  Voice_5937_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_5937_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_5938_AwakerVoiceContent = {
    Text = "Since its first clear documentation, the Dissolution has impacted over a million lives. Our actions are critical to the survival of the entire human population."
  },
  Voice_5938_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_5939_AwakerVoiceContent = {
    Text = "Full throttle!"
  },
  Voice_5939_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5940_AwakerVoiceContent = {
    Text = "Beware of the ocean's fury."
  },
  Voice_5940_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_5941_AwakerVoiceContent = {
    Text = "Beware of the ocean's fury."
  },
  Voice_5941_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5942_AwakerVoiceContent = {Text = "Hey!"},
  Voice_5942_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5943_AwakerVoiceContent = {
    Text = "I am His Daughter, and also His Mother. As for you, in His presence, you are merely an insignificant insect."
  },
  Voice_5943_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_5944_AwakerVoiceContent = {
    Text = "Everything went well. You may raise the triumphant sails."
  },
  Voice_5944_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_5945_AwakerVoiceContent = {
    Text = "Stay away. Do you wish to become my plaything? Or perhaps a sacrifice for the Divine Birth?"
  },
  Voice_5945_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_5945_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_59463_AwakerVoiceContent = {
    Text = "Make it an easy win! It's our total victory!"
  },
  Voice_59463_AwakerVoiceTitle = {
    Text = "Over-Exalt: II"
  },
  Voice_59464_AwakerVoiceContent = {
    Text = "Make it an easy win! It's our total victory!"
  },
  Voice_59464_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_5946_AwakerVoiceContent = {
    Text = "I bestow upon you the honor of being witness. You shall behold the glorious moment that defies mortal ethics."
  },
  Voice_5946_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_5946_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_5947_AwakerVoiceContent = {
    Text = "A hollow? I often create similar stuff during telekinesis. The ones I make link to another dimension; would the Dissolution ones do the same?"
  },
  Voice_5947_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_5948_AwakerVoiceContent = {
    Text = "Keeper, by the authority of the Divine Mother, I secure your place beside the Throne. You will witness the era reborn after destruction—this is the promise of the Divine Mother. Now rejoice! Rejoice with gratitude!"
  },
  Voice_5948_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_5948_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_5949_AwakerVoiceContent = {
    Text = "Seeing how deferential you are, I shall grant you an answer. In the beginning, I was indeed reluctant. But I've come to understand: I am only living this extravagant life because of Him. Death is never the end. He will in turn rebirth me, and we shall gain eternal life through this morbid cycle..."
  },
  Voice_5949_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_5949_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_5950_AwakerVoiceContent = {
    Text = "That woman's wish is hilarious. Nothing can survive the Annihilation, not even her \"god\"."
  },
  Voice_5950_AwakerVoiceTitle = {
    Text = "Chat: About Thais"
  },
  Voice_5950_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Thais\""
  },
  Voice_5951_AwakerVoiceContent = {
    Text = "I am not omnipotent. Even I err. That woman's ruinous action was my miscalculation... Hence, I require your aid. That you may heed my summons, you may place a bed here, in my chamber."
  },
  Voice_5951_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_5951_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_5952_AwakerVoiceContent = {
    Text = "To shoulder calamity's weight... it must be a heavy burden for your age. Tell me—had you known from the start that destiny is immutable... would you still have fought so fiercely? Keep your answer. Reflect as I rest. Your reply... interests me."
  },
  Voice_5952_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_5952_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_5953_AwakerVoiceContent = {
    Text = "It has been a while since you awakened me. Have you no questions? Divine secrets? The absolute prophecy? Even the drowned continent's treasures... Nothing stirs your curiosity? Hmph... You are peculiar, indeed."
  },
  Voice_5953_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_5953_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_5954_AwakerVoiceContent = {
    Text = "I never demanded worship. Mortals' fervor only exhausts me further... Withdraw. I will sleep now."
  },
  Voice_5954_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_5954_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_5955_AwakerVoiceContent = {
    Text = "I see none of my vassals' traits in you... Perhaps that is for the best. Merely recalling that woman wearies me."
  },
  Voice_5955_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_5955_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_5956_AwakerVoiceContent = {
    Text = "God treats all His children equally."
  },
  Voice_5956_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5957_AwakerVoiceContent = {
    Text = "I know, you're a special audience. I can't just zap you into another dimension; that would cause big trouble. Hey, have you ever done that to someone else? You mustn't ask, it is my secret!"
  },
  Voice_5957_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_5958_AwakerVoiceContent = {
    Text = "Aw, you're interested in my new look? Guess there's always a trade-off. Gotta be one of my lucky breaks—that's Ryker's luck!"
  },
  Voice_5958_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_5959_AwakerVoiceContent = {
    Text = "Mythag holds the most memories for me... it is also my warmest home."
  },
  Voice_5959_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_5960_AwakerVoiceContent = {
    Text = "Leave it to me."
  },
  Voice_5960_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_5961_AwakerVoiceContent = {Text = "How naive!"},
  Voice_5961_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_5962_AwakerVoiceContent = {
    Text = "Abyss Hymns!"
  },
  Voice_5962_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_5963_AwakerVoiceContent = {
    Text = "Behold what I have been bestowed—"
  },
  Voice_5963_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_5964_AwakerVoiceContent = {
    Text = "If you can still see me as \"Ramona\"... then please continue to use that name."
  },
  Voice_5964_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5965_AwakerVoiceContent = {
    Text = "What? You want to exploit my anger too?"
  },
  Voice_5965_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_5965_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_5966_AwakerVoiceContent = {
    Text = "The truth... it's revealed right here."
  },
  Voice_5966_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5967_AwakerVoiceContent = {
    Text = "Eat what you get the moment you grab it. That's the law of the streets."
  },
  Voice_5967_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_5968_AwakerVoiceContent = {
    Text = "I feel kinda full now."
  },
  Voice_5968_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_5969_AwakerVoiceContent = {
    Text = "Hmm.., I've got an itch. Brown, come scratch my back."
  },
  Voice_5969_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_5970_AwakerVoiceContent = {
    Text = "New mechanical parts will greatly help my system operate—doesn't that count as liking something? Sorry, I'm afraid I don't understand your question. Preferences hold no meaning for mechanical dolls."
  },
  Voice_5970_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_5971_AwakerVoiceContent = {
    Text = "Watch this."
  },
  Voice_5971_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_5972_AwakerVoiceContent = {
    Text = "Watch this!"
  },
  Voice_5972_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5973_AwakerVoiceContent = {
    Text = "Lalala...Hmm? A world-ending disaster is happening? I see... but first, I gotta do my hair and go find Tinct..."
  },
  Voice_5973_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_5974_AwakerVoiceContent = {
    Text = "Think it through."
  },
  Voice_5974_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_5975_AwakerVoiceContent = {
    Text = "Stay calm and think."
  },
  Voice_5975_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_5976_AwakerVoiceContent = {
    Text = "Miss Winkle, like me, isn't from this planet... There's nothing tying me to my home except Tinct. I wonder how Miss Winkle feels about her homeland?"
  },
  Voice_5976_AwakerVoiceTitle = {
    Text = "Chat: About Winkle"
  },
  Voice_5976_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Winkle\""
  },
  Voice_5977_AwakerVoiceContent = {
    Text = "Don't approach me from behind, unless you want your neck broken."
  },
  Voice_5977_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_5977_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_5978_AwakerVoiceContent = {
    Text = "Huh? How could you allow stray cats to roam the campus?! What if that savage creature scratches someone?!"
  },
  Voice_5978_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_5979_AwakerVoiceContent = {
    Text = "Does my eyes make you uncomfortable? Good. That's the ferocity that kept me alive in that hell."
  },
  Voice_5979_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_5979_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_5980_AwakerVoiceContent = {
    Text = "Spare me the high-sounding talk. What do you want from me? There must be a reason for keeping my sanity intact."
  },
  Voice_5980_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_5980_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_5981_AwakerVoiceContent = {
    Text = "My vengeance was always directed at the Spartans, but now, even that city-state no longer exists... Fine. Becoming your blade is not impossible. I reluctantly accept you as my partner, but if you dare to betray me, I will tear out your heart."
  },
  Voice_5981_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_5981_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_5982_AwakerVoiceContent = {
    Text = "My hands are stained with blood. My weak kin do not understand my revenge; they whisper about my cruelty, ingratitude, and betrayal... Revenge is always for myself alone, and no one else."
  },
  Voice_5982_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_5982_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_5983_AwakerVoiceContent = {
    Text = "It's time to use more steel."
  },
  Voice_5983_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5984_AwakerVoiceContent = {
    Text = "It's time to use more steel."
  },
  Voice_5984_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_5985_AwakerVoiceContent = {Text = "Die."},
  Voice_5985_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_5986_AwakerVoiceContent = {
    Text = "I'm... just call me Winkle. That's what everyone calls me. Yes, call me that, just like they do..."
  },
  Voice_5986_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5987_AwakerVoiceContent = {
    Text = "This body shall be my lord's shield!"
  },
  Voice_5987_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_5988_AwakerVoiceContent = {
    Text = "This body shall be my lord's shield!"
  },
  Voice_5988_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5989_AwakerVoiceContent = {
    Text = "\"The Nutcracker\" is supposed to be a romantic fairy tale for girls, but those repulsive individuals only saw the graceful limbs in motion and vulgar desires... Disgusting."
  },
  Voice_5989_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_5990_AwakerVoiceContent = {
    Text = "I must... eliminate it!"
  },
  Voice_5990_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_5991_AwakerVoiceContent = {
    Text = "Pandia... She calls THAT being a dominatrix? Haha... Allow me a moment of amusement. Humans are still too soft-hearted; everything they do seems like mere child's play."
  },
  Voice_5991_AwakerVoiceTitle = {
    Text = "Chat: About Pandia"
  },
  Voice_5991_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Pandia\""
  },
  Voice_5992_AwakerVoiceContent = {
    Text = "Don't come any closer!"
  },
  Voice_5992_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5993_AwakerVoiceContent = {
    Text = [[
What? Introductions again? Fine. I'm Jenkin, and this is Brown. "Squeak!"
Don't you forget it! You mess up our names, and I'll whack your *Beep* with my lantern!
"Squeak squeak?!"]]
  },
  Voice_5993_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5994_AwakerVoiceContent = {
    Text = "Let's dance! Let's dance!"
  },
  Voice_5994_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_5995_AwakerVoiceContent = {
    Text = "Let's dance! Let's dance!"
  },
  Voice_5995_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_5996_AwakerVoiceContent = {
    Text = "Here comes the opening tribute!"
  },
  Voice_5996_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_5997_AwakerVoiceContent = {Text = "Hmph."},
  Voice_5997_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_5998_AwakerVoiceContent = {
    Text = "I need only a bit of stone, two chisels, and three sun-facing irises... and I can create anything for you."
  },
  Voice_5998_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_5998_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_5999_AwakerVoiceContent = {Text = "(Groan)"},
  Voice_5999_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_6000_AwakerVoiceContent = {
    Text = "That's all?"
  },
  Voice_6000_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_6001_AwakerVoiceContent = {Text = "Hmm."},
  Voice_6001_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_6002_AwakerVoiceContent = {
    Text = "This meaningless struggle..."
  },
  Voice_6002_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_6003_AwakerVoiceContent = {Text = "(Groan)"},
  Voice_6003_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_6004_AwakerVoiceContent = {
    Text = "After Tiberius's death, the Romans finally had their long-time wish granted: they got to dump him into the Tiber to feed the fish. The price was small: Caligula threw those people to me in the arena for my amusement."
  },
  Voice_6004_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_6005_AwakerVoiceContent = {Text = "(Groan)"},
  Voice_6005_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_6006_AwakerVoiceContent = {
    Text = "I can sense that the little girl possesses powers similar to mine. She hasn't fully grasped the extent of their strength yet. For your sake, I will train her appropriately."
  },
  Voice_6006_AwakerVoiceTitle = {
    Text = "Chat: About Lily"
  },
  Voice_6006_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Lily\""
  },
  Voice_6007_AwakerVoiceContent = {
    Text = "Darn it! You—you still look down on me, don't you?!"
  },
  Voice_6007_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_6008_AwakerVoiceContent = {
    Text = "This is my proof of existence."
  },
  Voice_6008_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_6009_AwakerVoiceContent = {
    Text = "This is my proof of existence."
  },
  Voice_6009_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6010_AwakerVoiceContent = {
    Text = "I believe all things happen for a reason, but... the senseless violence, the prejudices that drive siblings to turn against each other... these things truly sadden me. If there is anything I detest, it is that."
  },
  Voice_6010_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_6011_AwakerVoiceContent = {
    Text = "I truly wish I didn't have to use this power."
  },
  Voice_6011_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6012_AwakerVoiceContent = {
    Text = "Don't drop your guard."
  },
  Voice_6012_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_6013_AwakerVoiceContent = {Text = "Hmph."},
  Voice_6013_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_6014_AwakerVoiceContent = {Text = "Stop!"},
  Voice_6014_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6015_AwakerVoiceContent = {Text = "Stop!"},
  Voice_6015_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_6016_AwakerVoiceContent = {
    Text = "Casiah is incredible! She can make a bunny appear in the blink of an eye!"
  },
  Voice_6016_AwakerVoiceTitle = {
    Text = "Chat: About Casiah"
  },
  Voice_6016_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Casiah\""
  },
  Voice_6017_AwakerVoiceContent = {
    Text = "My magic's ready!"
  },
  Voice_6017_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6018_AwakerVoiceContent = {
    Text = "Dissolution... I must admit, there are things in this world beyond the control of power."
  },
  Voice_6018_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_6019_AwakerVoiceContent = {Text = "Ahh—"},
  Voice_6019_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_6020_AwakerVoiceContent = {
    Text = "Dance amidst the emerald flames."
  },
  Voice_6020_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_6021_AwakerVoiceContent = {
    Text = "Don't fret; scars are a warrior's badge of honor!"
  },
  Voice_6021_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_6022_AwakerVoiceContent = {
    Text = "Tremble before these muscles... They are always ready to sever your head."
  },
  Voice_6022_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_6024_AwakerVoiceContent = {
    Text = "Mealtime? Or activity time?"
  },
  Voice_6024_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_6024_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_6025_AwakerVoiceContent = {
    Text = "Haha! Now Aurita's Friends won't disappear again!"
  },
  Voice_6025_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_6025_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_6026_AwakerVoiceContent = {
    Text = "Ms. Sylvia said I should say \"thank you\" when I receive something... Thank you, thank you, thank you!!"
  },
  Voice_6026_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_6026_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_6027_AwakerVoiceContent = {
    Text = "It's my turn to be the ghost this time! You only have 5 seconds to hide! 5, 4—"
  },
  Voice_6027_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_6027_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_6028_AwakerVoiceContent = {
    Text = "Everyone disappeared after starting hide-and-seek. This time, I'm determined to find everyone!"
  },
  Voice_6028_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_6028_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_6029_AwakerVoiceContent = {
    Text = "They found my bones beneath waves and presume I enjoy water? Now they wish to build a pool outside my chambers? ...Ha. They may do as they will. As long as they cease troubling me with trifles."
  },
  Voice_6029_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_6030_AwakerVoiceContent = {
    Text = "A mere drop in the tides, a shallow follower of the immortal, Miryam... greets you."
  },
  Voice_6030_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6031_AwakerVoiceContent = {
    Text = "It's my turn to act."
  },
  Voice_6031_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_6032_AwakerVoiceContent = {Text = "Hah!"},
  Voice_6032_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_6033_AwakerVoiceContent = {
    Text = "Absolutely amazing... Your offhand remark has resolved a creative problem that has been troubling me for months."
  },
  Voice_6033_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_6033_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_6034_AwakerVoiceContent = {
    Text = "Compared to the noble ladies at that party, Murphy's temper is rather endearing."
  },
  Voice_6034_AwakerVoiceTitle = {
    Text = "Chat: About Murphy"
  },
  Voice_6034_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Murphy\""
  },
  Voice_6035_AwakerVoiceContent = {
    Text = "They call me a master counselor? Those children are too kind. I simply do my best to listen and help them release their inner distress—as I have always tried to do."
  },
  Voice_6035_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_6036_AwakerVoiceContent = {
    Text = "Never look down on me!"
  },
  Voice_6036_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6037_AwakerVoiceContent = {
    Text = "Never look down on me!"
  },
  Voice_6037_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_6038_AwakerVoiceContent = {
    Text = "Feeling thirsty? Clean water is a rare luxury in the prison."
  },
  Voice_6038_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_6038_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_6039_AwakerVoiceContent = {
    Text = "Now, who's the good {Male=boy,Female=girl}? Good {Male=boy,Female=girl}s don't give up halfway~"
  },
  Voice_6039_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_6039_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_6040_AwakerVoiceContent = {
    Text = "You must have fallen into my sweet trap already at this point, yes?"
  },
  Voice_6040_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_6040_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_6041_AwakerVoiceContent = {
    Text = "Keep going, just a little more~ We're almost at the peak of ecstasy~"
  },
  Voice_6041_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_6041_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_6042_AwakerVoiceContent = {
    Text = "I joined Mythag at the age of fourteen. Had I graduated smoothly, you would be addressing me as Principal now."
  },
  Voice_6042_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_6043_AwakerVoiceContent = {
    Text = "Your feeble brain appears incapable of retaining lessons."
  },
  Voice_6043_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_6044_AwakerVoiceContent = {
    Text = "My wish? Ensuring safe and peaceful voyage—does that not suffice? I have never had any other wishes... but I will consider it carefully and tell you later."
  },
  Voice_6044_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_6044_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_6045_AwakerVoiceContent = {
    Text = "\"It was the secrets of heaven and earth that I desired to learn. I wanted to figure out what force is controlling me?\" ...Though I find this novel's plot unsatisfying and its fictional science laughably naive, after reading it, you should grasp my motivations... Wait, you haven't read this book?"
  },
  Voice_6045_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_6045_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_6046_AwakerVoiceContent = {
    Text = "Duty and destiny are much alike. Neither can be easily cast aside, nor is there any need to cast them aside."
  },
  Voice_6046_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_6046_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_6047_AwakerVoiceContent = {
    Text = "Do I always appear busy? Yes. Assistants can occasionally be useful, but in some research, I am simply irreplaceable. Do you wish to help? Then periodically check if I am still, in fact, alive."
  },
  Voice_6047_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_6047_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_6048_AwakerVoiceContent = {
    Text = "I look angry? Do you comprehend how many muscles are required for a smile? I once elucidated this in class, a lesson that evidently slipped from your smooth brain. The answer is a minimum of seventeen, and I possess no logical reason to be angry with you."
  },
  Voice_6048_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_6048_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_6049_AwakerVoiceContent = {
    Text = "Miss Ramona once said that I don't need to accommodate everyone. I do not understand... Does it mean my protection is no longer needed?"
  },
  Voice_6049_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_6049_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_6050_AwakerVoiceContent = {
    Text = "Thirteen reports require urgent approval, six damaged communicators await repair, and I must also monitor the results of five distinct Silver extraction experiments... So, instead of squandering my limited time by disturbing me, why not attempt to exercise your feeble brain matter?"
  },
  Voice_6050_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_6050_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_6051_AwakerVoiceContent = {
    Text = "I hope that next time, my homeland will answer my call."
  },
  Voice_6051_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_6052_AwakerVoiceContent = {
    Text = "Lock released."
  },
  Voice_6052_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6053_AwakerVoiceContent = {
    Text = "Audience, we need more audience..."
  },
  Voice_6053_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_6054_AwakerVoiceContent = {
    Text = "I'm so happy... You're so biased and favor me so much."
  },
  Voice_6054_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_6054_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_6055_AwakerVoiceContent = {
    Text = "Others may get upset if they think you're showing favoritism."
  },
  Voice_6055_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_6055_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_6056_AwakerVoiceContent = {
    Text = "Do you long for me as well?"
  },
  Voice_6056_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_6056_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_6057_AwakerVoiceContent = {
    Text = "Finally, it's over. No more seeing those black, slimy..."
  },
  Voice_6057_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_6058_AwakerVoiceContent = {
    Text = "For all that you have given me, your love has already become one with mine..."
  },
  Voice_6058_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_6058_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_6059_AwakerVoiceContent = {Text = "Hey!"},
  Voice_6059_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_6060_AwakerVoiceContent = {
    Text = "Ooh, that was a close one."
  },
  Voice_6060_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_6061_AwakerVoiceContent = {
    Text = "You've worked so hard; it's time to enjoy the fruits of your labor, right? Come closer, I won't disappoint you~"
  },
  Voice_6061_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_6061_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_6062_AwakerVoiceContent = {
    Text = "I... I understand your intention. Though I'm still clumsy, I will fight for you with all I have!"
  },
  Voice_6062_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_6062_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_6063_AwakerVoiceContent = {
    Text = "Your gaze is burning me... Have I caused you any trouble?"
  },
  Voice_6063_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_6063_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_6064_AwakerVoiceContent = {
    Text = "I am very anxious... unsure if I can ever meet your expectations..."
  },
  Voice_6064_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_6064_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_6065_AwakerVoiceContent = {
    Text = "I-I feel so uneasy... being looked at like this... Are you not afraid of my curse?"
  },
  Voice_6065_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_6065_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_6066_AwakerVoiceContent = {
    Text = "P-please don't look into my eyes... I don't want to hurt you... I'm a monster, after all..."
  },
  Voice_6066_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_6066_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_6067_AwakerVoiceContent = {
    Text = "This beast's sense of smell? That's just luck, alright? Don't get it twisted."
  },
  Voice_6067_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_6067_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_6068_AwakerVoiceContent = {
    Text = "I can't stop yet..."
  },
  Voice_6068_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_6069_AwakerVoiceContent = {
    Text = "Taste my endless power!"
  },
  Voice_6069_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_6070_AwakerVoiceContent = {
    Text = "Taste my endless power!"
  },
  Voice_6070_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6071_AwakerVoiceContent = {
    Text = "Do you like the sea? I love the sea no matter what. I still remember that day many years ago when the sea gently delivered long-awaited death to the unfortunate me."
  },
  Voice_6071_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_6073_AwakerVoiceContent = {
    Text = "I just felt a sense of pleasure like never before... for some reason..."
  },
  Voice_6073_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_6074_AwakerVoiceContent = {
    Text = "This undercurrent will tear our enemies apart."
  },
  Voice_6074_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6075_AwakerVoiceContent = {
    Text = "This undercurrent will tear our enemies apart."
  },
  Voice_6075_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_6076_AwakerVoiceContent = {
    Text = "I've been waiting for someone to teach me true love, pain, and desire. Can you fulfill my wish? Can you redeem me from this dark prison?"
  },
  Voice_6076_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_6076_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_6077_AwakerVoiceContent = {
    Text = "Do you want to know the truth? I hate prison, hate the darkness, and hate it so much that I could die. I want to be noticed. I want to be ignited..."
  },
  Voice_6077_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_6077_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_6078_AwakerVoiceContent = {
    Text = "All of this is for the eternal well-being of the future."
  },
  Voice_6078_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_6079_AwakerVoiceContent = {
    Text = "Want to enjoy me? Then become my slave. I'll make you melt with heat~"
  },
  Voice_6079_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_6079_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_6080_AwakerVoiceContent = {
    Text = "Fine. I shall consider it a subject's humble offering."
  },
  Voice_6080_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_6081_AwakerVoiceContent = {
    Text = "I'm so bored! Compared to those trembling big prisoners, this is just like playing house. Why don't you keep me company~"
  },
  Voice_6081_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_6081_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_6082_AwakerVoiceContent = {
    Text = "I want more slaves, I wanna hear their moans and pleas—Bring me more slaves, pretty please?"
  },
  Voice_6082_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_6082_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_6083_AwakerVoiceContent = {
    Text = "Forgive me, I lost myself in memories again. Please, do not look sad. It is your turn to narrate your story. Do you feel like writing a poem? Will your adventures, your experiences, your joys, your sorrows, flow like a gentle stream from your mind to your fingertips?"
  },
  Voice_6083_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_6083_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_6084_AwakerVoiceContent = {
    Text = "I was but a fleeting watermark on parchment, yet our encounter has caused me to linger. Perhaps this is a miracle. I will treasure this miracle and compose timeless poems for you."
  },
  Voice_6084_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_6084_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_6085_AwakerVoiceContent = {
    Text = "Someone once told me that poetry is written to be appreciated... May I hear your thoughts on this?"
  },
  Voice_6085_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_6085_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_6086_AwakerVoiceContent = {
    Text = "Have you ever felt this? Offering forgiveness for another's offense, only for the desired outcome to slip away. You extend a rose, yet your hands are left not with its lingering fragrance, but only the bloody marks of sharp thorns."
  },
  Voice_6086_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_6086_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_6087_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_6088_AwakerVoiceContent = {
    Text = "My pen and ink..."
  },
  Voice_6088_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_6089_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_6089_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_6090_AwakerVoiceContent = {
    Text = "This is the wrong rhyme..."
  },
  Voice_6090_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_6091_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_6091_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_6092_AwakerVoiceContent = {
    Text = "This is a blessing from the Great One!"
  },
  Voice_6092_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6093_AwakerVoiceContent = {
    Text = "Blessing of the Great Pale One..."
  },
  Voice_6093_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_6094_AwakerVoiceContent = {
    Text = "I have no time for rest. The Dissolution has already claimed two of my bodies. Before the inevitable end catches up, there is much I must comprehend... Assist me, starting with the preparation of experimental materials. I trust you won't miscalculate the balance."
  },
  Voice_6094_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_6094_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_6095_AwakerVoiceContent = {
    Text = "I love the stained glass at Fontainebleau. It casts different shades on people's faces: despairing purple, flattering blue, and, of course, my favorite—ambitious red..."
  },
  Voice_6095_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_6096_AwakerVoiceContent = {
    Text = "Here, I often sense the presence of my Lord, but perhaps I am not yet ready to face Him... In any case, thank you for offering me shelter."
  },
  Voice_6096_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_6097_AwakerVoiceContent = {
    Text = "Betrayal turns people into monsters, no matter which side they are on. That's why I detest traitors."
  },
  Voice_6097_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_60985_AwakerVoiceContent = {
    Text = "Hameln, at your service."
  },
  Voice_60985_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_60986_AwakerVoiceContent = {
    Text = [[
I once met someone with an almost instinctual understanding of music. The concertos and symphonies created by this person were unforgettable.
A true genius.]]
  },
  Voice_60986_AwakerVoiceTitle = {
    Text = "Chat: About His Friend"
  },
  Voice_60987_AwakerVoiceContent = {
    Text = "I don't enjoy spending time on strategy. Compared to music, the art of strategy holds little value. However, as a tool to clear obstacles, it is necessary. For the sake of reaching the pinnacle of music, I don't mind using it."
  },
  Voice_60987_AwakerVoiceTitle = {
    Text = "Chat: About His Strategies"
  },
  Voice_60988_AwakerVoiceContent = {Text = "Rude."},
  Voice_60988_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_60989_AwakerVoiceContent = {
    Text = "Here it is again. What is this melody? Ever since I last heard it, it has lingered in my mind, refusing to leave or rest."
  },
  Voice_60989_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_60989_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_6098_AwakerVoiceContent = {
    Text = "An astute observation!"
  },
  Voice_6098_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_60990_AwakerVoiceContent = {
    Text = "In terms of technique, strategic planning and music conducting are no different. Humanity, emotion, desire... they are as clear and docile as notes on a staff, displayed before my eyes, dancing along the path of the baton. To understand music is to understand everything."
  },
  Voice_60990_AwakerVoiceTitle = {
    Text = "Chat: About Your Commonalities"
  },
  Voice_60991_AwakerVoiceContent = {
    Text = "Almost there, just a little more. I must finish it; I must hear it!"
  },
  Voice_60991_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_60991_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_60992_AwakerVoiceContent = {Text = "Ugh."},
  Voice_60992_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_60993_AwakerVoiceContent = {Text = "Rude."},
  Voice_60993_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_60994_AwakerVoiceContent = {Text = "Hmm."},
  Voice_60994_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_60995_AwakerVoiceContent = {
    Text = "Music transcends language, writing, and everything. If this isn't perfection, I don't know what is."
  },
  Voice_60995_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_60995_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_60996_AwakerVoiceContent = {
    Text = "Pay attention to the beat."
  },
  Voice_60996_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_60997_AwakerVoiceContent = {
    Text = "Tuning complete."
  },
  Voice_60997_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_60998_AwakerVoiceContent = {
    Text = "Glad you understand the importance of training."
  },
  Voice_60998_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_60999_AwakerVoiceContent = {
    Text = "I will deliver a perfect performance."
  },
  Voice_60999_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_6099_AwakerVoiceContent = {
    Text = "Envious? These tough scales are proof of a noble lineage."
  },
  Voice_6099_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_61000_AwakerVoiceContent = {
    Text = [[
I was once praised, but... that wasn't true talent.
My works were merely imitations of my predecessors.]]
  },
  Voice_61000_AwakerVoiceTitle = {
    Text = "Chat: About His Works"
  },
  Voice_61001_AwakerVoiceContent = {
    Text = "Woodwinds and strings... interweaving upwards and downwards, the motif reappears... Now I remember, it's the requiem I composed for the prematurely deceased genius, the fallen star."
  },
  Voice_61001_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_61001_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_61002_AwakerVoiceContent = {
    Text = "Hmm? Do you have a new piece to show me?"
  },
  Voice_61002_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_61003_AwakerVoiceContent = {
    Text = "This melody is dedicated to the souls of the departed."
  },
  Voice_61003_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_61004_AwakerVoiceContent = {
    Text = [[
The green dancer possessed an elegance worthy of being the lead of a court troupe.
If given the chance, I truly hope we could collaborate.]]
  },
  Voice_61004_AwakerVoiceTitle = {
    Text = "Chat: About Liz"
  },
  Voice_61004_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Liz\""
  },
  Voice_61005_AwakerVoiceContent = {Text = "Arioso!"},
  Voice_61005_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_61006_AwakerVoiceContent = {
    Text = "There is a concertmaster in the orchestra, but a concertmaster alone cannot make a complete orchestra. My orchestra has no place for those who only seek to show off."
  },
  Voice_61006_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_61007_AwakerVoiceContent = {
    Text = "I think I heard a melody. Is someone rehearsing nearby?"
  },
  Voice_61007_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_61007_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_61008_AwakerVoiceContent = {Text = "Dal Segno!"},
  Voice_61008_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_61009_AwakerVoiceContent = {Text = "Da Capo!"},
  Voice_61009_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_6100_AwakerVoiceContent = {
    Text = "Prepare to meet your doom!"
  },
  Voice_6100_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_61010_AwakerVoiceContent = {
    Text = "Yes, yes, that's it—the final mass, a requiem for the music itself!"
  },
  Voice_61010_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_61010_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_61011_AwakerVoiceContent = {
    Text = "Ah, Keeper, you've arrived just in time. Tell me, what do you think of this movement?"
  },
  Voice_61011_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_61012_AwakerVoiceContent = {
    Text = "Strings, begin."
  },
  Voice_61012_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_61013_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_61014_AwakerVoiceContent = {
    Text = "It became clear, that winding melody, like the wailing of a soul... I'm sure I've heard it somewhere before."
  },
  Voice_61014_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_61014_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_61015_AwakerVoiceContent = {
    Text = "Rationality and order paved the way. I walked upward and opened the gates of the hall. Beyond them, neither remained— truly eternal music transcends reason."
  },
  Voice_61015_AwakerVoiceTitle = {
    Text = "Chat: About Reason and Order"
  },
  Voice_61016_AwakerVoiceContent = {
    Text = "Watch my hands, one, two, three."
  },
  Voice_61016_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_61017_AwakerVoiceContent = {
    Text = "I heard the performance of your so-called orchestra, full of mistakes. But no worries, I have a detailed plan to stage a perfect show before the Silver Frost Festival."
  },
  Voice_61017_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_61018_AwakerVoiceContent = {
    Text = "I can never forget the first time I heard the music deep within my consciousness. In those notes and chords, the real world vanished; only pure and sublime music remained."
  },
  Voice_61018_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_61019_AwakerVoiceContent = {
    Text = "It's a pity. It seems more rehearsals are needed."
  },
  Voice_61019_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_6101_AwakerVoiceContent = {
    Text = "This is an order."
  },
  Voice_6101_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_61020_AwakerVoiceContent = {
    Text = "I usually don't extend such invitations, but... would you like to give it a try? Hold the baton and breathe new life into the music?"
  },
  Voice_61020_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_61020_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_61021_AwakerVoiceContent = {
    Text = "I prefer expressing myself through music rather than words. But communicating with you feels like conducting an orchestra that has been rehearsed countless times—smooth, and often pleasantly surprising.\nYou hold a special place for both music and me."
  },
  Voice_61021_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_61021_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_61022_AwakerVoiceContent = {
    Text = [[
In a symphony, the coordination between instruments is crucial; how each section joins and exits brings a different experience to the music.
What I mean is, if commanding Awakeners is a performance, you're doing well.]]
  },
  Voice_61022_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_61022_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_61023_AwakerVoiceContent = {
    Text = "Do you like this piece? It fully presents the motif in just four measures, with the wind instruments pushing the melody upward until the theme is reached. Such a design has influenced countless successors... Sorry, am I talking too much?"
  },
  Voice_61023_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_61023_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_61024_AwakerVoiceContent = {
    Text = "Perfect performance."
  },
  Voice_61024_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_61025_AwakerVoiceContent = {Text = "Forte!"},
  Voice_61025_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_61026_AwakerVoiceContent = {Text = "Accent!"},
  Voice_61026_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_61027_AwakerVoiceContent = {
    Text = "Each of us hides a melody in our hearts, trapped by reason and the body, only to be fully expressed in madness."
  },
  Voice_61027_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_61028_AwakerVoiceContent = {
    Text = "Only music deserves praise."
  },
  Voice_61028_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_61029_AwakerVoiceContent = {
    Text = "Only music deserves praise."
  },
  Voice_61029_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_6102_AwakerVoiceContent = {Text = "Go."},
  Voice_6102_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_61030_AwakerVoiceContent = {
    Text = "Listen, this is the final requiem!"
  },
  Voice_61030_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_6103_AwakerVoiceContent = {
    Text = "Beg for mercy!"
  },
  Voice_6103_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_61049_AwakerVoiceContent = {
    Text = "Listen, this is the final requiem!"
  },
  Voice_61049_AwakerVoiceTitle = {
    Text = "Over-Exalt: II"
  },
  Voice_6104_AwakerVoiceContent = {Text = "(Groan)"},
  Voice_6104_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_6105_AwakerVoiceContent = {
    Text = "Do you also wish to be consumed by the green flames?"
  },
  Voice_6105_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_6106_AwakerVoiceContent = {
    Text = "I am neither mad nor have I ever felt sorrow. Please do not believe absurd rumors."
  },
  Voice_6106_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_6107_AwakerVoiceContent = {
    Text = "How dare you look elsewhere!"
  },
  Voice_6107_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_6108_AwakerVoiceContent = {Text = "Focus!"},
  Voice_6108_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_6109_AwakerVoiceContent = {
    Text = "Aww, you've got such a precious boy here! I asked him if he'd like to become my devoted slave, and he blushed, stammering so sweetly about having sworn his loyalty to you... As if true devotion can't be shared!"
  },
  Voice_6109_AwakerVoiceTitle = {
    Text = "Chat: About Ogier"
  },
  Voice_6109_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Ogier\""
  },
  Voice_6110_AwakerVoiceContent = {
    Text = "Don't think you can get close to me."
  },
  Voice_6110_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_6111_AwakerVoiceContent = {
    Text = "Accept your destiny."
  },
  Voice_6111_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_6112_AwakerVoiceContent = {
    Text = "The gates of my homeland are drifting away... No... Not again..."
  },
  Voice_6112_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_6113_AwakerVoiceContent = {
    Text = "Out of my way!"
  },
  Voice_6113_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6114_AwakerVoiceContent = {
    Text = "Out of my way!"
  },
  Voice_6114_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_6115_AwakerVoiceContent = {
    Text = "Pay the price for your actions."
  },
  Voice_6115_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_6116_AwakerVoiceContent = {
    Text = "Do you have a death wish?"
  },
  Voice_6116_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_6117_AwakerVoiceContent = {
    Text = "I think I've been afflicted with Dissolution again... My heart is getting Dissoluted! Just a few aspirins, a whip, and some pain should do the trick to cure me..."
  },
  Voice_6117_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_6118_AwakerVoiceContent = {
    Text = "Even you can't cure this darn rot? Then why are you chasing Dissolution? You're barking mad."
  },
  Voice_6118_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_6119_AwakerVoiceContent = {
    Text = "I am the last Roman warrior—Uvhash!"
  },
  Voice_6119_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6120_AwakerVoiceContent = {Text = "(Groan)"},
  Voice_6120_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_6121_AwakerVoiceContent = {
    Text = "I am the last Roman warrior—Uvhash!"
  },
  Voice_6121_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_6122_AwakerVoiceContent = {
    Text = "Dissolution...? Of course, I know! It just means the slave's leash is broken. What's so hard about that?"
  },
  Voice_6122_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_6123_AwakerVoiceContent = {
    Text = "I have been called; the line between god and supplicant now bleeds."
  },
  Voice_6123_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_6123_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_6124_AwakerVoiceContent = {
    Text = "Hmm... You're getting better at massaging. Nice application of pressure~"
  },
  Voice_6124_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_6125_AwakerVoiceContent = {
    Text = "Isn't the decor here too outdated? It's eerie, as if it's haunted."
  },
  Voice_6125_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_6126_AwakerVoiceContent = {
    Text = "Here are lush plants, tranquil air, and a remedy for my sister's illness. For the two of us, it is the most wonderful new home."
  },
  Voice_6126_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_6127_AwakerVoiceContent = {
    Text = "I never expected to see Faint again... I wonder how she has been doing since then. No matter how I ask, she only reassures me she's fine... Sigh. Ah, excuse me, I got carried away. I should thank you for reuniting us first."
  },
  Voice_6127_AwakerVoiceTitle = {
    Text = "Chat: About Faint"
  },
  Voice_6127_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Faint\""
  },
  Voice_6128_AwakerVoiceContent = {
    Text = "An offering to His will."
  },
  Voice_6128_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_6129_AwakerVoiceContent = {
    Text = "An offering to His will."
  },
  Voice_6129_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6130_AwakerVoiceContent = {
    Text = "Calm down, calm down..."
  },
  Voice_6130_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6131_AwakerVoiceContent = {
    Text = "There are many \"me\" inside. Happy, sad, angry... They love sponge cake, hate Londinium's rainy days. They all go by \"24,\" and they all adore you."
  },
  Voice_6131_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_6131_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_6132_AwakerVoiceContent = {
    Text = "I used to work until midnight every day—spinning, washing, cleaning, babysitting, even scavenging... I would do anything to earn money. Back then, living was merely surviving. Now, we have fresh food, warm bed, and a kind master like you... It's beyond my wildest dreams."
  },
  Voice_6132_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_6132_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_6133_AwakerVoiceContent = {
    Text = "Please don't worry. We'll all share a steak and a bed, and never cause you any trouble."
  },
  Voice_6133_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_6133_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_6134_AwakerVoiceContent = {
    Text = "Heh, that woman is so scared of me coming out that she doesn't even dare to sleep at night. Relax, I wouldn't kill you—not while you're giving me gifts. Who am I? Of course, I'm \"24,\" hahaha!"
  },
  Voice_6134_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_6134_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_6135_AwakerVoiceContent = {
    Text = "I feel fantastic right now. What? You say my mind has been taken over by something else? N-no way... uh..."
  },
  Voice_6135_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_6135_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_6136_AwakerVoiceContent = {
    Text = "For a subject, you observe keenly. Before my next long sleep, I shall... grace this era with my presence."
  },
  Voice_6136_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_6137_AwakerVoiceContent = {
    Text = "Hmm... the sea water is quite warm tonight..."
  },
  Voice_6137_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_6138_AwakerVoiceContent = {
    Text = "It has arrived... the white bird circling in my dream."
  },
  Voice_6138_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_6139_AwakerVoiceContent = {
    Text = "As you wished, my existence has grown more tangible."
  },
  Voice_6139_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_6140_AwakerVoiceContent = {
    Text = "So satisfying, ahaha!"
  },
  Voice_6140_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_6141_AwakerVoiceContent = {Text = "Sweet!"},
  Voice_6141_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6142_AwakerVoiceContent = {
    Text = "Leave it to me!"
  },
  Voice_6142_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_6143_AwakerVoiceContent = {
    Text = "Leave it to me!"
  },
  Voice_6143_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6144_AwakerVoiceContent = {
    Text = "Welcome—to our grand feast!"
  },
  Voice_6144_AwakerVoiceTitle = {
    Text = "Exalt: Mania"
  },
  Voice_6145_AwakerVoiceContent = {
    Text = "This girl... her veins undoubtedly carry my blood. No—I have not walked this earth long enough to sire progeny. And yet... her power mirrors my own."
  },
  Voice_6145_AwakerVoiceTitle = {
    Text = "Chat: About the Divine Bloodline"
  },
  Voice_6145_UnlockDesc = {
    Text = "Unlocks after acquiring either Awakener \"Aigis\" or \"Murphy\""
  },
  Voice_6146_AwakerVoiceContent = {
    Text = "Master's kindness, Karen dares not forget even for a moment!"
  },
  Voice_6146_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_6147_AwakerVoiceContent = {
    Text = "—Ah, it's so sweet and delicious!"
  },
  Voice_6147_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_6148_AwakerVoiceContent = {
    Text = "Well... I'm on a diet and can't eat too much today~"
  },
  Voice_6148_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_6149_AwakerVoiceContent = {
    Text = "These weaklings aren't even worth my blade."
  },
  Voice_6149_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_6150_AwakerVoiceContent = {
    Text = "Explaining art is as ridiculous as explaining railroad stocks—please don't make life harder for us artists."
  },
  Voice_6150_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_6151_AwakerVoiceContent = {
    Text = "Aigis... Did I do something wrong?"
  },
  Voice_6151_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_6152_AwakerVoiceContent = {
    Text = "Your prayers have been heard."
  },
  Voice_6152_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_6153_AwakerVoiceContent = {
    Text = "Your prayers have been heard."
  },
  Voice_6153_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6154_AwakerVoiceContent = {
    Text = "Hmph. Insolent crudes."
  },
  Voice_6154_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_6155_AwakerVoiceContent = {
    Text = "Ah, was that Mr. N who just walked us by? No, never mind. The last time I greeted him, he didn't recognize me... I waited for him in prison, hoping he would take me away, but he never came, not even during the riot."
  },
  Voice_6155_AwakerVoiceTitle = {
    Text = "Chat: About \"N\""
  },
  Voice_6155_UnlockDesc = {
    Text = "Unlocks after completing Main Story Chapter 7"
  },
  Voice_6156_AwakerVoiceContent = {
    Text = "Why did I answer your call? To finish what I started, of course. And if you grow strong enough to challenge me, that's just a bonus."
  },
  Voice_6156_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_6157_AwakerVoiceContent = {
    Text = [[
I've got Sis, Brown, plus that coward girl from the workhouse... That's my crew. Fine... I'll count you in too. Brown, share a scrap of candy with {Male=him,Female=her}. 
"Squeak?!"]]
  },
  Voice_6157_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_6157_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_6158_AwakerVoiceContent = {
    Text = "The East Slums are no place for kids. Cunning old foremen would find every way to dock paperboys' pay, and n-nitpick milk boys' speed! To survive out there, you only rely on yourself. No one else is worth trusting."
  },
  Voice_6158_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_6158_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_6159_AwakerVoiceContent = {
    Text = "My \"bad habits\" ain't changing overnight, get that? Sleeping under bridges and in drains, surviving on scraps—it was hard enough just to stay alive... You can't expect me to make my bed right after waking up! Give me at least two weeks to adjust!"
  },
  Voice_6159_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_6159_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_6160_AwakerVoiceContent = {
    Text = [[
Getting lost in space made me sick to my stomach. You pulled me out, so just spit out what you need, but don't expect miracles.
I'm just a kid, you wouldn't push me too hard, would you?]]
  },
  Voice_6160_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_6160_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_6161_AwakerVoiceContent = {
    Text = "Hey, West-Whelp! Seen Brown? That little glutton's sniffed out grub again."
  },
  Voice_6161_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_6161_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_6162_AwakerVoiceContent = {
    Text = "Those with strength must not use their power to oppress others, for you all share my blood.\" I remember the teachings of our Father God of Compassion. I will use this strength only to protect those around me."
  },
  Voice_6162_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_6162_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_6163_AwakerVoiceContent = {
    Text = "Curious what I saw at the universe's beginning? Sure, I can tell you. I saw nothing."
  },
  Voice_6163_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_6163_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_6164_AwakerVoiceContent = {
    Text = "It's getting brighter."
  },
  Voice_6164_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_6165_AwakerVoiceContent = {
    Text = "The everlasting lamp..."
  },
  Voice_6165_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_6166_AwakerVoiceContent = {
    Text = "My connection to the homeland has grown stronger."
  },
  Voice_6166_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_6167_AwakerVoiceContent = {
    Text = "If I can free this world from its suffering, I shall be content."
  },
  Voice_6167_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_6168_AwakerVoiceContent = {
    Text = "Give me your commands, Pale Messenger. May your flames ever light my path."
  },
  Voice_6168_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_6169_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_6169_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_6170_AwakerVoiceContent = {
    Text = "The tempering of a person involves not just the body, but the heart as well."
  },
  Voice_6170_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_6171_AwakerVoiceContent = {Text = "(Groan)"},
  Voice_6171_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_6172_AwakerVoiceContent = {Text = "Ouch!"},
  Voice_6172_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_6173_AwakerVoiceContent = {Text = "(Groan)"},
  Voice_6173_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_6174_AwakerVoiceContent = {
    Text = "Ugh! Your temperature is a bit high for coral. But... it's warm and intense. I like it."
  },
  Voice_6174_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_6175_AwakerVoiceContent = {
    Text = "Lah... Oh, do you need something? If possible, let's talk backstage."
  },
  Voice_6175_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_6176_AwakerVoiceContent = {
    Text = "Withering before blooming, like a water-lily... Seeking peace in the cold, raging tides, too timid to pursue my own happiness... That is the kind of person I am, Keeper."
  },
  Voice_6176_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_6176_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_6177_AwakerVoiceContent = {
    Text = "I once grappled with this dilemma: Is pain longer than life itself? If so, is a peaceful slumber happier than tormented wakefulness? After waking, I too was ensnared, until you brought me this safe haven..."
  },
  Voice_6177_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_6177_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_6178_AwakerVoiceContent = {
    Text = "During my time at the sanatorium, I tried making friends, but people were reluctant to approach me... Is it because of this bone-eroding \"poison\"? Please, be careful when you come near me."
  },
  Voice_6178_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_6178_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_6179_AwakerVoiceContent = {
    Text = "The sound of the bell carried by the night wind brings such peace. Would you like to sit on the stone chair and listen for a while? I will properly prepare your seat with a scarf."
  },
  Voice_6179_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_6179_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_6180_AwakerVoiceContent = {
    Text = "Have you heard of \"sea burial\"? In my old town, there was a custom of submerging the deceased into the sea; the ocean became everyone's final resting place. As for me, I returned to its embrace early..."
  },
  Voice_6180_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_6180_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_6181_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_6181_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_6182_AwakerVoiceContent = {Text = "Aah!"},
  Voice_6182_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_6183_AwakerVoiceContent = {Text = "Argh!"},
  Voice_6183_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_6184_AwakerVoiceContent = {Text = "Aah!"},
  Voice_6184_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_6185_AwakerVoiceContent = {
    Text = "The combat log has been archived. Thank you for your hard work, Keeper."
  },
  Voice_6185_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_6186_AwakerVoiceContent = {Text = "(Groan)"},
  Voice_6186_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_6187_AwakerVoiceContent = {Text = "(Groan)"},
  Voice_6187_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_6188_AwakerVoiceContent = {Text = "(Groan)"},
  Voice_6188_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_6189_AwakerVoiceContent = {
    Text = "I can keep going."
  },
  Voice_6189_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_6190_AwakerVoiceContent = {
    Text = "Guests at my salon receive the finest hospitality... As an entry ticket, have you prepared secrets worthy of this grand banquet?"
  },
  Voice_6190_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6191_AwakerVoiceContent = {
    Text = "I love new things. Over my millennia of travels, I have witnessed many fascinating innovations and inventions, such as poetic forms and cinematic scenes. Humans are truly intriguing creatures."
  },
  Voice_6191_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_6192_AwakerVoiceContent = {
    Text = "Yes. Lily remembers. Lily stayed at her house when Mommy was out."
  },
  Voice_6192_AwakerVoiceTitle = {
    Text = "Chat: About Daffodil"
  },
  Voice_6192_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Daffodil\""
  },
  Voice_6193_AwakerVoiceContent = {Text = "Oh."},
  Voice_6193_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_6194_AwakerVoiceContent = {Text = "Hmm...?"},
  Voice_6194_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_6195_AwakerVoiceContent = {
    Text = "Who dares disturb This One's slumber?"
  },
  Voice_6195_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6196_AwakerVoiceContent = {
    Text = "Gods? Only fools would entrust their lives to such intangible beings. Instead of betting your life on the so-called gods, you'd be better off focusing on how to become stronger."
  },
  Voice_6196_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_6197_AwakerVoiceContent = {
    Text = "That \"slave master\", \"owner of gladiators\"... Ha. She is just a worthless insect."
  },
  Voice_6197_AwakerVoiceTitle = {
    Text = "Chat: About Agrippa"
  },
  Voice_6197_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Agrippa\""
  },
  Voice_6198_AwakerVoiceContent = {
    Text = "After the victory, please allow me to take the materials needed for reproduction."
  },
  Voice_6198_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_6199_AwakerVoiceContent = {
    Text = "Big friend! Partner! Hoo-hoo, let's be best friends forever, okay?"
  },
  Voice_6199_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_6200_AwakerVoiceContent = {
    Text = "I'm really, really excited right now... If you still want to live, better stay away from me."
  },
  Voice_6200_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_6201_AwakerVoiceContent = {
    Text = "Is... Is it really okay for her to treat others like that? Ms. Sarah said kids shouldn't throw tantrums..."
  },
  Voice_6201_AwakerVoiceTitle = {
    Text = "Chat: About Murphy"
  },
  Voice_6201_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Murphy\""
  },
  Voice_6202_AwakerVoiceContent = {
    Text = "The glory of victory is yours, my lord."
  },
  Voice_6202_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_6203_AwakerVoiceContent = {
    Text = "P-Please, I'm all filled up~"
  },
  Voice_6203_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_6204_AwakerVoiceContent = {
    Text = "The void within has been filled~"
  },
  Voice_6204_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_6205_AwakerVoiceContent = {
    Text = "Yes, I'm getting hotter..."
  },
  Voice_6205_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_6206_AwakerVoiceContent = {
    Text = "I know that child. She sometimes stands far away, watching my performance. It's good that she doesn't come closer, otherwise my little audience will be mentally and physically exhausted!"
  },
  Voice_6206_AwakerVoiceTitle = {
    Text = "Chat: About Faint"
  },
  Voice_6206_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Faint\""
  },
  Voice_6207_AwakerVoiceContent = {
    Text = "Tinct said, \"Repay kindness.\" So, as long as it is within my ability to help, I will lend a hand..."
  },
  Voice_6207_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_6208_AwakerVoiceContent = {
    Text = "Hello, Keeper. How may I assist you?"
  },
  Voice_6208_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_6209_AwakerVoiceContent = {
    Text = "One day, I will return to the battlefield as the leader at the vanguard."
  },
  Voice_6209_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_6209_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_6210_AwakerVoiceContent = {
    Text = "Can you believe it? I can feel my broken leg bone healing."
  },
  Voice_6210_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_6210_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_6211_AwakerVoiceContent = {
    Text = "Thank you sincerely for your trust in training me to this level. You must also be someone who pursues justice; thus, I will continue to bring glory to our cause here."
  },
  Voice_6211_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_6211_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_6212_AwakerVoiceContent = {
    Text = "The day is fast approaching for another expedition, and my blood is boiling with purpose."
  },
  Voice_6212_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_6212_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_6213_AwakerVoiceContent = {
    Text = "The honor of being a warrior is being restored."
  },
  Voice_6213_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_6213_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_6214_AwakerVoiceContent = {Text = "(Groan)"},
  Voice_6214_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_6215_AwakerVoiceContent = {Text = "Ouch!"},
  Voice_6215_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_6216_AwakerVoiceContent = {Text = "(Groan)"},
  Voice_6216_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_6217_AwakerVoiceContent = {Text = "Cheater!"},
  Voice_6217_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_6218_AwakerVoiceContent = {
    Text = "Whoops, my bad! I'll make it happen next time, promise!"
  },
  Voice_6218_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_6219_AwakerVoiceContent = {
    Text = "I hear someone calling my name: Agrippa, Agrippa, Agrippina..."
  },
  Voice_6219_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_6219_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_6220_AwakerVoiceContent = {
    Text = "I saw... It climbing up from the darkness of the well; countless eyes appearing on its flesh egg. They stared at me, calling me... Maze God!"
  },
  Voice_6220_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_6220_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_6221_AwakerVoiceContent = {
    Text = "I have a very strong urge to watch a duel... It would be even better if it was in a maze!"
  },
  Voice_6221_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_6221_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_6222_AwakerVoiceContent = {
    Text = "Contract... Yes, I want to sign a contract with you; an everlasting master-servant contract..."
  },
  Voice_6222_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_6222_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_6223_AwakerVoiceContent = {
    Text = "Hmph... Not bad. Give me more. I need to feed these little spiderlings."
  },
  Voice_6223_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_6223_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_6224_AwakerVoiceContent = {
    Text = "What filth, what abomination! Ah—stop it! Please! Don't make me see it, don't speak of it near me..."
  },
  Voice_6224_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_6225_AwakerVoiceContent = {
    Text = "My past was routine and calm, like the seas near the equator; there is nothing worth mentioning."
  },
  Voice_6225_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_6225_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_6226_AwakerVoiceContent = {
    Text = "Hmm...? Mommy, uppies? ...You're so warm..."
  },
  Voice_6226_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_6227_AwakerVoiceContent = {
    Text = "O Stardust..."
  },
  Voice_6227_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_6228_AwakerVoiceContent = {
    Text = "Aww, are we quite lost?"
  },
  Voice_6228_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6229_AwakerVoiceContent = {Text = "Useless."},
  Voice_6229_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_6230_AwakerVoiceContent = {
    Text = "Whenever I recall those traitors kneeling and crying for mercy, I feel a wave of satisfaction, and the flames in my heart seem to subside."
  },
  Voice_6230_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_6231_AwakerVoiceContent = {
    Text = "I was brought to the ship and entrusted with the mission of the ship's maiden many years ago. Since then, my life—and its meaning—have been beyond my control. I've been told that I should live for my own wishes, at least in this second life as an Awakener... Would you help me? Help me become selfish, help me find my own wish."
  },
  Voice_6231_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_6231_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_6232_AwakerVoiceContent = {
    Text = "It's Agrippa. I have nothing to say to you—unless you dare to volunteer as my gladiator."
  },
  Voice_6232_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6233_AwakerVoiceContent = {
    Text = "Tawil... she is far more dangerous than we realize. When I'm no longer here, you must be extremely cautious of her."
  },
  Voice_6233_AwakerVoiceTitle = {
    Text = "Chat: About Tawil"
  },
  Voice_6235_AwakerVoiceContent = {
    Text = "With this deductive reasoning device... I shall interpret the world!"
  },
  Voice_6235_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6236_AwakerVoiceContent = {
    Text = "With this deductive reasoning device... I shall interpret the world!"
  },
  Voice_6236_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_6237_AwakerVoiceContent = {
    Text = "Shine for me!"
  },
  Voice_6237_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6238_AwakerVoiceContent = {
    Text = "To the best of my ability."
  },
  Voice_6238_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6239_AwakerVoiceContent = {
    Text = "To the best of my ability."
  },
  Voice_6239_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_6240_AwakerVoiceContent = {
    Text = "We shall decay... together."
  },
  Voice_6240_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6241_AwakerVoiceContent = {
    Text = "We shall decay... together."
  },
  Voice_6241_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_6242_AwakerVoiceContent = {
    Text = "Smiles and etiquette serve as a layer of armor, helping me maintain distance from others and avoid tedious disturbances. As for my true self... I don't mind showing it to you."
  },
  Voice_6242_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_6242_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_6243_AwakerVoiceContent = {
    Text = "My thoughts accumulate like white limestone and are washed into beautiful coral. They merge with me, pulsing with my heartbeat... Will you listen?"
  },
  Voice_6243_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_6243_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_6244_AwakerVoiceContent = {
    Text = "Inspiration is like bubbles rising in the sea: a gentle touch, and they vanish. Are you the same?"
  },
  Voice_6244_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_6244_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_6245_AwakerVoiceContent = {
    Text = "War, plunder, and fame are all human desires. The humble sculptor has no interest in what humans pursue; she only wishes to be a slave to beauty."
  },
  Voice_6245_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_6245_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_6246_AwakerVoiceContent = {
    Text = "A wonderful life lies in indulgence. Sometimes, you shouldn't be too hard on yourself."
  },
  Voice_6246_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_6246_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_6247_AwakerVoiceContent = {
    Text = "Just a mere scratch..."
  },
  Voice_6247_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_6248_AwakerVoiceContent = {
    Text = "I still remember the map of the new homeland. It was colorful and beautiful. That's where we should go. We can sing, and we can find happiness."
  },
  Voice_6248_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_6249_AwakerVoiceContent = {Text = "(Groan)"},
  Voice_6249_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_6250_AwakerVoiceContent = {Text = "Blast it!"},
  Voice_6250_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_6251_AwakerVoiceContent = {Text = "(Groan)"},
  Voice_6251_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_6252_AwakerVoiceContent = {
    Text = "Dissolution brings chaos and disasters. Perhaps my homeland sank into the deep sea because of it..."
  },
  Voice_6252_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_6253_AwakerVoiceContent = {Text = "Hah!"},
  Voice_6253_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_6254_AwakerVoiceContent = {Text = "Agh!"},
  Voice_6254_AwakerVoiceTitle = {
    Text = "Special Skill: I"
  },
  Voice_6255_AwakerVoiceContent = {
    Text = "Absolute command."
  },
  Voice_6255_AwakerVoiceTitle = {
    Text = "Special Skill: I"
  },
  Voice_6256_AwakerVoiceContent = {Text = "Try this!"},
  Voice_6256_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_6257_AwakerVoiceContent = {
    Text = "Inevitable sacrifice."
  },
  Voice_6257_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6258_AwakerVoiceContent = {
    Text = "Not bad; this is a warrior's glory!"
  },
  Voice_6258_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_6259_AwakerVoiceContent = {
    Text = "You! How did you let that woman in here?! Set up a perimeter immediately! Keep her at least fifty steps away from me!"
  },
  Voice_6259_AwakerVoiceTitle = {
    Text = "Chat: About Miryam"
  },
  Voice_6259_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Miryam\""
  },
  Voice_6260_AwakerVoiceContent = {
    Text = "The reason to be stronger? In my tribe, the weak are stripped bare, their heads shorn, and subjected to the most vile disgrace imaginable—the cost of weakness is not one that everyone can bear."
  },
  Voice_6260_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_6260_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_6261_AwakerVoiceContent = {
    Text = "Lady Luck, smile on me just this once!"
  },
  Voice_6261_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6262_AwakerVoiceContent = {
    Text = "I guess... human strength has its limits..."
  },
  Voice_6262_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_6263_AwakerVoiceContent = {
    Text = "Good. Less strain, more power."
  },
  Voice_6263_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_6263_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_6264_AwakerVoiceContent = {
    Text = "Is this the manifestation of your desire, to deepen my affection?"
  },
  Voice_6264_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_6264_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_6265_AwakerVoiceContent = {Text = "Revel!"},
  Voice_6265_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6266_AwakerVoiceContent = {Text = "(Yelp)"},
  Voice_6266_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_6267_AwakerVoiceContent = {Text = "(Groan)"},
  Voice_6267_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_6268_AwakerVoiceContent = {Text = "(Yelp)"},
  Voice_6268_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_6269_AwakerVoiceContent = {
    Text = "Ah, unpardonable..."
  },
  Voice_6269_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_6270_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_6271_AwakerVoiceContent = {
    Text = "Wouldn't hurt to be a lil reckless!"
  },
  Voice_6271_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_6272_AwakerVoiceContent = {Text = "Bang!"},
  Voice_6272_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_6273_AwakerVoiceContent = {
    Text = "Keep it up! Your final grades are promising."
  },
  Voice_6273_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_6274_AwakerVoiceContent = {
    Text = "I heard a thief from the slums showed up, bringing along a fat rat? Hehehe... Watch me eliminate this menace for my Master!"
  },
  Voice_6274_AwakerVoiceTitle = {
    Text = "Chat: About Jenkin"
  },
  Voice_6274_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Jenkin\""
  },
  Voice_6275_AwakerVoiceContent = {
    Text = "Come on, take a deep breath—"
  },
  Voice_6275_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6276_AwakerVoiceContent = {
    Text = "Interesting. Your growth in battle far surpasses my expectations. Given time, you might become... Strange. Even after all this time, I still find hope in a creature as seemingly weak as you."
  },
  Voice_6276_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_6276_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_6277_AwakerVoiceContent = {
    Text = "Perhaps now is the time. Listen closely. Lotan, the Beast of the Stars, formally challenges you. Do not fret; I shall ensure your survival until you reach your zenith. I will not allow my chosen opponent to suffer the same fate again."
  },
  Voice_6277_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_6277_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_6278_AwakerVoiceContent = {
    Text = "Hmph... I still can't fathom why Ramona picked you as her partner. You reek of strength, yes, but you're nowhere near my league."
  },
  Voice_6278_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_6278_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_6279_AwakerVoiceContent = {
    Text = "Yes, gaze upon me. I am this planet's most ancient being, demanding reverence from the insignificant. I've guarded this planet for eons. Is a thrilling battle truly too much to ask for in return?"
  },
  Voice_6279_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_6279_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_6280_AwakerVoiceContent = {
    Text = "Hah! I've no time for childish games. Find a corner and stay out of my way."
  },
  Voice_6280_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_6280_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_6281_AwakerVoiceContent = {
    Text = "Souls without protection, I shall grant you final peace."
  },
  Voice_6281_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_6282_AwakerVoiceContent = {Text = "Alert."},
  Voice_6282_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_6283_AwakerVoiceContent = {Text = "Alert."},
  Voice_6283_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_6284_AwakerVoiceContent = {
    Text = "Something is wailing... inside my mind."
  },
  Voice_6284_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_6284_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_6285_AwakerVoiceContent = {
    Text = "It feels like a veil of white mist is clouding my thoughts."
  },
  Voice_6285_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_6285_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_6286_AwakerVoiceContent = {
    Text = "The sound is louder now. The mist thickens."
  },
  Voice_6286_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_6286_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_6287_AwakerVoiceContent = {
    Text = "Is that the sound... of the clock's hands turning?"
  },
  Voice_6287_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_6287_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_6288_AwakerVoiceContent = {
    Text = "When the final bell tolls... will I still be here?"
  },
  Voice_6288_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_6288_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_6289_AwakerVoiceContent = {
    Text = "Such a clumsy trick... Hmph. You naive fool. Did you truly think you could bind me so easily?"
  },
  Voice_6289_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6290_AwakerVoiceContent = {
    Text = "Excuse me... Have you seen my sister, Jenkin? She's a girl who carries a mouse and can be quite fierce... I couldn't possibly mistake her."
  },
  Voice_6290_AwakerVoiceTitle = {
    Text = "Chat: About Jenkin"
  },
  Voice_6290_UnlockDesc = {
    Text = "Unlocks after clearing Main Story Chapter 2"
  },
  Voice_6291_AwakerVoiceContent = {
    Text = "It sounds like something has changed..."
  },
  Voice_6291_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_6291_UnlockDesc = {
    Text = "Unlocked at Enlighten Level 3"
  },
  Voice_6292_AwakerVoiceContent = {
    Text = "Thank you. You're too kind."
  },
  Voice_6292_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_6293_AwakerVoiceContent = {Text = "Ready."},
  Voice_6293_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_6294_AwakerVoiceContent = {
    Text = "Please look forward to my performance."
  },
  Voice_6294_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_6295_AwakerVoiceContent = {
    Text = "I shall sing for you."
  },
  Voice_6295_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_6296_AwakerVoiceContent = {
    Text = "New Keeper? Come on, give it your all. Let's see if you're worthy to face me!"
  },
  Voice_6296_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6297_AwakerVoiceContent = {
    Text = "Although I am a pacifist, \"they\" clearly think otherwise..."
  },
  Voice_6297_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_6298_AwakerVoiceContent = {Text = "Ha!"},
  Voice_6298_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_6299_AwakerVoiceContent = {
    Text = "Stand back!"
  },
  Voice_6299_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_6300_AwakerVoiceContent = {
    Text = "How dare you inflict such humiliation upon me..."
  },
  Voice_6300_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_6301_AwakerVoiceContent = {
    Text = "Ready? Casiah's magic show is about to begin! Don't look away, you don't want to miss the highlights. It's showtime!"
  },
  Voice_6301_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6302_AwakerVoiceContent = {
    Text = "Tekeli—Li!"
  },
  Voice_6302_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_6303_AwakerVoiceContent = {Text = "Ha!"},
  Voice_6303_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_6304_AwakerVoiceContent = {
    Text = [[
I got your schedule from Sylvia, and it's too demanding for newcomers. I understand you're doing the right thing, but overburdening rookies might cause unnecessary trouble for the team.
You say you're not a rookie? No, I can tell by the look in your eyes; there are many things you haven't experienced yet.]]
  },
  Voice_6304_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_6304_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_6305_AwakerVoiceContent = {
    Text = "I truly dislike my own failures... Oh! There's no need to comfort me! Those past hurts have become what drives me to grow. Haven't I already become your steadfast support?"
  },
  Voice_6305_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_6306_AwakerVoiceContent = {
    Text = "I just can't get along with that guy. Life isn't all about sin and punishment, is it? What's wrong with seizing the moment?"
  },
  Voice_6306_AwakerVoiceTitle = {
    Text = "Chat: About Salvador"
  },
  Voice_6306_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Salvador\""
  },
  Voice_6307_AwakerVoiceContent = {
    Text = "Time is limited. Let's move."
  },
  Voice_6307_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_6308_AwakerVoiceContent = {
    Text = "I hate candles that go out easily, black bread, and loose threads on skirts... No reason, I simply detest them. Isn't that natural?"
  },
  Voice_6308_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_6309_AwakerVoiceContent = {
    Text = "Since you have crowned me your Holy Maiden, you will submit!"
  },
  Voice_6309_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6310_AwakerVoiceContent = {
    Text = "Since you have crowned me your Holy Maiden, you will submit!"
  },
  Voice_6310_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_6311_AwakerVoiceContent = {
    Text = "Sing for me."
  },
  Voice_6311_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_6312_AwakerVoiceContent = {
    Text = "\"The Lady's Wardrobe\" and \"The Working Woman's Guide\" are both excellent reads... Though I can't afford those beautiful dresses, simply admiring them is fun."
  },
  Voice_6312_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_6313_AwakerVoiceContent = {
    Text = "It's strange. I usually have a hard time remembering things, but I memorized you in just a few days... What? It's been three months already? I'm sorry, I forgot again."
  },
  Voice_6313_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_6314_AwakerVoiceContent = {Text = "Savor it."},
  Voice_6314_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_6315_AwakerVoiceContent = {
    Text = "Sleep well..."
  },
  Voice_6315_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_6316_AwakerVoiceContent = {
    Text = "Keep improving your composure."
  },
  Voice_6316_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_6317_AwakerVoiceContent = {
    Text = "Fouette. Twenty more times."
  },
  Voice_6317_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_6318_AwakerVoiceContent = {
    Text = "Are my movements accurate enough?"
  },
  Voice_6318_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_6319_AwakerVoiceContent = {
    Text = "Please go ahead!"
  },
  Voice_6319_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_6320_AwakerVoiceContent = {
    Text = "Hurry, grab Brown and scram!"
  },
  Voice_6320_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_6321_AwakerVoiceContent = {
    Text = "Kneel before the throne."
  },
  Voice_6321_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6322_AwakerVoiceContent = {
    Text = "Kneel before the throne."
  },
  Voice_6322_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_6323_AwakerVoiceContent = {
    Text = "Human faces twisted by desire never cease to amuse. So fragile, so small... This alone makes me feel as if a cat were scratching at my heart.."
  },
  Voice_6323_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_6324_AwakerVoiceContent = {
    Text = "I've seen past events of the Dissolution in her memories... But every time I try to speak of it, my consciousness breaks. I believe it's her doing."
  },
  Voice_6324_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_6325_AwakerVoiceContent = {
    Text = "Good. Now we'll simply fade into oblivion."
  },
  Voice_6325_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_6326_AwakerVoiceContent = {
    Text = "A qualified servant must be pliable and vacuous—I prefer obedient lambs."
  },
  Voice_6326_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_6327_AwakerVoiceContent = {
    Text = "Our meeting must be a promise from the Father to those who suffer. You are the Pale Flame that dispels calamity, and I shall be your arm, standing faithfully by your side."
  },
  Voice_6327_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6328_AwakerVoiceContent = {
    Text = "That's enough!"
  },
  Voice_6328_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6329_AwakerVoiceContent = {
    Text = "Have you ever had D-Slime forced into your veins? The black goo coils around your heart like a viper, and then... boom! Your body explodes into a warm, pulpy mess. Disgusting, but effective."
  },
  Voice_6329_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_6330_AwakerVoiceContent = {
    Text = "Hmph, a haven for the weak to huddle together."
  },
  Voice_6330_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_6331_AwakerVoiceContent = {
    Text = "Every so often, the girl on the motorcycle helps me maintain my prosthetic limb. However, recently, hasn't the frequency of maintenance checks been excessively high?"
  },
  Voice_6331_AwakerVoiceTitle = {
    Text = "Chat: About Nautila"
  },
  Voice_6331_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Nautila\""
  },
  Voice_6332_AwakerVoiceContent = {
    Text = "Our relationship? Do you even need to ask? It's exactly what you're imagining!"
  },
  Voice_6332_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_6333_AwakerVoiceContent = {
    Text = "This is not my preferred genre of verse, but if you insist, I shall try."
  },
  Voice_6333_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_6334_AwakerVoiceContent = {
    Text = "Your dark circles are worsening... Why exert yourself so? You should be more like me and learn to indulge in your leisure."
  },
  Voice_6334_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_6334_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_6335_AwakerVoiceContent = {
    Text = "Wait, without my permission..."
  },
  Voice_6335_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_6335_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_6336_AwakerVoiceContent = {
    Text = "Good... I'm getting closer to my original form."
  },
  Voice_6336_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_6336_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_6337_AwakerVoiceContent = {
    Text = "This is the power to counter \"Green Corruption\"... You've touched something forbidden. As for me, I will never relinquish you again."
  },
  Voice_6337_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_6337_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_6338_AwakerVoiceContent = {
    Text = "Shh... The morning glow of the valley—this must be your first time seeing it, no? Consider it your reward for loyalty."
  },
  Voice_6338_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_6338_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_6339_AwakerVoiceContent = {
    Text = "This tome, \"The @1@2 Revelation,\" is yours now. It helps to enlighten the mind, or perhaps, to swiftly invite slumber."
  },
  Voice_6339_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_6339_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_6340_AwakerVoiceContent = {
    Text = "The mortal clamor wearies me. A quiet alcove in this academy would suffice... No, I don't need a fireplace. Only austerity can carry my prayers to Him..."
  },
  Voice_6340_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_6341_AwakerVoiceContent = {
    Text = "Is it wax or honey dripping from my body? Why don't you take a lick and see for yourself?"
  },
  Voice_6341_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_6341_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_6342_AwakerVoiceContent = {
    Text = "H-Hello... Nice to meet you. My name is Aigis... P-Please don't mind me! Just pretend I don't exist..."
  },
  Voice_6342_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6343_AwakerVoiceContent = {
    Text = "As long as I am still \"Ramona\"... we are still partners, aren't we?"
  },
  Voice_6343_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_6344_AwakerVoiceContent = {
    Text = "That lady with heavy dark circles once consulted me about \"living forever in the sun\"... She only needed to migrate between two dimensions. Yet, she refuses to step into the Dimension Tunnel. It was truly a headache."
  },
  Voice_6344_AwakerVoiceTitle = {
    Text = "Chat: About Winkle"
  },
  Voice_6344_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Winkle\""
  },
  Voice_6345_AwakerVoiceContent = {
    Text = "Welcome to my paradise! Now, are you ready for my whip?"
  },
  Voice_6345_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6346_AwakerVoiceContent = {
    Text = "Since He has deemed you worthy, I shall no longer consider you an adversary."
  },
  Voice_6346_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_6347_AwakerVoiceContent = {
    Text = "What do you mean, \"I took it\"? It's not fair! When her stupid screws went missing, I was busy—Brown, stop! ... Heh, just forget what you saw, alright?"
  },
  Voice_6347_AwakerVoiceTitle = {
    Text = "Chat: About Nautila"
  },
  Voice_6347_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Nautila\""
  },
  Voice_6348_AwakerVoiceContent = {
    Text = "Adventure is just as exciting as in the stories! What was that story again...?"
  },
  Voice_6348_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_6349_AwakerVoiceContent = {
    Text = "...Hic. Ah, sorry, I ate up too much energy again."
  },
  Voice_6349_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_6350_AwakerVoiceContent = {
    Text = "Once inside a human vessel, I lost all contact with my kin. I'm terrified that the others didn't escape the demon and that I might be the last of my kind... Please, Keeper, save me! Let me stay by your side, don't leave me to the darkness..."
  },
  Voice_6350_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_6350_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_6351_AwakerVoiceContent = {
    Text = "When my planet was destroyed, I abandoned my body and transferred my consciousness to a human vessel... But the black demon pursued me relentlessly, binding my spirit and preventing my escape! It seeks to pull this world into an abyss of darkness!"
  },
  Voice_6351_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_6351_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_6352_AwakerVoiceContent = {
    Text = "Please, Keeper... As long as you let me stay on the locator and not move, I'll do anything except enter the darkness and face that... that black thing! I can't leave this spot! Just a little more, and I'll locate the remains of my home planet! Only 1.2 billion calculations to go!"
  },
  Voice_6352_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_6352_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_6353_AwakerVoiceContent = {
    Text = "Could you use your supply share to get me two bags of caffeine supplements?... I can't sleep. Why would I sleep? I must never sleep! Once I close my eyes, everything turns into darkness... endless darkness..."
  },
  Voice_6353_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_6353_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_6354_AwakerVoiceContent = {
    Text = "Whoa! Stay away from me! F-First, you have to prove that you're not a servant of darkness! Yeah, just take off your clothes and show me that you don't have that disgusting black slime on your body, then I'll know you're not evil..."
  },
  Voice_6354_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_6354_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_6355_AwakerVoiceContent = {
    Text = "Don't ask! Don't ask! You know exactly what I fear and hate the most! Darkness! Endless darkness!"
  },
  Voice_6355_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_6356_AwakerVoiceContent = {
    Text = "A method to heal Dissolution? Such a thing doesn't exist anywhere. You ask how I remain uninfected? Hehe... It only takes \"not getting seen\"."
  },
  Voice_6356_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_6357_AwakerVoiceContent = {
    Text = "Thank you, Master."
  },
  Voice_6357_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_6358_AwakerVoiceContent = {
    Text = "The pustules are happy, too."
  },
  Voice_6358_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_6359_AwakerVoiceContent = {
    Text = "Lily has grown bigger."
  },
  Voice_6359_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_6360_AwakerVoiceContent = {
    Text = "Do I crush them?"
  },
  Voice_6360_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_6361_AwakerVoiceContent = {
    Text = "How dare you summon him! That useless, lazy oaf! He was once someone I held in high regard! Away with him! I refuse to look at that fool!"
  },
  Voice_6361_AwakerVoiceTitle = {
    Text = "Chat: About Tulu"
  },
  Voice_6361_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Tulu\""
  },
  Voice_6362_AwakerVoiceContent = {
    Text = "Disgusting!"
  },
  Voice_6362_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_6363_AwakerVoiceContent = {
    Text = "Tsk, annoying!"
  },
  Voice_6363_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_6364_AwakerVoiceContent = {
    Text = "Next time, let us go see the sea together. Febvre is fine; I can be your guide. Or anywhere else, even to the ends of the earth—I want to go with you."
  },
  Voice_6364_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_6364_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_6365_AwakerVoiceContent = {
    Text = "The sea has its own language. Just like this... I can sometimes chat with the little fish in the pond about our hometown. If you are curious, I can help translate for you."
  },
  Voice_6365_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_6365_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_6366_AwakerVoiceContent = {
    Text = "To be saved by you, I often feel a happiness that terrifies me... Please tell me this is not a dream, and that you will not vanish into the sea without a trace, will you?"
  },
  Voice_6366_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_6366_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_6367_AwakerVoiceContent = {
    Text = "Can this feeling truly be called \"happiness\"? I... never dared to hope for it before."
  },
  Voice_6367_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_6367_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_6368_AwakerVoiceContent = {
    Text = "My body feels warm, as if gently enveloped by the sea. It is truly incredible."
  },
  Voice_6368_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_6368_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_6369_AwakerVoiceContent = {
    Text = "Is that boy the fragment of Him? Not bad. He certainly has a regal bearing."
  },
  Voice_6369_AwakerVoiceTitle = {
    Text = "Chat: About Tulu"
  },
  Voice_6369_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Tulu\""
  },
  Voice_6370_AwakerVoiceContent = {
    Text = "No, don't! Don't continue! It will find me! It will find me!"
  },
  Voice_6370_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_6371_AwakerVoiceContent = {
    Text = "This should keep me awake."
  },
  Voice_6371_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_6372_AwakerVoiceContent = {
    Text = "It's over! It's over! It's over! They'll definitely find out..."
  },
  Voice_6372_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_6373_AwakerVoiceContent = {
    Text = "We won. Are you happy? What does \"happy\" feel like?"
  },
  Voice_6373_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_6374_AwakerVoiceContent = {
    Text = "Things I like? I like Tinct's lullabies... Of course, your singing is wonderful too!"
  },
  Voice_6374_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_6375_AwakerVoiceContent = {
    Text = "He was a worthy blade. I once named him \"comrade\"... Do you take issue with my choice of word? Then by all means, enlighten me."
  },
  Voice_6375_AwakerVoiceTitle = {
    Text = "Chat: About Goliath"
  },
  Voice_6375_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Goliath\""
  },
  Voice_6376_AwakerVoiceContent = {Text = "Ah"},
  Voice_6376_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_6377_AwakerVoiceContent = {Text = "Ah"},
  Voice_6377_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_6378_AwakerVoiceContent = {
    Text = "O Meteor..."
  },
  Voice_6378_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6379_AwakerVoiceContent = {Text = "Ah—"},
  Voice_6379_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6380_AwakerVoiceContent = {
    Text = "The power surges, nonstop, filling my whole body..."
  },
  Voice_6380_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_6381_AwakerVoiceContent = {
    Text = "Here you go! Fly!"
  },
  Voice_6381_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_6382_AwakerVoiceContent = {
    Text = "Not bad. You're less worthless than you appear."
  },
  Voice_6382_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_6383_AwakerVoiceContent = {
    Text = "Twenty, twenty-one, twenty-four... Wait, what number was I on? One, two, three..."
  },
  Voice_6383_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_6383_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_6384_AwakerVoiceContent = {
    Text = "I finally figured out how many materials I had before, so I can finish the repairs faster—Wait, where did these come from?"
  },
  Voice_6384_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_6384_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_6385_AwakerVoiceContent = {
    Text = "Thanks to your help, the efficiency of recent repairs has improved. We'll soon be able to set off on an adventure!"
  },
  Voice_6385_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_6385_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_6386_AwakerVoiceContent = {
    Text = "I think I'm starting to remember things... Did you hand me a No. 7 wrench yesterday?"
  },
  Voice_6386_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_6386_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_6387_AwakerVoiceContent = {
    Text = "Reparation complete! An unknown adventure, a mysterious world, here I come!"
  },
  Voice_6387_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_6387_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_6388_AwakerVoiceContent = {Text = "Boom—"},
  Voice_6388_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_6389_AwakerVoiceContent = {
    Text = "Don't deceive yourself. Mental shackles are still shackles and cannot be called fair."
  },
  Voice_6389_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_6390_AwakerVoiceContent = {
    Text = "Now, the line between me and the Awakener is even blurrier. Take good care of me, will you?"
  },
  Voice_6390_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_6390_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_6391_AwakerVoiceContent = {
    Text = "Let's go. We have a world to save."
  },
  Voice_6391_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_6391_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_6392_AwakerVoiceContent = {
    Text = "It feels as refreshing as reading \"On the Origin of Species\" in one go."
  },
  Voice_6392_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_6392_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_6393_AwakerVoiceContent = {
    Text = "I've gotten stronger. Let me try handling the next mission alone, alright?"
  },
  Voice_6393_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_6393_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_6394_AwakerVoiceContent = {
    Text = "Besides combat ability, my memory and logical thinking haven't improved much. Indeed, I shouldn't rely on something else to think for me."
  },
  Voice_6394_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_6394_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_6395_AwakerVoiceContent = {
    Text = "I want them to experience what it feels like to have their lives turned upside down, lose everything, and be trampled by everyone."
  },
  Voice_6395_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_6395_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_6396_AwakerVoiceContent = {
    Text = "The humiliation I've endured, everything I've lost... I will make them pay. I will make them all pay."
  },
  Voice_6396_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_6396_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_6397_AwakerVoiceContent = {
    Text = "Such sweet hatred, when seasoned with the blood of foes, is surely the most exquisite dish in the world."
  },
  Voice_6397_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_6397_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_6398_AwakerVoiceContent = {
    Text = "Aaah! Don't sneak up on me from behind!"
  },
  Voice_6398_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_6399_AwakerVoiceContent = {
    Text = "The scorching flames burn in my chest... Yes, I have never forgotten, nor can I ever forget."
  },
  Voice_6399_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_6399_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_6400_AwakerVoiceContent = {
    Text = "Burn, O soul of poetry."
  },
  Voice_6400_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6401_AwakerVoiceContent = {Text = "(Hums)"},
  Voice_6401_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_6402_AwakerVoiceContent = {Text = "(Hums)"},
  Voice_6402_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_6403_AwakerVoiceContent = {Text = "(Hums)"},
  Voice_6403_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_6404_AwakerVoiceContent = {Text = "(Hums)"},
  Voice_6404_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_6405_AwakerVoiceContent = {
    Text = "It tickles! Just like when the maid uses a feather to tickle the soles of my feet. You didn't do that on purpose, did you?!"
  },
  Voice_6405_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_6405_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_6406_AwakerVoiceContent = {
    Text = "May you have a sweet dream."
  },
  Voice_6406_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_6407_AwakerVoiceContent = {
    Text = "May you have a sweet dream."
  },
  Voice_6407_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6408_AwakerVoiceContent = {
    Text = "Grant serenity...!"
  },
  Voice_6408_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_6409_AwakerVoiceContent = {
    Text = "Move with elegance."
  },
  Voice_6409_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_6410_AwakerVoiceContent = {
    Text = "Can you hear me? Hear my voice?"
  },
  Voice_6410_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_6411_AwakerVoiceContent = {
    Text = "Do you hear me? Do you truly hear my voice?"
  },
  Voice_6411_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6412_AwakerVoiceContent = {
    Text = "It's raining. The rain washes away everything: spoiled food, stubborn filth, and people like me... the dispensable."
  },
  Voice_6412_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_6413_AwakerVoiceContent = {
    Text = "The raging tide of vengeance never ceases!"
  },
  Voice_6413_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6414_AwakerVoiceContent = {
    Text = "Bathe in my enemies' blood!"
  },
  Voice_6414_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6415_AwakerVoiceContent = {Text = "Ah!"},
  Voice_6415_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_6416_AwakerVoiceContent = {
    Text = "Look this way!"
  },
  Voice_6416_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_6417_AwakerVoiceContent = {
    Text = "You can't scare me."
  },
  Voice_6417_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_6418_AwakerVoiceContent = {Text = "Take care!"},
  Voice_6418_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_6419_AwakerVoiceContent = {
    Text = "A world untouched by sorrow, untainted by grief, free from pain and unmarred by suffering... perhaps an unattainable illusion, but it is the ideal I have pursued all my life."
  },
  Voice_6419_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_6420_AwakerVoiceContent = {
    Text = "Behold the magnificence of the Eternal Kingdom!"
  },
  Voice_6420_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_6421_AwakerVoiceContent = {
    Text = "Behold the magnificence of the Eternal Kingdom!"
  },
  Voice_6421_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6422_AwakerVoiceContent = {
    Text = "Offering tributes obediently again? Such a good {Male=boy,Female=girl}."
  },
  Voice_6422_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_6422_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_6423_AwakerVoiceContent = {
    Text = "Does it hurt?"
  },
  Voice_6423_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_6424_AwakerVoiceContent = {
    Text = "Stay focused."
  },
  Voice_6424_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_6425_AwakerVoiceContent = {
    Text = "The passage of millennia has made me somewhat careless."
  },
  Voice_6425_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_6426_AwakerVoiceContent = {
    Text = "That day, the flames of jealousy spread like a sea of blood-red roses in full bloom... All poems turned to shattered ashes amidst the crimson tongues of fire."
  },
  Voice_6426_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_6426_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_6427_AwakerVoiceContent = {
    Text = "I've learned a new technique!"
  },
  Voice_6427_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_6428_AwakerVoiceContent = {
    Text = "Be careful."
  },
  Voice_6428_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_6429_AwakerVoiceContent = {
    Text = "My wand wants to dance!"
  },
  Voice_6429_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_6430_AwakerVoiceContent = {
    Text = "Ah, this familiar sense of emptiness!"
  },
  Voice_6430_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_6431_AwakerVoiceContent = {
    Text = "My joint movement has notably improved."
  },
  Voice_6431_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_6432_AwakerVoiceContent = {
    Text = "That dark presence reminds me of my Formless sword-shield... Oh! Please rest assured, my lord, my guardian sword will never harm you!"
  },
  Voice_6432_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_6433_AwakerVoiceContent = {
    Text = "Do come now."
  },
  Voice_6433_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_6434_AwakerVoiceContent = {
    Text = "Not bad, I guess."
  },
  Voice_6434_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_6435_AwakerVoiceContent = {
    Text = "I will do my utmost."
  },
  Voice_6435_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6436_AwakerVoiceContent = {
    Text = "Play here today?"
  },
  Voice_6436_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_6437_AwakerVoiceContent = {
    Text = "That basement was filled with water, soft and cold. Thus, my body was always enveloped in moisture... As if I was the only physical being left between heaven and earth. Sometimes, I truly wished to dissolve into the water. But then I wouldn't exist and would never meet you."
  },
  Voice_6437_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_6437_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_6438_AwakerVoiceContent = {
    Text = "Here's a secret... I actually detest blood. I hate its color, its taste. But I can't live without it... I swallow the blood, then vomit it all up... Ah, how I hate myself."
  },
  Voice_6438_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_6438_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_6439_AwakerVoiceContent = {
    Text = "Ah! Your blood... it tastes like mead. I suppose I'm the only one who knows this secret, right?"
  },
  Voice_6439_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_6439_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_6440_AwakerVoiceContent = {
    Text = "In my fantasies, a valiant knight drags me out of the darkness, then binds me in chains. {Male=He,Female=She} can hit me, curse me, do anything {Male=he,Female=she} pleases—pain is my proof of life. Would you... be my knight?"
  },
  Voice_6440_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_6440_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_6441_AwakerVoiceContent = {
    Text = "Blood flows like a river. I am yours. Never have I felt so strongly."
  },
  Voice_6441_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_6441_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_6442_AwakerVoiceContent = {
    Text = "This is the will of the Three Goddesses of Vengeance!"
  },
  Voice_6442_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6443_AwakerVoiceContent = {
    Text = "My blade is ready."
  },
  Voice_6443_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_6444_AwakerVoiceContent = {Text = "Nuh-uh!"},
  Voice_6444_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_6445_AwakerVoiceContent = {
    Text = "Aw, you dirty little thing!"
  },
  Voice_6445_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_6446_AwakerVoiceContent = {
    Text = "...I... I see it now!"
  },
  Voice_6446_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_6447_AwakerVoiceContent = {
    Text = "...I... I see it now!"
  },
  Voice_6447_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6448_AwakerVoiceContent = {
    Text = "Tips, of course, tips! Look at those utterly clueless waiters in the school cafeteria! They don't even bother to prepare the lounge chairs in advance, yet they still expect extra pay? Dream on!"
  },
  Voice_6448_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_6449_AwakerVoiceContent = {
    Text = "It's black."
  },
  Voice_6449_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_6450_AwakerVoiceContent = {
    Text = "Let me out!"
  },
  Voice_6450_AwakerVoiceTitle = {
    Text = "Skill: I: Mania"
  },
  Voice_6451_AwakerVoiceContent = {
    Text = "Don't do this..."
  },
  Voice_6451_AwakerVoiceTitle = {
    Text = "Skill: I: Depression"
  },
  Voice_6452_AwakerVoiceContent = {
    Text = "There is no need for courtesy, Pale Messenger. There should be no barriers between us, for we are both the All-Father's creations, walking together on this muddy and testing path."
  },
  Voice_6452_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_6452_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_6453_AwakerVoiceContent = {
    Text = "No, I do not fear them. I feel only sorrow for those poor souls tormented by Dissolution. I know I cannot bear their suffering for them, but I would give them all that I have if it brings a moment's comfort."
  },
  Voice_6453_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_6453_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_6454_AwakerVoiceContent = {
    Text = "Will you pray with me, my Pale Flame? Let us pray for those who died in our battle today. Though cursed with dissolution and madness, they are still children of the All-Father, our brothers and sisters. May they now find their deserved peace."
  },
  Voice_6454_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_6454_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_6455_AwakerVoiceContent = {
    Text = "Even though the red flames make me uneasy, I would step onto the burning platform for you once more. Do not dwell on it, my Pale Flame. My sacrifice is insignificant next to the blessings you bring."
  },
  Voice_6455_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_6455_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_6456_AwakerVoiceContent = {
    Text = "Regret? No, of course not. My death eased their suffering and bought more time, and that is enough. But... as you have been honest with me, I shall not hide this: the pyre that day left its scars upon my heart."
  },
  Voice_6456_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_6456_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_6457_AwakerVoiceContent = {
    Text = "Make a promise with me? Promise that, no matter what happens, you'll remember \"Ramona\"."
  },
  Voice_6457_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_6457_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_6458_AwakerVoiceContent = {
    Text = "I don't regret becoming this, Keeper; I'd choose it again. But I am afraid... afraid that the \"Ramona\" I used to be will leave no trace behind."
  },
  Voice_6458_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_6458_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_6459_AwakerVoiceContent = {
    Text = "The eye patch doesn't affect my sight. If anything, it helps me avoid seeing too much."
  },
  Voice_6459_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_6459_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_6460_AwakerVoiceContent = {
    Text = "Do I look... unfamiliar? I've been trying to keep control. Her presence is growing stronger."
  },
  Voice_6460_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_6460_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_6461_AwakerVoiceContent = {
    Text = "Too many mysteries, too many people who need saving. I don't know how long I can keep this up... I cannot protect everyone. It is difficult."
  },
  Voice_6461_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_6461_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_6462_AwakerVoiceContent = {
    Text = "Still wanna bet on me? Guess living carefree isn't as easy as it looks. Don't worry, I'll solve your problems... with plenty of breaks."
  },
  Voice_6462_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_6462_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_6463_AwakerVoiceContent = {
    Text = "Well, looks like we gotta bring out the big guns, right? Where's the crime scene? I'll burn every last bit of my luck to bring the suspect in before the deadline!"
  },
  Voice_6463_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_6463_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_6464_AwakerVoiceContent = {
    Text = "Sigh, I owe you too many favors to keep this secret: Actually, I might be the unluckiest bloke in the whole world."
  },
  Voice_6464_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_6464_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_6465_AwakerVoiceContent = {
    Text = "Seems you didn't take my warning to heart... Ah, never mind. I'll still help you tear through the enemy. After all, these claws and fangs were won by chance, right?"
  },
  Voice_6465_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_6465_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_6466_AwakerVoiceContent = {
    Text = "My luck might not rub off on my companions. You know the saying, right? \"A rabbit's foot isn't lucky for the rabbit.\""
  },
  Voice_6466_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_6466_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_6467_AwakerVoiceContent = {
    Text = "Do you seek This One's sigil branded upon your soul?"
  },
  Voice_6467_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_6468_AwakerVoiceContent = {
    Text = "Do you covet my power so desperately?"
  },
  Voice_6468_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_6469_AwakerVoiceContent = {
    Text = "Don't be fooled by my appearance; I was once a noble lady, too... I embroidered, I read Tennyson... Oh, and I once sang songs: \"She flows like an endless river through my veins...\""
  },
  Voice_6469_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_6470_AwakerVoiceContent = {
    Text = "Pickman and I are working on some fascinating installation art, exploring the reconstruction of abstract representationism by deconstructing visual primitivism... Huh, why did Aurita faint?"
  },
  Voice_6470_AwakerVoiceTitle = {
    Text = "Chat: About Aurita"
  },
  Voice_6470_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Aurita\""
  },
  Voice_6471_AwakerVoiceContent = {
    Text = [[
Do you want me to smile?
Am I... smiling now?]]
  },
  Voice_6471_AwakerVoiceTitle = {
    Text = "Chat: About Her Smile"
  },
  Voice_6472_AwakerVoiceContent = {
    Text = [[
What a surprise, I've gained an equivalent companionship.
However... I request to retain the right to command you, merely for our mutual amusement. Come to my chambers tonight; I still have much to learn about human sensibilities...]]
  },
  Voice_6472_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_6472_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_6473_AwakerVoiceContent = {
    Text = "Do you know what makes you the most charming? It's when you say \"no\" to me. Your nose wrinkles, your eyebrows lift ever so slightly... Yes, precisely like that."
  },
  Voice_6473_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_6473_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_6474_AwakerVoiceContent = {
    Text = "I adore my servants. These handsome little creatures, trembling from Dissolution and hiding behind me, are so endearing. The tears of a beauty are always captivating. How about you? Do you fear Dissolution?"
  },
  Voice_6474_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_6474_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_6475_AwakerVoiceContent = {
    Text = "Keeper, is there anyone you don't like? As a favor, I can teach them a lesson. Within a week, they'll be a changed person, obediently prostrating themselves before you."
  },
  Voice_6475_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_6475_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_6476_AwakerVoiceContent = {
    Text = [[
Hmm... Although you're dull, you're not entirely unpleasant. Starting tomorrow, you shall serve me.
You don't want to...? Ha. This isn't a request; it is a command.]]
  },
  Voice_6476_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_6476_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_6477_AwakerVoiceContent = {
    Text = "It has been a long time since I felt this way. I will take the stage in perfect form and deliver a song that embraces the whole cosmos just for you."
  },
  Voice_6477_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_6477_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_6478_AwakerVoiceContent = {
    Text = "You should know this is all pointless."
  },
  Voice_6478_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_6478_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_6479_AwakerVoiceContent = {
    Text = "After plucking the flower of victory, I would like to claim a small prize..."
  },
  Voice_6479_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_6480_AwakerVoiceContent = {Text = "Ah!"},
  Voice_6480_AwakerVoiceTitle = {
    Text = "Hit: Depression: III"
  },
  Voice_6481_AwakerVoiceContent = {
    Text = "The spaceship was cramped and claustrophobic, like a metal coffin floating in space. I had been waiting for my Morning Star since forever, until you showed up for me."
  },
  Voice_6481_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_6481_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_6482_AwakerVoiceContent = {
    Text = "How could this be?!"
  },
  Voice_6482_AwakerVoiceTitle = {
    Text = "Hit: Hysteria: I"
  },
  Voice_6483_AwakerVoiceContent = {Text = "Ugh..."},
  Voice_6483_AwakerVoiceTitle = {
    Text = "Hit: Depression: I"
  },
  Voice_6484_AwakerVoiceContent = {
    Text = "It hurts..."
  },
  Voice_6484_AwakerVoiceTitle = {
    Text = "Hit: Depression: II"
  },
  Voice_6485_AwakerVoiceContent = {
    Text = "Divine Punishment!"
  },
  Voice_6485_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_6486_AwakerVoiceContent = {
    Text = "Divine Punishment!"
  },
  Voice_6486_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6487_AwakerVoiceContent = {Text = "Tedious."},
  Voice_6487_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_6488_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_6488_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_6489_AwakerVoiceContent = {
    Text = "I can still hold up."
  },
  Voice_6489_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_6490_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_6490_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_6491_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_6491_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_6492_AwakerVoiceContent = {
    Text = "May the irreverent be dissolved in this searing tranquility."
  },
  Voice_6492_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_6493_AwakerVoiceContent = {
    Text = "Be careful! If you reach into another dimensional space, you might not get your hand back!"
  },
  Voice_6493_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_6494_AwakerVoiceContent = {
    Text = "A bunch of incompetents. If you'd rather not end up as minced meat, you'd do well to pay closer attention next time."
  },
  Voice_6494_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_6495_AwakerVoiceContent = {
    Text = "Oh dear, are you being affectionate with me? This is troublesome. If this continues, I won't be able to wait until you fully mature, my dear {Male=Mr.,Female=Miss} Keeper..."
  },
  Voice_6495_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_6496_AwakerVoiceContent = {
    Text = "Dive into the depths of free will!"
  },
  Voice_6496_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6497_AwakerVoiceContent = {
    Text = "Hate? I despise those who give up halfway. The mere thought of them makes me want to regurgitate last night's meal."
  },
  Voice_6497_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_6498_AwakerVoiceContent = {
    Text = "Behold your visage, O endless skulls!"
  },
  Voice_6498_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6499_AwakerVoiceContent = {
    Text = "Behold your visage, O endless skulls!"
  },
  Voice_6499_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_6500_AwakerVoiceContent = {Text = "Hah!"},
  Voice_6500_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_6501_AwakerVoiceContent = {Text = "Hah!"},
  Voice_6501_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_6502_AwakerVoiceContent = {
    Text = "Do you trust me that much?"
  },
  Voice_6502_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_6502_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_6503_AwakerVoiceContent = {Text = "Come back."},
  Voice_6503_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_6504_AwakerVoiceContent = {Text = "Good!"},
  Voice_6504_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_6505_AwakerVoiceContent = {
    Text = "Yes, of course I know her. She is my other self, another possibility. But why does she resist? If she accepts her fate as the chosen one, wouldn't she get anything she wished at her fingertips?"
  },
  Voice_6505_AwakerVoiceTitle = {
    Text = "Chat: About \"Murphy\""
  },
  Voice_6505_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Murphy\""
  },
  Voice_6506_AwakerVoiceContent = {
    Text = [[
Hello, my name is Daffodil. I made an exchange with a guest who requested I assist you. So, let me hear what you require. 
Oh dear... what you wish for comes at quite a price, doesn't it?]]
  },
  Voice_6506_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6507_AwakerVoiceContent = {
    Text = "Shit! What are you doing?! Believe it or not, I'll chop your hand off!"
  },
  Voice_6507_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_6508_AwakerVoiceContent = {Text = "Hahaha!"},
  Voice_6508_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6509_AwakerVoiceContent = {Text = "Hahaha!"},
  Voice_6509_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_6510_AwakerVoiceContent = {
    Text = "Rose thorns prick my fingers, their crimson flowing into poetry."
  },
  Voice_6510_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6511_AwakerVoiceContent = {
    Text = "Bowed beneath this deep ink of sorrow, become a song of mourning..."
  },
  Voice_6511_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_6512_AwakerVoiceContent = {
    Text = "Watch this!"
  },
  Voice_6512_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_6513_AwakerVoiceContent = {Text = "Hngh...!"},
  Voice_6513_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_6514_AwakerVoiceContent = {
    Text = "Cataclysm descends!"
  },
  Voice_6514_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6515_AwakerVoiceContent = {
    Text = "Give it to me."
  },
  Voice_6515_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_6516_AwakerVoiceContent = {
    Text = "My name, uh, I can't remember. Oh, right, \"24\", that's what they call me... No! Stop! Don't come out! You can't, not now..."
  },
  Voice_6516_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6517_AwakerVoiceContent = {
    Text = "Ink mark, where are you going?..."
  },
  Voice_6517_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_6518_AwakerVoiceContent = {
    Text = "Emerge for me..."
  },
  Voice_6518_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6519_AwakerVoiceContent = {
    Text = "I don't deserve the title \"Heavenly Voice.\" As long as you enjoy my singing, that's all that matters."
  },
  Voice_6519_AwakerVoiceTitle = {
    Text = "Chat: About Singing"
  },
  Voice_6520_AwakerVoiceContent = {
    Text = "Ah, my dress is dirty. I should change out of it before the next salon."
  },
  Voice_6520_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_6521_AwakerVoiceContent = {
    Text = "It's catching up to me, the eternal darkness... No one can escape..."
  },
  Voice_6521_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_6522_AwakerVoiceContent = {
    Text = "Every time I see you, I think of the invisible shackles you've placed on me. Allowing you to live is my greatest act of tolerance."
  },
  Voice_6522_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_6523_AwakerVoiceContent = {
    Text = "No matter how many times we must start over, I will walk alongside you."
  },
  Voice_6523_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_6524_AwakerVoiceContent = {
    Text = "May His divine love warm your soul."
  },
  Voice_6524_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_6525_AwakerVoiceContent = {
    Text = "I enjoy wandering aimlessly. Swamps, graveyards, infirmaries, abandoned castles... In these places, I always find unexpected delights."
  },
  Voice_6525_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_6526_AwakerVoiceContent = {
    Text = "Feel honored, for the gates to the Eternal Kingdom are here!"
  },
  Voice_6526_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_6527_AwakerVoiceContent = {
    Text = "Hehe—so ticklish! Don't run! I've got to scratch you back!"
  },
  Voice_6527_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_6528_AwakerVoiceContent = {
    Text = "\"The Dying Swan,\" a performance in which the dancer uses body language to convey the longing and struggle of life. Isn't that twisted figure in the flames the same?"
  },
  Voice_6528_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_6529_AwakerVoiceContent = {
    Text = "Slice, slice, tear apart. Just like they did to me... Hehe... HAHAHA!"
  },
  Voice_6529_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_6530_AwakerVoiceContent = {
    Text = "You'd better not get too close to Lady Thais... No, I'm not jealous. I'm just afraid someone might fall for her tricks."
  },
  Voice_6530_AwakerVoiceTitle = {
    Text = "Chat: About Thais"
  },
  Voice_6530_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Thais\""
  },
  Voice_6531_AwakerVoiceContent = {Text = "...Thanks."},
  Voice_6531_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_6531_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_6532_AwakerVoiceContent = {
    Text = "Very well... You have a keen eye for recognizing capable people."
  },
  Voice_6532_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_6532_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_6533_AwakerVoiceContent = {
    Text = "My hometown is beautiful! It's a stone city in a lake. Every full moon, we dance silently in the flames, worshiping... Honestly, when I first arrived in this school, I missed home every night and cried in bed. But now, I have a new home and family. Everything's getting better!"
  },
  Voice_6533_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_6533_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_6534_AwakerVoiceContent = {
    Text = "Oh~ Still not satisfied? Come closer, I'll teach you true pleasure~"
  },
  Voice_6534_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_6535_AwakerVoiceContent = {
    Text = "Weak muscles, a haggard face—only those dead-like eyes hold some value. They're perfect for feeding spiders!"
  },
  Voice_6535_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_6536_AwakerVoiceContent = {
    Text = "T-Thank you... for everything you've done. I will do my absolute best... to not let you down!"
  },
  Voice_6536_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_6537_AwakerVoiceContent = {
    Text = "(Cry of fear)"
  },
  Voice_6537_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_6538_AwakerVoiceContent = {Text = "No!"},
  Voice_6538_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_6539_AwakerVoiceContent = {Text = "Spare me!"},
  Voice_6539_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_6540_AwakerVoiceContent = {
    Text = "(Cry of fear)"
  },
  Voice_6540_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_6541_AwakerVoiceContent = {
    Text = "Miss Ramona's swordsmanship is quite different from what I've learned. If my lord allows, I would dearly like to practice with her... Just for my own improvement, of course!"
  },
  Voice_6541_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_6541_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_6542_AwakerVoiceContent = {
    Text = "You ask why I don't play with the other children? It's hard to say... In my past life, I rarely had a chance to play. My only companion was the princess I served... Oh! To speak of another ruler before you, my lord, please forgive my slip."
  },
  Voice_6542_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_6542_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_6543_AwakerVoiceContent = {
    Text = "You are recognized by Mythag University as a Keeper, so I will grant you the corresponding access permissions."
  },
  Voice_6543_AwakerVoiceTitle = {
    Text = "Chat: About \"Protagonist\""
  },
  Voice_6544_AwakerVoiceContent = {
    Text = "Are you interested in the Seven Knightly Arts I've learned? That's wonderful! Ah... um... please forgive my rudeness earlier, my lord. What I meant was, if you'd like to practice mounted archery, I would be honored to be your sparring partner!"
  },
  Voice_6544_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_6544_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_6545_AwakerVoiceContent = {
    Text = "I am not a worthy knight. Whether it was the vile plague or the invading enemies, I failed to protect my former lord. Now, the trust you place in someone like me is a huge honor... I swear on my knightly honor and this small life that I will forever guard your path forward."
  },
  Voice_6545_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_6545_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_6546_AwakerVoiceContent = {
    Text = "Do not harm."
  },
  Voice_6546_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_6547_AwakerVoiceContent = {Text = "Come on~"},
  Voice_6547_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_6548_AwakerVoiceContent = {Text = "Hah!"},
  Voice_6548_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_6549_AwakerVoiceContent = {
    Text = "Do not kill."
  },
  Voice_6549_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_6550_AwakerVoiceContent = {Text = "Ah, yes~!"},
  Voice_6550_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_6551_AwakerVoiceContent = {
    Text = "Now we are simply water and oil. Never mixing."
  },
  Voice_6551_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_6552_AwakerVoiceContent = {
    Text = "I don't have any particular favorites. If I had to say, the feeling of going out on missions is quite nice."
  },
  Voice_6552_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_6553_AwakerVoiceContent = {
    Text = "Why, why lock me up here? Haha... you're not getting what you want. I'll tear these restraints, this prison, into fragments!"
  },
  Voice_6553_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_6554_AwakerVoiceContent = {
    Text = "Lily will protect."
  },
  Voice_6554_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6555_AwakerVoiceContent = {
    Text = "You guys, don't you ever get tired of watching the magic show? Sit still, alright? If you run onto the stage again, I'll toss you into another dimension!"
  },
  Voice_6555_AwakerVoiceTitle = {
    Text = "Chat: About Children"
  },
  Voice_6555_UnlockDesc = {
    Text = "Unlocks after acquiring any one of Awakeners \"Aigis\", \"Jenkin\", \"Lily\", \"Murphy\", \"Karen\", or \"Aurita\""
  },
  Voice_6556_AwakerVoiceContent = {
    Text = "I shall accept your generous gift with gratitude."
  },
  Voice_6556_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_6557_AwakerVoiceContent = {
    Text = "What kind of return gift could match your dedication?"
  },
  Voice_6557_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_6558_AwakerVoiceContent = {
    Text = "How beautiful..."
  },
  Voice_6558_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_6559_AwakerVoiceContent = {
    Text = "Detected high current, initiating maintenance... Correction: why is there no overheating?"
  },
  Voice_6559_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_6559_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_6560_AwakerVoiceContent = {
    Text = "Since the last Enlighten ritual, I've been seeing fragmented visions while in the state of dormancy. In them, I possess a human body like yours, and tears fall from my eyes. Is this a dream?"
  },
  Voice_6560_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_6560_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_6561_AwakerVoiceContent = {
    Text = "After each ritual, a high level of heat is detected in the chest area, but there are no energy-related components present. Do you know why?"
  },
  Voice_6561_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_6561_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_6562_AwakerVoiceContent = {
    Text = "I saw it. Everything should <Del:perish in the eternal current>. S-s-sorry, the module seems—Warning, warning. Non-Erica consciousness activity increasing. Destroy, destroydestroyDESTROY... Hello, how may I assist you?"
  },
  Voice_6562_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_6562_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_6563_AwakerVoiceContent = {
    Text = "After careful analysis, I deduced that what I saw in my dormant state was not a dream in the traditional sense, but rather my <Del:your pathetic meat bag of a body should be destroyed> memory. As for the burning heat akin to overload, it may be the emotion known as \"Unwillingness.\""
  },
  Voice_6563_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_6563_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_6564_AwakerVoiceContent = {
    Text = "If you want to watch my performance, sit properly in the audience!"
  },
  Voice_6564_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_6564_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_6565_AwakerVoiceContent = {
    Text = "The flames of hatred burn fiercely, never to be extinguished."
  },
  Voice_6565_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_6566_AwakerVoiceContent = {
    Text = "Shh... Don't speak. Bad guys are coming. They want to take my sister and me away, and won't let us board the ship..."
  },
  Voice_6566_AwakerVoiceTitle = {
    Text = "Chat: About Safety"
  },
  Voice_6567_AwakerVoiceContent = {
    Text = "The will I've merged with is quite boisterous; the higher I ascend, the clearer His voice becomes... like the geese in Hyde Park, perpetually clamoring."
  },
  Voice_6567_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_6567_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_6568_AwakerVoiceContent = {
    Text = "I will use this power to devour the betrayer."
  },
  Voice_6568_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_6569_AwakerVoiceContent = {Text = "...Thanks."},
  Voice_6569_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_6570_AwakerVoiceContent = {
    Text = "You, the oh-so-great world-saving Keeper? Ridiculous. Wake up. This dream's gone stale."
  },
  Voice_6570_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6571_AwakerVoiceContent = {
    Text = "The blood of vengeance is boiling..."
  },
  Voice_6571_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_6572_AwakerVoiceContent = {
    Text = "Move, you cur."
  },
  Voice_6572_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6573_AwakerVoiceContent = {
    Text = "Don't drown!"
  },
  Voice_6573_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_6574_AwakerVoiceContent = {Text = "Whoosh!"},
  Voice_6574_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_6575_AwakerVoiceContent = {
    Text = "I threw away the mousetraps by the dining hall backdoor. What if that clumsy Brown steps on one?! It's too dangerous!"
  },
  Voice_6575_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_6576_AwakerVoiceContent = {
    Text = "This feels so strange... Am I dying? No, save me! Help! No!!"
  },
  Voice_6576_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_6576_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_6577_AwakerVoiceContent = {
    Text = "Proper vocal training...? But I'm quite satisfied with my current voice."
  },
  Voice_6577_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_6577_UnlockDesc = {
    Text = "Unlocked at Enlighten Level 2"
  },
  Voice_6578_AwakerVoiceContent = {
    Text = "What a beautiful performance costume, so glittering, so dazzling..."
  },
  Voice_6578_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_6578_UnlockDesc = {
    Text = "Unlock at Enlighten Level 7"
  },
  Voice_6579_AwakerVoiceContent = {
    Text = "I want a lamp that never goes out. She actually said I could purchase it with... with a specimen of a \"wingless flying hydra.\" Where can I find such a bizarre species?!"
  },
  Voice_6579_AwakerVoiceTitle = {
    Text = "Chat: About Daffodil"
  },
  Voice_6579_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Daffodil\""
  },
  Voice_6580_AwakerVoiceContent = {
    Text = "It's been a while... Finally back on stage. Thank you, Keeper."
  },
  Voice_6580_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_6580_UnlockDesc = {
    Text = "Unlocked at Enlighten Level 15"
  },
  Voice_6581_AwakerVoiceContent = {
    Text = "Perfect rehearsal. I think I'm ready to take the stage."
  },
  Voice_6581_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_6581_UnlockDesc = {
    Text = "Unlocked at Enlighten Level 11"
  },
  Voice_6582_AwakerVoiceContent = {Text = "Danger."},
  Voice_6582_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_6583_AwakerVoiceContent = {Text = "Warning."},
  Voice_6583_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_6584_AwakerVoiceContent = {Text = "Hit."},
  Voice_6584_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_6585_AwakerVoiceContent = {
    Text = "A treasure that glitters like candy wrappers... I will cherish it dearly."
  },
  Voice_6585_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_6586_AwakerVoiceContent = {
    Text = "Damage taken."
  },
  Voice_6586_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_6587_AwakerVoiceContent = {
    Text = "My shop exists in any dimension, any location in the universe, and of course, it can be here. Besides, I like those careless children in Mythag."
  },
  Voice_6587_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_6588_AwakerVoiceContent = {
    Text = "Green pepper... nasty."
  },
  Voice_6588_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_6589_AwakerVoiceContent = {
    Text = "My relationship with you is like that of a sail and a ship. Without the ship, the sail shouldn't exist; without the sail, the ship can hardly voyage far. Is that not true?"
  },
  Voice_6589_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_6590_AwakerVoiceContent = {
    Text = "The devout dancer is dead, and the blasphemer of art is also dead, both perished in flames filled with the scent of tar. Death is not the end but the beginning, for only humans die; dance and art are eternal."
  },
  Voice_6590_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_6590_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_6591_AwakerVoiceContent = {
    Text = "Thank you for your understanding. Perhaps now is the time to reconcile with my past self... I believe I am doing the right thing and have not disgraced my family's legacy in dance. I will step onto the stage you have prepared and shine as you wish."
  },
  Voice_6591_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_6591_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_6592_AwakerVoiceContent = {
    Text = "Be careful what you wish for."
  },
  Voice_6592_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_6593_AwakerVoiceContent = {
    Text = "Do you want me to take the stage and shine? That's impossible now. These eyes have been consumed by hatred. All I can do is burn everything to ashes."
  },
  Voice_6593_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_6593_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_6594_AwakerVoiceContent = {
    Text = "Do you understand that feeling? Spinning, spinning, spinning, never stopping. Knees stretched to the limit, toes bleeding black, soaking the ballet shoes, yet never pausing. All because I refuse to accept the fate of being a mere toy..."
  },
  Voice_6594_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_6594_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_6595_AwakerVoiceContent = {
    Text = "I didn't burn skilled court dancers, graceful ballet masters, or nobles who appreciate beauty. I burned useless fools selling their bodies, sycophants disregarding others, and filthy beings lost in lust... You understand me, right?"
  },
  Voice_6595_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_6595_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_6596_AwakerVoiceContent = {
    Text = "I dislike those slimy tentacles, and I do not like the deep sea... Don't give me that knowing look! I am not a child afraid of my parents!"
  },
  Voice_6596_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_6596_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_6597_AwakerVoiceContent = {
    Text = "Your generosity is greatly cherished..."
  },
  Voice_6597_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_6598_AwakerVoiceContent = {Text = "Disappear."},
  Voice_6598_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6599_AwakerVoiceContent = {Text = "Disappear."},
  Voice_6599_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_6600_AwakerVoiceContent = {
    Text = "Hurry, grab Brown and scram!"
  },
  Voice_6600_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_6601_AwakerVoiceContent = {Text = "Don't..."},
  Voice_6601_AwakerVoiceTitle = {
    Text = "Defense: Depression"
  },
  Voice_6602_AwakerVoiceContent = {Text = "Scram!"},
  Voice_6602_AwakerVoiceTitle = {
    Text = "Defense: Mania"
  },
  Voice_6603_AwakerVoiceContent = {
    Text = "Who is Leigh? Oh, the woman who begged me to beat her up. Haha, interesting... This place isn't boring after all."
  },
  Voice_6603_AwakerVoiceTitle = {
    Text = "Chat: About Leigh"
  },
  Voice_6603_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Leigh\""
  },
  Voice_6604_AwakerVoiceContent = {
    Text = "The sunset on the small hill often reminds me of my days in Cleveland... Cleveland. I can't believe I still remember that name, the place that gave me these scars."
  },
  Voice_6604_AwakerVoiceTitle = {
    Text = "Chat: About Dusk"
  },
  Voice_6605_AwakerVoiceContent = {
    Text = "Ah... the stars... have fallen..."
  },
  Voice_6605_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_6606_AwakerVoiceContent = {
    Text = "Without a doubt, humans. Are there any creatures filthier than humans?"
  },
  Voice_6606_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_6607_AwakerVoiceContent = {Text = "It's now!"},
  Voice_6607_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_6608_AwakerVoiceContent = {Text = "Hah!"},
  Voice_6608_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_6609_AwakerVoiceContent = {
    Text = "Dissolution? Hmm... Yes! Ice cream melts! But if we share it, we can eat it before it completely turns into cream!"
  },
  Voice_6609_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_6610_AwakerVoiceContent = {
    Text = "I shall use this strength to keep you safe."
  },
  Voice_6610_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_6610_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_6611_AwakerVoiceContent = {
    Text = "Oh dear, no returns on items sold here! You do need a submarine to dive into the deep seas, don't you?"
  },
  Voice_6611_AwakerVoiceTitle = {
    Text = "Chat: About Caecus"
  },
  Voice_6611_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Caecus\""
  },
  Voice_6612_AwakerVoiceContent = {
    Text = "Ah, this is the best stage! The people at Mythag University all understand that my performance is true magic! This must be what they call a magician's best audience, yes?"
  },
  Voice_6612_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_6613_AwakerVoiceContent = {
    Text = "The order of the universe shifts here; the future of destruction is the magician's core belief!"
  },
  Voice_6613_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_6613_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_6614_AwakerVoiceContent = {
    Text = "Can I stay here a little longer? I will remain quiet, make no sound, and try my best not to disturb you..."
  },
  Voice_6614_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_6614_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_6615_AwakerVoiceContent = {
    Text = "Unveil the world's mysteries with human intellect!"
  },
  Voice_6615_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6616_AwakerVoiceContent = {
    Text = "In my dreams, I often hear the sound of the tide, growing fainter and fainter. I know I might stay here forever, Human."
  },
  Voice_6616_AwakerVoiceTitle = {
    Text = "Chat: About Aequor"
  },
  Voice_6617_AwakerVoiceContent = {
    Text = "More memories, more emotions, more dreams—"
  },
  Voice_6617_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_6617_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_6618_AwakerVoiceContent = {
    Text = "Magic time!"
  },
  Voice_6618_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6619_AwakerVoiceContent = {
    Text = "Don't blink!"
  },
  Voice_6619_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_6620_AwakerVoiceContent = {
    Text = "Once He is born... I won't have to endure such humiliation anymore..."
  },
  Voice_6620_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_6621_AwakerVoiceContent = {
    Text = "Pick me, pick me! Where there's a party, there's Karen!"
  },
  Voice_6621_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_6622_AwakerVoiceContent = {
    Text = "Hmm? Are you interested in me? Then I suppose... you're also ready to pay the price?"
  },
  Voice_6622_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_6623_AwakerVoiceContent = {
    Text = "No mercy, no mercy...!"
  },
  Voice_6623_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_6624_AwakerVoiceContent = {
    Text = "I still sing of the Color out of Space..."
  },
  Voice_6624_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6625_AwakerVoiceContent = {
    Text = "Sing, chant for me!"
  },
  Voice_6625_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_6626_AwakerVoiceContent = {
    Text = "I love Mommy!"
  },
  Voice_6626_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_6627_AwakerVoiceContent = {Text = "Come on."},
  Voice_6627_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_6628_AwakerVoiceContent = {
    Text = "Be careful."
  },
  Voice_6628_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_6629_AwakerVoiceContent = {
    Text = "Awakeners might consume out of curiosity, but food is not essential for our existence. Therefore, there is no need to summon me for every afternoon tea. Sugar intake only accelerates the wear and tear on this body's ball joints."
  },
  Voice_6629_AwakerVoiceTitle = {
    Text = "Chat: About Afternoon Tea"
  },
  Voice_6630_AwakerVoiceContent = {
    Text = "Oh, the lingering colors of the stars."
  },
  Voice_6630_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6631_AwakerVoiceContent = {
    Text = "Blossom with light."
  },
  Voice_6631_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6632_AwakerVoiceContent = {
    Text = "Please, spare my Master. D-do whatever you want with Karen!"
  },
  Voice_6632_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_6633_AwakerVoiceContent = {
    Text = "Are these... for me? Can I eat? Really?"
  },
  Voice_6633_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_6633_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_6634_AwakerVoiceContent = {
    Text = "What I... hate? Can I say it? I hate myself for being so useless... But if I say that, Jenkin will get really angry..."
  },
  Voice_6634_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_6635_AwakerVoiceContent = {
    Text = "Turn to ashes."
  },
  Voice_6635_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_6636_AwakerVoiceContent = {
    Text = "Turn to ashes."
  },
  Voice_6636_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6637_AwakerVoiceContent = {
    Text = "Well done, Keeper. So, who am I killing this time?"
  },
  Voice_6637_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_6637_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_6638_AwakerVoiceContent = {
    Text = "Dissolution is the reason this academy was founded and why we met. To save humanity's spark from Dissolution, let's do our best, partner."
  },
  Voice_6638_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_6639_AwakerVoiceContent = {
    Text = "I can sense that girl's hostility; my love for you has lit the fire of her jealousy... Look, even that humpback whale gapes with envy."
  },
  Voice_6639_AwakerVoiceTitle = {
    Text = "Chat: About Lotan"
  },
  Voice_6639_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Lotan\""
  },
  Voice_6640_AwakerVoiceContent = {
    Text = "Master, Master! Karen saw an incredibly gorgeous cameo brooch at Harold's today! Could you buy it for Karen? It's my lifelong request!"
  },
  Voice_6640_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_6641_AwakerVoiceContent = {
    Text = "I will serve as your guiding light in the darkness, but not forever."
  },
  Voice_6641_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_6642_AwakerVoiceContent = {
    Text = "Mommy... It hurts... Mommy..."
  },
  Voice_6642_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_6643_AwakerVoiceContent = {
    Text = "Yield! Victory is already mine!"
  },
  Voice_6643_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_6644_AwakerVoiceContent = {
    Text = "Yield! Victory is already mine!"
  },
  Voice_6644_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6645_AwakerVoiceContent = {
    Text = "Dissolution... Uh, My brain capacity is limited and I can't comprehend such complex diseases... If you need any machinery repaired, come find me!"
  },
  Voice_6645_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_6646_AwakerVoiceContent = {
    Text = "Oh no! I've been found! As a penalty for losing, you can make one request of me—just please don't make me go to class, pretty please!"
  },
  Voice_6646_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_6647_AwakerVoiceContent = {
    Text = "Clearing the path for His glorious return..."
  },
  Voice_6647_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_6648_AwakerVoiceContent = {
    Text = "One day, Uncle Ornn will bring me back to my underwater home. Until then, I can reluctantly be your friend."
  },
  Voice_6648_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_6648_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_6649_AwakerVoiceContent = {
    Text = "\"Our family carries a great bloodline; the chosen one will enjoy eternal peace in the deep sea.\" I never expected to feel this peace after leaving the sea and coming to the academy. You are different from those who bully me, so I won't allow others to bully you either."
  },
  Voice_6649_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_6649_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_6650_AwakerVoiceContent = {
    Text = "Super tough custom-made material!"
  },
  Voice_6650_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6651_AwakerVoiceContent = {
    Text = "This half-human shell really... disgusts me. I finally got rid of the past, and now I have to recall it again..."
  },
  Voice_6651_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_6651_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_6652_AwakerVoiceContent = {
    Text = "To think the heir of the great bloodline would stoop to serving a human... Hmph. Don't think you can command me at will."
  },
  Voice_6652_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_6652_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_6653_AwakerVoiceContent = {
    Text = "Hmph, you frail human do have some talent in command... and I would show you my true power if not for this inferior shell."
  },
  Voice_6653_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_6653_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_6654_AwakerVoiceContent = {
    Text = "My body is getting warmer."
  },
  Voice_6654_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_6655_AwakerVoiceContent = {
    Text = "Run... I must run! Get away from here!"
  },
  Voice_6655_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6656_AwakerVoiceContent = {
    Text = "Run... I must run! Get away from here!"
  },
  Voice_6656_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_6657_AwakerVoiceContent = {
    Text = "Thank you for your efforts. Allow me to reward you in kind."
  },
  Voice_6657_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_6658_AwakerVoiceContent = {
    Text = "It is manageable."
  },
  Voice_6658_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_6659_AwakerVoiceContent = {
    Text = "(A soft, suppressed inhale)"
  },
  Voice_6659_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_6660_AwakerVoiceContent = {
    Text = "Frail human, your conviction is sufficient. I will be your weapon. Let's carve out some chaos together!"
  },
  Voice_6660_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_6660_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_6662_AwakerVoiceContent = {
    Text = "This is MY salon."
  },
  Voice_6662_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6663_AwakerVoiceContent = {
    Text = "Sorry to bother you... Could you help me get down from this tree? I don't remember why I climbed up. Perhaps the clouds above made me feel nostalgic..."
  },
  Voice_6663_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_6664_AwakerVoiceContent = {
    Text = "A school where all is treated equal... I wonder what foolish dreams you harbor. Even if you haven't committed any wrongs, they will still trample you underfoot. I know that feeling."
  },
  Voice_6664_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_6665_AwakerVoiceContent = {
    Text = "This is the Source of Uncleanliness..."
  },
  Voice_6665_AwakerVoiceTitle = {
    Text = "Exalt: Depression"
  },
  Voice_6666_AwakerVoiceContent = {
    Text = "I was punished for failing to protect the sailors, who were lost to their families forever. They named me the chief culprit of the tragedy... Is this what Dissolution is?"
  },
  Voice_6666_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_6667_AwakerVoiceContent = {
    Text = "Closer... ever closer to my lord..."
  },
  Voice_6667_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_6668_AwakerVoiceContent = {
    Text = "Why? My lord, why do you still... resist awakening?"
  },
  Voice_6668_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_6669_AwakerVoiceContent = {
    Text = "I am Horla from Cité, and my pen name is... Ah, forgive me, I made a promise not to reveal it to anyone. My deepest apologies, but please, simply call me Horla."
  },
  Voice_6669_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6670_AwakerVoiceContent = {
    Text = "I oppose all acts of injustice; betrayal is the worst. In the army, if you cannot or dare not trust your comrades to guard your back, the entire unit will fall apart."
  },
  Voice_6670_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_6671_AwakerVoiceContent = {
    Text = "Why do you appear so dark, yet so radiant...? No, never mind, just ignore my rambling."
  },
  Voice_6671_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_6672_AwakerVoiceContent = {Text = "(Groan)"},
  Voice_6672_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_6673_AwakerVoiceContent = {
    Text = "(Grunted groan)"
  },
  Voice_6673_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_6674_AwakerVoiceContent = {Text = "What?!"},
  Voice_6674_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_6675_AwakerVoiceContent = {
    Text = "I love all lives. I love light. I want Faint to emerge from her secluded shell and experience the world with her own eyes and ears."
  },
  Voice_6675_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_6676_AwakerVoiceContent = {
    Text = "You can't see me!"
  },
  Voice_6676_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_6677_AwakerVoiceContent = {
    Text = "Does the maintenance work need to continue?"
  },
  Voice_6677_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_6678_AwakerVoiceContent = {
    Text = "Parts maintenance has been completed."
  },
  Voice_6678_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_6679_AwakerVoiceContent = {
    Text = "People may betray, but tools never will. If used properly, Dissolution can also become a tool for revenge."
  },
  Voice_6679_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_6680_AwakerVoiceContent = {
    Text = "This moment has finally arrived, after thousands of years of waiting... I am the Philistines' one and only ruler!"
  },
  Voice_6680_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_6680_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_6681_AwakerVoiceContent = {
    Text = "Was that a half-blood Deep One we just passed? Hmm... Look how uptight he stands. Tonight, I shall see him arch that beautiful little back, groveling before me."
  },
  Voice_6681_AwakerVoiceTitle = {
    Text = "Chat: About Caecus"
  },
  Voice_6681_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Caecus\""
  },
  Voice_6682_AwakerVoiceContent = {
    Text = "I'm regaining my strength... Next, I'll claim the dominion that is rightfully mine!"
  },
  Voice_6682_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_6682_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_6683_AwakerVoiceContent = {
    Text = "Not bad. One step closer to tearing off that hypocrite woman's veil."
  },
  Voice_6683_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_6683_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_6684_AwakerVoiceContent = {
    Text = "Calm down, calm down..."
  },
  Voice_6684_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_6685_AwakerVoiceContent = {
    Text = "No need to worry. My pain threshold might be far beyond your imagination."
  },
  Voice_6685_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_6685_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_6686_AwakerVoiceContent = {
    Text = "If you ask me, beautiful fools are the best. Unfortunately, there are far too many clever but useless minds around here."
  },
  Voice_6686_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_6687_AwakerVoiceContent = {
    Text = "Powered by the nuclear fusion of a red giant, supplemented by the energy from a collapsing star, you could start a perpetual motion machine and light an eternal lamp... Eh? You say there's no way to build a perpetual motion machine here, and no red giant? Hmm..."
  },
  Voice_6687_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_6688_AwakerVoiceContent = {
    Text = "The enemy's blood has not yet drained completely."
  },
  Voice_6688_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_6689_AwakerVoiceContent = {
    Text = "Sacrifice! Sacrifice it all... to me!"
  },
  Voice_6689_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6690_AwakerVoiceContent = {
    Text = "Sacrifice! Sacrifice it all... to me!"
  },
  Voice_6690_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6691_AwakerVoiceContent = {
    Text = "It's time to head to the battlefield!"
  },
  Voice_6691_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_6692_AwakerVoiceContent = {Text = "It's time!"},
  Voice_6692_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_6693_AwakerVoiceContent = {
    Text = "My slumber spills dreams like poison. Approach not while I sleep—and wake me never without cause."
  },
  Voice_6693_AwakerVoiceTitle = {
    Text = "Chat: About Slumber"
  },
  Voice_6694_AwakerVoiceContent = {Text = "It's time!"},
  Voice_6694_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6695_AwakerVoiceContent = {
    Text = "Although Herbert is a terrifying person, his cats are very gentle... No, to be precise, there are two cats, right?"
  },
  Voice_6695_AwakerVoiceTitle = {
    Text = "Chat: About Herbert"
  },
  Voice_6695_UnlockDesc = {
    Text = "Unlocks after clearing Main Story Chapter 2"
  },
  Voice_6696_AwakerVoiceContent = {
    Text = "That woman Murphy dresses too flashy... No way, Karen can't lose to her! Or maybe, I'll just kill her..."
  },
  Voice_6696_AwakerVoiceTitle = {
    Text = "Chat: About Murphy"
  },
  Voice_6696_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Murphy\""
  },
  Voice_6697_AwakerVoiceContent = {Text = "Ah..."},
  Voice_6697_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_6698_AwakerVoiceContent = {
    Text = "Does this feel good?"
  },
  Voice_6698_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_6699_AwakerVoiceContent = {
    Text = "When I partnered with Mythag University, it was clearly stipulated that I wouldn't be sent into battle..."
  },
  Voice_6699_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_6699_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_6700_AwakerVoiceContent = {
    Text = "Don't get carried away. Sometimes, the line between the noble and the lowly is but a single step."
  },
  Voice_6700_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_6700_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_6701_AwakerVoiceContent = {
    Text = "Faros greets you. Summoning me here must mean that you are ready to set sail."
  },
  Voice_6701_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6702_AwakerVoiceContent = {
    Text = "Yahoo—I'm so tired, can I go play now!"
  },
  Voice_6702_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_6703_AwakerVoiceContent = {
    Text = "Ah... His brilliance is so intense and dazzling, impossible to ignore! It was a foolish zeal that clouded my senses... No, I will not make any excuses for my stupidity..."
  },
  Voice_6703_AwakerVoiceTitle = {
    Text = "Chat: About Tulu"
  },
  Voice_6703_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Tulu\""
  },
  Voice_6704_AwakerVoiceContent = {
    Text = "How was my singing?"
  },
  Voice_6704_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6705_AwakerVoiceContent = {
    Text = "Slumbering stars of mine dream now stir—let them converge unto their ordained fate. Point thy path to the Divine Realm!"
  },
  Voice_6705_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6706_AwakerVoiceContent = {
    Text = "Don't you think it's fascinating to push all things toward their end, to still the universe's turning gears?"
  },
  Voice_6706_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_6707_AwakerVoiceContent = {
    Text = "Drink it up!"
  },
  Voice_6707_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_6708_AwakerVoiceContent = {Text = "Awesome！"},
  Voice_6708_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_6709_AwakerVoiceContent = {
    Text = "Enter battle command."
  },
  Voice_6709_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_6710_AwakerVoiceContent = {
    Text = "During my days of drifting among the stars, I dreamed of this moment countless times... Thank you for reuniting me with Tinct."
  },
  Voice_6710_AwakerVoiceTitle = {
    Text = "Chat: About Tinct"
  },
  Voice_6710_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Tinct\""
  },
  Voice_6711_AwakerVoiceContent = {
    Text = [[
Mythag University's a great place, especially with the underground casino that pops up every week...
Wait, you didn't know? Oops, let the cat out of the bag.]]
  },
  Voice_6711_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_6712_AwakerVoiceContent = {
    Text = "\"Resist the Dissolution crisis\"... Ha. Human arrogance never fails to amuse."
  },
  Voice_6712_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_6713_AwakerVoiceContent = {
    Text = "After all, humans are only shallow creatures. A few words, a hint, and they begin to fight each other... Sigh, this level of conflict is hardly enough to inspire."
  },
  Voice_6713_AwakerVoiceTitle = {
    Text = "Chat: About Humans"
  },
  Voice_6714_AwakerVoiceContent = {
    Text = "Perhaps I was too hasty to dismiss you as merely mortal. How does one untouched by grace still cling to purpose? This is Miryam's curiosity, not a question from the Holy Mother of the Seas. Will you... indulge me?"
  },
  Voice_6714_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_6714_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_6715_AwakerVoiceContent = {
    Text = "How could one as extraordinary as you not tire of this transient, tumultuous world? You shall find your rightful home in the eternal realm. There, your feet will kiss the hallowed ground, your breaths will be renewed in sacred waters, and your soul will flourish in blessed earth... You will join me in this holy pilgrimage. Join me in this holy pilgrimage. Together we'll rise far beyond mortal bounds, till we stand united at the Throne, and taste the ripened joy in its light..."
  },
  Voice_6715_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_6715_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_6716_AwakerVoiceContent = {
    Text = "We are all wretched mortals in the dust, but the Sage walks apart. He is the Emissary, a divine incarnation. His counsel echoes with the voices of gods, steering our frail civilization toward immortality... I do not expect your hollow mind to grasp devotion now, but one day, you too shall kneel before His throne."
  },
  Voice_6716_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_6716_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_6717_AwakerVoiceContent = {
    Text = "The Chosen are blessed indeed, don't you agree? Their flesh has been remade by His holy will, their lives extended beyond mortal measure. When He strides upon the shore, they will rise as His choir. Isn't this the utmost sweetness and highest happiness for mortals frail as sands?"
  },
  Voice_6717_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_6717_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_6718_AwakerVoiceContent = {
    Text = "The ecstasy of being illuminated by His glory is beyond your faithless comprehension... May He, in His mercy, forgive your blindness and impudence."
  },
  Voice_6718_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_6718_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_6719_AwakerVoiceContent = {
    Text = "Let's make it quick, Keeper."
  },
  Voice_6719_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_6720_AwakerVoiceContent = {Text = "Ehe!"},
  Voice_6720_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_6720_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_6721_AwakerVoiceContent = {
    Text = "Prepare to die, Spartan insect."
  },
  Voice_6721_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_6722_AwakerVoiceContent = {
    Text = "Miss Doll says that I can temporarily avoid Dissolution by abandoning my body like her... No, I can't do it! I can't do it! I will lose consciousness during the procedure, and the darkness will take over!"
  },
  Voice_6722_AwakerVoiceTitle = {
    Text = "Chat: About Doll"
  },
  Voice_6722_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Doll\""
  },
  Voice_6723_AwakerVoiceContent = {
    Text = "Hmph. What is it this time? Ready to embrace your fate of anniliation now?"
  },
  Voice_6723_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_6724_AwakerVoiceContent = {
    Text = "Still troubled by insomnia, Master? I've prepared Dobie's tranquilizer for you~! Although the dose might be a bit high, good sleep is the top priority!"
  },
  Voice_6724_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_6724_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_6725_AwakerVoiceContent = {
    Text = "We were drinking and singing when we suddenly turned into monsters! But it's okay, this greenish skintone is quite fun!"
  },
  Voice_6725_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_6725_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_6726_AwakerVoiceContent = {
    Text = "My dream? Hmm... To buy a beautiful pearl necklace and wear it to a ball. Then I'll be the center of everyone's attention!"
  },
  Voice_6726_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_6726_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_67276_AwakerVoiceContent = {
    Text = "The Aeon of Desire, Tifere Yesod, has found her path to survival. In the face of the unknown, no one can judge the nobility or baseness of her methods."
  },
  Voice_67276_AwakerVoiceTitle = {
    Text = "Chat: About Aeon of Desire"
  },
  Voice_67276_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Thais\""
  },
  Voice_67277_AwakerVoiceContent = {
    Text = "Pass through the Silver Key Gate to reach Their Throne."
  },
  Voice_67277_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_67278_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_67279_AwakerVoiceContent = {
    Text = "Do not let Their knowledge and memories be wasted."
  },
  Voice_67279_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_6727_AwakerVoiceContent = {
    Text = "Sweep left, wipe right, let's wipe away the dust and worries~!"
  },
  Voice_6727_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_6727_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_67280_AwakerVoiceContent = {
    Text = "I am not here."
  },
  Voice_67280_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_67281_AwakerVoiceContent = {
    Text = "A fragment from the infinite space-time continuum arrives within my awareness."
  },
  Voice_67281_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_67282_AwakerVoiceContent = {
    Text = "I have witnessed the whole."
  },
  Voice_67282_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_67283_AwakerVoiceContent = {
    Text = "Everything exists within the void."
  },
  Voice_67283_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_67284_AwakerVoiceContent = {
    Text = "You have gone deep, very deep. Soon, you will witness an extraordinary miracle. I hope you can remain as sane and calm as you are now."
  },
  Voice_67284_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_67284_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_67285_AwakerVoiceContent = {
    Text = "I hate... \"Ignorance.\" No, to diligently seek the ultimate truth is not ignorance. True ignorance lies in living in a haze, unaware of what one does not know."
  },
  Voice_67285_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_67286_AwakerVoiceContent = {
    Text = "I will show you my dreams. Everything bizarre and chaotic that you see is closer to the true nature of this world than the reality you know."
  },
  Voice_67286_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_67286_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_67287_AwakerVoiceContent = {
    Text = "Here is my advice: Remain calm. When you feel tired, stop immediately and conserve your strength. Otherwise, you will be forever lost in the dream realm."
  },
  Voice_67287_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_67287_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_67288_AwakerVoiceContent = {
    Text = "The universe cycles endlessly."
  },
  Voice_67288_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_67289_AwakerVoiceContent = {
    Text = "The synchronization between us should not require such a lengthy adjustment. However, to preserve your mental clarity from the illusions, I will proceed gradually."
  },
  Voice_67289_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_67289_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_6728_AwakerVoiceContent = {
    Text = "Dissolution... worked a case that touched on it. But disappearing seems pretty natural, doesn't it? Everyone vanishes in the end."
  },
  Voice_6728_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_67290_AwakerVoiceContent = {
    Text = "The First Gate. The infinite universe was born from a point."
  },
  Voice_67290_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_67290_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_67291_AwakerVoiceContent = {
    Text = "The Second Gate. A line extends from a point, stretching toward infinite polarities."
  },
  Voice_67291_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_67291_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_67292_AwakerVoiceContent = {
    Text = "The Fourth Gate. The eternal archetype solidified in a space of dimensions."
  },
  Voice_67292_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_67292_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_67293_AwakerVoiceContent = {
    Text = "The Third Gate. Planes are partial and one-sided constructs."
  },
  Voice_67293_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_67293_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_67294_AwakerVoiceContent = {
    Text = "The Ultimate Gate. The final void linking countless universes. Pass through it, and the mysteries of the world will be revealed to you."
  },
  Voice_67294_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_67294_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_67295_AwakerVoiceContent = {
    Text = "The Fifth Gate. The passage of time is but an illusion; there has never been a beginning, and thus, no end."
  },
  Voice_67295_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_67295_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_67296_AwakerVoiceContent = {
    Text = "I was only meant to be your guide, leading you on this journey before returning to rest in the illusory waters. Now, you are my Linker, and our connection is so intricate it is difficult to sever."
  },
  Voice_67296_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_67297_AwakerVoiceContent = {
    Text = "Do you wish to confirm something? The senses of this body are too restricted. If we meet in the Abyss, I can show you much more."
  },
  Voice_67297_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_67298_AwakerVoiceContent = {
    Text = "She is a Fragment of me from another dimension that has been eternally annihilated. Sadly, while she mastered time reversal, she failed to grasp the essence of transcending spacetime, repeatedly succumbing to anguish. This is my fault."
  },
  Voice_67298_AwakerVoiceTitle = {
    Text = "Chat: About Ramona: Timeworn"
  },
  Voice_67298_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Ramona: Timeworn\""
  },
  Voice_67299_AwakerVoiceContent = {Text = "I know."},
  Voice_67299_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_6729_AwakerVoiceContent = {
    Text = "You seem curious about the appearance of my current vessel? Don't overthink it. I was born with a human face."
  },
  Voice_6729_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_67300_AwakerVoiceContent = {Text = "I see."},
  Voice_67300_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_67301_AwakerVoiceContent = {
    Text = "Insignificant."
  },
  Voice_67301_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_67302_AwakerVoiceContent = {
    Text = "Maintain composure."
  },
  Voice_67302_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_67303_AwakerVoiceContent = {
    Text = "Directly linking with an Aeon will damage your mind. However, since you insist, I will respond to your call."
  },
  Voice_67303_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_67304_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_67305_AwakerVoiceContent = {
    Text = "That child has endured far too much because of the Fragment of me within her. Thankfully, her soul remains as clear as flowing silver."
  },
  Voice_67305_AwakerVoiceTitle = {
    Text = "Chat: About Ramona"
  },
  Voice_67305_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Ramona\""
  },
  Voice_67306_AwakerVoiceContent = {
    Text = "Visit Their dream and glimpse the universe's forbidden secrets."
  },
  Voice_67306_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_67307_AwakerVoiceContent = {Text = "Ugh."},
  Voice_67307_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_67308_AwakerVoiceContent = {
    Text = "The Ultimate Gate opens for you. Embrace the world of deathly silence beyond."
  },
  Voice_67308_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_67308_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_67309_AwakerVoiceContent = {
    Text = "I only helped them found this institution for \"Storage.\" The school has achieved more than I anticipated."
  },
  Voice_67309_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_6730_AwakerVoiceContent = {
    Text = "Dissolution is a divine gift. The pain it brings is just enough to paralyze our nerves, allowing us to wholeheartedly indulge in food, wine, and revelry, as we glide towards extinction."
  },
  Voice_6730_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_67310_AwakerVoiceContent = {
    Text = "Past, present, future. A billion brilliances gather as one!"
  },
  Voice_67310_AwakerVoiceTitle = {
    Text = "Over-Exalt: II"
  },
  Voice_67311_AwakerVoiceContent = {
    Text = "Past, present, future. A billion brilliances gather as one!"
  },
  Voice_67311_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_67312_AwakerVoiceContent = {
    Text = "The Ultimate Gate has opened. Witness the All-in-One and One-in-All!"
  },
  Voice_67312_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_67313_AwakerVoiceContent = {
    Text = "The Ultimate Gate has opened. Witness the All-in-One and One-in-All!"
  },
  Voice_67313_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_67314_AwakerVoiceContent = {
    Text = "Listen to the voice of wisdom."
  },
  Voice_67314_AwakerVoiceTitle = {
    Text = "Special Skill: II"
  },
  Voice_67315_AwakerVoiceContent = {
    Text = "Infinite, boundless, endless, limitless."
  },
  Voice_67315_AwakerVoiceTitle = {
    Text = "Special Skill: III"
  },
  Voice_67316_AwakerVoiceContent = {
    Text = "It is Their will... No, it is an unconscious gaze that encompasses all things within Their breath."
  },
  Voice_67316_AwakerVoiceTitle = {
    Text = "Chat: About the Crisis"
  },
  Voice_67317_AwakerVoiceContent = {
    Text = "I failed... to see it all...."
  },
  Voice_67317_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_67318_AwakerVoiceContent = {
    Text = "I will reveal the truth."
  },
  Voice_67318_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_67319_AwakerVoiceContent = {
    Text = "I love... the \"Answer.\" It is out of this love that I have guarded this Gate, and out of this love that I placed its Key in your hand."
  },
  Voice_67319_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_6731_AwakerVoiceContent = {
    Text = "Must... I must return..."
  },
  Voice_6731_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6732_AwakerVoiceContent = {
    Text = "Heaven and Earth, follow the cycle of causality!"
  },
  Voice_6732_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6733_AwakerVoiceContent = {
    Text = "Heaven and Earth, follow the cycle of causality!"
  },
  Voice_6733_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6734_AwakerVoiceContent = {
    Text = "The blade has not lost its edge yet."
  },
  Voice_6734_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_6735_AwakerVoiceContent = {
    Text = "Training must not be neglected!"
  },
  Voice_6735_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_6736_AwakerVoiceContent = {
    Text = "I am more agile now."
  },
  Voice_6736_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_6737_AwakerVoiceContent = {
    Text = "The Formless Spawns shall be at your command."
  },
  Voice_6737_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_6737_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_6738_AwakerVoiceContent = {
    Text = "Feel my scorching breath!"
  },
  Voice_6738_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6739_AwakerVoiceContent = {
    Text = "We will all become... part of the Green Flame..."
  },
  Voice_6739_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_6740_AwakerVoiceContent = {
    Text = "My shield shall always shine for you, my lord."
  },
  Voice_6740_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_6740_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_6741_AwakerVoiceContent = {
    Text = "I... I've just grown a bit stronger. I'm truly grateful!"
  },
  Voice_6741_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_6741_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_6742_AwakerVoiceContent = {
    Text = "Strange, they seem to fear my singing..."
  },
  Voice_6742_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_6743_AwakerVoiceContent = {Text = "Tsk..."},
  Voice_6743_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_6744_AwakerVoiceContent = {
    Text = "(A dismissive grunt)"
  },
  Voice_6744_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_6745_AwakerVoiceContent = {
    Text = "(A dismissive grunt)"
  },
  Voice_6745_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_6746_AwakerVoiceContent = {
    Text = "(A dismissive grunt)"
  },
  Voice_6746_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_6747_AwakerVoiceContent = {
    Text = "Time spent with friends is always so... relaxing."
  },
  Voice_6747_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_6748_AwakerVoiceContent = {
    Text = "The Bloody Chain of Slaughter, Tisiphone's Messenger, Blade of Hatred... I don't care. That's just what they called me. Well, I certainly don't mind living up to them."
  },
  Voice_6748_AwakerVoiceTitle = {
    Text = "Chat: About Helot Herself"
  },
  Voice_6749_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_6749_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_6750_AwakerVoiceContent = {Text = "ALL-IN!"},
  Voice_6750_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_6751_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_6751_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_6752_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_6752_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_6753_AwakerVoiceContent = {
    Text = "Can we go further this time? Let's head to the beach!"
  },
  Voice_6753_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_6754_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_6755_AwakerVoiceContent = {
    Text = "Wow—thank you, dear friend~"
  },
  Voice_6755_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_6756_AwakerVoiceContent = {
    Text = "Friends~ More Friends~"
  },
  Voice_6756_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_6757_AwakerVoiceContent = {
    Text = "Uvhash... he's special. Did you think my family's prosperity came easily? It's all thanks to him killing like a mad dog in the arena. He was our biggest cash cow."
  },
  Voice_6757_AwakerVoiceTitle = {
    Text = "Chat: About Uvhash"
  },
  Voice_6757_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Uvhash\""
  },
  Voice_6758_AwakerVoiceContent = {Text = "Foolish!"},
  Voice_6758_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_6759_AwakerVoiceContent = {Text = "Heh."},
  Voice_6759_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_6760_AwakerVoiceContent = {
    Text = "Go! Issue the battle command!"
  },
  Voice_6760_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_6761_AwakerVoiceContent = {
    Text = "In the abyss... there will be a light of justice."
  },
  Voice_6761_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_6762_AwakerVoiceContent = {
    Text = "The light of justice is lit here!"
  },
  Voice_6762_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6763_AwakerVoiceContent = {
    Text = "Human emotions are as fragile and precious as flowers..."
  },
  Voice_6763_AwakerVoiceTitle = {
    Text = "Chat: About Colette"
  },
  Voice_6764_AwakerVoiceContent = {
    Text = "Hit, Stand, Blackjack!"
  },
  Voice_6764_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6765_AwakerVoiceContent = {
    Text = "Hit, Stand, Blackjack!"
  },
  Voice_6765_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_67754_AwakerVoiceContent = {
    Text = "Do not resist. Do not weep. Become nothing!"
  },
  Voice_67754_AwakerVoiceTitle = {
    Text = "Over-Exalt: II"
  },
  Voice_67756_AwakerVoiceContent = {
    Text = "Do not resist. Do not weep. Become nothing!"
  },
  Voice_67756_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_67772_AwakerVoiceContent = {
    Text = "Gate, open for me."
  },
  Voice_67772_AwakerVoiceTitle = {
    Text = "Special Skill: I"
  },
  Voice_79297_AwakerVoiceContent = {Text = "Oh."},
  Voice_79297_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_79298_AwakerVoiceContent = {Text = "Hmm...?"},
  Voice_79298_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_80092_AwakerVoiceContent = {
    Text = "Hydrotherapy, electroconvulsive therapy, restraining therapy... those are not treatments, but torture. So, I've been treating the patients in those hospitals my way, pro bono. Eventually, they all achieved recovery and found true freedom."
  },
  Voice_80092_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_80092_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_80093_AwakerVoiceContent = {
    Text = "Poor Mr. White. His family kept him in a pigpen because asylums in the neighborhood were full. I treated him for free, and after that, he finally realized he was a person, not livestock. He then reclaimed his dignity, with his own hands."
  },
  Voice_80093_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_80093_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_80094_AwakerVoiceContent = {
    Text = "Weavers, lawyers, barons... I'll never turn a patient away for a fee. To me, they are all merely patients in need of healing."
  },
  Voice_80094_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_80094_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_80095_AwakerVoiceContent = {
    Text = "I admit I underestimated you. Your existence is pain itself. This time, there's no need for follow-up visits. I want to stay by your side and see the outcome firsthand."
  },
  Voice_80095_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_80095_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_80096_AwakerVoiceContent = {
    Text = "These patients have given me beautiful memories. Next, it's your turn, Keeper. I've already chosen a perfect ending for you. It will be the most exquisite consultation of my career."
  },
  Voice_80096_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_80096_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_81138_AwakerVoiceContent = {
    Text = "Refusing a doctor's help will not benefit you. Perhaps next time, we'll try deep hypnosis."
  },
  Voice_81138_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_81139_AwakerVoiceContent = {
    Text = "A dark room, all alone, along with the countless painful whispers constantly echoing in my mind... this is the best way to enjoy time."
  },
  Voice_81139_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_81140_AwakerVoiceContent = {
    Text = "Though it may be impolite to say, talking to that child only bores me. You can only ever see one expression... a smile."
  },
  Voice_81140_AwakerVoiceTitle = {
    Text = "Chat: About Aurita"
  },
  Voice_81140_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Aurita\""
  },
  Voice_81141_AwakerVoiceContent = {
    Text = "Forgive my intrusion, I simply sensed a low psychological energy and came to check on you. Now, Keeper, shall we embark on a journey through your mind?"
  },
  Voice_81141_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_81143_AwakerVoiceContent = {
    Text = "Psychiatrists once cured patients by drilling open their skulls with a trepanation technique... Please, relax. That was long ago. We have since developed far more methods to delve into the mind."
  },
  Voice_81143_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_81143_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_81144_AwakerVoiceContent = {
    Text = "To understand each other, one must open their heart. Touch here, and my silver heart will open for you."
  },
  Voice_81144_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_81145_AwakerVoiceContent = {
    Text = "If you seek my thoughts, you may be disappointed. I'm better at listening than I am at offering commentary."
  },
  Voice_81145_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_81146_AwakerVoiceContent = {
    Text = "Ah, I heard His voice... those murmurs, every syllable filled with the utmost agony."
  },
  Voice_81146_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_81147_AwakerVoiceContent = {
    Text = "I will remember the pain of this moment... recalling and savoring it again and again."
  },
  Voice_81147_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_81148_AwakerVoiceContent = {
    Text = "As a fragment of that existence, you carry Their scent... A beautiful scent, filled with pain. It makes any memory of yours taste incredibly delicious."
  },
  Voice_81148_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_81149_AwakerVoiceContent = {
    Text = "Remember those fears, detail your feelings of pain. The essence of emotional impact therapy is to face pain directly and conquer it. Here, I'll wipe away your tears. Take your time. Tell me those memories in detail..."
  },
  Voice_81149_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_81149_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_81150_AwakerVoiceContent = {
    Text = "Congratulations, you have been healed. Yes, those hallucinations and illusions are normal; they are proof of your recovery."
  },
  Voice_81150_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_81150_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_81151_AwakerVoiceContent = {
    Text = "Your vision is probably filled with bizarre hallucinations now, which is quite normal. Draw them out, and your subconscious and instincts will reveal everything."
  },
  Voice_81151_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_81151_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_81152_AwakerVoiceContent = {
    Text = "Next is Philip Pinel's moral therapy. You must express your innermost desires and fears. It's a necessary procedure to unshackle the mind and restore dormant humanity."
  },
  Voice_81152_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_81152_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_81153_AwakerVoiceContent = {
    Text = "Keeper, can you help me with a small test? The Rorschach inkblot test. It will help me see the depths of your inner self... I will become the only Awakener to unveil the secrets of your heart."
  },
  Voice_81153_AwakerVoiceTitle = {
    Text = "Chat: About Psychological Analysis"
  },
  Voice_81154_AwakerVoiceContent = {
    Text = "First, let's listen to some music. How do you like this melody? Soothing and gentle. Now, let your body and mind resonate with the music, entering a state of spiritual relaxation."
  },
  Voice_81154_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_81154_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_81155_AwakerVoiceContent = {
    Text = "Watch the pendulum... follow its movement with your eyes."
  },
  Voice_81155_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_81156_AwakerVoiceContent = {
    Text = "Shh... quiet. Now, walk toward the ending I'll guide you to."
  },
  Voice_81156_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_81157_AwakerVoiceContent = {
    Text = "A numb soul holds no interest for me. Their souls are already dead. No matter how much one stirs them, there will not be a ripple."
  },
  Voice_81157_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_81158_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_81159_AwakerVoiceContent = {
    Text = "I am listening. Please, continue."
  },
  Voice_81159_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_81160_AwakerVoiceContent = {
    Text = "Please remain quiet."
  },
  Voice_81160_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_81161_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_81162_AwakerVoiceContent = {
    Text = "Trust me a little more."
  },
  Voice_81162_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_81163_AwakerVoiceContent = {
    Text = "Expose your pain."
  },
  Voice_81163_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_81164_AwakerVoiceContent = {
    Text = "Don't be shy, there's no need to hide. I am your sole confidante. Come, pour out your deepest pain to me."
  },
  Voice_81164_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_81165_AwakerVoiceContent = {
    Text = "Aigis looks much brighter now. Of course, if my little guest needs help, I'm happy to offer it. I mean, genuine help."
  },
  Voice_81165_AwakerVoiceTitle = {
    Text = "Chat: About Aigis"
  },
  Voice_81165_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Aigis\""
  },
  Voice_81166_AwakerVoiceContent = {
    Text = "Show me your truest self."
  },
  Voice_81166_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_81168_AwakerVoiceContent = {
    Text = "I will savor this sweet pain."
  },
  Voice_81168_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_81169_AwakerVoiceContent = {
    Text = "Don't be shy, there's no need to hide. I am your sole confidante. Come, pour out your deepest pain to me."
  },
  Voice_81169_AwakerVoiceTitle = {
    Text = "Over-Exalt: II"
  },
  Voice_81170_AwakerVoiceContent = {
    Text = "Mental illness is not exclusive to this era; it transcends time and space. Dissolution is the same. Both transcend the boundaries of human cognition, don't they?"
  },
  Voice_81170_AwakerVoiceTitle = {
    Text = "Chat: About the Crisis"
  },
  Voice_81171_AwakerVoiceContent = {
    Text = "Shh... quiet. Now, walk toward the ending I'll guide you to."
  },
  Voice_81171_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_81172_AwakerVoiceContent = {
    Text = "This place is filled with traces of history, and to some extent, history represents memories... painful memories of the departed."
  },
  Voice_81172_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_81173_AwakerVoiceContent = {
    Text = "Take a deep breath."
  },
  Voice_81173_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_81174_AwakerVoiceContent = {
    Text = "Pain, despair, death... these memories taste like dessert after a fine meal."
  },
  Voice_81174_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_81175_AwakerVoiceContent = {
    Text = "No need for such nervousness. This is merely a regular consultation."
  },
  Voice_81175_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_81176_AwakerVoiceContent = {
    Text = "Listen to my guidance."
  },
  Voice_81176_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_84185_AwakerVoiceContent = {
    Text = "An unexpected incident occurred during the ritual. Forgive me for striking your arm with the flag; I had to keep you conscious."
  },
  Voice_84185_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_84185_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_84186_AwakerVoiceContent = {
    Text = "Here, I encounter many kinds of ships and work with advanced navigation equipment. I find it deeply rewarding. Above all, I believe this \"ship\" is charting the right course for human history."
  },
  Voice_84186_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_84187_AwakerVoiceContent = {
    Text = "The ritual is complete. Thank you for your cooperation. Next time, I'll prepare special flags to guide us more safely through it."
  },
  Voice_84187_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_84187_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_84188_AwakerVoiceContent = {
    Text = "I don't know why it exists. I know only this: I must navigate successfully, and bring everyone home."
  },
  Voice_84188_AwakerVoiceTitle = {
    Text = "Chat: About the Crisis"
  },
  Voice_84189_AwakerVoiceContent = {
    Text = "Rest assured, I shall use this power to guide the ship safely, and I will never misuse it."
  },
  Voice_84189_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_84190_AwakerVoiceContent = {
    Text = "Please stop resisting."
  },
  Voice_84190_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_84191_AwakerVoiceContent = {
    Text = "You have my full respect. I vow to carry out every order you give."
  },
  Voice_84191_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_84192_AwakerVoiceContent = {
    Text = "Forgive me. I understand ships better than people. But if I may: your keel is neither wood nor iron, but steel. Strong. Steadfast. Truly admirable."
  },
  Voice_84192_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_84192_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_84193_AwakerVoiceContent = {Text = "Surrender."},
  Voice_84193_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_84194_AwakerVoiceContent = {
    Text = "Rather than \"like, \" I prefer the word \"devotion.\" When I look directly at that indescribable god, my mind loses reason and fills with ecstasy. I should fear Him, but I can't help myself."
  },
  Voice_84194_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_84195_AwakerVoiceContent = {
    Text = "I will not be defeated by this storm."
  },
  Voice_84195_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_84196_AwakerVoiceContent = {
    Text = "Without order, what remains in this world? Only chaos."
  },
  Voice_84196_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_84197_AwakerVoiceContent = {
    Text = "On our next voyage, I'd like to board the ship as something other than navigator. Uh... I mean, as one who follows your lead. You have my complete trust, Keeper."
  },
  Voice_84197_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_84197_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_84198_AwakerVoiceContent = {
    Text = "I am merely fulfilling my duty as navigator and require neither report nor praise."
  },
  Voice_84198_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_84199_AwakerVoiceContent = {
    Text = "The lighthouse system eases the demands of navigation. Its beam is strong and clear. I'm glad to sail with Faros."
  },
  Voice_84199_AwakerVoiceTitle = {
    Text = "Chat: About Faros"
  },
  Voice_84199_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Faros\""
  },
  Voice_84200_AwakerVoiceContent = {
    Text = "Sailors, follow my guidance. I will make sure we reach the harbour safely."
  },
  Voice_84200_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_84201_AwakerVoiceContent = {
    Text = "The spiritual link has been established. I can sense your presence. This is my first time navigating the void. If anything drifts off course, please correct me at once."
  },
  Voice_84201_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_84201_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_84202_AwakerVoiceContent = {
    Text = "Cirrus clouds observed, with a continued drop in barometric pressure. All hands alert. The ship is about to enter a storm."
  },
  Voice_84202_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_84203_AwakerVoiceContent = {
    Text = "This chaos is the result of my miscalculation of the route. I am willing to accept punishment in accordance with the rules."
  },
  Voice_84203_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_84204_AwakerVoiceContent = {
    Text = "Measuring the altitude angle of celestial bodies."
  },
  Voice_84204_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_84205_AwakerVoiceContent = {
    Text = "This dizzying sensation is much like seasickness. Please close your eyes, take my hand, and lean against me. That should ease it a little."
  },
  Voice_84205_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_84205_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_84206_AwakerVoiceContent = {
    Text = "Lower the foremast sails. Waves are pressing against the port side. Helmsman, adjust course per my calculations."
  },
  Voice_84206_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_84207_AwakerVoiceContent = {
    Text = "These experiences are invaluable. I will record them in detail in the logbook, for future sailors."
  },
  Voice_84207_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_84208_AwakerVoiceContent = {
    Text = "The ritual to deepen spiritual connection carries risks and unknown results. But rest assured, I will navigate for you to ensure the ritual is completed smoothly."
  },
  Voice_84208_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_84208_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_84209_AwakerVoiceContent = {
    Text = "Readjusting weight distribution."
  },
  Voice_84209_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_84210_AwakerVoiceContent = {
    Text = "Ensure the ship's safety above all else."
  },
  Voice_84210_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_84211_AwakerVoiceContent = {
    Text = "Some people are like steamships—slow to respond, but capable of high speed. Others, diesel ships—quick to start, but with limited power. So what about you, Keeper?"
  },
  Voice_84211_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_84211_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_84212_AwakerVoiceContent = {
    Text = "I firmly believe in the fundamental law that effort brings reward, and I shall work even harder in future."
  },
  Voice_84212_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_84213_AwakerVoiceContent = {
    Text = "You've proven self on multiple occassions. I believe you're an excellent navigator, perhaps more capable than I am."
  },
  Voice_84213_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_84213_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_84214_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_84215_AwakerVoiceContent = {
    Text = "As long as you are in need, Corposant is always on standby."
  },
  Voice_84215_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_84215_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_84216_AwakerVoiceContent = {
    Text = "Sailors, follow my guidance. I will make sure we reach the harbour safely."
  },
  Voice_84216_AwakerVoiceTitle = {
    Text = "Over-Exalt: II"
  },
  Voice_84217_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_84218_AwakerVoiceContent = {
    Text = "The navigator Corposant reports for duty! The flag has been prepared, personal condition is good, please give the launch order, Keeper."
  },
  Voice_84218_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_84219_AwakerVoiceContent = {
    Text = "I will lead my ship to the correct course."
  },
  Voice_84219_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_84220_AwakerVoiceContent = {
    Text = "Is my hat askew? Apologies, but I'm not sure what you mean. Please give me clear instructions."
  },
  Voice_84220_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_84221_AwakerVoiceContent = {
    Text = "The flag is the navigator's language, and also their epitaph. When the ship sinks, salvagers will read the last message I left from the wreckage of the flag."
  },
  Voice_84221_AwakerVoiceTitle = {
    Text = "Chat: About Her Flag"
  },
  Voice_84222_AwakerVoiceContent = {
    Text = "Assessing the ship's trim and balance."
  },
  Voice_84222_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_84223_AwakerVoiceContent = {
    Text = "Lower the foremast sails. Waves are pressing against the port side. Helmsman, adjust course per my calculations."
  },
  Voice_84223_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_84224_AwakerVoiceContent = {
    Text = "E flag conveys instructions."
  },
  Voice_84224_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_84225_AwakerVoiceContent = {
    Text = "When necessary, a navigator trained in engine room cooperation can act as helmsman. But for the ship's safety, I still prefer to entrust that task to someone more skilled."
  },
  Voice_84225_AwakerVoiceTitle = {
    Text = "Chat: About Celeste"
  },
  Voice_84225_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Celeste\""
  },
  Voice_84226_AwakerVoiceContent = {
    Text = "I feel... a sense of weightlessness, followed by violent shaking—as if the ship were being tossed about. Keeper, follow my movements to find your centre and stay balanced."
  },
  Voice_84226_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_84226_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_84406_AwakerVoiceContent = {
    Text = "Begin updating the nautical chart with corrections."
  },
  Voice_84406_AwakerVoiceTitle = {
    Text = "Special Skill: I"
  },
  Voice_84407_AwakerVoiceTitle = {
    Text = "Special Skill: III"
  },
  Voice_84408_AwakerVoiceContent = {
    Text = "C flag acknowledges instructions."
  },
  Voice_84408_AwakerVoiceTitle = {
    Text = "Special Skill: II"
  },
  Voice_84409_AwakerVoiceTitle = {
    Text = "Special Skill: III"
  },
  Voice_90333_AwakerVoiceContent = {
    Text = "You will not get past me."
  },
  Voice_90333_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_90334_AwakerVoiceContent = {
    Text = "How should friends get along? Pollux likes ordering me around when he could do those things himself. And I'm willing to help him with those tasks, it's our way of hanging out together. If you want, I'll do something for you too."
  },
  Voice_90334_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_90334_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_90335_AwakerVoiceContent = {
    Text = "Let the Cataclysm come. This immortal flesh will stand unbroken!"
  },
  Voice_90335_AwakerVoiceTitle = {
    Text = "Over-Exalt: II"
  },
  Voice_90336_AwakerVoiceContent = {
    Text = "Even before that book, we wondered about the world beyond the lake's island, the scarlet walls. Yet when Pollux suffered, I didn't resist. I lack his courage. Unlike Pollux, I am much more cowardly and clumsy."
  },
  Voice_90336_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_90336_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_90337_AwakerVoiceContent = {
    Text = "Do I... sound stupid? Sorry, please forgive my ignorance. My knowledge begins and ends with the Lantern's doctrines. Teach me your likes and dislikes—I'll commit them to memory."
  },
  Voice_90337_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_90337_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_90338_AwakerVoiceContent = {
    Text = "Witness this will of mine—this hunger for freedom."
  },
  Voice_90338_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_90339_AwakerVoiceContent = {
    Text = "A store that can fulfill any wish, overflowing with countless treasures... It makes one hesitate to approach. Not that I doubt the lady's power, but \"to obtain something, one must pay the corresponding price\"—this is a lesson Pollux and I have learned through bitter experience, time and again."
  },
  Voice_90339_AwakerVoiceTitle = {
    Text = "Chat: About Daffodil"
  },
  Voice_90339_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Daffodil\""
  },
  Voice_90340_AwakerVoiceContent = {
    Text = "Will these cursed wings ever find the strength to take flight again..."
  },
  Voice_90340_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_90341_AwakerVoiceContent = {
    Text = "You can't destroy me!"
  },
  Voice_90341_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_90342_AwakerVoiceContent = {
    Text = "Would you like to touch my feathers? Sure, go ahead. Should I extend them further?"
  },
  Voice_90342_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_90343_AwakerVoiceContent = {
    Text = "Your generosity unsettles me. The expensive books, the meteorite crystals you gave me... is there a price? Sorry, please forgive my suspicion. I shouldn't doubt you like this."
  },
  Voice_90343_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_90343_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_90344_AwakerVoiceContent = {
    Text = "All birds find their sky eventually."
  },
  Voice_90344_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_90345_AwakerVoiceContent = {
    Text = "Ah, I heard he's a master chef... The knowledge of making food is indeed very necessary. Although I'm not that particular about food, Pollux is extremely picky. I should find some time to learn from him... I shouldn't go? Why? The food that mister makes looks delicious though."
  },
  Voice_90345_AwakerVoiceTitle = {
    Text = "Chat: About Doresain"
  },
  Voice_90345_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Doresain\""
  },
  Voice_90346_AwakerVoiceContent = {
    Text = "Now that I reflect on it, the maids carrying lanterns weren't so different from Pollux and me. We all lived shackled by invisible chains, quietly submitting to our fate. Yet that green maid... she was different. There was a lightness to her, as if she genuinely took pleasure in her duties. Maybe... maybe she had already discovered true freedom."
  },
  Voice_90346_AwakerVoiceTitle = {
    Text = "Chat: About Karen"
  },
  Voice_90346_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Karen\""
  },
  Voice_90347_AwakerVoiceContent = {
    Text = "You can't destroy me!"
  },
  Voice_90347_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_90348_AwakerVoiceContent = {
    Text = "Guess I never... made it out, huh..."
  },
  Voice_90348_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_90349_AwakerVoiceContent = {
    Text = "Vanish with the wind!"
  },
  Voice_90349_AwakerVoiceTitle = {
    Text = "Special Skill: II"
  },
  Voice_90350_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_90351_AwakerVoiceContent = {
    Text = "Greetings. I am Castor... Was there more I should say? Forgive me—words don't come easily. If you need anything, just ask."
  },
  Voice_90351_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_90352_AwakerVoiceContent = {
    Text = "Just a scratch..."
  },
  Voice_90352_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_90353_AwakerVoiceContent = {Text = "Fall!"},
  Voice_90353_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_90354_AwakerVoiceContent = {
    Text = "So much unseen... so much undone. Those desolate deep green lakes and the thick fog that lingers on will no longer hold us back. Oceans, cities, farms from the book's pages... I'll see them. With Pollux. With you."
  },
  Voice_90354_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_90354_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_90355_AwakerVoiceContent = {
    Text = "When you hear the leaves rustling in the trees, you'll know I'm by your side."
  },
  Voice_90355_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_90355_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_90356_AwakerVoiceContent = {
    Text = "These dark feathers grow heavier each day."
  },
  Voice_90356_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_90357_AwakerVoiceContent = {
    Text = "What I covet most is how you effortlessly trust your companions. Being forgotten... betrayed... the wounds never fade."
  },
  Voice_90357_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_90358_AwakerVoiceContent = {
    Text = "That master thief offered to teach me the best survival skills for just five hundred Leonian Florins... Have I been deceived? No, I believe this is knowledge worth learning, and it's precisely what Pollux and I are lacking... Is it a money issue? I understand. Then, how about I go negotiate with her and pay her four hundred and fifty Leonian Florins instead?"
  },
  Voice_90358_AwakerVoiceTitle = {
    Text = "Chat: About Jenkin"
  },
  Voice_90358_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Jenkin\""
  },
  Voice_90359_AwakerVoiceContent = {
    Text = "I can take more..."
  },
  Voice_90359_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_90360_AwakerVoiceContent = {
    Text = "When we were children, the rules weren't this strict. Sometimes, Pollux would go off and say something, and magically get a handful of candies. That sweetness... it feels like this moment now."
  },
  Voice_90360_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_90360_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_90361_AwakerVoiceContent = {
    Text = "Let the Cataclysm come. This immortal flesh will stand unbroken!"
  },
  Voice_90361_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_90362_AwakerVoiceContent = {
    Text = "Could you teach me how to trade? How to exchange items and how to manage the currency obtained—it's truly a profound subject. Gaining freedom is just the start; Pollux and I still have a lot to learn to live independently. May I rely on you?"
  },
  Voice_90362_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_90363_AwakerVoiceContent = {
    Text = "Vanish with the wind!"
  },
  Voice_90363_AwakerVoiceTitle = {
    Text = "Special Skill: I"
  },
  Voice_90364_AwakerVoiceContent = {
    Text = "Wind, carry them to death's maw!"
  },
  Voice_90364_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_90365_AwakerVoiceContent = {
    Text = "Pollux... The Lantern filled his mind with poisonous ideas, but he's actually kind. It's not that he's selfish... He's just terrified. Terrified of losing the Lantern's approval, of vanishing without that fragile sense of identity. His desperation to please them... it's the panic of someone clinging to the only \"self\" he's ever known."
  },
  Voice_90365_AwakerVoiceTitle = {
    Text = "Chat: About Pollux"
  },
  Voice_90365_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Pollux\""
  },
  Voice_90366_AwakerVoiceContent = {
    Text = "Sorry, I didn't mean to zone out... You asked me what this feather is? This is... His most prized thing... and now mine. Do you like it? It's pretty, right?"
  },
  Voice_90366_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_90367_AwakerVoiceContent = {
    Text = "Theology lessons under Albino and the Light Watch filled our days. I dreamed of shorter scriptures—fewer verses to stumble over, fewer reprimands."
  },
  Voice_90367_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_90367_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_90368_AwakerVoiceContent = {
    Text = "Thank you... for the key to my freedom. For letting me grasp my own fate."
  },
  Voice_90368_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_90369_AwakerVoiceContent = {
    Text = "These wings are fully grown now. So sturdy, so powerful. Now I can carry both Pollux and you. Call for me when you wish to fly."
  },
  Voice_90369_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_90369_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_90370_AwakerVoiceContent = {
    Text = "Get behind my wings!"
  },
  Voice_90370_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_90371_AwakerVoiceContent = {
    Text = "At last... I've seen the stars from those pages."
  },
  Voice_90371_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_90372_AwakerVoiceContent = {
    Text = "The High Priestess... Juliette. She was gentle with us then. Her warm smiles made disobedience unthinkable. A pat on the head silenced all protests. We didn't want to let her down. Yeah, don't worry, I don't feel that way anymore... You may pat my head instead."
  },
  Voice_90372_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_90372_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_90373_AwakerVoiceContent = {
    Text = "I was immersed in that black, sticky ooze for a long, long time—so long that I forgot about time itself, so long that even Pollux forgot about me. It didn't bring physical pain... just dread, watching my soul dissolve away."
  },
  Voice_90373_AwakerVoiceTitle = {
    Text = "Chat: About the Crisis"
  },
  Voice_90374_AwakerVoiceContent = {
    Text = "We weren't allowed to talk to other people since childhood. \"Friend\" was a foreign concept to me... until recently. Pollux and I were everything to each other: brothers, friends, fellow prisoners, each other's only solace. Now... perhaps I should make some new friends."
  },
  Voice_90374_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_90374_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_90375_AwakerVoiceContent = {Text = "Back off!"},
  Voice_90375_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_90376_AwakerVoiceContent = {
    Text = "A school without Theology? Where you choose lessons... skip them? It sounds like a dream."
  },
  Voice_90376_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_90377_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_90378_AwakerVoiceContent = {
    Text = "Out of the way!"
  },
  Voice_90378_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_95050_AwakerVoiceContent = {
    Text = "You blasphemers... will be punished..."
  },
  Voice_95050_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_95051_AwakerVoiceContent = {
    Text = "My heart is alight!"
  },
  Voice_95051_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_95052_AwakerVoiceContent = {Text = "Filth."},
  Voice_95052_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_95053_AwakerVoiceContent = {
    Text = "Ah, that overzealous believer. The world might see her as a raving madwoman. Though she once committed evil, such fervent devotion—the will to offer everything to her god—is a resoluteness most ordinary souls could never muster. What do I think of her, you ask? ...I only feel... a certain commiseration. A kinship, with one cast adrift in the same turbulent sea."
  },
  Voice_95053_AwakerVoiceTitle = {
    Text = "Chat: About Miryam"
  },
  Voice_95053_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Miryam\""
  },
  Voice_95054_AwakerVoiceContent = {
    Text = "I shall bring Guidance and Judgment; may the White Night purge your sins!"
  },
  Voice_95054_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_95055_AwakerVoiceContent = {
    Text = "Ha... After all this time, he hasn't changed one bit. I never imagined as a child that I would be the one to hurt my brother—that I'd come to owe him so much it aches with shame, for a fate we did not choose. We have suffered enough separation. Now that I am back, I swear: nothing will ever separate us again. Not even death itself."
  },
  Voice_95055_AwakerVoiceTitle = {
    Text = "Chat: About Castor"
  },
  Voice_95055_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Castor\""
  },
  Voice_95056_AwakerVoiceContent = {
    Text = "I once hated many things—the impolite servants, the disrespectful attendants, the heretics who defiled the Light... But now? I hate the Lantern. Only the Lantern! Juliette and her Church brought upon my brother and I irreparable pain. I swear upon my title as the former Divus, I shall never permit such pain to befall another!"
  },
  Voice_95056_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_95057_AwakerVoiceContent = {
    Text = "I shall walk the path of light until my final breath."
  },
  Voice_95057_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_95058_AwakerVoiceContent = {
    Text = "May the Lightbearer's radiance pierce this endless night!"
  },
  Voice_95058_AwakerVoiceTitle = {
    Text = "Over-Exalt: II"
  },
  Voice_95059_AwakerVoiceContent = {
    Text = "Your generosity and compassion are without end; I shall meditate upon the warmth of your light."
  },
  Voice_95059_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_95060_AwakerVoiceContent = {
    Text = "The Apostle of the Lightbearer, scion of the White Night, One who Dispels Darkness, Divus of the Divine Heart—I, Pollux, have answered your call. I offer unto you my power over Darkness, and my soul forged of Light."
  },
  Voice_95060_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_95061_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_95062_AwakerVoiceContent = {
    Text = "Purge your sins!"
  },
  Voice_95062_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_95063_AwakerVoiceContent = {
    Text = "I was told this abyssal darkness was worthy of faith. That it was a blessing I would deliver unto the faithful. Now, this darkness has long since corroded me, merging with my very being... Yet the heart that beats within this sinful vessel remains a sanctum that can never be tainted. Rest assured, I shall use the power it has bestowed upon me to bring true benediction to this world!"
  },
  Voice_95063_AwakerVoiceTitle = {
    Text = "Chat: About Dissolution"
  },
  Voice_95064_AwakerVoiceContent = {
    Text = "I will herald your glorious name, and all that is unclean and impure shall be purified by its radiance."
  },
  Voice_95064_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_95065_AwakerVoiceContent = {
    Text = "The sins of the past are committed; I shall flee them no longer. I must also correct the Lantern's mistakes and guide the strayed back to the true path. Let me bear my sins. Then, I shall answer the light of your call and tread the right path as the Divus."
  },
  Voice_95065_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_95065_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_95066_AwakerVoiceContent = {
    Text = "Yours is a compassionate soul, to forgive one so burdened by sin. I feel the pure, radiant light within your spirit—it outshines the brightest flame. Perhaps you can guide my heart, which has lost its way..."
  },
  Voice_95066_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_95066_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_95067_AwakerVoiceContent = {
    Text = "The Darkness... the Darkness spread by Juliette's incantation, it has lingered in my mind... And now, a single ray of light has pierced it! Could that faint glimmer be trying to tell me something?"
  },
  Voice_95067_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_95067_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_95068_AwakerVoiceContent = {
    Text = "I heard she was once a Divine Maiden. But with such uncouth manners and brutish behavior... What? She cannot recite a single prayer? Such profound impiety... I feel a vicarious shame for her deity."
  },
  Voice_95068_AwakerVoiceTitle = {
    Text = "Chat: About Murphy"
  },
  Voice_95068_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Murphy\""
  },
  Voice_95069_AwakerVoiceContent = {
    Text = "The one who can lead all from the mist is the true Lightbearer, forged of purest silver. The sinless paradise preached by Juliette is, in truth, built upon the bones of the faithful. As the Divus, I shall sow the new gospel among all who are worthy of salvation."
  },
  Voice_95069_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_95070_AwakerVoiceContent = {
    Text = "You have lead me and granted me Light. For so long I was blinded by false purpose. Now, I have found my true calling: to correct the ignorant and distorted heretics and bring everlasting Light to this world. I know of your selflessness; You have no need for my devotion or offerings. Then I beg this: allow me to walk at your side, to record every sacred word and deed, that they may guide my path through the darkness."
  },
  Voice_95070_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_95070_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_95071_AwakerVoiceContent = {
    Text = "Chained in shackles, bathed in dark sludge, I shall chase that ray of light, no matter what... Is this what you wanted to teach me?"
  },
  Voice_95071_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_95071_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_95072_AwakerVoiceContent = {
    Text = "I have lost my light, and this blind suffering torments me. I beg you, save my lost soul. Please, take my hand as I guide yours over this Holy Heart in my chest. Please, guide toward the light..."
  },
  Voice_95072_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_95072_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_95073_AwakerVoiceContent = {
    Text = "What an unfortunate child. Since she has devoted herself to your cause, she shall surely attain ultimate redemption. But why has her monkey-like companion also received your mercy? That evil child even stole my sacramentals! A torrent of sins must rage within her soul. Ahh, the disrespect! THE UTTER DISRESPECT!"
  },
  Voice_95073_AwakerVoiceTitle = {
    Text = "Chat: About Aigis and Jenkin"
  },
  Voice_95073_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Aigis\" and \"Jenkin\""
  },
  Voice_95074_AwakerVoiceContent = {Text = "Begone."},
  Voice_95074_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_95075_AwakerVoiceContent = {
    Text = "May the Lightbearer's radiance pierce this endless night!"
  },
  Voice_95075_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_95076_AwakerVoiceContent = {
    Text = "Ah... now I see! I see such mighty power, I see the world's truth... I have erred in the past. You are the real Lightbearer! Please allow me to become your loyal Apostle. This heart, born for the Lightbearer, shall henceforth beat and tremble in your service only..."
  },
  Voice_95076_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_95076_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_95077_AwakerVoiceContent = {
    Text = "That priest's blind pursuit of redemption is the height of folly. Divine grace should be bestowed solely upon the devout and the righteous. If even he, an apostle, lacks the discernment to separate the wheat from the chaff, rewarding unrepentant sinners and allowing them to defile his deity's kingdom... is that not the most profound betrayal of his faith and of the righteous souls he claims to serve?"
  },
  Voice_95077_AwakerVoiceTitle = {
    Text = "Chat: About Salvador"
  },
  Voice_95077_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Salvador\""
  },
  Voice_95078_AwakerVoiceContent = {
    Text = "My heart is alight!"
  },
  Voice_95078_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_95079_AwakerVoiceContent = {Text = "Hah!"},
  Voice_95079_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_95080_AwakerVoiceContent = {
    Text = "In my youth, I was determined to break free from that place. It brought me only pain, and I deemed it unworthy of longing. But now, granted a second life, I see that freedom is not my sole desire. The true meaning of being Divus is to witness the devoted, hopeful, and grateful countenances of the followers when they learn redemption is at hand."
  },
  Voice_95080_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_95081_AwakerVoiceContent = {
    Text = "In my time following Juliette, I committed grave errors and was undeserving of your trust. Yet you chose me anyway... Be assured, I shall seek my conviction once more. As the Divus, I will not disappoint my subjects again, nor will I disappoint you."
  },
  Voice_95081_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_95081_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_95082_AwakerVoiceContent = {
    Text = "Your bestowed gift I shall wield, with deepest gratitude."
  },
  Voice_95082_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_95083_AwakerVoiceContent = {Text = "Impudence!"},
  Voice_95083_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_95084_AwakerVoiceContent = {Text = "Tsk."},
  Voice_95084_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_95085_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_95086_AwakerVoiceContent = {
    Text = "In my name!"
  },
  Voice_95086_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_95087_AwakerVoiceContent = {
    Text = "I see it! That light, shining deep within my consciousness—it brightens! It calls to me..."
  },
  Voice_95087_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_95087_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_95088_AwakerVoiceContent = {
    Text = "In our childhood, Castor and I served together as the Twin Divi. I always thought him too dull, too clumsy, that I alone must guide our future. Now, having witnessed the path you walk, I see the world's foundation is built and paved by those like you and him: the steadfast and the upright."
  },
  Voice_95088_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_95088_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_95089_AwakerVoiceContent = {
    Text = "My Light, ever since I received your guidance, I believe I have embarked upon the one true path. Yet your rather dim-witted believer remains perplexed by one question: does the legendary sinless paradise also fall under your dominion? \"It doesn't exist,\" you say...? Could it be... you mean to say that paradise exists here, in the mortal world, within the pure hearts of the righteous?"
  },
  Voice_95089_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_95090_AwakerVoiceContent = {
    Text = "This heart, which once heeded the divine will, now beats closer to yours."
  },
  Voice_95090_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_95091_AwakerVoiceContent = {
    Text = "D-Do you have an order for me, my Light? Your Apostle stands ever-ready to hear your teaching."
  },
  Voice_95091_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_95092_AwakerVoiceContent = {
    Text = "Please illuminate me, my guiding light! By your light, I have now seen all that must be seen... I shall use this cursed form to purify all that has passed, and let all that is to come bask in your radience!"
  },
  Voice_95092_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_95092_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_95093_AwakerVoiceContent = {
    Text = "Chanting Light!"
  },
  Voice_95093_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_95391_AwakerVoiceContent = {
    Text = "Looking for salvation in this ugly world? Keep at it, hopeful little one."
  },
  Voice_95391_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_95391_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_95392_AwakerVoiceContent = {
    Text = "Here, you can have these. Forbidden relics from some ruins. Was gonna burn them, but figured you might get some use. How'd I get my hands on these? Let's just say some folks <Italic:voluntarily> handed 'em over. And don't worry, source is clean."
  },
  Voice_95392_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_95392_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_95393_AwakerVoiceContent = {
    Text = "Hunt's over. Payment? Give me a smile. That'll do."
  },
  Voice_95393_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_95394_AwakerVoiceContent = {
    Text = "You know, these guns don't fire bullets. They shoot desire and malice. Seven shots, and everything burns. These chaotic flames, resembling flesh, will drag everything into the inferno."
  },
  Voice_95394_AwakerVoiceTitle = {
    Text = "Chat: About Guns"
  },
  Voice_95395_AwakerVoiceContent = {
    Text = "Don't push yourself too hard, Keeper. I know it's rough out there, and one wrong step means disaster. But if you keep this up, you'll break. Come find me when you need someone to talk to. We're family."
  },
  Voice_95395_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_95395_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_95396_AwakerVoiceContent = {
    Text = "Burn. Shatter. Howl!"
  },
  Voice_95396_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_95397_AwakerVoiceContent = {Text = "Disappear."},
  Voice_95397_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_95398_AwakerVoiceContent = {
    Text = "I see clearer now. I see what writhes beneath the abyss... I, We, require more power. For you. For my family. I must..."
  },
  Voice_95398_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_95398_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_95399_AwakerVoiceContent = {
    Text = "Come here. Sit closer. No need to be so stiff. \nFunny, isn't it? When we first met, I never thought I could let my guard down like this. Ha, the mighty Living Flame, yearning for a family she could fully trust.\nNow, promise me something. When the day comes... when you can't hold on any longer— speak My name. And I, We, shall come. We shall take you into Our Kingdom. It may only delay the inevitable... but in your final moments, you will rest, cradled in Our embrace."
  },
  Voice_95399_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_95399_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_95400_AwakerVoiceContent = {
    Text = "Your end is neigh."
  },
  Voice_95400_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_95401_AwakerVoiceContent = {Text = "Ugh!"},
  Voice_95401_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_95402_AwakerVoiceContent = {
    Text = "In the forge of infinite wrath and desires... Burn!"
  },
  Voice_95402_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_95403_AwakerVoiceContent = {
    Text = "After a good hunt comes a good feast. Here, try my roasted camel and fresh tequila. What? You're not good with liquor? Fine, well, have some juice instead."
  },
  Voice_95403_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_95403_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_95404_AwakerVoiceContent = {
    Text = "What's wrong, little one? Need a hug? Come here. Big sis has got you... Haha, don't be shy."
  },
  Voice_95404_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_95406_AwakerVoiceContent = {Text = "Damn it."},
  Voice_95406_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_95407_AwakerVoiceContent = {
    Text = "The Amber-Tinted Death is here."
  },
  Voice_95407_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_95408_AwakerVoiceContent = {
    Text = "Fall back, I'll cover you... Don't you fret, I always make it back alive."
  },
  Voice_95408_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_95409_AwakerVoiceContent = {
    Text = "C'mon. Let's burn this whole world to the ground!"
  },
  Voice_95409_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_95410_AwakerVoiceContent = {
    Text = "Blazing fire, rise from ash and oblivion!"
  },
  Voice_95410_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_95411_AwakerVoiceContent = {
    Text = "Fire's burning brighter. Wanna see a real fireworks show, little one?"
  },
  Voice_95411_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_95412_AwakerVoiceContent = {
    Text = "Those sick bastards playing with human lives in the dark? Yeah. I'll kill 'em all. Every last one."
  },
  Voice_95412_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_95413_AwakerVoiceContent = {Text = "Bang!"},
  Voice_95413_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_95414_AwakerVoiceContent = {
    Text = "I'll find Him. Doesn't matter where in this rotten universe He's hiding. That filthy rat's gonna pay. Every last bit of His \"rapture and delight\" will burn in hellfire. Rest assured, I'll save you a premium seat at His funeral... so we can savor His final screams together."
  },
  Voice_95414_AwakerVoiceTitle = {
    Text = "Chat: About N"
  },
  Voice_95415_AwakerVoiceContent = {
    Text = "Listen. That's the dying cries of melting stars."
  },
  Voice_95415_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_95415_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_95416_AwakerVoiceContent = {
    Text = "Welcome your end."
  },
  Voice_95416_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_95417_AwakerVoiceContent = {
    Text = "You're my family. And I'm damn proud of you. So stand tall, my %player%! No matter what, I've got your back."
  },
  Voice_95417_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_95418_AwakerVoiceContent = {
    Text = "Those unnamable things slither in the dark, gnawing at the edges of the world. Sooner or later, you'll have to face them. But don't worry, I've got your back. Always."
  },
  Voice_95418_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_95418_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_95420_AwakerVoiceContent = {
    Text = "Burn. Shatter. Howl!"
  },
  Voice_95420_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_95421_AwakerVoiceContent = {Text = "Stay calm."},
  Voice_95421_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_95422_AwakerVoiceContent = {Text = "Back off."},
  Voice_95422_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_95423_AwakerVoiceContent = {
    Text = "What do I think of Dissolution? Ask a sewer rat what it thinks of the king. My answer is simple: a deep, instinctual disgust. Give me the chance, and I'll pour a glass of camel milk wine and listen to their scream as my guns burns them to ashes."
  },
  Voice_95423_AwakerVoiceTitle = {
    Text = "Chat: About the Crisis"
  },
  Voice_95424_AwakerVoiceContent = {
    Text = "Wanna make the flames burn even brighter?"
  },
  Voice_95424_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_95424_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_95425_AwakerVoiceContent = {
    Text = "I only come when there's work. Need me? Say the words. Come on, repeat after me: ...@4...@2Ia! Kathigu-Ra!"
  },
  Voice_95425_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_95426_AwakerVoiceContent = {
    Text = "Back in that shithole town, we survived by being meaner than the rest. Even after clawing our way up, we had to watch our backs—lords, guards, those damn \"noble knights\" clinging to the past. Now's different. They are my family. My Kynde. No more bowing. Just one little stray left out there... but that one? That one's gonna be just fine. Always took care of the rest for me while I'm away."
  },
  Voice_95426_AwakerVoiceTitle = {
    Text = "Chat: About Family"
  },
  Voice_95427_AwakerVoiceContent = {
    Text = "That's your enemy? Then the hunt is on."
  },
  Voice_95427_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_95428_AwakerVoiceContent = {
    Text = "I am the Living Flame—unforgettable, unstoppable! Witness now, THE ANNIHILATION OF ALL!"
  },
  Voice_95428_AwakerVoiceTitle = {
    Text = "Over-Exalt: II"
  },
  Voice_95429_AwakerVoiceContent = {
    Text = "Burn and Destruction are my everything, I'm obsessed with the death that comes from hunting... Do you really think I'd say something like that? Haha. I only ever cared about my family... Even more than myself."
  },
  Voice_95429_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_95430_AwakerVoiceContent = {
    Text = "You in trouble, kid? Kathigu-Ra's coming, and she's bringing Destruction. Say goodbye to your problems. Poof! Gone."
  },
  Voice_95430_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_95431_AwakerVoiceContent = {
    Text = "Ah, the taste of power... Shall we find some poor bastards to try it out on?"
  },
  Voice_95431_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_95431_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_95432_AwakerVoiceContent = {
    Text = "I am the Living Flame—unforgettable, unstoppable! Witness now, THE ANNIHILATION OF ALL!"
  },
  Voice_95432_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_95433_AwakerVoiceContent = {
    Text = "The legendary Queen of Aram, the Great Aeon of Desire, Tifere Yesod... I saw her once, when I was hunting N down. Don't agree with her methods, but... if it was the only way to protect my family from \"Its\" gaze... I'd have done the same. We are not so different, her and me."
  },
  Voice_95433_AwakerVoiceTitle = {
    Text = "Chat: About Thais"
  },
  Voice_95433_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Thais\""
  },
  Voice_95434_AwakerVoiceContent = {
    Text = "Fine work keeping your iron clean. A polished gun's a happy gun."
  },
  Voice_95434_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_95435_AwakerVoiceContent = {
    Text = "We are the Fire. The Eternal Flame. The Undying Chaos. And We will bring you all... home..."
  },
  Voice_95435_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_95435_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_96361_AwakerVoiceContent = {
    Text = "I adore the classic beauty of this institution's Gothic clock tower. And the Awakeners here, ah... They exude an aromatic flavor I've never tasted: a perfect blend of departed fragrance and a trace of living scent. It truly makes me crave a little bite."
  },
  Voice_96361_AwakerVoiceTitle = {
    Text = "Chat: About Mythag"
  },
  Voice_96362_AwakerVoiceContent = {
    Text = "If death is what you seek, then I shall grant your wish."
  },
  Voice_96362_AwakerVoiceTitle = {Text = "Exalt: II"},
  Voice_96363_AwakerVoiceContent = {
    Text = "I am rather eager to begin."
  },
  Voice_96363_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_96364_AwakerVoiceContent = {
    Text = "Have I finally piqued your interest? Do come, my dear guest, join me at my table and partake in this grand banquet. Allow me to guide you as we savour the delicate afterglow of every spirit together."
  },
  Voice_96364_AwakerVoiceTitle = {
    Text = "Enlighten: Florish"
  },
  Voice_96364_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 15"
  },
  Voice_96365_AwakerVoiceContent = {
    Text = "Shhh, please, do be quiet. Let's listen to the voices of the departed."
  },
  Voice_96365_AwakerVoiceTitle = {
    Text = "Affinity: I"
  },
  Voice_96365_UnlockDesc = {
    Text = "Unlocks at Affinity Level 2"
  },
  Voice_96366_AwakerVoiceContent = {
    Text = "My people and I revere the beauty of permanence. Dissolution slowly weathers a living person, wiping away all traces of their existence... Such cruel torture should not be allowed."
  },
  Voice_96366_AwakerVoiceTitle = {
    Text = "Chat: About the Crisis"
  },
  Voice_96367_AwakerVoiceContent = {
    Text = "Like me, Mr. Pickman is in pursuit of immortalized beauty. We could have become closer friends. But he sees eating as a violation of preserved eternity. Such a narrow artistic philosophy."
  },
  Voice_96367_AwakerVoiceTitle = {
    Text = "Chat: About Pickman"
  },
  Voice_96367_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Pickman\""
  },
  Voice_96368_AwakerVoiceContent = {Text = "Hah!"},
  Voice_96368_AwakerVoiceTitle = {Text = "Strike: I"},
  Voice_96369_AwakerVoiceContent = {
    Text = "No adjective can describe the intoxicating fragrance of your body. It is like the tart aftertaste of a rich Bordeaux wine, and the thick aroma of a mellow, buttery sponge cake. The day of your death will perhaps be the most important event of my remaining time."
  },
  Voice_96369_AwakerVoiceTitle = {
    Text = "Chat: About the Keeper"
  },
  Voice_96370_AwakerVoiceContent = {
    Text = "There was a man who slowly carved away a young girl's flesh, fingernails, hands, and feet, all while continuously healing her. He didn't want her to die, nor did he want her to live. I could not, of course, grant him a peaceful death. So, I gave him a taste of his own medicine. I wonder how many years he's been trapped there... For someone who desecrates death, this is quite fair, isn't it?"
  },
  Voice_96370_AwakerVoiceTitle = {
    Text = "Chat: What I Hate"
  },
  Voice_96371_AwakerVoiceContent = {
    Text = "I preside over death, but please, do not misunderstand. I never create it; I merely follow in its wake, harvesting the choicest morsels left behind.."
  },
  Voice_96371_AwakerVoiceTitle = {
    Text = "Enlighten: Observe"
  },
  Voice_96371_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 1"
  },
  Voice_96372_AwakerVoiceContent = {
    Text = "Do you, too, crave the taste of my flesh, dear Keeper?"
  },
  Voice_96372_AwakerVoiceTitle = {
    Text = "Chat: Touch"
  },
  Voice_96373_AwakerVoiceContent = {
    Text = "Who shall grace my dinner table today, I wonder?"
  },
  Voice_96373_AwakerVoiceTitle = {
    Text = "Investigation Begins"
  },
  Voice_96374_AwakerVoiceContent = {
    Text = "I shall bestow upon you the honour of becoming tonight's feast."
  },
  Voice_96374_AwakerVoiceTitle = {
    Text = "Investigation Success"
  },
  Voice_96375_AwakerVoiceContent = {
    Text = "How terribly inelegant."
  },
  Voice_96375_AwakerVoiceTitle = {Text = "Hit: III"},
  Voice_96376_AwakerVoiceContent = {
    Text = "I shall bring a clean rest."
  },
  Voice_96376_AwakerVoiceTitle = {Text = "Skill: I"},
  Voice_96377_AwakerVoiceContent = {
    Text = [[
Before every meal, I converse with the departed. For them, being eaten and savoured with true sincerity is a continuation of life and their final, most glorious moment.
Like how I long for them, they, too, long for me.]]
  },
  Voice_96377_AwakerVoiceTitle = {
    Text = "Affinity: III"
  },
  Voice_96377_UnlockDesc = {
    Text = "Unlocks at Affinity Level 6"
  },
  Voice_96378_AwakerVoiceContent = {
    Text = "Quiet, will you?"
  },
  Voice_96378_AwakerVoiceTitle = {Text = "Hit: IV"},
  Voice_96379_AwakerVoiceContent = {
    Text = "Scatter and fade into the shadows!"
  },
  Voice_96379_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_96380_AwakerVoiceContent = {
    Text = "Let's keep our distance."
  },
  Voice_96380_AwakerVoiceTitle = {Text = "Defense: I"},
  Voice_96381_AwakerVoiceContent = {
    Text = "Scatter and fade into the shadows!"
  },
  Voice_96381_AwakerVoiceTitle = {Text = "Skill: IV"},
  Voice_96382_AwakerVoiceContent = {
    Text = "Why are you so wary of me? You needn't and shouldn't be alarmed; to feed on a living human goes against my aesthetic."
  },
  Voice_96382_AwakerVoiceTitle = {
    Text = "Chat: About Food"
  },
  Voice_96383_AwakerVoiceContent = {
    Text = "If death is what you seek, then I shall grant your wish."
  },
  Voice_96383_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_96384_AwakerVoiceContent = {
    Text = "How terribly inelegant."
  },
  Voice_96384_AwakerVoiceTitle = {Text = "Hit: I"},
  Voice_96385_AwakerVoiceContent = {
    Text = "Watch your steps."
  },
  Voice_96385_AwakerVoiceTitle = {
    Text = "Defense: II"
  },
  Voice_96386_AwakerVoiceContent = {
    Text = "While that lady's enthusiasm is very touching, her body has a sort of over-fermented, damp smell. Even though she keeps begging me to have a taste, it simply does not suit my palate. How vexing."
  },
  Voice_96386_AwakerVoiceTitle = {
    Text = "Chat: About Leigh"
  },
  Voice_96386_UnlockDesc = {
    Text = "Unlocks after acquiring Awakener \"Leigh\""
  },
  Voice_96387_AwakerVoiceContent = {
    Text = [[
Do you know?
Every life has a long-lasting echo as it fades.
They vary in pitch and tone, stretching little by little from the moment death arrives until they dissipate into the heavens and earth, much like a sighing cry.]]
  },
  Voice_96387_AwakerVoiceTitle = {
    Text = "Affinity: II"
  },
  Voice_96387_UnlockDesc = {
    Text = "Unlocks at Affinity Level 4"
  },
  Voice_96388_AwakerVoiceContent = {
    Text = "Rest assured, {Male=Mr.,Female=Miss} Keeper, I'll remain by your side until the day your life meets its destined end. On that day, I will, with all due solemnity, consume your body piece by piece. And your soul shall reside within me, forever."
  },
  Voice_96388_AwakerVoiceTitle = {
    Text = "Affinity: V"
  },
  Voice_96388_UnlockDesc = {
    Text = "Unlocks at Affinity Level 10"
  },
  Voice_96389_AwakerVoiceContent = {
    Text = "You can't smell yourself? Ah, what a shame. You're missing out on the sweetest, the most sublime... Oh, my, what is it? Why are you pulling away?"
  },
  Voice_96389_AwakerVoiceTitle = {
    Text = "Affinity: IV"
  },
  Voice_96389_UnlockDesc = {
    Text = "Unlocks at Affinity Level 8"
  },
  Voice_96390_AwakerVoiceContent = {
    Text = "I see more impending deaths. The other side is becoming ever clearer..."
  },
  Voice_96390_AwakerVoiceTitle = {
    Text = "Upgrade: III"
  },
  Voice_96391_AwakerVoiceContent = {
    Text = "Please, entrust your body to me. I will savour you meticulously: every drop of blood, every piece of flesh, every single bone."
  },
  Voice_96391_AwakerVoiceTitle = {Text = "Over-Exalt"},
  Voice_96392_AwakerVoiceContent = {
    Text = "Different ingredients demand different preparations. The organs, they need to be marinated. The tendons in the legs are best stewed. Fatty parts are perfect for fermentation and ageing, while the more delicate pieces can be fried, roasted, or even transformed into beautifully sculpted jellies. These choices are all about discretion. For without preserving and accentuating the ingredient's natural flavour, there is no respect."
  },
  Voice_96392_AwakerVoiceTitle = {
    Text = "Enlighten: Insight"
  },
  Voice_96392_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 7"
  },
  Voice_96393_AwakerVoiceContent = {
    Text = "This might be a bit chilly."
  },
  Voice_96393_AwakerVoiceTitle = {Text = "Strike: II"},
  Voice_96394_AwakerVoiceContent = {
    Text = [[
The pairing of dishes also holds great importance.
The juxtaposition of sour with sweet, crisp with tender, light with rich, and delicate with coarse, creates a layered flavour and a textural contrast that leads to different sensations upon entry, mastication, and when savouring the aftertaste.
This is the endless and wondrous pleasure a proper meal provides.]]
  },
  Voice_96394_AwakerVoiceTitle = {
    Text = "Enlighten: Elevate"
  },
  Voice_96394_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 11"
  },
  Voice_96395_AwakerVoiceContent = {
    Text = "Thank you so much for your enthusiasm. The honour is all mine."
  },
  Voice_96395_AwakerVoiceTitle = {
    Text = "Upgrade: II"
  },
  Voice_96396_AwakerVoiceContent = {
    Text = "Truly delicious food is always worth the wait."
  },
  Voice_96396_AwakerVoiceTitle = {
    Text = "Investigation Halted"
  },
  Voice_96397_AwakerVoiceContent = {
    Text = "I am no barbaric beast who gorges on raw flesh. The consumption of death is a solemn and elegant affair. You must commune with and truly understand each ingredient's unique flavour."
  },
  Voice_96397_AwakerVoiceTitle = {
    Text = "Enlighten: Ponder"
  },
  Voice_96397_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 2"
  },
  Voice_96398_AwakerVoiceContent = {
    Text = "The deceased who have found peace are beautiful and fragrant. Their beauty isn't in the flesh, before or after death, but in their souls. Those souls' enlightenment regarding death, their longing for life, and their desire to be remembered are the delicacies I have always dreamt of."
  },
  Voice_96398_AwakerVoiceTitle = {
    Text = "Chat: What I Like"
  },
  Voice_96399_AwakerVoiceContent = {
    Text = "No perfume compares to the human body's own natural fragrance. To know a person by their scent is a simply divine pleasure."
  },
  Voice_96399_AwakerVoiceTitle = {
    Text = "Enlighten: Reflect"
  },
  Voice_96399_UnlockDesc = {
    Text = "Unlocks at Enlighten Level 3"
  },
  Voice_96400_AwakerVoiceContent = {
    Text = "Ah, what an unforgettable scent... I simply cannot wait to welcome you into my sanctuary."
  },
  Voice_96400_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_96401_AwakerVoiceContent = {
    Text = "Please, entrust your body to me. I will savour you meticulously: every drop of blood, every piece of flesh, every single bone."
  },
  Voice_96401_AwakerVoiceTitle = {
    Text = "Over-Exalt: II"
  },
  Voice_96402_AwakerVoiceContent = {
    Text = "I shall bring a clean rest."
  },
  Voice_96402_AwakerVoiceTitle = {Text = "Skill: II"},
  Voice_96403_AwakerVoiceContent = {
    Text = "Quiet, will you?"
  },
  Voice_96403_AwakerVoiceTitle = {Text = "Hit: II"},
  Voice_96404_AwakerVoiceContent = {
    Text = "Your fragrant aroma is positively intoxicating."
  },
  Voice_96404_AwakerVoiceTitle = {Text = "Upgrade: I"},
  Voice_98324_AwakerVoiceContent = {
    Text = "In the forge of infinite wrath and desires... Burn!"
  },
  Voice_98324_AwakerVoiceTitle = {
    Text = "Special Skill: I"
  }
})
return Text_Voice
